from scipy.optimize import differential_evolution, minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = (h.sum()**2) * L.max()
    if den <= 0:
        return -1.0
    return num / den


def _make(w1, w2, g, r):
    w1 = max(1, int(round(w1)))
    w2 = max(1, int(round(w2)))
    g = max(0, int(round(g)))
    r = max(1.0, float(r))
    N = w1 + g + w2
    if N > 20000:
        # scale down proportionally
        s = 20000.0 / N
        w1 = max(1, int(round(w1 * s)))
        w2 = max(1, int(round(w2 * s)))
        g = max(0, int(round(g * s)))
        N = w1 + g + w2
    h = np.zeros(N)
    h[:w1] = 1.0
    h[w1 + g:w1 + g + w2] = r
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9

    best_h = None
    best_R = -1.0

    if start is not None:
