            pass

    # Differential evolution with bounds
    remaining = deadline - time.process_time()
    if remaining > 1.0:
        bounds = [(1, 200), (1, 200), (0, 100), (1.0, 6.0)]
        try:
            res = differential_evolution(
                obj, bounds, maxiter=200, popsize=15, tol=1e-6,
                seed=0, polish=True, workers=1,
                callback=lambda xk, convergence: time.process_time() > deadline
            )
            if -res.fun > best_R:
                best_R = -res.fun
                best_h = _make(*res.x)
        except Exception:
            pass

    # Local refinement with Nelder-Mead around best
    while time.process_time() < deadline:
        if best_h is None:
            break
        # extract current params
        nz = np.nonzero(best_h)[0]
        if nz.size == 0:
            break
        w1 = int(nz[0])
        # find gap
        diffs = np.diff(nz)
        if np.any(diffs > 1):
            gi = np.argmax(diffs)
            g = int(diffs[gi] - 1)
            w2 = int(nz[-1] - nz[gi + 1] + 1)
            r = float(best_h[nz[-1]] / best_h[0]) if best_h[0] > 0 else 1.0
        else:
            g = 0
            w2 = 1
            r = 1.0
        x0 = np.array([w1, w2, g, r], dtype=float)
        try:
            res = minimize(obj, x0, method='Nelder-Mead',
                           options={'maxiter': 500, 'xatol': 1e-3, 'fatol': 1e-8})
            if -res.fun > best_R:
                best_R = -res.fun
                best_h = _make(*res.x)
            else:
                break
        except Exception:
            break
        if time.process_time() > deadline:
            break

    if best_h is None:
