    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = (h.sum()**2) * L.max()
    if den <= 0:
        return -1.0
    return num / den


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(987654321)

    # Seed: start if given, else a smooth bump.
    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        if best.size == 0 or best.sum() <= 0 or not np.all(np.isfinite(best)):
            best = np.ones(50)
    else:
        best = np.ones(50)
    best = np.clip(best, 0.0, None)
    if best.max() > 0:
        best = best / best.max()
    bestR = _R(best)

    # Work at a fixed moderate resolution for the continuous optimisation,
    # then try upsampling to see if more steps help.
    def optimise(h0, seconds):
        """Coordinate-wise + pattern-search hill climb on heights."""
        h = h0.copy()
        cur = _R(h)
        n = h.size
        end = min(deadline, time.process_time() + seconds)
        step = 0.25
        while time.process_time() < end:
            improved = False
            order = rng.permutation(n)
            for i in order:
                if time.process_time() > end:
                    break
                old = h[i]
                for d in (step, -step):
                    new = old + d
                    if new < 0:
                        new = 0.0
                    if new == old:
                        continue
                    h[i] = new
                    r = _R(h)
                    if r > cur:
                        cur = r
                        old = new
                        improved = True
                    else:
                        h[i] = old
            if not improved:
                step *= 0.5
                if step < 1e-4:
                    break
        return h, cur

    # Phase A: refine the start with coordinate search.
    h, r = optimise(best, budget_seconds * 0.45)
    if r > bestR:
        best, bestR = h.copy(), r

    # Phase B: random perturbations (~ bumps) to escape local optima.
    while time.process_time() < deadline:
        seed = best.copy()
        n = seed.size
        # Smooth multiplicative / additive perturbation
        k = max(1, n // 8)
        idx = rng.integers(0, n, size=k)
        seed[idx] += rng.normal(0, 0.15, size=k)
        seed = np.clip(seed, 0.0, None)
        h, r = optimise(seed, min(2.0, max(0.5, (deadline - time.process_time()) * 0.5)))
        if r > bestR:
            best, bestR = h.copy(), r

    # Phase C: try upsampling the best shape to more steps (finer step function).
    if time.process_time() < deadline:
        for factor in (2, 3, 4):
            if time.process_time() > deadline:
                break
            N = best.size * factor
            if N > 200000:
                break
            up = np.interp(np.linspace(0, best.size - 1, N),
                           np.arange(best.size), best)
            h, r = optimise(up, min(2.0, max(0.5, deadline - time.process_time())))
            if r > bestR:
                best, bestR = h.copy(), r

    # Phase D: final fine coordinate polish on best.
    while time.process_time() < deadline:
        h, r = optimise(best, min(1.5, max(0.3, deadline - time.process_time())))
        if r > bestR:
            best, bestR = h.copy(), r
        else:
            break

    if best is None or best.sum() <= 0:
        return np.ones(50)
    return np.clip(best, 0.0, None)


