import time
from scipy.optimize import minimize_scalar


def _knots(h):
    return np.concatenate(([0.0], np.convolve(h, h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * L.max()
    return num / den if den > 0 else 0.0


def R_p_of(h, p):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    Lp = np.sum(np.abs(L)**p) ** (1.0 / p)
    den = s * s * Lp
    return num / den if den > 0 else 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

