        """Exact-R L-BFGS-B polish, run twice for large N (no coord sweep)."""
        for _ in range(2):
            if time.process_time() >= deadline - 0.05:
                break
            try:
                res = minimize(exact_obj, h, jac=True, method='L-BFGS-B',
                               bounds=[(0, None)] * h.size,
                               options={'maxiter': 3000, 'maxfun': 6000})
                cand = np.clip(res.x, 0, None)
                if cand.sum() > 0:
                    cand = cand / cand.max()
                    rc = R_of(cand)
                    if rc > cur:
                        h, cur = cand, rc
            except Exception:
                break
        return h, cur

    def run_schedule(h0, mu_list, stage_cap=1.2):
        h = _rescale_maxL(h0.copy())
        cur = R_of(h)
        for mu in mu_list:
            if time.process_time() >= deadline:
                break
            stage_end = min(deadline, time.process_time() + stage_cap)
            rem = stage_end - time.process_time()
            if rem <= 0.05:
                break
            try:
                res = minimize(make_pen(mu), h, jac=True, method='L-BFGS-B',
                               bounds=[(0, None)] * h.size,
                               options={'maxiter': 2000, 'maxfun': 4000})
                h = _rescale_maxL(res.x)
            except Exception as e:
                print("  mu=%g failed: %s" % (mu, e))
            r = R_of(h)
            print("  mu=%g R=%.6f" % (mu, r))
            if r > cur:
                cur = r
        return h, cur

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7]

    # Pass 1: full schedule from the start
    h, cur = run_schedule(best, mu_list)
    h, cur = polish(h, cur)
    if cur > bestR:
        best, bestR = h.copy(), cur
        print("after pass1 R=%.6f (N=%d)" % (bestR, best.size))

    # Pass 2: shifted one decade higher, from best
    mu_shift = [m * 10.0 for m in mu_list]
    while time.process_time() < deadline - 0.5:
        h, cur = run_schedule(best, mu_shift)
        h, cur = polish(h, cur)
        if cur > bestR + 1e-12:
            best, bestR = h.copy(), cur
            print("after pass2 R=%.6f (N=%d)" % (bestR, best.size))
        else:
            break

    # --- Experiment: iterative resolution doubling/tripling loop ---
    dense_mu = [1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8]
    round_idx = 0
    while time.process_time() < deadline - 0.5:
        if best.size > 16000:
            break
        fac = 2 if (round_idx % 2 == 0) else 3
        newN = best.size * fac
        if newN > 20000:
            fac = 2
            newN = best.size * fac
            if newN > 20000:
                break
        remaining = deadline - time.process_time()
        stage_cap = float(np.clip(0.6 * remaining / 8.0, 0.2, 0.8))
        up = np.repeat(best, fac)
        up = up / max(up.max(), 1e-30)
        hh, cc = run_schedule(up, dense_mu, stage_cap=stage_cap)
        if hh.size > 2500:
            hh, cc = polish_large(hh, cc)
        else:
            hh, cc = polish(hh, cc)
        print("round %d x%d R=%.6f (N=%d)" % (round_idx, fac, cc, hh.size))
        if cc > bestR:
            best, bestR = hh.copy(), cc
            print("  new best R=%.6f (N=%d)" % (bestR, best.size))
        round_idx += 1

    # Pair-summed downsample check of the final best
    if best.size >= 2 and time.process_time() < deadline - 0.2:
        ds = _downsample_pair(best)
        if ds.sum() > 0:
            ds = ds / ds.max()
            ds, dc = polish(ds, R_of(ds))
            print("downsample R=%.6f (N=%d)" % (dc, ds.size))
            if dc > bestR:
                best, bestR = ds.copy(), dc
                print("downsample wins R=%.6f (N=%d)" % (bestR, best.size))

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar


def _knots(h):
    L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, h.sum(), Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    ds = -num * 2.0 * s * mx / (den * den)
    grad += ds
    return R, grad


def _penalty_and_grad(h, mu):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _downsample_pair(h):
    n = h.size
    if n < 2:
        return h.copy()
    m = n // 2
    return h[:2*m].reshape(m, 2).sum(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def exact_obj(x):
        xc = np.clip(x, 0, None)
        R, g = _R_and_grad(xc)
        g = g * (x > 0)
        return -R, -g

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            g = g * (x > 0)
            return P, g
        return f

    def coord_sweep(h, cur, n_passes):
        n = h.size
        for _ in range(n_passes):
            if time.process_time() > deadline:
                return h, cur
            improved = False
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() > deadline:
                    return h, cur
                old = h[idx]
                hi = max(4.0 * old, 1.0)

                def neg_r(alpha):
                    h[idx] = alpha
                    return -R_of(h)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                          method='bounded',
                                          options={'xatol': 1e-8})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand = old
                    cand_r = cur
                if cand_r > cur + 1e-14:
                    h[idx] = cand
                    cur = cand_r
                    improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, cur

    def polish(h, cur):
        if time.process_time() >= deadline:
            return h, cur
        try:
            res = minimize(exact_obj, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': 2000, 'maxfun': 4000})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                cand = cand / cand.max()
                rc = R_of(cand)
                if rc > cur:
                    h, cur = cand, rc
        except Exception:
            pass
        if time.process_time() < deadline:
            h2, c2 = coord_sweep(h.copy(), cur, 1)
            if c2 > cur:
                h, cur = h2, c2
        return h, cur

    def run_schedule(h0, mu_list, stage_cap=1.2):
        h = _rescale_maxL(h0.copy())
        cur = R_of(h)
        for mu in mu_list:
            if time.process_time() >= deadline:
                break
            stage_end = min(deadline, time.process_time() + stage_cap)
            rem = stage_end - time.process_time()
            if rem <= 0.05:
                break
            try:
                res = minimize(make_pen(mu), h, jac=True, method='L-BFGS-B',
                               bounds=[(0, None)] * h.size,
                               options={'maxiter': 2000, 'maxfun': 4000})
                h = _rescale_maxL(res.x)
            except Exception as e:
                print("  mu=%g failed: %s" % (mu, e))
            r = R_of(h)
            print("  mu=%g R=%.6f" % (mu, r))
            if r > cur:
                cur = r
        return h, cur

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7]

    # Pass 1: full schedule from the start
    h, cur = run_schedule(best, mu_list)
    h, cur = polish(h, cur)
    if cur > bestR:
        best, bestR = h.copy(), cur
        print("after pass1 R=%.6f (N=%d)" % (bestR, best.size))

    # Pass 2: shifted one decade higher, from best
    mu_shift = [m * 10.0 for m in mu_list]
    while time.process_time() < deadline - 0.5:
        h, cur = run_schedule(best, mu_shift)
        h, cur = polish(h, cur)
        if cur > bestR + 1e-12:
            best, bestR = h.copy(), cur
            print("after pass2 R=%.6f (N=%d)" % (bestR, best.size))
        else:
            break

    # --- Experiment: pure exact-R doubling ladder ---
    def exact_run(h, maxiter=3000, maxfun=6000):
        try:
            res = minimize(exact_obj, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                return cand
        except Exception:
            pass
        return h

    ladder_round = 0
    while time.process_time() < deadline - 0.5 and best.size < 8000:
        ladder_round += 1
        up = np.repeat(best, 2)
        up = _rescale_maxL(up)
        up = exact_run(up)
        up = _rescale_maxL(up)
        rc = R_of(up)
        if up.size <= 1500:
            up2, rc2 = coord_sweep(up.copy(), rc, 1)
            if rc2 > rc:
                up, rc = up2, rc2
        else:
            up = exact_run(up)
            up = _rescale_maxL(up)
            rc = R_of(up)
        print("ladder %d: R=%.6f (N=%d)" % (ladder_round, rc, up.size))
        if rc > bestR + 1e-12:
            best, bestR = up.copy(), rc
        else:
            # accept anyway to continue ladder growth, but keep best separately
            if rc >= bestR - 5e-3:
                best, bestR = up.copy(), max(bestR, rc)
            else:
                break

    # Finish with exact-R L-BFGS polish of the best
    if time.process_time() < deadline - 0.2:
        h = exact_run(best)
        h = _rescale_maxL(h)
        rc = R_of(h)
        if rc > bestR:
            best, bestR = h.copy(), rc
        print("final polish R=%.6f (N=%d)" % (bestR, best.size))

    # Pair-summed downsample check
    if best.size >= 2 and time.process_time() < deadline - 0.2:
        ds = _downsample_pair(best)
        if ds.sum() > 0:
            ds = ds / ds.max()
            ds, dc = polish(ds, R_of(ds))
            print("downsample R=%.6f (N=%d)" % (dc, ds.size))
            if dc > bestR:
                best, bestR = ds.copy(), dc
                print("downsample wins R=%.6f (N=%d)" % (bestR, best.size))

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar


def _knots(h):
    L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
