def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    ds = -num * 2.0 * s * mx / (den * den)
    grad += ds
    return R, grad


def _penalty_and_grad(h, mu):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _upsample_interp(h, f):
    h = np.asarray(h, dtype=float)
    n = h.size
    xf = (np.arange(n * f) + 0.5) / f - 0.5
    out = np.interp(xf, np.arange(n), h)
    out = np.clip(out, 0, None)
    m = out.max()
    if m > 0:
        out = out / m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def exact_obj(x):
        xc = np.clip(x, 0, None)
        R, g = _R_and_grad(xc)
        g = g * (x > 0)
        return -R, -g

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            g = g * (x > 0)
            return P, g
        return f

    def coord_sweep(h, cur, n_passes, indices=None):
        n = h.size
        for _ in range(n_passes):
            if time.process_time() > deadline:
                return h, cur
            improved = False
            if indices is None:
                order = rng.permutation(n)
            else:
                order = indices[rng.permutation(indices.size)]
            for idx in order:
                if time.process_time() > deadline:
                    return h, cur
                old = h[idx]
                hi = max(4.0 * old, 1.0)

                def neg_r(alpha):
                    h[idx] = alpha
                    return -R_of(h)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                          method='bounded',
                                          options={'xatol': 1e-9})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand = old
                    cand_r = cur
                if cand_r > cur + 1e-15:
                    h[idx] = cand
                    cur = cand_r
                    improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, cur

    def targeted_indices(h, window=6):
        """Indices near the max knot of f*f and near zero positions."""
        Lf = _knots(h)
        am = int(np.argmax(Lf))
        # Lf index k corresponds to h index k-1 in the convolution sense;
        # a knot Lf[k] = sum h[i]h[k-1-i].  Perturb h indices near am.
        lo = max(0, am - 1 - window)
        hi = min(h.size, am - 1 + window + 1)
        idx = list(range(lo, hi))
        # zero positions and their neighbours
        zeros = np.where(h <= 1e-12)[0]
        for z in zeros:
            for d in range(-window, window + 1):
                j = z + d
                if 0 <= j < h.size:
                    idx.append(j)
        return np.unique(np.array(idx, dtype=int))

    def polish(h, cur, do_coord=True, targeted=False):
        if time.process_time() >= deadline:
            return h, cur
        try:
            res = minimize(exact_obj, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': 3000, 'maxfun': 6000,
                                    'ftol': 1e-15, 'gtol': 1e-12})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                cand = cand / cand.max()
                rc = R_of(cand)
                if rc > cur:
                    h, cur = cand, rc
        except Exception:
            pass
        if do_coord and time.process_time() < deadline:
            if targeted:
                idx = targeted_indices(h)
                h2, c2 = coord_sweep(h.copy(), cur, 1, indices=idx)
            else:
                h2, c2 = coord_sweep(h.copy(), cur, 1)
            if c2 > cur:
                h, cur = h2, c2
        return h, cur

    def run_schedule(h0, mu_list, maxiter=2000):
        h = _rescale_maxL(h0.copy())
        cur = R_of(h)
        for mu in mu_list:
            if time.process_time() >= deadline:
                break
            try:
                res = minimize(make_pen(mu), h, jac=True, method='L-BFGS-B',
                               bounds=[(0, None)] * h.size,
                               options={'maxiter': maxiter, 'maxfun': 2*maxiter,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                h = _rescale_maxL(res.x)
            except Exception:
                pass
            r = R_of(h)
            if r > cur:
                cur = r
        return h, cur

    full_mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
                    1e5, 3e5, 1e6, 3e6, 1e7, 3e7, 1e8]
    reduced_mu_list = [1e3, 1e4, 1e5, 1e6]

    high_R = bestR > 0.93

    if high_R:
        # Skip the wasteful re-run at current N.  Go straight to upsampling.
        print("high R start, skipping current-N schedule")
        seeds = []
        if best.size < 100000:
            seeds.append(("up2", _upsample_interp(best, 2)))
        if best.size < 100000:
            seeds.append(("up3", _upsample_interp(best, 3)))
        for name, up in seeds:
            if time.process_time() >= deadline - 1.0:
                break
            hu, cu = run_schedule(up, reduced_mu_list, maxiter=1500)
            hu, cu = polish(hu, cu, do_coord=True, targeted=True)
            if cu > bestR:
                best, bestR = hu.copy(), cu
                print("%s R=%.6f (N=%d)" % (name, bestR, best.size))

        # If time remains, upsample the winner again and repeat.
        while time.process_time() < deadline - 2.0 and best.size < 100000:
            up = _upsample_interp(best, 2)
            hu, cu = run_schedule(up, reduced_mu_list, maxiter=1500)
            hu, cu = polish(hu, cu, do_coord=True, targeted=True)
            if cu > bestR + 1e-13:
                best, bestR = hu.copy(), cu
                print("up2-again R=%.6f (N=%d)" % (bestR, best.size))
            else:
                # try a full polish at this resolution to squeeze more
                hu2, cu2 = polish(hu, cu, do_coord=True, targeted=False)
                if cu2 > bestR + 1e-13:
                    best, bestR = hu2.copy(), cu2
                    print("up2-full R=%.6f (N=%d)" % (bestR, best.size))
                else:
                    break
    else:
        # Original behaviour for lower-R starts.
        h, cur = polish(best, bestR, do_coord=False)
        if cur > bestR:
            best, bestR = h.copy(), cur

        if best.size < 100000:
            for f in (2, 3):
                up = _upsample_interp(best, f)
                hu, cu = run_schedule(up, full_mu_list)
                hu, cu = polish(hu, cu)
                if cu > bestR:
                    best, bestR = hu.copy(), cu
                    print("after up%d-interp R=%.6f (N=%d)" %
                          (f, bestR, best.size))

