import numpy as np
import time
from scipy.optimize import minimize, minimize_scalar
from scipy.interpolate import PchipInterpolator, Akima1DInterpolator, CubicSpline


def _knots(h):
    L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, h.sum(), Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    ds = -num * 2.0 * s * mx / (den * den)
    grad += ds
    return R, grad


def _penalty_and_grad(h, mu):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _upsample_interp(h, f):
    h = np.asarray(h, dtype=float)
    n = h.size
    xf = (np.arange(n * f) + 0.5) / f - 0.5
    P = PchipInterpolator(np.arange(n), h)
    out = P(xf)
    out = np.clip(out, 0, None)
    m = out.max()
    if m > 0:
        out = out / m
    return out


def _seed_kernels(h, N):
    """Build four seeds at fixed N via different interpolation kernels."""
    h = np.asarray(h, dtype=float)
    n = h.size
    x = np.arange(n, dtype=float)
    xf = (np.arange(N) + 0.5) / (N / n) - 0.5
    seeds = {}
    try:
        seeds['linear'] = np.interp(xf, x, h)
    except Exception:
        seeds['linear'] = np.ones(N)
    try:
        seeds['pchip'] = PchipInterpolator(x, h)(xf)
    except Exception:
        seeds['pchip'] = seeds['linear'].copy()
    try:
        seeds['akima'] = Akima1DInterpolator(x, h)(xf)
    except Exception:
        seeds['akima'] = seeds['linear'].copy()
    try:
        seeds['cubic'] = CubicSpline(x, h, bc_type='natural')(xf)
    except Exception:
        seeds['cubic'] = seeds['linear'].copy()
    out = {}
    for k, v in seeds.items():
        v = np.clip(np.asarray(v, dtype=float), 0, None)
        m = v.max()
        if m > 0:
            v = v / m
        out[k] = v
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def exact_obj(x):
        xc = np.clip(x, 0, None)
        R, g = _R_and_grad(xc)
        g = g * (x > 0)
        return -R, -g

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            g = g * (x > 0)
            return P, g
        return f

    def coord_sweep(h, cur, n_passes):
        n = h.size
        for _ in range(n_passes):
            if time.process_time() > deadline:
                return h, cur
            improved = False
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() > deadline:
                    return h, cur
                old = h[idx]
                hi = max(4.0 * old, 1.0)

                def neg_r(alpha):
                    h[idx] = alpha
                    return -R_of(h)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                          method='bounded',
                                          options={'xatol': 1e-9})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand = old
                    cand_r = cur
                if cand_r > cur + 1e-15:
                    h[idx] = cand
                    cur = cand_r
                    improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, cur

    def polish(h, cur, do_coord=True):
        if time.process_time() >= deadline:
            return h, cur
        try:
            res = minimize(exact_obj, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': 3000, 'maxfun': 6000,
                                    'ftol': 1e-15, 'gtol': 1e-12})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                cand = cand / cand.max()
                rc = R_of(cand)
                if rc > cur:
                    h, cur = cand, rc
        except Exception:
            pass
        if do_coord and time.process_time() < deadline:
            h2, c2 = coord_sweep(h.copy(), cur, 1)
            if c2 > cur:
                h, cur = h2, c2
        return h, cur

    def run_schedule(h0, mu_list):
        h = _rescale_maxL(h0.copy())
        cur = R_of(h)
        for mu in mu_list:
            if time.process_time() >= deadline:
                break
            try:
                res = minimize(make_pen(mu), h, jac=True, method='L-BFGS-B',
                               bounds=[(0, None)] * h.size,
                               options={'maxiter': 2000, 'maxfun': 4000,
                                        'ftol': 1e-15, 'gtol': 1e-12})
                h = _rescale_maxL(res.x)
            except Exception:
                pass
            r = R_of(h)
            if r > cur:
                cur = r
        return h, cur

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7, 3e7, 1e8]
    seed_mu = [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8]

    # --- Experiment: kernel sweep at fixed N=2656 ---
    N_fixed = 2656
    if base.size != N_fixed:
        seeds = _seed_kernels(base, N_fixed)
        seed_results = {}
        for name in ('linear', 'pchip', 'akima', 'cubic'):
            if time.process_time() >= deadline - 1.0:
                break
            s = seeds[name]
            hs, cs = run_schedule(s, seed_mu)
            hs, cs = polish(hs, cs, do_coord=False)
            seed_results[name] = cs
            print("seed %-6s R=%.6f" % (name, cs))
            if cs > bestR:
                best, bestR = hs.copy(), cs
        if seed_results:
            print("kernel sweep best=%.6f" % bestR)

    # Quick polish of best (cheap).
    h, cur = polish(best, bestR, do_coord=False)
    if cur > bestR:
        best, bestR = h.copy(), cur

    # Try PCHIP-upsampled best at higher resolution.
    if best.size < 100000:
        for f in (2, 3):
            if time.process_time() >= deadline - 1.0:
                break
            up = _upsample_interp(best, f)
            hu, cu = run_schedule(up, mu_list)
            hu, cu = polish(hu, cu)
            if cu > bestR:
                best, bestR = hu.copy(), cu
                print("after up%d-pchip R=%.6f (N=%d)" %
                      (f, bestR, best.size))

    # Repeated schedule + upsampling rounds until time runs out.
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        h, cur = run_schedule(best, mu_list)
        h, cur = polish(h, cur)
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        if best.size < 100000 and time.process_time() < deadline - 1.5:
            up = _upsample_interp(best, 2)
            hu, cu = run_schedule(up, mu_list)
            hu, cu = polish(hu, cu)
            if cu > bestR:
                best, bestR = hu.copy(), cu
                print("iter%d up2-pchip R=%.6f (N=%d)" %
                      (it, bestR, best.size))
        if time.process_time() < deadline - 2.0 and best.size < 50000:
            pert = best * (1.0 + 0.02 * rng.standard_normal(best.size))
            pert = np.clip(pert, 0, None)
            if pert.sum() > 0:
                hp, cp = polish(pert, R_of(pert), do_coord=False)
                if cp > bestR:
                    best, bestR = hp.copy(), cp
                    print("iter%d pert R=%.6f (N=%d)" %
                          (it, bestR, best.size))

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

