    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        w = 2.0 * mu * r
        grad += _backprop(w, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _upsample_interp(h, f):
