            hu, cu = polish(hu, cu)
            if cu > bestR:
                best, bestR = hu.copy(), cu
                print("up%d-pchip R=%.6f (N=%d)" % (f, bestR, best.size))

    # Ladder refinement.
    if time.process_time() < deadline - 2.0 and best.size < 100000:
