        nonlocal best, bestR
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            return True
        return False

    # Initial exact polish of the start.
    h = lbfgs_exact(best, 1500, 3000)
    try_update(h, bestR)

    mu_list = [1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9, 1e10, 1e11]

    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        # Continuation on the penalty, shrinking the L_inf violation.
        h = best.copy()
        for mu in mu_list:
            if time.process_time() >= deadline - 2.0:
                break
            h = lbfgs_pen(h, mu, 300, 600)
        h = lbfgs_exact(h, 1500, 3000)
        if try_update(h, bestR):
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))

        # Quick coordinate polish on a small targeted set of indices.
        if time.process_time() < deadline - 2.0:
            n = best.size
            Lf = _knots(best)
            center = int(np.argmax(Lf)) // 2
            S = set(int(i) for i in rng.integers(0, n, size=60))
            S.update(int(i) for i in np.argsort(best)[-40:])
            S.update(range(max(0, center - 20), min(n, center + 20)))
            hc = best.copy()
            cc = bestR
            for idx in S:
                if time.process_time() >= deadline - 1.5:
                    break
                old = hc[idx]
                hi_b = max(4.0 * old, 1.0)

                def neg_r(alpha, _i=idx):
                    hc[_i] = alpha
                    return -R_of(hc)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi_b),
                                          method='bounded',
                                          options={'xatol': 1e-10})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand, cand_r = old, cc
                if cand_r > cc + 1e-15:
                    hc[idx] = cand
                    cc = cand_r
                else:
                    hc[idx] = old
            if cc > bestR + 1e-13:
                best, bestR = hc.copy(), cc
                print("coord R=%.6f (N=%d)" % (bestR, best.size))

    # Final stiff-mu continuation with tiny per-call cost.
    h = best.copy()
    stiff = [1e12, 1e13, 1e14, 1e15]
    while time.process_time() < deadline - 0.6:
        improved = False
        for mu in stiff:
            if time.process_time() >= deadline - 0.6:
                break
            h = lbfgs_pen(h, mu, 200, 400)
        h = lbfgs_exact(h, 400, 800)
        if try_update(h, bestR):
            improved = True
            print("stiff R=%.6f (N=%d)" % (bestR, best.size))
        if not improved:
            h = best.copy()

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

