    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    grad += -num * 2.0 * s * mx / (den * den)
    return R, grad


def _penalty_and_grad(h, mu):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        grad += _backprop(2.0 * mu * r, h)
    return P, grad


def _softmax_and_grad(h, p):
    """Objective F_p = -num/(s^2 * M_p), M_p = (sum Lf^p)^(1/p)."""
    n = h.size
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    Lp = np.maximum(Lf, 0.0)
    # M_p
    pw = Lp ** p
    Sp = pw.sum()
    if Sp <= 0:
        return 1e18, np.zeros(n)
    Mp = Sp ** (1.0 / p)
    den = s2 * Mp
    F = -num / den
    # dF/dnum = -1/den ; dnum/dLf = dq
    gLf = -dq / den
    # dF/dMp = num / (s2 * Mp^2)
    dF_dMp = num / (s2 * Mp * Mp)
    # dMp/dLf = Lf^(p-1) * Mp^(1-p)
    dMp = (Lp ** (p - 1)) * (Mp ** (1 - p))
    gLf += dF_dMp * dMp
    grad = _backprop(gLf, h)
    # dF/ds: num/(s^3 * Mp) * 2 ... careful: den = s^2*Mp, dF/ds = num * 2s*Mp/(den^2)
    grad += num * 2.0 * s * Mp / (den * den)
    return F, grad


