               3e9, 1e10, 3e10, 1e11, 3e11, 1e12]

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            h = run_pen(h, mu)
            r = R_of(h)
            if r > cur:
                cur = r
        # Final exact polish of the continuation result.
        if time.process_time() < deadline - 1.0:
            h2 = lbfgs_exact(h, 1500, 3000)
            r2 = R_of(h2)
            if r2 > cur:
