    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, Lf = _num_and_dq(h)
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    coef = num * s * s / (den * den)
    gLf = dq / den
    gLf[am] -= coef
    grad = _backprop(gLf, h)
    grad += -num * 2.0 * s * mx / (den * den)
    return R, grad


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        grad += _backprop(2.0 * mu * r, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(999)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter, maxfun):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def lbfgs_exact(h, maxiter=2000, maxfun=4000):
        def obj(x):
            xc = np.clip(x, 0, None)
            R, g = _R_and_grad(xc)
            return -R, -g * (x > 0)
        try:
            res = minimize(obj, h, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            cand = np.clip(res.x, 0, None)
            if cand.sum() > 0:
                cand /= cand.max()
                return cand
        except Exception:
            pass
        return h

    def try_update(h):
        nonlocal best, bestR
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            return True
        return False

    # Exact polish of start.
    h = lbfgs_exact(best, 1500, 3000)
    try_update(h)

    mu_list = []
    m = 1.0
    while m < 1e13:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            if mu < 1e3:
                mi, mf = 400, 800
            elif mu < 1e8:
                mi, mf = 600, 1200
            else:
                mi, mf = 1000, 2000
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
        h = lbfgs_exact(h, 1500, 3000)
        cur = R_of(h)
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))

        # Coordinate polish on targeted set.
        if time.process_time() < deadline - 1.0:
            n = best.size
            Lf = _knots(best)
            center = int(np.argmax(Lf)) // 2
            S = set(int(i) for i in rng.integers(0, n, size=50))
            S.update(int(i) for i in np.argsort(best)[-50:])
            S.update(range(max(0, center - 30), min(n, center + 30)))
            hc = best.copy()
            cc = bestR
            for idx in S:
                if time.process_time() >= deadline - 0.8:
                    break
                old = hc[idx]
                hi_b = max(4.0 * old, 1.0)

                def neg_r(alpha, _i=idx):
                    hc[_i] = alpha
                    return -R_of(hc)

                try:
                    res = minimize_scalar(neg_r, bounds=(0.0, hi_b),
                                          method='bounded',
                                          options={'xatol': 1e-11})
                    cand = res.x
                    cand_r = -res.fun
                except Exception:
                    cand, cand_r = old, cc
                if cand_r > cc + 1e-15:
                    hc[idx] = cand
                    cc = cand_r
                else:
                    hc[idx] = old
            if cc > bestR + 1e-13:
                best, bestR = hc.copy(), cc
                print("coord R=%.6f (N=%d)" % (bestR, best.size))

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

