def _R_and_grad(h):
    """True R and its exact gradient (including argmax-knot derivative)."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    n = h.size
    if s <= 0:
        return 0.0, np.zeros(n)
    num, dq, s, Lf = _num_and_dq(h)
    s2 = s * s
    mx = Lf.max()
    if mx <= 0:
        return 0.0, np.zeros(n)
    R = (num / s2) / mx
    # d(num/s2)/dh
    g_num = _backprop(dq / s2, h)
    g_num += -2.0 * num / (s2 * s)
    # R = (num/s2)/mx  -> dR = (g_num * mx - (num/s2) * dmx)/mx^2
