    # dLf[k]/dh_i = 2*h_{k-1-i} for valid i
    dmx = np.zeros(n)
    j = k - 1
    lo = max(0, j - (n - 1))
    hi = min(n - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dmx[idx] = 2.0 * h[j - idx]
    grad = (g_num * mx - (num / s2) * dmx) / (mx * mx)
    return R, grad


