    return num, dq, Lf


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _lbfgs_pen(h0, mu, maxiter):
    # lightweight L-BFGS with bounds via projected gradient + line search
    h = h0.copy()
    n = h.size
    s = h.sum()
    if s <= 0:
        return _rescale(h)
    num, dq, Lf = _num_dq(h)
    s2 = s * s
    P, g = _pen(h, mu, s, s2, num, dq, Lf)
    m = 8
    S = []
    Y = []
    for _ in range(maxiter):
        # two-loop recursion
        q = g.copy()
        alphas = []
        for Sk, Yk in reversed(list(zip(S, Y))):
            rho = 1.0 / np.dot(Yk, Sk)
            a = rho * np.dot(Sk, q)
            alphas.append((a, rho, Sk, Yk))
            q -= a * Yk
        if S:
            gamma = np.dot(S[-1], Y[-1]) / np.dot(Y[-1], Y[-1])
        else:
            gamma = 0.01 / (np.abs(g).max() + 1e-30)
        r = gamma * q
        for a, rho, Sk, Yk in reversed(alphas):
            b = rho * np.dot(Yk, r)
            r += (a - b) * Sk
        d = -r
        # project: only allow descent on free (positive) coords
        d = np.where((h <= 0) & (d < 0), 0.0, d)
        gd = np.dot(g, d)
        if gd >= 0 or not np.isfinite(gd):
            d = -g * (1e-3 / (np.abs(g).max() + 1e-30))
            gd = np.dot(g, d)
            if gd >= 0:
                break
        # backtracking line search (Armijo)
        step = 1.0
        improved = False
        for _ls in range(30):
            h_new = np.clip(h + step * d, 0, None)
            if h_new.sum() <= 0:
                step *= 0.5
                continue
            s_n = h_new.sum(); s2_n = s_n * s_n
            num_n, dq_n, Lf_n = _num_dq(h_new)
            P_n, g_n = _pen(h_new, mu, s_n, s2_n, num_n, dq_n, Lf_n)
            if P_n <= P + 1e-4 * step * gd:
                improved = True
                break
            step *= 0.5
        if not improved:
            break
        sk = h_new - h
        yk = g_n - g
        sy = np.dot(sk, yk)
        if sy > 1e-12:
            S.append(sk); Y.append(yk)
            if len(S) > m:
                S.pop(0); Y.pop(0)
        h, g, P = h_new, g_n, P_n
        if np.abs(g).max() < 1e-14:
            break
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()
    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Geometric continuation of mu; heavier iterations at high mu.
    mu_list = []
    m = 1.0
    while m < 1e15:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def stage_iters(mu):
        if mu < 1e4:
            return 60
        if mu < 1e10:
            return 120
        return 250

    it = 0
    while time.process_time() < deadline - 0.8:
        it += 1
        h = _rescale(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 0.8:
                break
            h = _lbfgs_pen(h, mu, stage_iters(mu))
            r = R_of(h)
            if r > cur:
                cur = r
        if cur > bestR + 1e-14:
            best, bestR = h.copy(), cur
            print("iter%d R=%.7f" % (it, bestR))
        else:
            break

    # Final focused high-mu polish on the best.
    while time.process_time() < deadline - 0.4:
        h = _rescale(best.copy())
        cur = bestR
        for mu in [1e11, 3e11, 1e12, 3e12, 1e13, 3e13, 1e14]:
            if time.process_time() >= deadline - 0.4:
                break
            h = _lbfgs_pen(h, mu, 400)
            r = R_of(h)
            if r > cur:
                cur = r
        if cur > bestR + 1e-14:
            best, bestR = h.copy(), cur
            print("polish R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    if a.size * b.size > 4_000_000:
        return fftconvolve(a, b)
    return np.convolve(a, b)


def _knots(h):
    return np.concatenate(([0.0], _conv(h, h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    mx = L.max()
    den = s * s * mx
    if den <= 0:
        return 0.0
    return num / den


def _R_and_grad(h):
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    L = _conv(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    am = int(np.argmax(Lf))
    mx = Lf[am]
    den = s * s * mx
    if den <= 0:
        return 0.0, np.zeros(n)
    R = num / den
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    gLf = dq / den
    gLf[am] -= num * s * s / (den * den)
    gL = gLf[1:-1]
    grad = 2.0 * _conv(gL, h[::-1])[:n]
    grad += -num * 2.0 * s * mx / (den * den)
    return R, grad


def _refine(h, maxiter=100):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    if h.sum() <= 0 or h.max() <= 0:
        return h, R_of(h)
    h = h / h.max()

    def fun(x):
        r, g = _R_and_grad(x)
        return -r, -g

    try:
        res = minimize(fun, h, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * h.size,
                       options={'maxiter': maxiter, 'ftol': 1e-14, 'gtol': 1e-12})
        x = np.clip(res.x, 0, None)
        if x.sum() <= 0 or x.max() <= 0:
            return h, R_of(h)
        x = x / x.max()
        return x, R_of(x)
    except Exception:
        return h, R_of(h)


def _upsample(h, factor):
    n = h.size
    idx = np.arange(n * factor) // factor
    idx = np.clip(idx, 0, n - 1)
    return h[idx].astype(float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88
    rng = np.random.default_rng(20240)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(176)
    else:
        base = np.ones(176)
    base = base / base.max()

    best, bestR = _refine(base, maxiter=200)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Phase A: multi-scale upsample + refine; try several factors and pick best
    cur = best.copy()
    curR = bestR
    for fac in (2, 3, 4):
        if time.process_time() > deadline - 5:
            break
        if cur.size * fac > 200000:
            continue
        up = _upsample(cur, fac)
        up = up * rng.uniform(0.99, 1.01, up.size)
        up, upR = _refine(up, maxiter=150)
        if upR > curR + 1e-7:
            cur, curR = up, upR
            print("upsample x%d R=%.6f (N=%d)" % (fac, curR, cur.size))

    best, bestR = cur.copy(), curR

    # Phase B: coordinate polish using exact R
    def coord_polish(h, curR, phase_deadline, passes=2):
        n = h.size
        for _ in range(passes):
            if time.process_time() > phase_deadline:
                break
            improved = False
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() > phase_deadline:
                    break
                old = h[idx]
                # golden-section on (0, 2.5*max(old, small))
                hi = 2.5 * max(old, 1e-6)
                lo = 0.0
                gr = (np.sqrt(5) - 1) / 2
                c = hi - gr * (hi - lo)
                d = lo + gr * (hi - lo)
                h[idx] = c; fc = R_of(h)
                h[idx] = d; fd = R_of(h)
                for _ in range(18):
                    if fc > fd:
                        hi = d; d = c; fd = fc
                        c = hi - gr * (hi - lo); h[idx] = c; fc = R_of(h)
                    else:
                        lo = c; c = d; fc = fd
                        d = lo + gr * (hi - lo); h[idx] = d; fd = R_of(h)
                cand = d if fd > fc else c
                candR = max(fc, fd)
                if candR > curR + 1e-15:
                    h[idx] = cand; curR = candR; improved = True
                else:
                    h[idx] = old
            if not improved:
                break
        return h, curR

    cd = min(deadline, time.process_time() + budget_seconds * 0.18)
    cur, curR = coord_polish(cur, curR, cd, passes=2)
    if curR > bestR:
        best, bestR = cur.copy(), curR
        print("coord polish R=%.6f (N=%d)" % (bestR, best.size))

    # Phase C: anneal - proposals + refine + polish
    cur = best.copy(); curR = bestR
    n_try = 0; n_acc = 0
    total_time = max(deadline - t0, 1e-6)

    def propose(h):
        h = h.copy()
        n = h.size
        op = rng.integers(0, 5)
        if op == 0:
            w = max(2, n // 6)
            i = rng.integers(0, max(1, n - w + 1))
            h[i:i+w] *= np.exp(rng.normal(0, 0.06, min(w, n - i)))
        elif op == 1:
            if rng.random() < 0.5 and n < 1200:
                i = rng.integers(0, n)
                h = np.insert(h, i, h[i])
            elif n > 20:
                i = rng.integers(0, n)
                h = np.delete(h, i)
        elif op == 2:
            h *= np.exp(rng.normal(0, 0.015, n))
        elif op == 3:
            i = rng.integers(0, n)
            w = max(2, n // 25)
            j = min(n, i + w)
            h[i:j] += h.max() * rng.uniform(0.005, 0.06)
        else:
            # local shift
            s = int(rng.integers(-2, 3))
            if s != 0:
                h = np.roll(h, s)
        h = np.clip(h, 0, None)
        if h.sum() <= 0 or h.max() <= 0:
            return None
        return h / h.max()

    while time.process_time() < deadline - 0.5:
        n_try += 1
        now = time.process_time()
        frac = max(0.0, (deadline - now) / total_time)
        T = 2e-5 * frac * frac + 1e-9

        trial = propose(cur)
        if trial is None:
            continue
        tr = R_of(trial)
        d = tr - curR
        if not (d >= 0 or rng.random() < np.exp(d / T)):
            continue
        ph, pr = _refine(trial, maxiter=40)
        if pr > tr:
            trial, tr = ph, pr
        if tr > curR - 1e-4:
            pd = min(deadline - 0.4, time.process_time() + 0.12)
            trial, tr = coord_polish(trial, tr, pd, passes=1)
        if tr >= curR:
            cur, curR = trial, tr
            n_acc += 1
            if curR > bestR + 1e-7:
                best, bestR = cur.copy(), curR
                print("  R=%.6f (N=%d, tries=%d, acc=%d)" % (bestR, best.size, n_try, n_acc))

    # Final polish
    if time.process_time() < deadline:
        ph, pr = _refine(best, maxiter=400)
        if pr > bestR:
            best, bestR = ph, pr
    if time.process_time() < deadline:
        cd = min(deadline, time.process_time() + 0.6)
        ph, pr = coord_polish(best.copy(), bestR, cd, passes=2)
        if pr > bestR:
            best, bestR = ph, pr

    print("final R=%.6f (N=%d, tries=%d, acc=%d)" % (bestR, best.size, n_try, n_acc))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        grad += _backprop(2.0 * mu * r, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter, maxfun, ftol=1e-16, gtol=1e-12):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': ftol, 'gtol': gtol})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def make_direct(beta):
        def f(x):
            xc = np.clip(x, 0, None)
            s = xc.sum()
            if s <= 0:
                return 1e18, np.zeros(xc.size)
            num, dq, Lf = _num_and_dq(xc)
            if num <= 0:
                return 1e18, np.zeros(xc.size)
            M = Lf.max()
            z = beta * (Lf - M)
            e = np.exp(z)
            Z = e.sum()
            logM = M + np.log(Z) / beta
            P = -np.log(num) + 2.0 * np.log(s) + logM
            gLf = -dq / num
            w = e / Z
            gLf = gLf + w
            grad = _backprop(gLf, xc)
            grad += 2.0 / s
            return P, grad * (x > 0)
        return f

    def run_direct(h0, beta, maxiter, maxfun, ftol=1e-18, gtol=1e-14):
        try:
            res = minimize(make_direct(beta), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': ftol, 'gtol': gtol})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def stage_budget(mu):
        if mu < 1e3:
            return 200, 400
        if mu < 1e8:
            return 400, 800
        return 1000, 2000

    best = _rescale_maxL(best)
    bestR = R_of(best)

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            mi, mf = stage_budget(mu)
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        else:
            break

    # --- Beta ladder polishing phase ---
    beta_ladder = [50.0, 150.0, 500.0, 1500.0, 5000.0, 20000.0]
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        ladder_start_R = bestR
        for b in beta_ladder:
            if time.process_time() >= deadline - 1.0:
                break
            if b <= 500.0:
                ftol, gtol = 1e-18, 1e-14
            else:
                ftol, gtol = 1e-19, 1e-15
            h = run_direct(h, b, 400, 800, ftol=ftol, gtol=gtol)
            r = R_of(h)
            if r > bestR + 1e-14:
                best, bestR = h.copy(), r
                print("direct%d b=%.0f R=%.7f" % (it, b, bestR))
        if bestR - ladder_start_R < 1e-10:
            break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

