            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-16, 'gtol': 1e-12})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def schedule(h, mus, mi, mf):
        h = _rescale_maxL(h.copy())
        cur = R_of(h)
        out = h
        for mu in mus:
            if time.process_time() >= deadline - 0.5:
                break
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
                out = h.copy()
        return out, cur

    best = _rescale_maxL(best)
    bestR = R_of(best)

    # Stage A: refine at current resolution. Push mu hard.
    h, cur = schedule(best, mu_list, 600, 1200)
    if cur > bestR:
        best, bestR = h, cur
        print("A refine R=%.6f (N=%d)" % (bestR, best.size))

    # Stage B: one resolution bump to N*2, refine hard.
    if time.process_time() < deadline - 3.0 and best.size < 100000:
        up = _upsample_interp(best, 2)
        h, cur = schedule(up, mu_list[6:], 600, 1200)
        if cur > bestR:
            best, bestR = h, cur
            print("B up2 R=%.6f (N=%d)" % (bestR, best.size))

    # Stage C: another bump if budget allows, mostly high-mu tail.
    if time.process_time() < deadline - 3.0 and best.size < 100000:
        up = _upsample_interp(best, 2)
        h, cur = schedule(up, mu_list[12:], 400, 800)
        if cur > bestR:
            best, bestR = h, cur
            print("C up2 R=%.6f (N=%d)" % (bestR, best.size))

    # Stage D: repeat high-mu refinement at current best resolution.
    while time.process_time() < deadline - 1.0:
        h, cur = schedule(best, mu_list[10:], 500, 1000)
        if cur > bestR + 1e-13:
            best, bestR = h, cur
            print("D refine R=%.6f (N=%d)" % (bestR, best.size))
        else:
            # small coordinate-free L-BFGS on exact R via penalty already done;
            # try a mild resolution bump
            if best.size < 100000 and time.process_time() < deadline - 3.0:
                up = _upsample_interp(best, 2)
                h, cur = schedule(up, mu_list[14:], 400, 800)
                if cur > bestR:
                    best, bestR = h, cur
                    print("D up2 R=%.6f (N=%d)" % (bestR, best.size))
                    continue
            break

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        grad += _backprop(2.0 * mu * r, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


# ---- Direct-R polish via logsumexp soft-max of L (from p0163) ----

def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    # logsumexp over Lf (including endpoints, which are 0)
    mx = Lf.max()
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z  # softmax weights
    # objective: -log(num) + 2 log(s) + logM
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    # grad wrt Lf: -dq/num + w
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.5:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter, maxfun, ftol=1e-16, gtol=1e-12):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': ftol, 'gtol': gtol})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def direct_polish(h, cur):
        # beta=200 then beta=1000, accept only if R improves
        if time.process_time() < deadline - 1.5:
            h2 = run_direct(h, 200, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-13:
                h, cur = h2, r2
        if time.process_time() < deadline - 1.5:
            h3 = run_direct(h, 1000, 400, 800, deadline)
            r3 = R_of(h3)
            if r3 > cur + 1e-13:
                h, cur = h3, r3
        return h, cur

    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def stage_budget(mu):
        if mu < 1e3:
            return 300, 600
        if mu < 1e8:
            return 500, 1000
        return 1200, 2400

    polish_list = [1e9, 3e9, 1e10, 3e10, 1e11, 3e11, 1e12,
                   1e13, 3e13, 1e14]

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            mi, mf = stage_budget(mu)
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
        # After a full improving mu pass, run direct polish to feed levers
        if cur > bestR + 1e-13:
            h, cur = direct_polish(h, cur)
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        else:
            polished_any = False
            while time.process_time() < deadline - 1.0:
                h2 = _rescale_maxL(best.copy())
                cur2 = bestR
                for mu in polish_list:
                    if time.process_time() > deadline - 1.5:
                        break
                    if mu >= 1e13:
                        h2 = run_pen(h2, mu, 2000, 4000,
                                     ftol=1e-20, gtol=1e-16)
                    else:
                        h2 = run_pen(h2, mu, 1500, 3000,
                                     ftol=1e-18, gtol=1e-14)
                    r = R_of(h2)
                    if r > cur2:
                        cur2 = r
                # After polish_list completes, run direct polish
                h2, cur2 = direct_polish(h2, cur2)
                gain = cur2 - bestR
                if cur2 > bestR + 1e-13:
                    best, bestR = h2.copy(), cur2
                    polished_any = True
                    print("polish R=%.6f (N=%d)" % (bestR, best.size))
                if gain < 1e-9:
                    break
            if polished_any:
                continue
            rng = np.random.default_rng(it)
            h2 = best.copy()
            nz = h2 > 1e-9 * h2.max()
            h2[nz] *= (1.0 + 2e-4 * rng.standard_normal(nz.sum()))
            h2 = _rescale_maxL(np.clip(h2, 0, None))
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
                print("perturb%d R=%.6f (N=%d)" % (it, bestR, best.size))
            else:
                break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

