            num, dq, Lf = _num_and_dq(xc)
            s2 = s * s
            P = -num / s2
            gLf = -dq / s2
            grad = _backprop(gLf, xc)
            grad += 2.0 * num / (s2 * s)
            r = np.maximum(Lf - 1.0, 0.0)
            if np.any(r > 0):
                P += mu * np.sum(r * r)
                grad += _backprop(2.0 * mu * r, xc)
            return P, grad * (x > 0)
