    def beta_pass(h, cur):
        for b in beta_ladder:
            if time.process_time() >= deadline - 0.8:
                return h, cur
            h = run_direct(h, b, 600, 1200)
            r = R_of(h)
            if r > cur:
                cur = r
        return h, cur

    best, bestR = beta_pass(best, bestR)
    if bestR > R_of(base):
        print("beta R=%.6f (N=%d)" % (bestR, best.size))

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        h, cur = refine_pass(h, cur)
        h, cur = beta_pass(h, cur)
        if cur > bestR + 1e-14:
            best, bestR = h.copy(), cur
            print("it%d R=%.6f (N=%d)" % (it, bestR, best.size))

        # Try upsampling to finer grid
        if best.size < 100000 and time.process_time() < deadline - 4.0:
            up = _upsample_lin(best, 2)
            hu = _rescale_maxL(up)
            cu = R_of(hu)
