                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': ftol, 'gtol': gtol})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # ---- experiment: ZOH doubling to fine grid, focused polish ----
    if base.size == 42496:
        h2 = np.repeat(base, 2)
        r2 = R_of(h2)
        print("double R=%.6f (N=%d)" % (r2, h2.size))
        fine = h2.copy()
        fineR = r2

        for mu in [1e11, 1e12, 1e13]:
            if time.process_time() >= deadline - 2.0:
                break
            fine = run_pen(fine, mu, 300, 600, ftol=1e-18, gtol=1e-14)
            rr = R_of(fine)
            if rr > fineR + 1e-13:
                fineR = rr
                print("fine pen mu=%.0e R=%.6f" % (mu, fineR))

        for beta, mi, mf in [(200, 400, 800), (1000, 300, 600),
                             (3000, 200, 400)]:
            if time.process_time() >= deadline - 2.0:
                break
            h3 = run_direct(fine, beta, mi, mf, deadline)
            rr = R_of(h3)
            if rr > fineR + 1e-13:
                fine, fineR = h3, rr
                print("fine direct beta=%d R=%.6f" % (beta, fineR))

        if fineR > bestR + 1e-13:
            best, bestR = fine.copy(), fineR
            print("fine accepted R=%.6f (N=%d)" % (bestR, best.size))
        else:
            print("fine no gain R=%.6f" % fineR)
        print("final R=%.6f (N=%d)" % (bestR, best.size))
        return best

    # ---- original path for other sizes ----
    def direct_polish(h, cur):
        if time.process_time() < deadline - 1.5:
            h2 = run_direct(h, 200, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-13:
                h, cur = h2, r2
        if time.process_time() < deadline - 1.5:
            h3 = run_direct(h, 1000, 400, 800, deadline)
            r3 = R_of(h3)
            if r3 > cur + 1e-13:
                h, cur = h3, r3
        return h, cur

    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def stage_budget(mu):
        if mu < 1e3:
            return 300, 600
        if mu < 1e8:
            return 500, 1000
        return 1200, 2400

    polish_list = [1e9, 3e9, 1e10, 3e10, 1e11, 3e11, 1e12,
                   1e13, 3e13, 1e14]

    act_mu_list = [1e10, 1e11, 1e12, 1e13]

    def activation_trial(rng):
        h = best
        mx = h.max()
        if mx <= 0:
            return None
        thr = 1e-9 * mx
        zero_idx = np.flatnonzero(h < thr)
        nz_mask = h > thr
        if zero_idx.size == 0 or not np.any(nz_mask):
            return None
        k = min(400, zero_idx.size)
        idx = rng.choice(zero_idx, size=k, replace=False)
        mval = float(h[nz_mask].mean())
        vals = mval * rng.uniform(0.05, 0.5, size=k)
        h2 = h.copy()
        h2[idx] = vals
        h2 = _rescale_maxL(np.clip(h2, 0, None))
        for mu in act_mu_list:
            if time.process_time() >= deadline - 1.5:
                break
            h2 = run_pen(h2, mu, 150, 300, ftol=1e-18, gtol=1e-14)
        if time.process_time() < deadline - 1.5:
            h2 = run_direct(h2, 200, 200, 400, deadline)
        if time.process_time() < deadline - 1.5:
            h2 = run_direct(h2, 1000, 200, 400, deadline)
        return h2

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            mi, mf = stage_budget(mu)
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
        if cur > bestR + 1e-13:
            h, cur = direct_polish(h, cur)
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        else:
            polished_any = False
            while time.process_time() < deadline - 1.0:
                h2 = _rescale_maxL(best.copy())
                cur2 = bestR
                for mu in polish_list:
                    if time.process_time() > deadline - 1.5:
                        break
                    if mu >= 1e13:
                        h2 = run_pen(h2, mu, 2000, 4000,
                                     ftol=1e-20, gtol=1e-16)
                    else:
                        h2 = run_pen(h2, mu, 1500, 3000,
                                     ftol=1e-18, gtol=1e-14)
                    r = R_of(h2)
                    if r > cur2:
                        cur2 = r
                h2, cur2 = direct_polish(h2, cur2)
                gain = cur2 - bestR
                if cur2 > bestR + 1e-13:
                    best, bestR = h2.copy(), cur2
                    polished_any = True
                    print("polish R=%.6f (N=%d)" % (bestR, best.size))
                if gain < 1e-9:
                    break
            if polished_any:
                continue

            rng = np.random.default_rng(it)
            accepted = False
            rejects = 0
            while (not accepted and rejects < 3
                   and time.process_time() < deadline - 1.5):
                h2 = activation_trial(rng)
                if h2 is None:
                    break
                r2 = R_of(h2)
                if r2 > bestR + 1e-13:
                    best, bestR = h2, r2
                    print("activate%d R=%.6f (N=%d)" % (it, bestR, best.size))
                    accepted = True
                else:
                    rejects += 1
            if accepted:
                continue

            h2 = best.copy()
            nz = h2 > 1e-9 * h2.max()
            if np.any(nz):
                h2[nz] *= (1.0 + 2e-4 * rng.standard_normal(nz.sum()))
            h2 = _rescale_maxL(np.clip(h2, 0, None))
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
                print("perturb%d R=%.6f (N=%d)" % (it, bestR, best.size))
            else:
                break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _penalty_and_grad(h, mu):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    s2 = s * s
    P = -num / s2
    gLf = -dq / s2
    grad = _backprop(gLf, h)
    grad += 2.0 * num / (s2 * s)
    r = np.maximum(Lf - 1.0, 0.0)
    if np.any(r > 0):
        P += mu * np.sum(r * r)
        grad += _backprop(2.0 * mu * r, h)
    return P, grad


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter, maxfun, ftol=1e-16, gtol=1e-12):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': ftol, 'gtol': gtol})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def run_direct(h0, beta, maxiter, maxfun):
        if time.process_time() >= deadline - 1.5:
            return h0
        def f(x):
            xc = np.clip(x, 0, None)
            o, g = _direct_obj_grad(xc, beta)
            return o, g * (x > 0)
        try:
            res = minimize(f, h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-17, 'gtol': 1e-13})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def stage_budget(mu):
        if mu < 1e3:
            return 300, 600
        if mu < 1e8:
            return 500, 1000
        return 1200, 2400

    polish_list = [1e9, 3e9, 1e10, 3e10, 1e11, 3e11, 1e12,
                   1e13, 3e13, 1e14]

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        for mu in mu_list:
            if time.process_time() >= deadline - 1.0:
                break
            mi, mf = stage_budget(mu)
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
        # direct soft-max polish
        if time.process_time() < deadline - 1.5:
            h = run_direct(h, 200, 600, 1200)
            r = R_of(h)
            if r > cur:
                cur = r
        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))

        # extended high-mu polish + direct polish loop
        while time.process_time() < deadline - 1.0:
            h2 = _rescale_maxL(best.copy())
            cur2 = bestR
            for mu in polish_list:
                if time.process_time() > deadline - 1.5:
                    break
                if mu >= 1e13:
                    h2 = run_pen(h2, mu, 2000, 4000,
                                 ftol=1e-20, gtol=1e-16)
                else:
                    h2 = run_pen(h2, mu, 1500, 3000,
                                 ftol=1e-18, gtol=1e-14)
                r = R_of(h2)
                if r > cur2:
                    cur2 = r
            if time.process_time() < deadline - 1.5:
                h2 = run_direct(h2, 1000, 400, 800)
                r = R_of(h2)
                if r > cur2:
                    cur2 = r
            if time.process_time() < deadline - 1.5:
                h2 = run_direct(h2, 5000, 300, 600)
                r = R_of(h2)
                if r > cur2:
                    cur2 = r
            gain = cur2 - bestR
            if cur2 > bestR + 1e-13:
                best, bestR = h2.copy(), cur2
                print("polish R=%.6f (N=%d)" % (bestR, best.size))
            if gain < 1e-10:
                break

        # perturb restart
        rng = np.random.default_rng(it)
        h2 = best.copy()
        nz = h2 > 1e-9 * h2.max()
        h2[nz] *= (1.0 + 2e-4 * rng.standard_normal(nz.sum()))
        h2 = _rescale_maxL(np.clip(h2, 0, None))
        r2 = R_of(h2)
        if r2 > bestR + 1e-13:
            best, bestR = h2, r2
            print("perturb%d R=%.6f (N=%d)" % (it, bestR, best.size))
        else:
            # try zero-activation to escape plateau
            h3 = best.copy()
            mx = h3.max()
            thr = 1e-9 * mx
            zero_idx = np.flatnonzero(h3 < thr)
            if zero_idx.size:
                k = min(400, zero_idx.size)
                idx = rng.choice(zero_idx, size=k, replace=False)
                h3[idx] = 1e-3 * mx * rng.random(k)
                h3 = _rescale_maxL(h3)
                r3 = R_of(h3)
                if r3 > bestR + 1e-13:
                    best, bestR = h3, r3
                    print("activate%d R=%.6f (N=%d)" % (it, bestR, best.size))
                else:
                    break
            else:
                break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * Lf.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _upsample_lin(h, f):
    h = np.asarray(h, dtype=float)
    n = h.size
    ext = np.concatenate(([h[0]], h, [h[-1]]))
    out = np.empty(n * f)
    i = np.arange(n)
    for k in range(f):
        t = (k + 0.5) / f
        out[k::f] = (1 - t) * ext[i] + t * ext[i + 1]
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.87

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            s = xc.sum()
            if s <= 0:
                return 1e18, np.zeros(xc.size)
            num, dq, Lf = _num_and_dq(xc)
            s2 = s * s
            P = -num / s2
            gLf = -dq / s2
            grad = _backprop(gLf, xc)
            grad += 2.0 * num / (s2 * s)
            r = np.maximum(Lf - 1.0, 0.0)
            if np.any(r > 0):
                P += mu * np.sum(r * r)
                grad += _backprop(2.0 * mu * r, xc)
            return P, grad * (x > 0)
        return f

    def run_pen(h0, mu, maxiter, maxfun):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-17, 'gtol': 1e-13})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def make_direct(beta):
        def f(x):
            xc = np.clip(x, 0, None)
            s = xc.sum()
            if s <= 0:
                return 1e18, np.zeros(xc.size)
            num, dq, Lf = _num_and_dq(xc)
            if num <= 0:
                return 1e18, np.zeros(xc.size)
            M = Lf.max()
            z = beta * (Lf - M)
            e = np.exp(z)
            Z = e.sum()
            logM = M + np.log(Z) / beta
            P = -np.log(num) + 2.0 * np.log(s) + logM
            gLf = -dq / num + e / Z
            grad = _backprop(gLf, xc)
            grad += 2.0 / s
            return P, grad * (x > 0)
        return f

    def run_direct(h0, beta, maxiter, maxfun):
        try:
            res = minimize(make_direct(beta), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-18, 'gtol': 1e-14})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    mu_list = [1e0, 3e0, 1e1, 3e1, 1e2, 3e2, 1e3, 3e3, 1e4, 3e4,
               1e5, 3e5, 1e6, 3e6, 1e7, 3e7, 1e8, 3e8, 1e9, 3e9,
               1e10, 3e10, 1e11, 3e11, 1e12]

    def stage_budget(mu):
        if mu < 1e4:
            return 150, 300
        if mu < 1e8:
            return 400, 800
        return 800, 1600

    def refine_pass(h, cur):
        for mu in mu_list:
            if time.process_time() >= deadline - 0.8:
                return h, cur
            mi, mf = stage_budget(mu)
            h = run_pen(h, mu, mi, mf)
            r = R_of(h)
            if r > cur:
                cur = r
        return h, cur

    best = _rescale_maxL(best)
    best, bestR = refine_pass(best, bestR)
    if bestR > R_of(base):
        print("polish R=%.6f (N=%d)" % (bestR, best.size))

    beta_ladder = [100.0, 500.0, 2000.0, 8000.0, 30000.0, 1e5, 3e5]

    def beta_pass(h, cur):
        for b in beta_ladder:
            if time.process_time() >= deadline - 0.8:
                return h, cur
            h = run_direct(h, b, 600, 1200)
            r = R_of(h)
            if r > cur:
                cur = r
        return h, cur

    best, bestR = beta_pass(best, bestR)
    if bestR > R_of(base):
        print("beta R=%.6f (N=%d)" % (bestR, best.size))

    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        h = _rescale_maxL(best.copy())
        cur = bestR
        h, cur = refine_pass(h, cur)
        h, cur = beta_pass(h, cur)
        if cur > bestR + 1e-14:
            best, bestR = h.copy(), cur
            print("it%d R=%.6f (N=%d)" % (it, bestR, best.size))

        if best.size < 100000 and time.process_time() < deadline - 4.0:
            up = _upsample_lin(best, 2)
            hu = _rescale_maxL(up)
            cu = R_of(hu)
            hu, cu = refine_pass(hu, cu)
            hu, cu = beta_pass(hu, cu)
            if cu > bestR + 1e-14:
                best, bestR = hu.copy(), cu
                print("it%d up2 R=%.6f (N=%d)" % (it, bestR, best.size))

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

