    return f


def run_pen(h0, mu, maxiter, maxfun, ftol=1e-16, gtol=1e-12):
    try:
        res = minimize(_make_pen(mu), h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': ftol, 'gtol': gtol})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _upsample_zoh(h, factor):
    return np.repeat(h, factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # ---- Strategy: upsample to a finer grid via zero-order-hold doubling,
    # then polish on the finer grid. Since R is invariant to the number of
    # steps for a ZOH'd function, this gives extra degrees of freedom to
    # smooth the autoconvolution near its maximum and lift R. ----

    def polish(h, cur, tag=""):
        # penalty continuation on the current grid
        for mu in [1e10, 1e11, 1e12, 1e13]:
            if time.process_time() >= deadline - 2.5:
                break
            h = run_pen(h, mu, 800, 1600, ftol=1e-18, gtol=1e-14)
            r = R_of(h)
            if r > cur + 1e-13:
                cur = r
        # direct soft-max polish
        for beta, mi, mf in [(200, 500, 1000), (1000, 400, 800),
                             (4000, 300, 600)]:
            if time.process_time() >= deadline - 1.5:
                break
            h2 = run_direct(h, beta, mi, mf, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-13:
                h, cur = h2, r2
        if tag:
            print("%s R=%.6f (N=%d)" % (tag, cur, h.size))
        return h, cur

    # First polish at original resolution
    h, r = polish(best.copy(), bestR, "coarse")
    if r > bestR + 1e-13:
        best, bestR = h, r

    # Now try progressively finer grids, keeping the best that improves.
    for factor in [2, 3, 4]:
        if time.process_time() >= deadline - 3.0:
            break
        if best.size * factor > 200000:
            break
        hf = _upsample_zoh(best, factor)
        rf = R_of(hf)
        print("upsample x%d R=%.6f (N=%d)" % (factor, rf, hf.size))
        hf, rf = polish(hf, rf, "fine x%d" % factor)
        if rf > bestR + 1e-13:
            # Keep fine version if it genuinely improves
            best, bestR = hf, rf
            print("accepted x%d R=%.6f (N=%d)" % (factor, bestR, best.size))
        else:
            # try to map back: merge pairs back to coarse if fine didn't help
            print("rejected x%d (R=%.6f)" % (factor, rf))

    # Final aggressive polish on best
    while time.process_time() < deadline - 1.5:
        before = bestR
        h = best.copy()
        for mu in [3e11, 1e12, 3e12, 1e13, 3e13]:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_pen(h, mu, 1500, 3000, ftol=1e-20, gtol=1e-16)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
        for beta in [1000, 3000, 8000]:
            if time.process_time() >= deadline - 1.5:
                break
            h2 = run_direct(h, beta, 300, 600, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
        if bestR - before < 1e-9:
            break
        print("polish R=%.6f (N=%d)" % (bestR, best.size))

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

