def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    def make_pen(mu):
        def f(x):
            xc = np.clip(x, 0, None)
            P, g = _penalty_and_grad(xc, mu)
            return P, g * (x > 0)
        return f

    def run_pen(h0, mu, maxiter, maxfun, ftol=1e-16, gtol=1e-12):
        try:
            res = minimize(make_pen(mu), h0, jac=True, method='L-BFGS-B',
                           bounds=[(0, None)] * h0.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': ftol, 'gtol': gtol})
            return _rescale_maxL(res.x)
        except Exception:
            return h0

    def direct_polish(h, cur):
        if time.process_time() < deadline - 1.5:
            h2 = run_direct(h, 200, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-13:
                h, cur = h2, r2
        if time.process_time() < deadline - 1.5:
            h3 = run_direct(h, 1000, 400, 800, deadline)
            r3 = R_of(h3)
            if r3 > cur + 1e-13:
                h, cur = h3, r3
        return h, cur

    mu_list = []
    m = 1.0
    while m < 3e12:
        mu_list.append(m)
        mu_list.append(3.0 * m)
        m *= 10.0

    def stage_budget(mu):
        if mu < 1e3:
            return 300, 600
        if mu < 1e8:
            return 500, 1000
        return 1200, 2400

    polish_list = [1e9, 3e9, 1e10, 3e10, 1e11, 3e11, 1e12,
                   1e13, 3e13, 1e14]

    # ---- Multigrid V-cycle with decimation coarsening ----
    def vcycle(best, bestR):
        n = best.size
        if n < 4:
            return best, bestR, 0.0
        # (a) coarsen by decimation: take every other sample
        h_c = best[::2].copy()
        if h_c.size < 2 or h_c.sum() <= 0:
            return best, bestR, 0.0
        h_c = _rescale_maxL(h_c)
        # (b) coarse optimize
        for mu in (1e9, 1e11, 1e13):
            if time.process_time() >= deadline - 1.5:
                return best, bestR, 0.0
            h_c = run_pen(h_c, mu, 250, 500, ftol=1e-18, gtol=1e-14)
        # (c) prolong back to length n by linear interpolation
        xp = np.arange(0, n, 2, dtype=float)
        x = np.arange(n, dtype=float)
        h_u = np.interp(x, xp, h_c)
        h_u = _rescale_maxL(h_u)
        # (d) fine polish
        for mu in (1e10, 1e12, 1e14):
            if time.process_time() >= deadline - 1.5:
                break
            h_u = run_pen(h_u, mu, 150, 300)
        if time.process_time() < deadline - 1.5:
            h_u = run_direct(h_u, 200, 200, 400, deadline)
        if time.process_time() < deadline - 1.5:
            h_u = run_direct(h_u, 1000, 200, 400, deadline)
        r_u = R_of(h_u)
        # (e) accept
        if r_u > bestR + 1e-13:
