    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # (1) short warm-up with LSE
    if time.process_time() < deadline - 2.0:
        h = run_direct(best, 1000, 200, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h.copy(), r
            print("warmup R=%.7f" % bestR)

    # (2) Cyclic exact-objective L-BFGS with shrinking active set
    rng = np.random.default_rng(12345)
    for it in range(60):
        if time.process_time() >= deadline - 1.0:
            break
        h = np.clip(best, 0, None)
        if h.sum() <= 0:
            break
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
        if active.size == 0:
            break
        n = h.size
        u0 = np.log(np.clip(h[active], 1e-300, None))

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val = _norm_eq_fun(hh)
            g = _norm_eq_grad(hh)[active] * hh[active]
            return val, g

        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           options={'maxiter': 400, 'maxfun': 800,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            h2 = _rescale_maxL(h2)
        except Exception:
            h2 = h
        r2 = R_of(h2)
        if r2 > bestR + 1e-14:
            best, bestR = h2.copy(), r2
        else:
            zeros = np.flatnonzero(h <= thresh)
            if zeros.size > 0:
                k = min(30, zeros.size)
                idx = rng.choice(zeros, size=k, replace=False)
                h3 = h.copy()
                mval = float(h[active].mean()) if active.size else 1.0
                h3[idx] = mval * rng.uniform(0.01, 0.3, size=k)
                h3 = _rescale_maxL(h3)
                h3 = run_direct(h3, 1000, 100, 200, deadline)
                r3 = R_of(h3)
                if r3 > bestR + 1e-14:
                    best, bestR = h3.copy(), r3
                elif it > 5:
                    break

    # (3) final polish with increasing LSE beta
    for beta in [2000, 5000, 20000, 100000]:
        if time.process_time() >= deadline - 0.5:
            break
        h = run_direct(best, beta, 300, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # (4) EXPERIMENT: top-k average max ladder
    for k in [2000, 1000, 500, 200, 100]:
        if time.process_time() >= deadline - 0.5:
            break
        h = run_topk(best, k, 300, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("topk k=%d R=%.7f" % (k, bestR))

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

