    if time.process_time() < deadline - 1.0:
        h = run_exact(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("exact A R=%.7f" % bestR)

    for rnd in range(3):
        if time.process_time() > deadline - 2.0:
            break
        h = _local_refine(best, nsplit=3000)
        h = run_exact(h, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("refine%d R=%.7f (N=%d)" % (rnd, bestR, best.size))

    betas = [50, 200, 800, 3000, 12000]
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        beta = betas[min(it - 1, len(betas) - 1)]
        h = run_direct(best, beta, 400, 800, deadline)
        h = run_exact(h, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("direct%d R=%.7f (N=%d)" % (it, bestR, best.size))
        if best.size < 150000 and time.process_time() < deadline - 3.0:
            h = _local_refine(best, nsplit=2000)
            h = run_exact(h, 400, 800, deadline)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                print("refine-loop R=%.7f (N=%d)" % (bestR, best.size))

    best = best / best.max()
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

