def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _zoh_double(h):
    return np.repeat(h, 2)


def _block_avg(h, k):
    n = h.size
    m = n // k
    if m * k != n:
        h = h[:m * k]
    return h.reshape(m, k).mean(axis=1)


def _targeted_split(h, deadline, n_near=400, n_tall=800):
    """Split cells near argmax(Lf)/2 and the tallest cells, then polish."""
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    target = m / 2.0
    idx_near = np.argsort(np.abs(np.arange(n) - target))[:n_near]
    idx_tall = np.argsort(-h)[:min(n_tall, n)]
    split_set = np.unique(np.concatenate([idx_near, idx_tall]))
    split_set = split_set[(split_set >= 0) & (split_set < n)]

    h2 = np.repeat(h, 2)
    free = np.concatenate([2 * split_set, 2 * split_set + 1])
    free = np.unique(free)
    h2 = _rescale_maxL(h2)
    h3 = _exact_lbfgs(h2, 500, 1000, deadline, free=free)
    if R_of(h3) > R_of(h2) + 1e-16:
        return h3
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    N0 = base.size

    # NEW KEY IDEA: instead of relying on global LSE ladder, directly attack
    # the exact (max-knot) objective with targeted cell splitting.  This lets
    # the grid grow only where it helps (near argmax(Lf)/2 and tall cells),
    # which is where the true optimum needs resolution.

    # First, a couple of exact-LBFGS polishes at the given resolution.
    for _ in range(2):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("exact R=%.7f (N=%d)" % (bestR, best.size))
        else:
            break

    # Now iterate targeted splits; each split refines the grid near the
    # active zone, growing N gradually, always re-polishing exactly.
    # Cap total N to stay within limits and FFT cost.
    max_N = 200000
    while time.process_time() < deadline - 2.0 and best.size < max_N:
        h = _targeted_split(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("split R=%.7f (N=%d)" % (bestR, best.size))
        else:
            # try a broader split once more before giving up
            h = _targeted_split(best, deadline, n_near=800, n_tall=1600)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
                print("split2 R=%.7f (N=%d)" % (bestR, best.size))
            else:
                break

    # Final LSE ladder on whatever grid we've reached, tapering betas.
    for beta in [5000, 20000, 80000, 300000]:
        if time.process_time() >= deadline - 0.5:
            break
        h = run_direct(best, beta, 300, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("lse beta=%d R=%.7f" % (beta, bestR))

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("final exact R=%.7f" % bestR)

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _num_and_dq(h):
    Lf = np.concatenate(([0.0], _conv(h), [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    Lf = np.concatenate(([0.0], _conv(h), [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * Lf.max()
    if den <= 0:
        return 0.0
    return num / den


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    s = h.sum()
    if s <= 0:
        return h
    mx = _conv(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _exact_obj_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return obj, grad


def run_exact(h0, maxiter, maxfun, deadline, logspace=False):
    if time.process_time() >= deadline - 0.6:
        return h0
    h0 = np.clip(h0, 0, None)
    if logspace:
        thresh = 1e-12 * h0.max()
        active = np.flatnonzero(h0 > thresh)
        if active.size == 0:
            return h0
        n = h0.size
        u0 = np.log(np.clip(h0[active], 1e-300, None))
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            o, g = _exact_obj_grad(hh)
            return o, g[active] * hh[active]
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale(h2)
        except Exception:
            return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _exact_obj_grad(xc)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-18, 'gtol': 1e-14})
        return _rescale(res.x)
    except Exception:
        return h0


def _smooth_obj_grad(h, eps):
    """Smooth max via p-norm-ish: logsumexp with small beta near max only."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    # softmax weighting to include near-max knots -> smoother gradient
    beta = 1.0 / (eps * mx + 1e-300)
    e = np.exp(np.clip(beta * (Lf - mx), -60, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h) + 2.0 / s
    return obj, grad


def run_smooth(h0, eps, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.6:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _smooth_obj_grad(xc, eps)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-18, 'gtol': 1e-14})
        return _rescale(res.x)
    except Exception:
        return h0


def _split_near_max(h, nsplit=2000):
    n = h.size
    if n < 4 or n >= 199000:
        return h.copy()
    nsplit = min(nsplit, 199000 - n)
    if nsplit <= 0:
        return h.copy()
    _, _, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    score = h.copy()
    lo = max(0, m - 400); hi = min(n, m + 400)
    score[lo:hi] *= 3.0
    idx = np.argpartition(-score, nsplit - 1)[:nsplit]
    sel = np.zeros(n, dtype=bool)
    sel[idx] = True
    new_n = n + int(sel.sum())
    h2 = np.empty(new_n, dtype=float)
    pos = 0
    for i in range(n):
        if sel[i]:
            h2[pos] = h[i]; h2[pos + 1] = h[i]
            pos += 2
        else:
            h2[pos] = h[i]
            pos += 1
    return h2


def _merge(h, k=2):
    """Block-average by k, keeping non-negative."""
    n = h.size
    m = n // k
    if m < 4:
        return h.copy()
    hh = h[:m * k].reshape(m, k).mean(axis=1)
    return hh


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale(base)
    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # 1) log-space exact refine (handles zeros gracefully)
    h = run_exact(best, 600, 1200, deadline, logspace=True)
    r = R_of(h)
    if r > bestR + 1e-13:
        best, bestR = h.copy(), r
        print("logspace R=%.7f" % bestR)

    # 2) split near max then re-optimize
    for rnd in range(2):
        if time.process_time() > deadline - 3.0:
            break
        h = _split_near_max(best, nsplit=2000)
        h = run_exact(h, 500, 1000, deadline, logspace=False)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("split%d R=%.7f (N=%d)" % (rnd, bestR, best.size))

    # 3) smoothing homotopy: eps -> 0
    eps_list = [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5]
    for eps in eps_list:
        if time.process_time() > deadline - 1.5:
            break
        h = run_smooth(best, eps, 400, 800, deadline)
        h = run_exact(h, 400, 800, deadline, logspace=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("eps=%.0e R=%.7f" % (eps, bestR))

    # 4) alternating split + exact as long as time allows
    while time.process_time() < deadline - 1.5:
        h = _split_near_max(best, nsplit=1500)
        h = run_exact(h, 500, 1000, deadline, logspace=True)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("loop R=%.7f (N=%d)" % (bestR, best.size))
        else:
            # try merge for a different basin
            if best.size > 8000:
                hm = _merge(best, 2)
                hm = run_exact(hm, 400, 800, deadline, logspace=True)
                rm = R_of(hm)
                if rm > bestR + 1e-13:
                    best, bestR = hm.copy(), rm
                    print("merge R=%.7f (N=%d)" % (bestR, best.size))
                    continue
            # small perturbation restart
            h = best * (1.0 + 0.02 * np.random.randn(best.size))
            h = np.clip(h, 0, None)
            h = run_exact(h, 400, 800, deadline, logspace=True)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                print("perturb R=%.7f" % bestR)

    best = best / best.max()
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _zoh_double(h):
    return np.repeat(h, 2)


def _block_avg(h, k):
    n = h.size
    m = n // k
    if m * k != n:
        h = h[:m * k]
    return h.reshape(m, k).mean(axis=1)


def _refine_subcell(h, deadline, rounds=1):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    h2 = np.repeat(h, 2) * 0.5
    best = h2.copy()
    bestR = R_of(best)
    for frac in [0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65]:
        cand = np.empty(2 * n)
        cand[0::2] = h * frac
        cand[1::2] = h * (1.0 - frac)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand
            bestR = r
    if bestR > R_of(h) + 1e-15:
        h3 = _exact_lbfgs(best, 300, 600, deadline)
        if R_of(h3) > bestR:
            return h3
        return best
    return h


def _full_split(h, deadline):
    """Mass-conserving split at full resolution: pick best t by exact R."""
    n = h.size
    best = None
    bestR = -1.0
    for frac in [0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65]:
        cand = np.empty(2 * n)
        cand[0::2] = h * frac
        cand[1::2] = h * (1.0 - frac)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # EXPERIMENT: full-resolution subcell split + exact LBFGS
    if base.size * 2 <= 200000 and time.process_time() < deadline - 3.0:
        cand, candR = _full_split(base, deadline)
        print("full split R=%.7f (N=%d)" % (candR, cand.size))
        if candR > bestR + 1e-15:
            h = _exact_lbfgs(cand, 600, 1200, deadline)
            r = R_of(h)
            print("full split exact R=%.7f (N=%d)" % (r, h.size))
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
        if time.process_time() < deadline - 1.0:
            h = run_direct(best, 100000, 300, 600, deadline)
            r = R_of(h)
            print("full split lse R=%.7f (N=%d)" % (r, h.size))
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r

    # Keep base's low-res basin escape as fallback
    N0 = base.size
    if time.process_time() < deadline - 2.0:
        low = None
        if N0 % 4 == 0 and N0 >= 8:
            low = _rescale_maxL(_block_avg(base, 4))
        else:
            low = base.copy()
        low_best = low.copy()
        low_bestR = R_of(low_best)
        for beta in [200, 1000, 5000, 20000]:
            if time.process_time() >= deadline - 2.0:
                break
            h = run_direct(low_best, beta, 400, 800, deadline)
            r = R_of(h)
            if r > low_bestR + 1e-15:
                low_best, low_bestR = h.copy(), r
        for rnd in range(2):
            if time.process_time() >= deadline - 2.0:
                break
