    bestR = R_of(best)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.5:
            break
        hh = _exact_lbfgs(best, 400, 800, deadline)
        r2 = R_of(hh)
        if r2 > bestR + 1e-16:
