    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Main improvement: targeted split of tallest/near-peak cells at full
    # resolution, then a full exact-argmax polish. Iterate while improving.
    for cyc in range(6):
        if time.process_time() >= deadline - 3.0:
            print("skip cycle %d (time)" % cyc)
            break
        cand = _targeted_zoh(best, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16 and cand.size <= 200000:
            best, bestR = cand, r
            print("split cycle %d R=%.7f (N=%d)" % (cyc, bestR, best.size))
        else:
