            hh = _polish_full(best, deadline)
            r2 = R_of(hh)
            if r2 > bestR + 1e-16:
                best, bestR = hh, r2
                print("polish cycle %d R=%.7f (N=%d)" % (cyc, bestR, best.size))
            else:
                print("cycle %d no improvement (R=%.7f)" % (cyc, bestR))
                break

    # Final polish with whatever time remains.
    if time.process_time() < deadline - 1.0:
        hh = _polish_full(best, deadline, rounds=4)
        if R_of(hh) > bestR + 1e-16:
            best = hh
            bestR = R_of(best)
            print("final polish R=%.7f (N=%d)" % (bestR, best.size))

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

