def _refine_subcell(h, deadline, rounds=1):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    h2 = np.repeat(h, 2) * 0.5
    best = h2.copy()
    bestR = R_of(best)
    for frac in [0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65]:
        cand = np.empty(2 * n)
        cand[0::2] = h * frac
        cand[1::2] = h * (1.0 - frac)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand
            bestR = r
    if bestR > R_of(h) + 1e-15:
        h3 = _exact_lbfgs(best, 300, 600, deadline)
        if R_of(h3) > bestR:
            return h3
        return best
    return h


def _full_split(h, deadline):
    """Mass-conserving split at full resolution: pick best t by exact R."""
    n = h.size
    best = None
    bestR = -1.0
    for frac in [0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65]:
        cand = np.empty(2 * n)
        cand[0::2] = h * frac
        cand[1::2] = h * (1.0 - frac)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def _split_and_polish(h, deadline, tag=""):
    """Split once to 2N (best global t by exact R), then exact LBFGS + softmax."""
    best = h
    bestR = R_of(h)
    if h.size * 2 <= 200000 and time.process_time() < deadline - 3.0:
        cand, candR = _full_split(h, deadline)
        print("%s full split R=%.7f (N=%d)" % (tag, candR, cand.size))
        if candR > bestR + 1e-15:
            hh = _exact_lbfgs(cand, 600, 1200, deadline)
            r = R_of(hh)
            print("%s split exact R=%.7f (N=%d)" % (tag, r, hh.size))
            if r > bestR + 1e-15:
                best, bestR = hh.copy(), r
            else:
                best, bestR = cand.copy(), candR
        if time.process_time() < deadline - 1.0:
            hh = run_direct(best, 100000, 300, 600, deadline)
            r = R_of(hh)
            print("%s split lse R=%.7f (N=%d)" % (tag, r, hh.size))
            if r > bestR + 1e-15:
                best, bestR = hh.copy(), r
    return best, bestR


def _coarsen_cycle(h, k, target_N, deadline, tag=""):
    """block_avg(k) -> softmax ladder -> ZOH-double to target_N -> split+polish."""
    if time.process_time() >= deadline - 3.0:
        return h, R_of(h)
    low = _rescale_maxL(_block_avg(h, k))
    low_best = low.copy()
    low_bestR = R_of(low_best)
    for beta in [200, 1000, 5000, 20000]:
        if time.process_time() >= deadline - 3.0:
            break
        hh = run_direct(low_best, beta, 400, 800, deadline)
        r = R_of(hh)
        if r > low_bestR + 1e-15:
            low_best, low_bestR = hh.copy(), r
    print("%s k=%d ladder R=%.7f (N=%d)" % (tag, k, low_bestR, low_best.size))
    cand = low_best
    while cand.size < target_N:
        cand = _zoh_double(cand)
    if cand.size > target_N:
        cand = cand[:target_N]
    cand = _rescale_maxL(cand)
    r = R_of(cand)
    print("%s k=%d redoubled R=%.7f (N=%d)" % (tag, k, r, cand.size))
    return _split_and_polish(cand, deadline, tag="%s k=%d" % (tag, k))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    N0 = base.size

    # EXPERIMENT: coarsen (k=2,4) -> softmax ladder -> ZOH-double -> split+polish
    for k in (2, 4):
        if time.process_time() >= deadline - 4.0:
            break
        h, r = _coarsen_cycle(best, k, N0, deadline, tag="cyc1")
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("cyc1 k=%d NEW BEST R=%.7f" % (k, bestR))

    # Repeat the k=2 cycle once more from the new best
    if time.process_time() < deadline - 4.0:
        h, r = _coarsen_cycle(best, 2, N0, deadline, tag="cyc2")
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("cyc2 k=2 NEW BEST R=%.7f" % bestR)

    # Final exact polish on whatever we have
    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("final exact R=%.7f" % bestR)

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

