        cand[0::2] = h * frac
        cand[1::2] = h * (1.0 - frac)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand
            bestR = r
    if best is None:
        return h
    h3 = _exact_lbfgs(best, 400, 800, deadline)
    if R_of(h3) > bestR:
        return h3
    return best


def _coord_sweep(h, cur, n_passes, deadline, rng):
    n = h.size
    for _ in range(n_passes):
        if time.process_time() > deadline:
            return h, cur
        improved = False
        order = rng.permutation(n)
        for idx in order:
            if time.process_time() > deadline:
                return h, cur
            old = h[idx]
            hi = max(4.0 * old, 1.0)

            def neg_r(alpha):
                h[idx] = alpha
                return -R_of(h)
            try:
                res = minimize_scalar(neg_r, bounds=(0.0, hi),
                                      method='bounded',
                                      options={'xatol': 1e-10})
                cand = res.x
                cand_r = -res.fun
            except Exception:
                cand = old
                cand_r = cur
            if cand_r > cur + 1e-16:
                h[idx] = cand
                cur = cand_r
                improved = True
            else:
                h[idx] = old
        if not improved:
            break
    return h, cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(64)
    else:
        base = np.ones(64)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Phase 1: exact L-BFGS from start
    c = _exact_lbfgs(best, 500, 1000, deadline)
    rc = R_of(c)
    if rc > bestR:
        best, bestR = c, rc
        print("  exact L-BFGS R=%.6f" % bestR)

    # Phase 2: subcell refinement (double resolution, mass-conserving)
    while time.process_time() < deadline - 2.0 and best.size < 200000:
        h2 = _refine_subcell(best, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-14:
            best, bestR = h2, r2
            print("  subcell R=%.6f (N=%d)" % (bestR, best.size))
            # polish with exact L-BFGS after each doubling
            c = _exact_lbfgs(best, 400, 800, deadline)
            rc = R_of(c)
            if rc > bestR:
                best, bestR = c, rc
        else:
            break

    # Phase 3: alternating coord sweep + exact L-BFGS
    while time.process_time() < deadline - 1.0:
        h2, c2 = _coord_sweep(best.copy(), bestR, 2, deadline, rng)
        if c2 > bestR + 1e-14:
            best, bestR = h2, c2
        h3 = _exact_lbfgs(best.copy(), 300, 600, deadline)
        r3 = R_of(h3)
        if r3 > bestR + 1e-14:
            best, bestR = h3, r3
        else:
            break
    print("after coord+refine R=%.6f (N=%d)" % (bestR, best.size))

    # Phase 4: structural mutations
    while time.process_time() < deadline - 0.6:
        trial = best.copy()
        op = rng.integers(0, 3)
        if op == 0 and trial.size > 4:
            i = rng.integers(1, trial.size - 1)
            trial = np.delete(trial, i)
        elif op == 1 and trial.size < 800:
            i = rng.integers(0, trial.size)
            v = trial[i]
            trial = np.insert(trial, i, v)
        else:
            m = rng.integers(1, 4)
            idxs = rng.integers(0, trial.size, m)
            trial[idxs] *= rng.uniform(0.7, 1.3, m)
            trial = np.clip(trial, 0, None)
        if trial.sum() <= 0:
            continue
        trial = trial / trial.max()
        if R_of(trial) < bestR - 0.005:
            continue
        tb = _exact_lbfgs(trial, 300, 600, deadline)
        if time.process_time() > deadline - 0.4:
            continue
        tb, tr2 = _coord_sweep(tb, R_of(tb), 1, deadline, rng)
        if tr2 > bestR + 1e-14:
            best, bestR = tb, tr2
            print("  mutation R=%.6f (N=%d)" % (bestR, best.size))

    # Final polish
    c = _exact_lbfgs(best, 400, 800, deadline)
    rc = R_of(c)
    if rc > bestR:
        best, bestR = c, rc
    if time.process_time() < deadline:
        best, bestR = _coord_sweep(best, bestR, 2, deadline, rng)

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _doubling_scan(h, deadline):
    """Try doubling resolution, choose best split fraction, then polish."""
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    baseR = R_of(h)
    best = h
    bestR = baseR
    for frac in [0.5, 0.45, 0.55, 0.4, 0.6, 0.35, 0.65]:
        cand = np.empty(2 * h.size)
        cand[0::2] = h * frac
        cand[1::2] = h * (1.0 - frac)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    if bestR > baseR + 1e-15:
        h3 = _exact_lbfgs(best, 400, 800, deadline)
        r3 = R_of(h3)
        if r3 > bestR:
            return h3, r3
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    betas = [50, 150, 400, 1000, 2500, 6000, 15000, 40000, 100000]
    iters = [400, 400, 400, 500, 500, 600, 700, 800, 1000]

    h = best.copy()
    cur = bestR
    round_no = 0
    while time.process_time() < deadline - 1.5:
        round_no += 1
        improved = False
        for beta, mi in zip(betas, iters):
            if time.process_time() >= deadline - 1.5:
                break
            h2 = run_direct(h, beta, mi, 2 * mi, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-14:
                h, cur = h2, r2
                improved = True
        if cur > bestR + 1e-14:
            best, bestR = h.copy(), cur
            print("round%d R=%.6f" % (round_no, bestR))
        # try doubling
        if time.process_time() < deadline - 3.0 and h.size < 100000:
            h3, r3 = _doubling_scan(h, deadline)
            if r3 > cur + 1e-14:
                h, cur = h3, r3
                if cur > bestR + 1e-14:
                    best, bestR = h.copy(), cur
                    print("double R=%.6f (N=%d)" % (bestR, best.size))
                improved = True
        if not improved:
            h4 = run_direct(h, 300000, 1500, 3000, deadline)
            r4 = R_of(h4)
            if r4 > cur + 1e-14:
                h, cur = h4, r4
                if cur > bestR + 1e-14:
                    best, bestR = h.copy(), cur
                    print("sharp R=%.6f" % bestR)
            else:
                break

    # final polish with exact max
    if time.process_time() < deadline - 0.5:
        h5 = _exact_lbfgs(best, 600, 1200, deadline)
        r5 = R_of(h5)
        if r5 > bestR:
            best, bestR = h5, r5
            print("exact R=%.6f" % bestR)

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

