        if r > bestR + 1e-15:
            best = cand
            bestR = r
    if bestR > R_of(h) + 1e-15:
        h3 = _exact_lbfgs(best, 300, 600, deadline)
        if R_of(h3) > bestR:
            return h3
        return best
    return h


def _full_split(h, deadline):
    n = h.size
    best = None
    bestR = -1.0
    for frac in [0.35, 0.4, 0.45, 0.5, 0.55, 0.6, 0.65]:
        cand = np.empty(2 * n)
        cand[0::2] = h * frac
        cand[1::2] = h * (1.0 - frac)
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand
    return best, bestR


def _activation_trial(base, bestR, deadline, trials):
    """Try activating zero cells with most negative gradient, then polish."""
    best = base.copy()
    printed = False
    while time.process_time() < deadline - 1.5:
        h = best.copy()
        if h.sum() <= 0:
            break
        g = _norm_eq_grad(h)
        Z = np.flatnonzero(h == 0.0)
        if Z.size == 0:
            break
        gz = g[Z]
        neg = gz < 0
        nneg = int(neg.sum())
        if not printed:
            mn = float(gz.min()) if gz.size > 0 else 0.0
            print("zeros=%d neg-grad zeros=%d min g=%.3e" % (Z.size, nneg, mn))
            printed = True
        if nneg == 0:
            break
        order = np.argsort(gz)  # most negative first
        Zsorted = Z[order]
        hmax = h.max()
        improved_this_round = False
        for (m, eps) in trials:
            if time.process_time() >= deadline - 1.5:
                break
            mm = min(m, Zsorted.size)
            if mm == 0:
                continue
            cand = h.copy()
            cand[Zsorted[:mm]] = eps * hmax
            cand = _rescale_maxL(cand)
            # h-space L-BFGS-B on frozen-argmax objective
            cand = _hspace_lbfgs(cand, 500, 1000, deadline)
            r = R_of(cand)
            if r > bestR + 1e-15:
                # polish
                h2 = _exact_lbfgs(cand, 400, 800, deadline)
                r2 = R_of(h2)
                if r2 > r:
                    cand, r = h2, r2
                if time.process_time() < deadline - 1.5:
                    h3 = run_direct(cand, 1e5, 300, 600, deadline)
                    r3 = R_of(h3)
                    if r3 > r:
                        cand, r = h3, r3
                best = cand
                bestR = r
                improved_this_round = True
                print("activation m=%d eps=%.0e -> R=%.7f" % (mm, eps, bestR))
        if not improved_this_round:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # EXPERIMENT: zero-cell activation + h-space polish
    trials = [(300, 1e-2), (300, 1e-3), (1000, 1e-3),
              (1000, 1e-4), (3000, 1e-4)]
    if time.process_time() < deadline - 3.0:
        h, r = _activation_trial(best, bestR, deadline, trials)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("after activation R=%.7f (N=%d)" % (bestR, best.size))

    # Keep base's full-split step as fallback / additional improvement
    if base.size * 2 <= 200000 and time.process_time() < deadline - 3.0:
        cand, candR = _full_split(best, deadline)
        print("full split R=%.7f (N=%d)" % (candR, cand.size))
        if candR > bestR + 1e-15:
            h = _exact_lbfgs(cand, 600, 1200, deadline)
            r = R_of(h)
            print("full split exact R=%.7f (N=%d)" % (r, h.size))
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
        if time.process_time() < deadline - 1.0:
            h = run_direct(best, 100000, 300, 600, deadline)
            r = R_of(h)
            print("full split lse R=%.7f (N=%d)" % (r, h.size))
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r

    # Keep base's low-res basin escape as fallback
    N0 = base.size
    if time.process_time() < deadline - 2.0:
        low = None
        if N0 % 4 == 0 and N0 >= 8:
            low = _rescale_maxL(_block_avg(base, 4))
        else:
            low = base.copy()
        low_best = low.copy()
        low_bestR = R_of(low_best)
        for beta in [200, 1000, 5000, 20000]:
            if time.process_time() >= deadline - 2.0:
                break
            h = run_direct(low_best, beta, 400, 800, deadline)
            r = R_of(h)
            if r > low_bestR + 1e-15:
                low_best, low_bestR = h.copy(), r
        for rnd in range(2):
            if time.process_time() >= deadline - 2.0:
                break
            h = _refine_subcell(low_best, deadline)
            r = R_of(h)
            if r > low_bestR + 1e-15:
                low_best, low_bestR = h.copy(), r
            else:
                break
        cand = low_best
        while cand.size < N0:
            cand = _zoh_double(cand)
        if cand.size > N0:
            cand = cand[:N0]
        cand = _rescale_maxL(cand)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand.copy(), r
            print("redoubled R=%.7f (N=%d)" % (bestR, best.size))

    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("final exact R=%.7f" % bestR)

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

