    ks = [500, 200, 50, 20, 5, 1]
    betas = [1e5, 3e5, 1e6, 3e6]
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False

        # Top-k stages
        for k in ks:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_topk(best, k, 400, 800, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            else:
                h = best
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(h, 400, 800, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
            print("cycle %d topk %d R=%.7f" % (cycle, k, bestR))

        # LSE ladder
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 800, 1600, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
