import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


# ---------------- exact-max objective (true R) ----------------

def _exact_obj_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.8:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _exact_obj_grad(xc)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


# ---------------- soft-max (direct) objective ----------------

def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.8:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


# ---------------- top-k surrogate ----------------

def _topk_obj_grad(h, k):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = max(1, min(k, n))
    if kk < n:
        idx = np.argpartition(Lf, -kk)[-kk:]
    else:
        idx = np.arange(n)
    M = Lf[idx].mean()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(M)
    gLf = -dq / num
    gLf[idx] += (1.0 / kk) / M
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def _topk_lbfgs(h0, k, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.8:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _k_ladder(h, deadline):
    ks = [2000, 800, 300, 100, 30, 10, 3, 1]
    cur = h
    curR = R_of(cur)
    for k in ks:
        if time.process_time() >= deadline - 1.2:
            break
        cand = _topk_lbfgs(cur, k, 300, 600, deadline)
        r = R_of(cand)
        if r > curR + 1e-15:
            cur, curR = cand, r
        elif r >= curR - 1e-10:
            cur = cand
    return cur, curR


# ---------------- resampling: upsample / downsample ----------------

def _upsample(h, factor):
    n = h.size
    if n * factor > 200000:
        return h
    # linear interpolation preserving mass roughly
    x = np.arange(n)
    xn = np.linspace(0, n - 1, n * factor)
    hh = np.interp(xn, x, h)
    # preserve total mass
    s0 = h.sum()
    s1 = hh.sum()
    if s1 > 0:
        hh *= s0 / s1
    return hh


def _downsample(h, factor):
    n = h.size
    if n % factor != 0 or n // factor < 1:
        return h
    # area-average so mass preserved
    return h.reshape(-1, factor).mean(axis=1) * 1.0


# ---------------- main ----------------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Try a couple of resolution changes: the key new move.
    # Upsampling sometimes lets the optimizer break symmetry; downsampling
    # smooths a noisy optimum. We try both, reoptimize, keep if better.
    def try_resolution(h, factor, tag):
        nonlocal best, bestR
        if time.process_time() >= deadline - 1.5:
            return
        if factor > 1:
            cand0 = _upsample(h, factor)
        else:
            cand0 = _downsample(h, -factor)
        if cand0.size == h.size:
            return
        cand0 = _rescale_maxL(cand0)
        r0 = R_of(cand0)
        cur = cand0
        curR = r0
        # quick polish on the new grid
        if time.process_time() < deadline - 1.2:
            hh = _exact_lbfgs(cur, 400, 800, deadline)
            rr = R_of(hh)
            if rr > curR:
                cur, curR = hh, rr
        if time.process_time() < deadline - 1.2:
            hh, rr = _k_ladder(cur, deadline)
            if rr > curR:
                cur, curR = hh, rr
        if time.process_time() < deadline - 1.0:
            hh = run_direct(cur, 2e4, 200, 400, deadline)
            rr = R_of(hh)
            if rr > curR:
                cur, curR = hh, rr
        if curR > bestR + 1e-12:
            best, bestR = cur.copy(), curR
            print("%s R=%.7f (N=%d)" % (tag, bestR, best.size))

    # Phase 1: original-scale refinement
    if time.process_time() < deadline - 2.0:
        h, r = _k_ladder(best, deadline)
        if r > bestR:
            best, bestR = h.copy(), r
        if time.process_time() < deadline - 1.5:
            h2 = _exact_lbfgs(best, 500, 1000, deadline)
            r2 = R_of(h2)
            if r2 > bestR:
                best, bestR = h2.copy(), r2
        print("phase1 R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 2: resolution changes
    for factor in [2, 3]:
        try_resolution(best, factor, "up%d" % factor)
    # downsample then reoptimize (smoothing)
    for factor in [2, 3]:
        if best.size % factor == 0 and best.size // factor >= 20:
            try_resolution(best, -factor, "down%d" % factor)
    # and upsample again after any downsampling (different basin)
    for factor in [2]:
        try_resolution(best, factor, "up%d_b" % factor)

    # Phase 3: perturb-and-reoptimize with resolution-aware noise
    rng = np.random.default_rng(987654321)
    while time.process_time() < deadline - 1.5:
        scale = 0.02
        noise = 1.0 + scale * rng.standard_normal(best.size)
        cand = _rescale_maxL(best * np.clip(noise, 0.5, 1.5))
        h, r = _k_ladder(cand, deadline)
        if time.process_time() < deadline - 1.2:
            h2 = _exact_lbfgs(h, 300, 600, deadline)
            r2 = R_of(h2)
            if r2 > r:
                h, r = h2, r2
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
            print("perturb R=%.7f (N=%d)" % (bestR, best.size))
        else:
            # try once more with a different seed; break after a miss
            break

    # Phase 4: final direct + exact polish
    if time.process_time() < deadline - 1.2:
        h = run_direct(best, 5e4, 300, 600, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h.copy(), r
    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 600, 1200, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h.copy(), r

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

