    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 1200, 2400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            else:
                h = best
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(h, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
            print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        if not any_improved:
            # Aggressive polish, but only until 60% of remaining time is used.
            polish_end = time.process_time() + 0.60 * max(
                0.0, (deadline - 1.5) - time.process_time())
            while time.process_time() < polish_end:
                h2 = _exact_lbfgs(best, 2000, 4000, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-16:
                    best, bestR = h2.copy(), r2
                    print("polish R=%.7f" % bestR)
                else:
                    break
            # Resume ladder from beta=1e5 (loop continues).

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

