            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(h, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                improved_cycle = True
            print("cycle %d beta %.0e exact  R=%.7f" % (cycle, beta, bestR))
        if not improved_cycle:
            # No-improvement branch: top-k polishing loop.
            while time.process_time() < deadline - 1.5:
                pass_improved = False
                h = _exact_lbfgs(best, 800, 1600, deadline)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    pass_improved = True
                print("topk pass exact R=%.7f" % bestR)
                for k in [20, 5, 1]:
