                        break
                    hk = _topk_lbfgs(best, k, 300, deadline)
                    rk = R_of(hk)
                    if rk > bestR + 1e-15:
                        best, bestR = hk.copy(), rk
                        pass_improved = True
                    print("topk k=%d R=%.7f" % (k, bestR))
                    if time.process_time() >= deadline - 1.5:
                        break
