    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def _flat_obj_grad(h, lam=1.0, beta=1e6):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    e = np.exp(np.clip(beta * (Lf - M), -50, 0))
    Z = e.sum()
    w = e / Z
    N = Lf.size
    gLf = -dq / num + w
    mask = (Lf > 0.3 * M) & (Lf < 0.9 * M)
    if mask.any():
        gLf[mask] -= lam / (N * M)
    pen = lam * np.sum(np.maximum(0.9 * M - Lf[mask])) / (N * M) if mask.any() else 0.0
    obj = -np.log(num) + 2.0 * np.log(s) + np.log(M) + pen
    grad = _backprop(gLf, h) + 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def run_flat(h0, lam, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _flat_obj_grad(xc, lam=lam)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
