    # Try refined (2x upsampled) discretisation: more degrees of freedom can
    # capture the optimal shape better than the current resolution allows.
    if best.size * 2 <= 200000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
