                print("upsample+polish R=%.7f (N=%d)" % (bestR, best.size))

    # Sustained exact-gradient polishing at full resolution until the budget
    # is exhausted.  Each pass restarts L-BFGS from the current best, which
    # keeps making tiny but real gains on the exact objective.
    stall = 0
    while time.process_time() < deadline - 0.6:
