import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_avg(h, k):
    n = (h.size // k) * k
    return h[:n].reshape(-1, k).sum(1)


def _coarse_escape(best, bestR, deadline):
    """Try a block-average coarse escape. Return (h, R) if improved else (best, bestR)."""
    if time.process_time() >= deadline - 1.5:
        return best, bestR
    try:
        hc = _block_avg(best, 2)
        for beta in [200, 1000, 5000, 20000]:
            if time.process_time() >= deadline - 1.5:
                break
            hc = run_direct(hc, beta, 800, 1600, deadline)
            hc = _exact_lbfgs(hc, 400, 800, deadline)
        # split back to full resolution
        hb = np.repeat(hc, 2)
        if hb.size != best.size:
            xo = np.linspace(0.0, hb.size - 1, best.size)
            hb = np.interp(xo, np.arange(hb.size), hb)
        hb = _rescale_maxL(hb)
        hb = _exact_lbfgs(hb, 600, 1200, deadline)
        for beta in [1e5, 3e5]:
            if time.process_time() >= deadline - 1.5:
                break
            hb = run_direct(hb, beta, 800, 1600, deadline)
        r = R_of(hb)
        if r > bestR + 1e-12:
            print("coarse escape R=%.7f (N=%d)" % (r, hb.size))
            return hb, r
    except Exception:
        pass
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Try an upsampled refinement of the start; keep whichever scores higher.
    if best.size < 120000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR + 1e-9:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    cycle = 0
    coarse_count = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 1200, 2400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(best, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
                print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        if not any_improved:
            # Allow up to 3 coarse escape attempts, one per stall.
            if coarse_count < 3:
                coarse_count += 1
                best, bestR = _coarse_escape(best, bestR, deadline)
                if time.process_time() < deadline - 1.5:
                    continue
            polish_end = time.process_time() + 0.60 * max(
                0.0, (deadline - 1.5) - time.process_time())
            while time.process_time() < polish_end:
                h2 = _exact_lbfgs(best, 2000, 4000, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-16:
                    best, bestR = h2.copy(), r2
                    print("polish R=%.7f" % bestR)
                else:
                    break

    # Final long exact polish to squeeze the last bits.
    end = time.process_time() + 0.9 * max(0.0, (t0 + budget_seconds * 0.97) - time.process_time())
    while time.process_time() < end:
        h2 = _exact_lbfgs(best, 3000, 6000, deadline=t0 + budget_seconds * 0.98)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

