    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        # seed with a smooth bump so the very first run has something usable
        n = 400
        x = np.linspace(-1, 1, n)
        base = np.clip(1.0 - x*x, 0, None) ** 2 + 1e-3
        base = _rescale_maxL(base)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # (1) upsampling escape: refine on a finer grid, then coarsen back.
    # This is the main new lever: it can break out of the current resolution's
    # local optimum, then re-relax at full resolution.
    if time.process_time() < deadline - 6.0:
        for factor in [2]:
            if time.process_time() >= deadline - 6.0:
                break
            try:
                hu = _upsample(best, factor)
                hu = _rescale_maxL(hu)
                for beta in [300, 1000, 3000, 10000]:
                    if time.process_time() >= deadline - 6.0:
                        break
                    hu = run_direct(hu, beta, 400, 800, deadline)
                hu = _exact_lbfgs(hu, 400, 800, deadline)
                ru = R_of(hu)
                if ru > bestR + 1e-12:
                    best, bestR = hu.copy(), ru
                    print("upsample R=%.7f (N=%d)" % (bestR, best.size))
            except Exception:
                pass

    # (2) exact-objective L-BFGS relaxation at full resolution
    h = _exact_lbfgs(best, 800, 1600, deadline)
    r = R_of(h)
    if r > bestR + 1e-14:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    # (3) LSE polish ladder
    for beta in [1000, 3000, 10000, 30000, 100000, 300000]:
        if time.process_time() >= deadline - 0.5:
            break
        h = run_direct(best, beta, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # (4) alternating exact / LSE with residual time
    while time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 400, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            # one last direct push with a strong beta
            h = run_direct(best, 1e6, 300, 600, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
            else:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    h = best.copy()
    cur = bestR

    # Phase 1: exact objective (hard max) polishing at current resolution.
    for it in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        h_new = _exact_lbfgs(h, maxiter=200, maxfun=2000, deadline=deadline)
        r = R_of(h_new)
        if r > cur:
            h, cur = h_new, r
            print("exact R=%.6f (N=%d)" % (cur, h.size))

    # Phase 2: top-k soft-max polishing.
    for k in (1, 3, 8, 20):
        if time.process_time() >= deadline - 1.0:
            break
        h_new = run_topk(h, k, maxiter=200, maxfun=2000, deadline=deadline, beta=1e5)
        r = R_of(h_new)
        if r > cur:
            h, cur = h_new, r
            print("topk k=%d R=%.6f" % (k, cur))

    # Phase 3: upsample and continue polishing if budget remains.
    while time.process_time() < deadline - 2.0 and h.size < 200000:
        factor = 2
        if h.size * factor > 200000:
            break
        h_up = _upsample(h, factor)
        h_up = _rescale_maxL(h_up)
        r_up = R_of(h_up)
        print("upsample N=%d R=%.6f" % (h_up.size, r_up))
        h2, r2 = h_up, r_up
        for k in (1, 3, 8, 20):
            if time.process_time() >= deadline - 1.0:
                break
            h_new = run_topk(h2, k, maxiter=150, maxfun=1500, deadline=deadline, beta=1e5)
            r = R_of(h_new)
            if r > r2:
                h2, r2 = h_new, r
        if time.process_time() < deadline - 1.0:
            h_new = _exact_lbfgs(h2, maxiter=150, maxfun=1500, deadline=deadline)
            r = R_of(h_new)
            if r > r2:
                h2, r2 = h_new, r
        if r2 > cur:
            h, cur = h2, r2
            print("upsampled R=%.6f (N=%d)" % (cur, h.size))
        else:
            break

    # Final soft-max polish at current best resolution for remaining budget.
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 0.5:
            break
        h_new = run_direct(h, beta=beta, maxiter=300, maxfun=3000, deadline=deadline)
        r = R_of(h_new)
        if r > cur:
            h, cur = h_new, r
            print("final beta=%.0e R=%.6f" % (beta, cur))

    if cur > bestR:
        best, bestR = h, cur
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

