        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _coarse_escape(best, bestR, deadline):
    """Try a block-average coarse escape. Return (h, R) if improved else (best, bestR)."""
    if time.process_time() >= deadline - 1.5:
        return best, bestR
    try:
        hc = _block_avg(best, 2)
        for beta in [200, 1000, 5000, 20000]:
            if time.process_time() >= deadline - 1.5:
                break
            hc = run_direct(hc, beta, 800, 1600, deadline)
            hc = _exact_lbfgs(hc, 400, 800, deadline)
        # split back to full resolution
        hb = np.repeat(hc, 2)
        if hb.size != best.size:
            xo = np.linspace(0.0, hb.size - 1, best.size)
            hb = np.interp(xo, np.arange(hb.size), hb)
        hb = _rescale_maxL(hb)
        hb = _exact_lbfgs(hb, 600, 1200, deadline)
        for beta in [1e5, 3e5]:
            if time.process_time() >= deadline - 1.5:
                break
            hb = run_direct(hb, beta, 800, 1600, deadline)
        r = R_of(hb)
        if r > bestR + 1e-12:
            print("coarse escape R=%.7f (N=%d)" % (r, hb.size))
            return hb, r
    except Exception:
        pass
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Try an upsampled refinement of the start; keep whichever scores higher.
    if best.size < 120000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR + 1e-9:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    cycle = 0
    coarse_count = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 1200, 2400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(best, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
                print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        if not any_improved:
            # Allow up to 2 coarse escapes, each followed by the top-k ladder.
            if coarse_count < 2:
                coarse_count += 1
                best, bestR = _coarse_escape(best, bestR, deadline)
                if time.process_time() < deadline - 1.5:
                    for k in [200, 50, 20, 5, 1]:
                        if time.process_time() >= deadline - 1.5:
                            break
                        hk = run_topk(best, k, 400, 800, deadline)
                        hk = _exact_lbfgs(hk, 400, 800, deadline)
                        rk = R_of(hk)
                        if rk > bestR + 1e-15:
                            best, bestR = hk.copy(), rk
                            print("topk k=%d R=%.7f" % (k, bestR))
                if time.process_time() < deadline - 1.5:
                    continue
            polish_end = time.process_time() + 0.60 * max(
                0.0, (deadline - 1.5) - time.process_time())
            while time.process_time() < polish_end:
                h2 = _exact_lbfgs(best, 2000, 4000, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-16:
                    best, bestR = h2.copy(), r2
                    print("polish R=%.7f" % bestR)
                else:
                    break

    # Final long exact polish to squeeze the last bits.
