    """Upsample to finer grids, exact-LBFGS polish, keep best."""
    best = np.clip(h, 0, None).copy()
    bestR = R_of(best)
    for factor in (2, 2, 2, 2):
        if time.process_time() > deadline - 1.0:
            break
        up = _upsample(best, factor)
        up = _rescale_maxL(up)
        # short exact polish
        sub_deadline = min(deadline, time.process_time() + (deadline - time.process_time()) * 0.5)
        cand = _exact_lbfgs(up, 300, 6000, sub_deadline)
        if cand.size <= 200000:
            r = R_of(cand)
            if r > bestR:
                bestR = r
                best = cand
        else:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.clip(h, 0, None)
        if h.size == 0 or h.sum() <= 0:
            h = np.ones(50)
    else:
        h = np.ones(50)
    h = _rescale_maxL(h)
    best = h.copy()
    bestR = R_of(best)

    # Phase 1: exact L-BFGS polish at current resolution
    cand = _exact_lbfgs(h, 500, 20000, deadline)
    if cand.size == h.size:
        r = R_of(cand)
        if r > bestR:
            bestR = r; best = cand.copy()

    # Phase 2: multi-scale refinement (upsample + polish)
    cand, r = _refine_multiscale(best, deadline, rng)
    if r > bestR:
        bestR = r; best = cand.copy()

    # Phase 3: final exact polish at best resolution with remaining time
    if time.process_time() < deadline - 0.5:
        cand = _exact_lbfgs(best, 2000, 100000, deadline)
        if cand.size == best.size:
            r = R_of(cand)
            if r > bestR:
                bestR = r; best = cand.copy()

    return best

