import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * Lf.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _obj_grad(h, beta):
    """Minimize -log(num) + 2 log(s) + log(softmax-max of Lf)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def _run_direct(h0, beta, deadline, maxiter=4000, maxfun=8000):
    if time.process_time() >= deadline - 0.5:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
