def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Stage 1: sharp direct optimization of the true objective on the start's grid.
    # Tightening beta on the soft-max pushes it toward the true max-knot objective.
    for beta in [3e2, 1e3, 3e3, 1e4, 3e4, 1e5, 3e5, 1e6, 3e6]:
        if time.process_time() >= deadline - 0.5:
            break
        cand = _run_direct(best, beta, deadline)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc
    print("after direct R=%.6f" % bestR)

    # Stage 2: try upsampling to a finer grid to allow more degrees of freedom,
    # then re-optimize. This is the main lever for improvement.
    factor = 2
    if best.size * factor <= 200000:
        up = _upsample(best, factor)
        up = _rescale_maxL(up)
        cand = _run_direct(up, 1e5, deadline)
        if time.process_time() < deadline - 0.5:
            cand = _run_direct(cand, 1e6, deadline)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc
            print("after upsample x%d R=%.6f (N=%d)" % (factor, bestR, best.size))

    # Stage 3: keep refining on current grid with increasing beta until deadline.
    betas = [3e6, 1e7, 3e7, 1e8, 3e8, 1e9]
    while time.process_time() < deadline - 0.5:
        improved = False
        for beta in betas:
            if time.process_time() >= deadline - 0.5:
                break
            cand = _run_direct(best, beta, deadline)
            rc = R_of(cand)
            if rc > bestR + 1e-13:
                best, bestR = cand, rc
                improved = True
        if not improved:
            # random perturbation to escape local optimum
            h2 = best * (1.0 + 0.01 * rng.standard_normal(best.size))
            h2 = _rescale_maxL(h2)
            cand = _run_direct(h2, 1e7, deadline)
            rc = R_of(cand)
            if rc > bestR + 1e-13:
                best, bestR = cand, rc
            else:
                break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

