    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Finer-grid experiment: mass-conserving repeat x2, then optimise on the
    # finer grid. Only keep it if it actually beats the coarse best.
    if budget_seconds >= 25 and best.size < 100000:
        fine_deadline = t0 + budget_seconds * 0.40
        h2 = _rescale_maxL(np.repeat(best, 2))
        r2 = R_of(h2)
        print("fine init R=%.7f (N=%d)" % (r2, h2.size))
        h2 = _exact_lbfgs(h2, 400, 800, fine_deadline)
        r2 = R_of(h2)
        if time.process_time() < fine_deadline - 1.0:
            h2b = run_direct(h2, 1e5, 400, 800, fine_deadline)
            rb = R_of(h2b)
            if rb > r2:
                h2, r2 = h2b, rb
        print("fine stage R=%.7f (N=%d)" % (r2, h2.size))
        if r2 > bestR + 1e-12:
            best, bestR = h2.copy(), r2
            print("fine grid accepted R=%.7f (N=%d)" % (bestR, best.size))
        else:
            print("fine grid rejected, reverting to N=%d" % best.size)

    betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 1200, 2400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(best, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
                print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        if not any_improved:
            break

    # Final exact polish on all active coordinates.
    hard = t0 + budget_seconds * 0.96
    while time.process_time() < hard - 1.0:
        h2 = _exact_lbfgs(best, 4000, 8000, hard - 0.5)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

