    for rnd in range(2):
        if time.process_time() >= deadline - 1.5:
            break
        round_best = best.copy()
        round_bestR = bestR
        improved = False
        for thresh in [1e-4, 1e-3]:
            if time.process_time() >= deadline - 1.5:
                break
            hh = _prune(round_best, thresh)
            hh = _exact_lbfgs(hh, 600, 1200, deadline)
            r = R_of(hh)
            if r > round_bestR + 1e-15:
                round_best, round_bestR = hh.copy(), r
                improved = True
        for frac in [1e-3, 1e-2]:
            if time.process_time() >= deadline - 1.5:
                break
            hh2 = _unzero(round_best, frac)
            hh2 = _exact_lbfgs(hh2, 600, 1200, deadline)
            if time.process_time() < deadline - 1.5:
                hh2 = run_direct(hh2, 1e6, 800, 1600, deadline)
                hh2 = _exact_lbfgs(hh2, 600, 1200, deadline)
            r = R_of(hh2)
            if r > round_bestR + 1e-15:
                round_best, round_bestR = hh2.copy(), r
                improved = True
        if round_bestR > bestR + 1e-15:
            best, bestR = round_best, round_bestR
            print("shake round %d R=%.7f" % (rnd + 1, bestR))
        if not improved:
            break

    # NEW: translation search. R is invariant to shift of the support,
    # but a shift changes which knots are on the boundary, so try
    # small shifts and repolish. This is cheap and can find tiny gains.
    if time.process_time() < deadline - 2.0:
        shift_best, shift_bestR = best.copy(), bestR
        for s in (1, -1, 2, -2):
            if time.process_time() >= deadline - 2.0:
                break
            hh = _shift(best, s)
            hh = _rescale_maxL(hh)
            hh = _exact_lbfgs(hh, 400, 800, deadline)
            r = R_of(hh)
            if r > shift_bestR + 1e-16:
                shift_best, shift_bestR = hh.copy(), r
        if shift_bestR > bestR + 1e-16:
            best, bestR = shift_best, shift_bestR
            print("shift polish R=%.7f" % bestR)

    hard = t0 + budget_seconds * 0.96
    while time.process_time() < hard - 1.0:
        h2 = _exact_lbfgs(best, 4000, 8000, hard - 0.5)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_min_plus_ridge(h, beta, ridge):
    """Objective: -log(num) + 2log(s) + softmax(beta) of L + ridge * sum(h^2)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM + ridge * np.dot(h, h)
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s + 2.0 * ridge * h
    return obj, grad


def run_smooth(h0, beta, ridge, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _smooth_min_plus_ridge(xc, beta, ridge)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-18, 'gtol': 1e-14})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Try an upsampled refinement of the start.
    if best.size < 120000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR + 1e-9:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    # Smooth-max + tiny ridge: the ridge makes the L-infinity "active set"
    # less degenerate, which helps L-BFGS make progress on the exact objective.
    ridge = 1e-6 / max(best.size, 1)
    while time.process_time() < deadline - 1.5:
        improved = False
        for beta in [3e4, 1e5, 3e5, 1e6, 3e6, 1e7]:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_smooth(best, beta, ridge, 1500, 3000, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                improved = True
                print("smooth beta %.0e R=%.7f" % (beta, bestR))
            h2 = _exact_lbfgs(best, 800, 1600, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                improved = True
                print("  exact R=%.7f" % bestR)
        if not improved:
            break

    # Long exact polish on the final support.
    end = t0 + budget_seconds * 0.97
    while time.process_time() < end - 0.5:
        h2 = _exact_lbfgs(best, 4000, 8000, deadline=end - 0.3)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

