    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _prune(h, frac):
    h = np.asarray(h, dtype=float)
    out = h * (h > frac * h.max())
    return _rescale_maxL(out)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _window_polish(h, deadline):
    """Exact L-BFGS restricted to indices near the argmax-knot region, then full."""
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # knots index maps to h windows; the max of f*f at knot m involves h[i]*h[m-1-i]
    # support of f*f near peak: indices i where both i and m-1-i valid.
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi <= lo:
        return h
    pad = max(4, (hi - lo) // 4)
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    h2 = _exact_lbfgs(h, 800, 1600, deadline, free=free)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Try to upsample once (higher N often unlocks a bit).
    if best.size < 120000:
        for factor in (2, 3):
            cand = _rescale_maxL(_upsample(best, factor))
            if cand.size > 200000:
                continue
            r = R_of(cand)
            if r > bestR - 2e-6:
                best, bestR = cand, max(r, bestR)
                print("upsample x%d R=%.7f (N=%d)" % (factor, bestR, best.size))
                break

    betas = [1e5, 1e6, 1e7, 1e8, 1e9]
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        improved = False
        for beta in betas:
            if time.process_time() >= deadline - 2.0:
                break
            h = run_direct(best, beta, 1000, 2000, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                improved = True
            if time.process_time() >= deadline - 2.0:
                break
            h2 = _exact_lbfgs(best, 500, 1000, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                improved = True
                print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        # window-restricted polish
        h3 = _window_polish(best, deadline)
        r3 = R_of(h3)
        if r3 > bestR + 1e-15:
            best, bestR = h3.copy(), r3
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            break

    # Shake ladder: prune / unzero alternations.
    for rnd in range(3):
        if time.process_time() >= deadline - 2.0:
            break
        round_best = best.copy()
        round_bestR = bestR
        improved = False
        for thresh in [1e-4, 1e-3, 1e-2]:
            if time.process_time() >= deadline - 2.0:
                break
            hh = _prune(round_best, thresh)
            hh = _exact_lbfgs(hh, 500, 1000, deadline)
            r = R_of(hh)
            if r > round_bestR + 1e-15:
                round_best, round_bestR = hh.copy(), r
                improved = True
        for frac in [1e-3, 1e-2]:
            if time.process_time() >= deadline - 2.0:
                break
            hh2 = _unzero(round_best, frac)
            hh2 = _exact_lbfgs(hh2, 500, 1000, deadline)
            if time.process_time() < deadline - 2.0:
                hh2 = run_direct(hh2, 1e6, 600, 1200, deadline)
                hh2 = _exact_lbfgs(hh2, 500, 1000, deadline)
            r = R_of(hh2)
            if r > round_bestR + 1e-15:
                round_best, round_bestR = hh2.copy(), r
                improved = True
        if round_bestR > bestR + 1e-15:
            best, bestR = round_best, round_bestR
            print("shake round %d R=%.7f" % (rnd + 1, bestR))
        if not improved:
            break

    hard = t0 + budget_seconds * 0.96
    while time.process_time() < hard - 1.0:
        h2 = _exact_lbfgs(best, 4000, 8000, hard - 0.5)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0

    def f(x):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)

    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_avg(h, k):
    n = (h.size // k) * k
    return h[:n].reshape(-1, k).sum(1)


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0

    def f(x):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)

    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    mask = (h <= 0)
    out = h.copy()
    out[mask] = out[mask] + frac * m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    fine_deadline = t0 + budget_seconds * 0.78
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Fine-grid phase: np.repeat(h,2) is the same step function, so R is
    # identical, but the finer grid gives the optimiser more freedom.
    # Do not double an already-fine start; polish it at its own resolution.
    fine_best = None
    fineR = -1.0
    if best.size * 2 <= 100000 and best.size < 60000:
        h2 = _rescale_maxL(np.repeat(best, 2))
        fine_best = h2
        fineR = R_of(h2)
        print("fine start R=%.7f (N=%d)" % (fineR, fine_best.size))
        cycle = 0
        while time.process_time() < fine_deadline - 1.5:
            cycle += 1
            cand = _exact_lbfgs(fine_best, 1500, 3000, fine_deadline)
            cand = run_direct(cand, 1e6, 800, 1600, fine_deadline)
            cand = _exact_lbfgs(cand, 1500, 3000, fine_deadline)
            r = R_of(cand)
            improved = r > fineR + 1e-15
            if improved:
                fine_best, fineR = cand, r
                print("fine cycle %d R=%.7f" % (cycle, fineR))
            # unzero variant
            if time.process_time() < fine_deadline - 1.5:
                hh = _unzero(fine_best, 1e-3)
                hh = _exact_lbfgs(hh, 1500, 3000, fine_deadline)
                rh = R_of(hh)
                if rh > fineR + 1e-15:
                    fine_best, fineR = hh, rh
                    improved = True
                    print("fine unzero R=%.7f" % fineR)
        print("fine final R=%.7f (N=%d)" % (fineR, fine_best.size))
        if fineR > bestR:
            best, bestR = fine_best.copy(), fineR

    # Coarse ladder with any leftover time; skip it for already-fine starts.
    if best.size < 80000:
        if best.size < 100000:
            cand = _rescale_maxL(_upsample(best, 2))
            r = R_of(cand)
            if r > bestR - 1e-6:
                best, bestR = cand, max(r, bestR)
                print("upsample R=%.7f (N=%d)" % (bestR, best.size))

        betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
        cycle = 0
        while time.process_time() < deadline - 1.5:
            cycle += 1
            any_improved = False
            for beta in betas:
                if time.process_time() >= deadline - 1.5:
                    break
                h = run_direct(best, beta, 1200, 2400, deadline)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    any_improved = True
                if time.process_time() >= deadline - 1.5:
                    break
                h2 = _exact_lbfgs(best, 600, 1200, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-15:
                    best, bestR = h2.copy(), r2
                    any_improved = True
                    print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
            if not any_improved:
                break

    if time.process_time() < deadline - 1.5:
        for frac in [1e-3, 1e-2, 3e-2]:
            if time.process_time() >= deadline - 1.5:
                break
            hh = _unzero(best, frac)
            hh = _exact_lbfgs(hh, 600, 1200, deadline)
            hh = run_direct(hh, 1e5, 400, 800, deadline)
            hh = _exact_lbfgs(hh, 600, 1200, deadline)
            r = R_of(hh)
            if r > bestR + 1e-15:
                best, bestR = hh.copy(), r
                print("unzero frac %.0e R=%.7f" % (frac, bestR))
            else:
                break

    hard = t0 + budget_seconds * 0.96
    while time.process_time() < hard - 1.0:
        h2 = _exact_lbfgs(best, 4000, 8000, hard - 0.5)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

