    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_avg(h, k):
    n = (h.size // k) * k
    return h[:n].reshape(-1, k).sum(1)


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    mask = (h <= 0)
    out = h.copy()
    out[mask] = out[mask] + frac * m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    fine_deadline = t0 + budget_seconds * 0.78
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Fine-grid phase: np.repeat(h,2) is the same step function, so R is
    # identical, but the finer grid gives the optimiser more freedom.
    # Budget-safe: do not double past N=84992.
    fine_best = None
    fineR = -1.0
    if best.size * 2 <= 200000:
        h2 = _rescale_maxL(np.repeat(best, 2))
        fine_best = h2
        fineR = R_of(h2)
        print("fine start R=%.7f (N=%d)" % (fineR, fine_best.size))
        cycle = 0
        while time.process_time() < fine_deadline - 1.5:
            cycle += 1
            cand = _exact_lbfgs(fine_best, 1500, 3000, fine_deadline)
            # q-norm ladder replaces the single LSE run_direct call
            for q in (2, 4, 8, 16, 32, 64):
                if time.process_time() >= fine_deadline - 1.5:
                    break
                cand = run_qnorm(cand, q, 400, 800, fine_deadline)
            cand = _exact_lbfgs(cand, 1500, 3000, fine_deadline)
            r = R_of(cand)
            improved = r > fineR + 1e-15
            if improved:
                fine_best, fineR = cand, r
                print("fine cycle %d R=%.7f" % (cycle, fineR))
            # unzero variant
            if time.process_time() < fine_deadline - 1.5:
                hh = _unzero(fine_best, 1e-3)
                hh = _exact_lbfgs(hh, 1500, 3000, fine_deadline)
                rh = R_of(hh)
                if rh > fineR + 1e-15:
                    fine_best, fineR = hh, rh
                    improved = True
                    print("fine unzero R=%.7f" % fineR)
            if not improved:
                break
        print("fine final R=%.7f (N=%d)" % (fineR, fine_best.size))
        if fineR > bestR:
            best, bestR = fine_best.copy(), fineR

    # Coarse ladder with any leftover time.
    if best.size < 100000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR - 1e-6:
            best, bestR = cand, max(r, bestR)
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 1200, 2400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(best, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
                print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        if not any_improved:
            break

    if time.process_time() < deadline - 1.5:
        for frac in [1e-3, 1e-2, 3e-2]:
            if time.process_time() >= deadline - 1.5:
                break
            hh = _unzero(best, frac)
            hh = _exact_lbfgs(hh, 600, 1200, deadline)
            hh = run_direct(hh, 1e5, 400, 800, deadline)
            hh = _exact_lbfgs(hh, 600, 1200, deadline)
            r = R_of(hh)
            if r > bestR + 1e-15:
                best, bestR = hh.copy(), r
                print("unzero frac %.0e R=%.7f" % (frac, bestR))
            else:
                break

    hard = t0 + budget_seconds * 0.96
    while time.process_time() < hard - 1.0:
        h2 = _exact_lbfgs(best, 4000, 8000, hard - 0.5)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_avg(h, k):
    n = (h.size // k) * k
    return h[:n].reshape(-1, k).sum(1)


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _perturb(h, rng, scale):
    """Small multiplicative perturbation on a random subset to escape local optima."""
    h2 = h.copy()
    n = h2.size
    m = max(1, int(0.02 * n))
    idx = rng.choice(n, size=m, replace=False)
    fac = 1.0 + scale * (2.0 * rng.random(m) - 1.0)
    h2[idx] *= fac
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # Try upsampled refinement
    if best.size < 120000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR + 1e-9:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    cycle = 0
    stall = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 1200, 2400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(best, 600, 1200, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
                print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        if not any_improved:
            stall += 1
            # Perturbation escapes: try small random perturbations and re-optimize
            if stall <= 6 and time.process_time() < deadline - 3.0:
                scale = 0.02 + 0.05 * stall
                cand = _perturb(best, rng, scale)
                for beta in [1e5, 1e6, 1e7]:
                    if time.process_time() >= deadline - 2.0:
                        break
                    cand = run_direct(cand, beta, 600, 1200, deadline)
                cand = _exact_lbfgs(cand, 800, 1600, deadline)
                rc = R_of(cand)
                if rc > bestR + 1e-15:
                    best, bestR = cand.copy(), rc
                    print("perturb R=%.7f" % bestR)
                    stall = 0
                    continue
            # Top-k ladder as another escape
            if stall <= 8 and time.process_time() < deadline - 3.0:
                for k in [200, 50, 20, 5, 1]:
                    if time.process_time() >= deadline - 2.0:
                        break
                    hk = run_topk(best, k, 400, 800, deadline)
                    hk = _exact_lbfgs(hk, 400, 800, deadline)
                    rk = R_of(hk)
                    if rk > bestR + 1e-15:
                        best, bestR = hk.copy(), rk
                        print("topk k=%d R=%.7f" % (k, bestR))
                        stall = 0
                        break

    # Final long exact polish
    end = time.process_time() + 0.9 * max(0.0, (t0 + budget_seconds * 0.97) - time.process_time())
    while time.process_time() < end:
        h2 = _exact_lbfgs(best, 3000, 6000, deadline=t0 + budget_seconds * 0.98)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

