            if time.process_time() < fine_deadline - 1.5:
                hh = _unzero(fine_best, 1e-3)
                hh = _exact_lbfgs(hh, 1500, 3000, fine_deadline)
                rh = R_of(hh)
                if rh > fineR + 1e-15:
                    fine_best, fineR = hh, rh
                    improved = True
                    print("fine unzero R=%.7f" % fineR)
            # Coarse escape after a non-improving fine cycle.
            if not improved:
                if time.process_time() >= fine_deadline - 1.5:
                    break
                n = fine_best.size
                if n % 2 == 0:
                    hc = 0.5 * (fine_best[0::2] + fine_best[1::2])
                else:
                    hc = fine_best.copy()
                hc = _prune(hc, 1e-4)
                hc = _exact_lbfgs(hc, 400, 800, fine_deadline)
