                hc = _exact_lbfgs(hc, 400, 800, fine_deadline)
                hc = run_direct(hc, 1e6, 400, 800, fine_deadline)
                if time.process_time() >= fine_deadline - 1.5:
                    break
                hup = _rescale_maxL(np.repeat(hc, 2))
                hup = _exact_lbfgs(hup, 800, 1600, fine_deadline)
                rup = R_of(hup)
                if rup > fineR + 1e-15:
                    fine_best, fineR = hup, rup
                    print("coarse escape R=%.7f" % fineR)
                    continue
                else:
                    print("coarse escape failed R=%.7f" % rup)
                    break
        print("fine final R=%.7f (N=%d)" % (fineR, fine_best.size))
        if fineR > bestR:
            best, bestR = fine_best.copy(), fineR

    # Coarse ladder with any leftover time; skip it for already-fine starts.
    if best.size < 80000:
        if best.size < 100000:
            cand = _rescale_maxL(_upsample(best, 2))
            r = R_of(cand)
            if r > bestR - 1e-6:
                best, bestR = cand, max(r, bestR)
                print("upsample R=%.7f (N=%d)" % (bestR, best.size))

        betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
        cycle = 0
        while time.process_time() < deadline - 1.5:
            cycle += 1
            any_improved = False
            for beta in betas:
                if time.process_time() >= deadline - 1.5:
                    break
                h = run_direct(best, beta, 1200, 2400, deadline)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    any_improved = True
                if time.process_time() >= deadline - 1.5:
                    break
                h2 = _exact_lbfgs(best, 600, 1200, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-15:
                    best, bestR = h2.copy(), r2
                    any_improved = True
                    print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
            if not any_improved:
                break

    if time.process_time() < deadline - 1.5:
        for frac in [1e-3, 1e-2, 3e-2]:
            if time.process_time() >= deadline - 1.5:
                break
            hh = _unzero(best, frac)
            hh = _exact_lbfgs(hh, 600, 1200, deadline)
            hh = run_direct(hh, 1e5, 400, 800, deadline)
            hh = _exact_lbfgs(hh, 600, 1200, deadline)
            r = R_of(hh)
            if r > bestR + 1e-15:
                best, bestR = hh.copy(), r
                print("unzero frac %.0e R=%.7f" % (frac, bestR))
            else:
                break

    hard = t0 + budget_seconds * 0.96
    while time.process_time() < hard - 1.0:
        h2 = _exact_lbfgs(best, 4000, 8000, hard - 0.5)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


def _exact_lbfgs(h0, deadline, maxiter=4000, maxfun=8000):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 0.5:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return h0
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Exact normalisation-free L-BFGS on start.
    h = _exact_lbfgs(best, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact-start R=%.6f (N=%d)" % (bestR, best.size))

    # Ladder of refinements; at each level optimise then double resolution.
    while time.process_time() < deadline - 1.0:
        if best.size < 100000 and time.process_time() < deadline - 2.0:
            up = _upsample(best, 2)
            up = _rescale_maxL(up)
            hu = _exact_lbfgs(up, deadline)
            ru = R_of(hu)
            if ru > bestR + 1e-12:
                best, bestR = hu.copy(), ru
                print("up2 R=%.6f (N=%d)" % (bestR, best.size))
            else:
                # try continuing from current best directly (re-opt)
                hb = _exact_lbfgs(best, deadline)
                rb = R_of(hb)
                if rb > bestR + 1e-13:
                    best, bestR = hb.copy(), rb
                    print("reopt R=%.6f (N=%d)" % (bestR, best.size))
                else:
                    break
        else:
            break

    best = best / best.max()
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

