def _window_polish(h, deadline, frac=0.25, extra=4):
    """Polish indices near the peak-knot support of f*f."""
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact equality-constrained polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # Phase 2: windowed polish (fewer variables, denser convergence) and
    # unzero perturbations interleaved.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 4:
        improved = False
        for frac in (0.25, 0.5, 1.0):
            if time.process_time() >= deadline - 2.0:
                break
            cand = _window_polish(best, deadline, frac=frac)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
        if time.process_time() < deadline - 2.0:
            hh = _unzero(best, 1e-3)
            hh = _exact_lbfgs(hh, 800, 1600, deadline)
            r = R_of(hh)
            if r > bestR + 1e-16:
                best, bestR = hh, r
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1
    print("phase2 R=%.7f" % bestR)

    # Phase 3: try upsampling if there is room, then polish.
    if best.size * 2 <= 200000 and time.process_time() < deadline - 3.0:
        cand = _rescale_maxL(np.repeat(best, 2))
        r = R_of(cand)
        if r > bestR - 1e-9:
            cand2 = _exact_lbfgs(cand, 2000, 4000, deadline)
            r2 = R_of(cand2)
            if r2 > bestR + 1e-16:
                best, bestR = cand2, r2
                print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 4: final intensive polish.
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 6000, 12000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("final R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1200:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1200:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1200:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _free_set(h, nfree_cap=6000):
    n = h.size
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    free = np.zeros(n, dtype=bool)
    k = min(24, n)
    top = np.argpartition(h, -k)[-k:]
    for idx in top:
        lo = max(0, idx - 80); hi = min(n, idx + 81)
        free[lo:hi] = True
    lo_r = m - n + 1
    a_lo = max(0, lo_r); a_hi = min(n - 1, lo_r + 250)
    if a_hi >= a_lo:
        free[a_lo:a_hi + 1] = True
    b_lo = max(0, m - 250); b_hi = min(n - 1, m)
    if b_hi >= b_lo:
        free[b_lo:b_hi + 1] = True
    gLf = -dq / num
    gLf[m] += 1.0
    grad = _backprop(gLf, h)
    kk = min(3000, n)
    topg = np.argpartition(np.abs(grad), -kk)[-kk:]
    free[topg] = True
    idxs = np.nonzero(free)[0]
    if idxs.size > nfree_cap:
        sel = idxs[np.argpartition(np.abs(grad[idxs]), -nfree_cap)[-nfree_cap:]]
        free[:] = False
        free[sel] = True
    return free


def _refine_local(h, deadline):
    """Coordinate-wise local refinement of a fine grid: try small shifts of
    mass between neighbouring cells to nudge R up, guarding exact R."""
    h = h.copy()
    n = h.size
    bestR = R_of(h)
    # Try smoothing / sharpening via small convolution-like mixing of neighbours.
    for it in range(6):
        if time.process_time() >= deadline - 0.6:
            break
        improved = False
        for w in (0.02, 0.005, 0.001):
            for sign in (1.0, -1.0):
                if time.process_time() >= deadline - 0.6:
                    break
                hh = h.copy()
                # apply local curvature tweak: h += sign*w*(neighbor avg - h)
                nb = np.concatenate(([hh[0]], hh[:-1])) + np.concatenate((hh[1:], [hh[-1]]))
                hh = np.clip(hh + sign * w * (0.5 * nb - hh), 0, None)
                if hh.sum() <= 0:
                    continue
                r = R_of(hh)
                if r > bestR + 1e-13:
                    h, bestR = hh, r
                    improved = True
        if not improved:
            break
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.9f (N=%d)" % (bestR, best.size))

    def try_update(h):
        nonlocal best, bestR
        if h.size == 0 or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            return True
        return False

    # Main change: ZOH-doubling to escape discretisation, then restricted polish.
    h2 = np.repeat(best, 2)
    h2 = _rescale_maxL(h2)
    r2 = R_of(h2)
    print("doubled R=%.9f vs %.9f (N=%d)" % (r2, bestR, h2.size))
    if r2 > bestR + 1e-13:
        best, bestR = h2, r2

    # Exact full polish on the doubled representation.
    h = run_direct(best, 1e6, 800, 1600, deadline)
    if try_update(h):
        print("direct R=%.9f (N=%d)" % (bestR, best.size))

    # Restricted-mask polish over a beta continuation.
    betas = (300, 2000, 10000, 50000)
    cur = best.copy()
    while time.process_time() < deadline - 1.5:
        free = _free_set(cur)
        for beta in betas:
            if time.process_time() >= deadline - 1.0:
                break
            cur = run_direct(cur, beta, 400, 800, deadline)
            if try_update(cur):
                print("mask beta=%g R=%.9f (N=%d)" % (beta, bestR, best.size))
        if not np.array_equal(cur, best):
            cur = best.copy()
        else:
            break

    # Final stiff-mu continuation in logM form, on the best.
    h = best.copy()
    for beta in (1e5, 1e6, 1e7, 1e8):
        if time.process_time() >= deadline - 0.5:
            break
        h = run_direct(h, beta, 300, 600, deadline)
        if try_update(h):
            print("stiff beta=%g R=%.9f (N=%d)" % (beta, bestR, best.size))

    # NEW: local neighbour-mixing refinement to squeeze out small gains.
    if time.process_time() < deadline - 1.0:
        h, r = _refine_local(best, deadline)
        if try_update(h):
            print("local R=%.9f (N=%d)" % (bestR, best.size))

    best = best / best.max()
    print("final R=%.9f (N=%d)" % (bestR, best.size))
    return best

