        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_avg(h, k):
    n = (h.size // k) * k
    return h[:n].reshape(-1, k).sum(1)


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0

    def f(x):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)

    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    mask = (h <= 0)
    out = h.copy()
    out[mask] = out[mask] + frac * m
    return out


def _perturb(h, m, sigma, rng):
    cand = h.copy()
    pos = np.flatnonzero(cand > 0)
    if pos.size == 0:
        return cand
    k = min(m, pos.size)
    idx = rng.choice(pos, size=k, replace=False)
    factors = np.exp(rng.normal(0.0, sigma, size=k))
    factors = np.clip(factors, 0.2, 5.0)
    cand[idx] = cand[idx] * factors
    return cand


def construct(budget_seconds, start):
    t0 = time.process_time()
    fine_deadline = t0 + budget_seconds * 0.80
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    rng = np.random.default_rng(12345)

    # Fine-grid phase
    fine_best = None
    fineR = -1.0
    if best.size * 2 <= 100000 and best.size < 60000:
        h2 = _rescale_maxL(np.repeat(best, 2))
        fine_best = h2
        fineR = R_of(h2)
        print("fine start R=%.7f (N=%d)" % (fineR, fine_best.size))
        cycle = 0
        while time.process_time() < fine_deadline - 1.5:
            cycle += 1
            cand = _exact_lbfgs(fine_best, 1500, 3000, fine_deadline)
            cand = run_direct(cand, 1e6, 800, 1600, fine_deadline)
            cand = _exact_lbfgs(cand, 1500, 3000, fine_deadline)
            r = R_of(cand)
            improved = r > fineR + 1e-15
            if improved:
                fine_best, fineR = cand, r
                print("fine cycle %d R=%.7f" % (cycle, fineR))
            else:
                # perturbation-escape block
                for _round in range(8):
                    if time.process_time() >= fine_deadline - 1.5:
                        break
                    pc = _perturb(fine_best, 400, 0.08, rng)
                    pc = _rescale_maxL(pc)
                    pc = _exact_lbfgs(pc, 250, 500, fine_deadline)
                    pc = run_direct(pc, 1e6, 200, 400, fine_deadline)
                    pc = _exact_lbfgs(pc, 250, 500, fine_deadline)
                    rp = R_of(pc)
                    if rp > fineR + 1e-15:
                        fine_best, fineR = pc, rp
                        improved = True
                        print("pert R=%.7f" % fineR)
