    out = h.copy()
    out[h <= 0] += frac * m
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: equality-constrained L-BFGS at native resolution.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-17:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # Phase 2: windowed polish around the peak-support of f*f, plus unzero.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 4:
        improved = False
        for frac in (0.25, 0.5, 1.0):
            if time.process_time() >= deadline - 2.0:
                break
            cand = _window_polish(best, deadline, frac=frac)
            r = R_of(cand)
            if r > bestR + 1e-17:
                best, bestR = cand, r
                improved = True
        if time.process_time() < deadline - 2.0:
            for uf in (1e-4, 1e-3):
                cand = _unzero(best, uf)
                cand = _exact_lbfgs(cand, 1500, 3000, deadline)
                r = R_of(cand)
                if r > bestR + 1e-17:
                    best, bestR = cand, r
                    improved = True
                    break
        stall = 0 if improved else stall + 1
    print("phase2 R=%.7f" % bestR)

    # Phase 3: final full polish until deadline.
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 4000, 8000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-17:
            best, bestR = cand, r
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

