def _block_avg(h, k):
    n = (h.size // k) * k
    return h[:n].reshape(-1, k).sum(1)


def _window_polish(h, deadline, frac=0.10):
    """Exact L-BFGS on indices within a window around the argmax-knot's support."""
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))  # in Lf index; equals convolution index + 1
    # support of h contributing to Lf[m]: indices around m-1
    c = m - 1
    half = max(4, int(frac * n))
    lo = max(0, c - half)
    hi = min(n, c + half + 1)
    free = np.arange(lo, hi)
    if free.size >= n:
        return h
    h2 = _exact_lbfgs(h, 800, 1600, deadline, free=free)
    r2 = R_of(h2)
    if r2 >= R_of(h):
        return h2
    return h


def construct(budget_seconds, start):
