    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _local_pair_gradient(h, rng, nsample, step):
    """Stochastic coordinate ascent on adjacent-pair mass transfer."""
    n = h.size
    if n < 2:
        return h
    h = h.copy()
    # sample random adjacent pairs
    idx = rng.integers(0, n - 1, size=nsample)
    for j in idx:
        if h[j] <= 0 and h[j + 1] <= 0:
            continue
        # try +/- step transfer
        best_delta = 0.0
        best_r = R_of(h)
        for sgn in (1.0, -1.0):
            t = sgn * step * (h[j] + h[j + 1] + 1e-12)
            if h[j] - t < 0 or h[j + 1] + t < 0:
                continue
            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 3.0 and stall < 2:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # Phase 2: stochastic adjacent-pair mass transfer to escape basin,
    # then re-polish.
    rng = np.random.default_rng(987654321)
    for k in range(4):
        if time.process_time() >= deadline - 4.0:
            break
        hh = best.copy()
        for step in (2e-3, 5e-4, 1e-4):
            hh = _local_pair_gradient(hh, rng, nsample=400, step=step)
            if time.process_time() >= deadline - 4.0:
                break
        hh = _exact_lbfgs(hh, 1500, 3000, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
            print("transfer %d R=%.7f" % (k + 1, bestR))
        else:
            hh = _unzero(best, 2e-4)
            hh = _exact_lbfgs(hh, 1000, 2000, deadline)
            r = R_of(hh)
            if r > bestR + 1e-16:
                best, bestR = hh, r
                print("unzero %d R=%.7f" % (k + 1, bestR))

    # Phase 3: windowed polish around peak-region.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        improved = False
        for frac in (0.15, 0.35, 0.7):
            if time.process_time() >= deadline - 2.0:
                break
            cand = _window_polish(best, deadline, frac=frac)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1
    print("phase3 R=%.7f" % bestR)

    # Phase 4: final intensive full polish.
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 6000, 12000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("final R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # tight refinement ladder: exact gradient polish first (most reliable),
    # then increasing-beta smooth-max refinements.
    betas = [1e5, 3e5, 1e6, 3e6, 1e7, 3e7]
    cycle = 0
    topk_done = False
    while time.process_time() < deadline - 1.5:
        cycle += 1
        any_improved = False
        # exact polish first (fast convergence near optimum)
        h2 = _exact_lbfgs(best, 1500, 3000, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-15:
            best, bestR = h2.copy(), r2
            any_improved = True
            print("cycle %d exact R=%.7f" % (cycle, bestR))
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = run_direct(best, beta, 1200, 2400, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            if time.process_time() >= deadline - 1.5:
                break
            h2 = _exact_lbfgs(best, 800, 1600, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
                print("cycle %d beta %.0e R=%.7f" % (cycle, beta, bestR))
        if not any_improved:
            if not topk_done:
                topk_done = True
                for k in [2000, 500, 100, 20, 5, 1]:
                    if time.process_time() >= deadline - 1.5:
                        break
                    hk = run_topk(best, k, 400, 800, deadline)
                    hk = _exact_lbfgs(hk, 400, 800, deadline)
                    rk = R_of(hk)
                    if rk > bestR + 1e-15:
                        best, bestR = hk.copy(), rk
                        print("topk k=%d R=%.7f" % (k, bestR))
                if time.process_time() < deadline - 1.5:
                    continue
            break

    # Final long exact polish.
    end = t0 + budget_seconds * 0.97
    while time.process_time() < end:
        h2 = _exact_lbfgs(best, 4000, 8000, deadline=end)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

