import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _shift_resample(h, shift, factor):
    # resample to finer grid with a sub-cell alignment shift (in old units)
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m) + shift
    return np.interp(xo, np.arange(n), h, left=0.0, right=0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    hard = t0 + budget_seconds * 0.97

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Polish native resolution.
    while time.process_time() < deadline - 3.0:
        cand = _exact_lbfgs(best, 4000, 8000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            break
    print("native polish R=%.7f" % bestR)

    # Resolution upgrade: upsample (with a few sub-cell shifts) and re-optimise.
    # Try multiple shifts so we don't get stuck at a bad interpolation phase.
    while time.process_time() < deadline - 4.0 and best.size < 190000:
        improved = False
        for shift in (0.0, 0.25, 0.5, 0.75):
            if time.process_time() >= deadline - 4.0:
                break
            cand = _rescale_maxL(_shift_resample(best, shift, 2))
            cand = _exact_lbfgs(cand, 3000, 6000, deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("upsample R=%.7f (N=%d, shift=%.2f)" % (bestR, best.size, shift))
                improved = True
                for _ in range(2):
                    c2 = _exact_lbfgs(best, 3000, 6000, deadline)
                    r2 = R_of(c2)
                    if r2 > bestR + 1e-16:
                        best, bestR = c2, r2
                    else:
                        break
                break
        if not improved:
            break

    # Final exact polish until near the hard stop.
    while time.process_time() < hard - 1.5:
        c = _exact_lbfgs(best, 4000, 8000, hard - 1.0)
        r = R_of(c)
        if r > bestR + 1e-16:
            best, bestR = c, r
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

