    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _pair_transfer(h, bestR, deadline, rng, npairs=200, top_frac=0.05):
    h = h.copy()
    n = h.size
    if n < 2:
        return h, bestR
    thresh = np.quantile(h, 1.0 - top_frac)
    cand = np.flatnonzero(h >= thresh)
    cand = cand[cand < n - 1]
    cand = cand[(h[cand] > 0) & (h[cand + 1] > 0)]
    if cand.size == 0:
        return h, bestR
    invphi = (np.sqrt(5.0) - 1.0) / 2.0

    def eval_pair(j, t):
        hh = h.copy()
        hh[j] = h[j] - t
        hh[j + 1] = h[j + 1] + t
        if hh[j] < 0 or hh[j + 1] < 0:
            return -1.0
        return R_of(hh)

    for _ in range(npairs):
        if time.process_time() >= deadline:
            break
        j = int(cand[rng.integers(0, cand.size)])
        lo = -h[j + 1]
        hi = h[j]
        if hi <= lo:
            continue
        a, b = lo, hi
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_pair(j, c)
        fd = eval_pair(j, d)
        for _k in range(7):
            if time.process_time() >= deadline:
                break
            if fc > fd:
                b, d, fd = d, c, fc
                c = b - invphi * (b - a)
                fc = eval_pair(j, c)
            else:
                a, c, fc = c, d, fd
                d = a + invphi * (b - a)
                fd = eval_pair(j, d)
        tbest = 0.5 * (a + b)
        rbest = eval_pair(j, tbest)
        if rbest > bestR + 1e-15:
            h[j] = h[j] - tbest
            h[j + 1] = h[j + 1] + tbest
            bestR = rbest
    return h, bestR


