    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 1: exact L-BFGS polishing on the given grid.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    # Stage 2: window polish near the peak (peak-shaving region).
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Stage 3: pair-transfer (mass reallocation) phase.
    if time.process_time() < deadline - 3.0:
        best, bestR = _pair_transfer(best, bestR, deadline - 2.0, rng, npairs=400)
        print("pair R=%.7f" % bestR)
        h = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h.copy(), r
            print("pair-exact R=%.7f" % bestR)

    # Stage 4: fine-grid upsampling refinement if N allows.
    if best.size * 2 <= 100000 and time.process_time() < deadline - 3.0:
        fine = _upsample(best, 2)
        fine = _exact_lbfgs(fine, 400, 800, deadline)
        rf = R_of(fine)
        if rf > bestR:
            best, bestR = fine.copy(), rf
            print("fine R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 5: alternate window polish + exact until budget exhausted.
    while time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline)
        r = R_of(h)
        improved = False
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            improved = True
            print("final window R=%.7f" % bestR)
        if time.process_time() >= deadline - 2.0:
            break
        h2 = _exact_lbfgs(best, 1500, 3000, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            improved = True
            print("final exact R=%.7f" % bestR)
        if not improved:
            break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

