def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _active_trust_ncg(h, deadline, n_grad, n_height, maxiter=60):
    if time.process_time() >= deadline - 2.0:
        return h
    h = np.asarray(h, dtype=float)
    n = h.size
    val0, g0 = _norm_eq_fun_grad(h)
    if not np.isfinite(val0):
        return h
    ag = np.argsort(-np.abs(g0))[:n_grad]
    ah = np.argsort(-h)[:n_height]
    free = np.unique(np.concatenate([ag, ah]))
    if free.size == 0:
        return h
    u0 = np.log(np.clip(h[free], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[free] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[free] * hh[free]

    def hessp(u, v):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        eps = 1e-6
        uu = np.clip(u, -30.0, 30.0)
        up = np.clip(uu + eps * v, -30.0, 30.0)
        um = np.clip(uu - eps * v, -30.0, 30.0)
        hp = np.zeros(n); hp[free] = np.exp(up)
        hm = np.zeros(n); hm[free] = np.exp(um)
        _, gp = _norm_eq_fun_grad(hp)
        _, gm = _norm_eq_fun_grad(hm)
        gup = gp[free] * hp[free]
        gum = gm[free] * hm[free]
        return (gup - gum) / (2.0 * eps)

    try:
        res = minimize(f, u0, jac=True, hessp=hessp, method='trust-ncg',
                       options={'maxiter': maxiter, 'gtol': 1e-12},
                       tol=1e-14)
        h2 = np.zeros(n)
        h2[free] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return h
    except Exception:
        return h


