                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _local_pair_gradient(h, rng, nsample, step):
    n = h.size
    if n < 2:
        return h
    h = h.copy()
    idx = rng.integers(0, n - 1, size=nsample)
    for j in idx:
        if h[j] <= 0 and h[j + 1] <= 0:
            continue
        best_delta = 0.0
        best_r = R_of(h)
        for sgn in (1.0, -1.0):
            t = sgn * step * (h[j] + h[j + 1] + 1e-12)
            if h[j] - t < 0 or h[j + 1] + t < 0:
                continue
            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
    return h


def _long_range_transfer(h, rng, deadline, max_trials=400):
    h = h.copy()
    n = h.size
    if n < 2:
        return h
    bestR = R_of(h)
    k = max(1, int(0.05 * n))
    top_idx = np.argpartition(h, -k)[-k:]
    invphi = (np.sqrt(5.0) - 1.0) / 2.0

    for trial in range(max_trials):
        if time.process_time() >= deadline:
            break
        i = int(top_idx[rng.integers(0, top_idx.size)])
        j = int(rng.integers(0, n))
        if j == i:
            continue
        hi = h[i]; hj = h[j]
        if hi <= 0 and hj <= 0:
            continue
        lo_t = -hj
        hi_t = hi
        if hi_t <= lo_t:
            continue

        def eval_t(t):
            hh = h.copy()
            hh[i] -= t
            hh[j] += t
            return R_of(hh)

        a = lo_t; b = hi_t
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        best_t = 0.0
        best_val = bestR
        for _ in range(7):
            if fc > fd:
                b = d; d = c; fd = fc
                c = b - invphi * (b - a)
                fc = eval_t(c)
                if fc > best_val:
                    best_val = fc; best_t = c
            else:
                a = c; c = d; fc = fd
                d = a + invphi * (b - a)
                fd = eval_t(d)
                if fd > best_val:
                    best_val = fd; best_t = d
        if best_val > bestR + 1e-16:
            h[i] -= best_t
            h[j] += best_t
            bestR = best_val

        if (trial + 1) % 50 == 0:
            if time.process_time() >= deadline:
                break
            h = _exact_lbfgs(h, 300, 600, deadline)
            r = R_of(h)
            if r > bestR:
                bestR = r
    return h


def _global_surrogate_polish(h, deadline):
    if time.process_time() >= deadline - 1.0:
        return h
    return _exact_lbfgs(h, 4000, 8000, deadline)


def _coarsen_solve(h, factor, deadline, maxiter, maxfun):
    """Block-average by `factor`, exact-LBFGS solve, upsample back."""
    n = h.size
    if n % factor != 0:
        return h
    coarse = h.reshape(-1, factor).mean(axis=1)
    coarse = _rescale_maxL(coarse)
    coarse = _exact_lbfgs(coarse, maxiter, maxfun, deadline)
    up = np.repeat(coarse, factor)
    return up


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # === NEW: factor-4 coarsening basin path ===
    d4 = t0 + budget_seconds * 0.45
    if time.process_time() < d4 - 1.0:
        up = _coarsen_solve(best, 4, d4, 2000, 4000)
        d4b = t0 + budget_seconds * 0.70
        up = _exact_lbfgs(up, 1500, 3000, d4b)
        r = R_of(up)
        if r > bestR + 1e-16:
            best, bestR = up, r
            print("coarse4 R=%.7f" % bestR)
        else:
            print("coarse4 R=%.7f (no gain)" % bestR)

    # === NEW: factor-8 coarsening basin path ===
    d8 = t0 + budget_seconds * 0.80
    if time.process_time() < d8 - 1.0:
        up = _coarsen_solve(best, 8, d8, 1500, 3000)
        up = _exact_lbfgs(up, 1000, 2000, d8)
        r = R_of(up)
        if r > bestR + 1e-16:
            best, bestR = up, r
            print("coarse8 R=%.7f" % bestR)
        else:
            print("coarse8 R=%.7f (no gain)" % bestR)

    # === Fallback: p0357's transfer/window machinery, time permitting ===
    long_deadline = min(t0 + budget_seconds * 0.85, deadline - 3.0)
    if time.process_time() < long_deadline:
        rng_lr = np.random.default_rng(1357911)
        cand = _long_range_transfer(best, rng_lr, long_deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        print("long transfer R=%.7f" % bestR)

    rng = np.random.default_rng(987654321)
    for k in range(2):
        if time.process_time() >= deadline - 4.0:
            break
        hh = best.copy()
        for step in (2e-3, 5e-4):
            hh = _local_pair_gradient(hh, rng, nsample=400, step=step)
            if time.process_time() >= deadline - 4.0:
                break
        hh = _exact_lbfgs(hh, 1000, 2000, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
            print("transfer %d R=%.7f" % (k + 1, bestR))

    # === Final polish loop: alternate exact-LBFGS and window polish to deadline ===
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish(best, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            # no progress this round; try a small unzero perturbation
            if time.process_time() >= deadline - 1.0:
                break
            cand = _unzero(best, 1e-5)
            cand = _exact_lbfgs(cand, 600, 1200, deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
            else:
                break
    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR < R_of(base):
        best, bestR = base, R_of(base)
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _local_pair_gradient(h, rng, nsample, step):
    n = h.size
    if n < 2:
        return h
    h = h.copy()
    idx = rng.integers(0, n - 1, size=nsample)
    for j in idx:
        if h[j] <= 0 and h[j + 1] <= 0:
            continue
        best_delta = 0.0
        best_r = R_of(h)
        for sgn in (1.0, -1.0):
            t = sgn * step * (h[j] + h[j + 1] + 1e-12)
            if h[j] - t < 0 or h[j + 1] + t < 0:
                continue
            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
    return h


def _long_range_transfer(h, rng, deadline, max_trials=400):
    h = h.copy()
    n = h.size
    if n < 2:
        return h
    bestR = R_of(h)
    k = max(1, int(0.05 * n))
    top_idx = np.argpartition(h, -k)[-k:]
    invphi = (np.sqrt(5.0) - 1.0) / 2.0

    for trial in range(max_trials):
        if time.process_time() >= deadline:
            break
        i = int(top_idx[rng.integers(0, top_idx.size)])
        j = int(rng.integers(0, n))
        if j == i:
            continue
        hi = h[i]; hj = h[j]
        if hi <= 0 and hj <= 0:
            continue
        lo_t = -hj
        hi_t = hi
        if hi_t <= lo_t:
            continue

        def eval_t(t):
            hh = h.copy()
            hh[i] -= t
            hh[j] += t
            return R_of(hh)

        a = lo_t; b = hi_t
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        best_t = 0.0
        best_val = bestR
        for _ in range(7):
            if fc > fd:
                b = d; d = c; fd = fc
                c = b - invphi * (b - a)
                fc = eval_t(c)
                if fc > best_val:
                    best_val = fc; best_t = c
            else:
                a = c; c = d; fc = fd
                d = a + invphi * (b - a)
                fd = eval_t(d)
                if fd > best_val:
                    best_val = fd; best_t = d
        if best_val > bestR + 1e-16:
            h[i] -= best_t
            h[j] += best_t
            bestR = best_val

        if (trial + 1) % 50 == 0:
            if time.process_time() >= deadline:
                break
            h = _exact_lbfgs(h, 300, 600, deadline)
