        return val, gc

    try:
        if time.process_time() < deadline - 1.0:
            res = minimize(fc, c, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * nB,
                           options={'maxiter': iters_c, 'maxfun': 2 * iters_c,
                                    'ftol': 1e-20, 'gtol': 1e-16})
