    def fd(dvec):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        hh = build_h(c, dvec)
        val, g = _norm_eq_fun_grad(hh)
        gu = g * hh
        gu[n:] = 0.0
        bm = gu.reshape(nB, B).mean(axis=1)
        gd = gu - np.repeat(bm, B)
        gd[n:] = 0.0
        return val, gd

    try:
        if time.process_time() < deadline - 1.0:
            res = minimize(fd, d, jac=True, method='L-BFGS-B',
                           bounds=[(-60.0, 60.0)] * npad,
                           options={'maxiter': iters_d, 'maxfun': 2 * iters_d,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            d = np.clip(res.x, -60.0, 60.0)
    except TimeoutError:
        return _rescale_maxL(h)

    return build_h(c, d)


def _anneal_perturb(h, rng, deadline, iters=200):
    """Accept-ever-better perturb + polish at small scale to escape local min."""
    best = h.copy()
    bestR = R_of(best)
    n = h.size
    k = max(1, n // 200)
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        hh = best.copy()
        idx = rng.integers(0, n, size=k)
        amp = 1e-3 * hh.max()
        hh[idx] = np.clip(hh[idx] + rng.normal(0, amp, size=k), 0, None)
        hh = _exact_lbfgs(hh, 200, 400, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    long_deadline = t0 + budget_seconds * 0.50

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    stall = 0
    while time.process_time() < deadline - 3.0 and stall < 2:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    for B, iters_c, iters_d in ((64, 300, 300), (256, 300, 300), (16, 300, 300)):
        if time.process_time() >= deadline - 3.0:
            break
        cand = _two_scale(best, B, iters_c, iters_d, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("two-scale B=%d R=%.7f" % (B, bestR))
        else:
            print("two-scale B=%d R=%.7f (no gain)" % (B, bestR))

    if time.process_time() < deadline - 2.0:
        cand = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("post two-scale polish R=%.7f" % bestR)

    cand = _global_surrogate_polish(best, deadline)
    r = R_of(cand)
    if r > bestR + 1e-16:
        best, bestR = cand, r
    print("global polish R=%.7f" % bestR)

    rng_lr = np.random.default_rng(1357911)
    if time.process_time() < long_deadline:
        cand = _long_range_transfer(best, rng_lr, long_deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        print("long transfer R=%.7f" % bestR)
    else:
        print("long transfer R=%.7f (skipped)" % bestR)

    rng = np.random.default_rng(987654321)
    for k in range(4):
        if time.process_time() >= deadline - 4.0:
            break
        hh = best.copy()
        for step in (2e-3, 5e-4, 1e-4):
            hh = _local_pair_gradient(hh, rng, nsample=400, step=step)
            if time.process_time() >= deadline - 4.0:
                break
        hh = _exact_lbfgs(hh, 1500, 3000, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
            print("transfer %d R=%.7f" % (k + 1, bestR))
        else:
            hh = _unzero(best, 2e-4)
            hh = _exact_lbfgs(hh, 1000, 2000, deadline)
            r = R_of(hh)
            if r > bestR + 1e-16:
                best, bestR = hh, r
                print("unzero %d R=%.7f" % (k + 1, bestR))

    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        improved = False
        for frac in (0.15, 0.35, 0.7):
            if time.process_time() >= deadline - 2.0:
                break
            cand = _window_polish(best, deadline, frac=frac)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
                print("window %.2f R=%.7f" % (frac, bestR))
        if not improved:
            stall += 1

    # NEW: anneal-perturb + polish loop to escape local minima until near deadline.
    rng_a = np.random.default_rng(424242)
    while time.process_time() < deadline - 2.5:
        cand = _anneal_perturb(best, rng_a, deadline - 1.5, iters=20)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("anneal R=%.7f" % bestR)
        # also try a final full polish of current best
        if time.process_time() < deadline - 2.0:
            cand = _exact_lbfgs(best, 800, 1600, deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("final polish R=%.7f" % bestR)

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _shift_subpixel(h, shift):
    """Resample h onto a grid shifted by `shift` steps (fractional)."""
    n = h.size
    xo = np.arange(n) + shift
    xo = np.clip(xo, 0, n - 1)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact full polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 6.0 and stall < 2:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # Phase 2: try a sub-pixel shift of the grid (breaks the symmetry that
    # keeps LBFGS stuck at a fixed knot alignment), then re-polish.
    if time.process_time() < deadline - 8.0:
        for shift in (0.5, -0.5, 0.25, -0.25, 0.75, -0.75):
            if time.process_time() >= deadline - 6.0:
                break
            hs = _shift_subpixel(best, shift)
            hs = _rescale_maxL(hs)
            cand = _exact_lbfgs(hs, 3000, 6000, deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("shift %.2f R=%.7f" % (shift, bestR))

    # Phase 3: try upsampling to higher N.
    if best.size < 200000 and time.process_time() < deadline - 6.0:
        for f in (2,):
            if time.process_time() >= deadline - 6.0:
                break
            up = _upsample(best, f)
            up = _rescale_maxL(up)
            cand = _exact_lbfgs(up, 3000, 6000, deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("upsample x%d R=%.7f" % (f, bestR))
            else:
                print("upsample x%d no gain (%.7f vs %.7f)" % (f, r, bestR))

    # Phase 4: windowed polish around the peak region.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        improved = False
        n = best.size
        Lf = _knots(best)
        m = int(np.argmax(Lf))
        lo = max(0, m - 1 - (n - 1))
        hi = min(n - 1, m - 1)
        if hi >= lo:
            for frac in (0.15, 0.35, 0.7):
                if time.process_time() >= deadline - 2.0:
                    break
                pad = max(4, int((hi - lo) * frac))
                l2 = max(0, lo - pad)
                h2 = min(n - 1, hi + pad)
                free = np.arange(l2, h2 + 1)
                cand = _exact_lbfgs(best, 800, 1600, deadline, free=free)
                r = R_of(cand)
                if r > bestR + 1e-16:
                    best, bestR = cand, r
                    improved = True
        if improved:
            stall = 0
        else:
            stall += 1
    print("phase4 R=%.7f" % bestR)

    # Phase 5: final intensive full polish.
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 6000, 12000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("final R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

