        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh, m_override=m_override)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _local_pair_gradient(h, rng, nsample, step):
    n = h.size
    if n < 2:
        return h
    h = h.copy()
    idx = rng.integers(0, n - 1, size=nsample)
    for j in idx:
        if h[j] <= 0 and h[j + 1] <= 0:
            continue
        best_delta = 0.0
        best_r = R_of(h)
        for sgn in (1.0, -1.0):
            t = sgn * step * (h[j] + h[j + 1] + 1e-12)
            if h[j] - t < 0 or h[j + 1] + t < 0:
                continue
            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
    return h


def _long_range_transfer(h, rng, deadline, max_trials=400):
    h = h.copy()
    n = h.size
    if n < 2:
        return h
    bestR = R_of(h)
    k = max(1, int(0.05 * n))
    top_idx = np.argpartition(h, -k)[-k:]
    invphi = (np.sqrt(5.0) - 1.0) / 2.0

    for trial in range(max_trials):
        if time.process_time() >= deadline:
            break
        i = int(top_idx[rng.integers(0, top_idx.size)])
        j = int(rng.integers(0, n))
        if j == i:
            continue
        hi = h[i]; hj = h[j]
        if hi <= 0 and hj <= 0:
            continue
        lo_t = -hj
        hi_t = hi
        if hi_t <= lo_t:
            continue

        def eval_t(t):
            hh = h.copy()
            hh[i] -= t
            hh[j] += t
            return R_of(hh)

        a = lo_t; b = hi_t
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        best_t = 0.0
        best_val = bestR
        for _ in range(7):
            if fc > fd:
                b = d; d = c; fd = fc
                c = b - invphi * (b - a)
                fc = eval_t(c)
                if fc > best_val:
                    best_val = fc; best_t = c
            else:
                a = c; c = d; fc = fd
                d = a + invphi * (b - a)
                fd = eval_t(d)
                if fd > best_val:
                    best_val = fd; best_t = d
        if best_val > bestR + 1e-16:
            h[i] -= best_t
            h[j] += best_t
            bestR = best_val

        if (trial + 1) % 50 == 0:
            if time.process_time() >= deadline:
                break
            h = _exact_lbfgs(h, 300, 600, deadline)
            r = R_of(h)
            if r > bestR:
                bestR = r
    return h


def _global_surrogate_polish(h, deadline):
    if time.process_time() >= deadline - 1.0:
        return h
    return _exact_lbfgs(h, 4000, 8000, deadline)


def _frozen_m_explore(h, deadline, max_choices=6, seed=24681357):
    """Experiment: freeze a near-max knot, optimize, then true-max polish."""
    if time.process_time() >= deadline:
        return h
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    top = np.flatnonzero(Lf >= 0.95 * mx)
    if top.size <= 1:
        return h
    true_m = int(np.argmax(Lf))
    cands = [int(m) for m in top if int(m) != true_m]
    if not cands:
        return h
    rng = np.random.default_rng(seed)
    if len(cands) > max_choices:
        pick = rng.choice(len(cands), size=max_choices, replace=False)
        cands = [cands[int(i)] for i in pick]
    else:
        cands = cands[:max_choices]

    best = h.copy()
    bestR = R_of(h)
    for m in cands:
        if time.process_time() >= deadline:
            break
        hh = _exact_lbfgs(best, 400, 800, deadline, m_override=m)
        if time.process_time() >= deadline:
            break
        hh = _exact_lbfgs(hh, 1500, 3000, deadline)
        if time.process_time() >= deadline:
            break
        hh = _window_polish(hh, deadline, frac=0.35)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    long_deadline = t0 + budget_seconds * 0.50
    exp_deadline = t0 + budget_seconds * 0.50

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 3.0 and stall < 2:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # NEW EXPERIMENT: frozen near-max knot exploration.
    if time.process_time() < exp_deadline - 1.0:
        cand = _frozen_m_explore(best, exp_deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("frozen-m R=%.7f" % bestR)
        else:
            print("frozen-m no gain R=%.7f" % bestR)

    # Global full-index polish.
    cand = _global_surrogate_polish(best, deadline)
    r = R_of(cand)
    if r > bestR + 1e-16:
        best, bestR = cand, r
    print("global polish R=%.7f" % bestR)

    # Phase 1b: long-range (distant-pair) mass transfer.
    rng_lr = np.random.default_rng(1357911)
    if time.process_time() < long_deadline:
        cand = _long_range_transfer(best, rng_lr, long_deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        print("long transfer R=%.7f" % bestR)
    else:
        print("long transfer R=%.7f (skipped)" % bestR)

    # Phase 2: stochastic adjacent-pair mass transfer.
    rng = np.random.default_rng(987654321)
    for k in range(4):
        if time.process_time() >= deadline - 4.0:
            break
        hh = best.copy()
        for step in (2e-3, 5e-4, 1e-4):
            hh = _local_pair_gradient(hh, rng, nsample=400, step=step)
            if time.process_time() >= deadline - 4.0:
                break
        hh = _exact_lbfgs(hh, 1500, 3000, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
            print("transfer %d R=%.7f" % (k + 1, bestR))
        else:
            hh = _unzero(best, 2e-4)
            hh = _exact_lbfgs(hh, 1000, 2000, deadline)
            r = R_of(hh)
            if r > bestR + 1e-16:
                best, bestR = hh, r
                print("unzero %d R=%.7f" % (k + 1, bestR))

    # Phase 3: windowed polish around peak-region.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        improved = False
        for frac in (0.15, 0.35, 0.7):
            if time.process_time() >= deadline - 2.0:
                break
            cand = _window_polish(best, deadline, frac=frac)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1
    print("phase3 R=%.7f" % bestR)

    # Phase 4: final intensive full polish.
    while time.process_time() < deadline - 1.0:
        cand = _global_surrogate_polish(best, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("final R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _local_pair_gradient(h, rng, nsample, step):
    n = h.size
    if n < 2:
        return h
    h = h.copy()
    idx = rng.integers(0, n - 1, size=nsample)
    for j in idx:
        if h[j] <= 0 and h[j + 1] <= 0:
            continue
        best_delta = 0.0
        best_r = R_of(h)
        for sgn in (1.0, -1.0):
            t = sgn * step * (h[j] + h[j + 1] + 1e-12)
            if h[j] - t < 0 or h[j + 1] + t < 0:
                continue
            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
    return h


def _long_range_transfer(h, rng, deadline, max_trials=400):
    h = h.copy()
    n = h.size
    if n < 2:
        return h
    bestR = R_of(h)
    k = max(1, int(0.05 * n))
    top_idx = np.argpartition(h, -k)[-k:]
    invphi = (np.sqrt(5.0) - 1.0) / 2.0

    for trial in range(max_trials):
        if time.process_time() >= deadline:
            break
        i = int(top_idx[rng.integers(0, top_idx.size)])
        j = int(rng.integers(0, n))
        if j == i:
            continue
        hi = h[i]; hj = h[j]
        if hi <= 0 and hj <= 0:
            continue
        lo_t = -hj
        hi_t = hi
        if hi_t <= lo_t:
            continue

        def eval_t(t):
            hh = h.copy()
            hh[i] -= t
            hh[j] += t
            return R_of(hh)

        a = lo_t; b = hi_t
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        best_t = 0.0
        best_val = bestR
        for _ in range(7):
            if fc > fd:
                b = d; d = c; fd = fc
                c = b - invphi * (b - a)
                fc = eval_t(c)
                if fc > best_val:
                    best_val = fc; best_t = c
            else:
                a = c; c = d; fc = fd
                d = a + invphi * (b - a)
                fd = eval_t(d)
                if fd > best_val:
                    best_val = fd; best_t = d
        if best_val > bestR + 1e-16:
            h[i] -= best_t
            h[j] += best_t
            bestR = best_val

        if (trial + 1) % 50 == 0:
            if time.process_time() >= deadline:
                break
            h = _exact_lbfgs(h, 300, 600, deadline)
            r = R_of(h)
            if r > bestR:
                bestR = r
    return h


def _global_surrogate_polish(h, deadline):
    if time.process_time() >= deadline - 1.0:
        return h
    return _exact_lbfgs(h, 4000, 8000, deadline)


def _two_scale(h, B, iters_c, iters_d, deadline):
    if time.process_time() >= deadline - 1.0:
        return h
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n < 2 or h.sum() <= 0:
        return h
    nB = int(np.ceil(n / float(B)))
    npad = nB * B
    u_full = np.full(npad, -30.0)
    u_full[:n] = np.log(np.clip(h, 1e-300, None))
    c = u_full.reshape(nB, B).mean(axis=1)
    d = u_full - np.repeat(c, B)

    def build_h(cvec, dvec):
        uu = np.repeat(cvec, B) + dvec
        uu = np.clip(uu, -30.0, 30.0)
        hh = np.exp(uu)
        hh[n:] = 0.0
        return _rescale_maxL(hh)

    def fc(cvec):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        hh = build_h(cvec, d)
        val, g = _norm_eq_fun_grad(hh)
        gu = g * hh
        gu[n:] = 0.0
        gc = gu.reshape(nB, B).sum(axis=1)
        return val, gc

    try:
        if time.process_time() < deadline - 1.0:
            res = minimize(fc, c, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * nB,
                           options={'maxiter': iters_c, 'maxfun': 2 * iters_c,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            c = np.clip(res.x, -30.0, 30.0)
    except TimeoutError:
        return _rescale_maxL(h)

    def fd(dvec):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        hh = build_h(c, dvec)
        val, g = _norm_eq_fun_grad(hh)
        gu = g * hh
        gu[n:] = 0.0
        bm = gu.reshape(nB, B).mean(axis=1)
        gd = gu - np.repeat(bm, B)
        gd[n:] = 0.0
        return val, gd

    try:
        if time.process_time() < deadline - 1.0:
            res = minimize(fd, d, jac=True, method='L-BFGS-B',
                           bounds=[(-60.0, 60.0)] * npad,
                           options={'maxiter': iters_d, 'maxfun': 2 * iters_d,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            d = np.clip(res.x, -60.0, 60.0)
    except TimeoutError:
        return _rescale_maxL(h)

    return build_h(c, d)


def _box_smooth(h, w):
    """Mass-conserving box smoothing of width w (odd-ish), mode='same'."""
    if w <= 1:
        return h.copy()
    k = np.ones(w) / float(w)
    hs = np.convolve(h, k, mode='same')
    hs = np.clip(hs, 0, None)
    return _rescale_maxL(hs)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    long_deadline = t0 + budget_seconds * 0.50

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 3.0 and stall < 2:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # EXPERIMENT: box-smoothing escape at several widths.
    for w in (2, 4, 8, 16, 32):
        if time.process_time() >= deadline - 4.0:
            print("smooth w=%d skipped" % w)
            break
        hs = _box_smooth(best, w)
        cand = _exact_lbfgs(hs, 1200, 2400, deadline)
        if time.process_time() < deadline - 3.0:
            cand = _window_polish(cand, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("smooth w=%d R=%.7f (GAIN)" % (w, bestR))
        else:
            print("smooth w=%d R=%.7f (no gain)" % (w, bestR))

    # two-scale rounds (kept from base)
    for B, iters_c, iters_d in ((64, 300, 300), (256, 300, 300), (16, 300, 300)):
        if time.process_time() >= deadline - 3.0:
            break
        cand = _two_scale(best, B, iters_c, iters_d, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("two-scale B=%d R=%.7f" % (B, bestR))
        else:
            print("two-scale B=%d R=%.7f (no gain)" % (B, bestR))

    if time.process_time() < deadline - 2.0:
        cand = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("post two-scale polish R=%.7f" % bestR)

    cand = _global_surrogate_polish(best, deadline)
    r = R_of(cand)
    if r > bestR + 1e-16:
        best, bestR = cand, r
    print("global polish R=%.7f" % bestR)

