def _peak_region(h):
    """Return indices [lo, hi] of the flat-top region of f*f near its maximum."""
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    # support of f*f is knots index 0..2n-2 in Lf; heights of f index 0..n-1
    # The flat top corresponds to heights near the overlap center.
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    # map knot indices to f indices: knot k ~ overlap of h[k] and h[k-1]
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


