            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
    return h


def _long_range_transfer(h, rng, deadline, max_trials=400):
    h = h.copy()
    n = h.size
    if n < 2:
        return h
    bestR = R_of(h)
    k = max(1, int(0.05 * n))
    top_idx = np.argpartition(h, -k)[-k:]
    invphi = (np.sqrt(5.0) - 1.0) / 2.0

    for trial in range(max_trials):
        if time.process_time() >= deadline:
            break
        i = int(top_idx[rng.integers(0, top_idx.size)])
        j = int(rng.integers(0, n))
        if j == i:
            continue
        hi = h[i]; hj = h[j]
        if hi <= 0 and hj <= 0:
            continue
        lo_t = -hj
        hi_t = hi
        if hi_t <= lo_t:
            continue

        def eval_t(t):
            hh = h.copy()
            hh[i] -= t
            hh[j] += t
            return R_of(hh)

        a = lo_t; b = hi_t
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        best_t = 0.0
        best_val = bestR
        for _ in range(7):
            if fc > fd:
                b = d; d = c; fd = fc
                c = b - invphi * (b - a)
                fc = eval_t(c)
                if fc > best_val:
                    best_val = fc; best_t = c
            else:
                a = c; c = d; fc = fd
                d = a + invphi * (b - a)
                fd = eval_t(d)
                if fd > best_val:
                    best_val = fd; best_t = d
        if best_val > bestR + 1e-16:
            h[i] -= best_t
            h[j] += best_t
            bestR = best_val

        if (trial + 1) % 50 == 0:
            if time.process_time() >= deadline:
                break
            h = _exact_lbfgs(h, 300, 600, deadline)
            r = R_of(h)
            if r > bestR:
                bestR = r
    return h


def _global_surrogate_polish(h, deadline):
    if time.process_time() >= deadline - 1.0:
        return h
    return _exact_lbfgs(h, 4000, 8000, deadline)


def _two_scale(h, B, iters_c, iters_d, deadline):
    if time.process_time() >= deadline - 1.0:
        return h
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n < 2 or h.sum() <= 0:
        return h
    nB = int(np.ceil(n / float(B)))
    npad = nB * B
    u_full = np.full(npad, -30.0)
    u_full[:n] = np.log(np.clip(h, 1e-300, None))
    c = u_full.reshape(nB, B).mean(axis=1)
    d = u_full - np.repeat(c, B)

    def build_h(cvec, dvec):
        uu = np.repeat(cvec, B) + dvec
        uu = np.clip(uu, -30.0, 30.0)
        hh = np.exp(uu)
        hh[n:] = 0.0
        return _rescale_maxL(hh)

    def fc(cvec):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        hh = build_h(cvec, d)
        val, g = _norm_eq_fun_grad(hh)
        gu = g * hh
        gu[n:] = 0.0
        gc = gu.reshape(nB, B).sum(axis=1)
        return val, gc

    try:
        if time.process_time() < deadline - 1.0:
            res = minimize(fc, c, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * nB,
                           options={'maxiter': iters_c, 'maxfun': 2 * iters_c,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            c = np.clip(res.x, -30.0, 30.0)
    except TimeoutError:
        return _rescale_maxL(h)

    def fd(dvec):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        hh = build_h(c, dvec)
        val, g = _norm_eq_fun_grad(hh)
        gu = g * hh
        gu[n:] = 0.0
        bm = gu.reshape(nB, B).mean(axis=1)
        gd = gu - np.repeat(bm, B)
        gd[n:] = 0.0
        return val, gd

    try:
        if time.process_time() < deadline - 1.0:
            res = minimize(fd, d, jac=True, method='L-BFGS-B',
                           bounds=[(-60.0, 60.0)] * npad,
                           options={'maxiter': iters_d, 'maxfun': 2 * iters_d,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            d = np.clip(res.x, -60.0, 60.0)
    except TimeoutError:
        return _rescale_maxL(h)

    return build_h(c, d)


def _anneal_perturb(h, rng, deadline, iters=200):
    """Accept-ever-better perturb + polish at small scale to escape local min."""
    best = h.copy()
    bestR = R_of(best)
    n = h.size
    k = max(1, n // 200)
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        hh = best.copy()
        idx = rng.integers(0, n, size=k)
        amp = 1e-3 * hh.max()
        hh[idx] = np.clip(hh[idx] + rng.normal(0, amp, size=k), 0, None)
        hh = _exact_lbfgs(hh, 200, 400, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    long_deadline = t0 + budget_seconds * 0.50

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
