    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
