    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _interp_to(h, m):
    n = h.size
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _fourier_init(N, m_modes, rng):
    x = np.arange(N, dtype=float) / N
    f = np.full(N, 0.5)
    for k in range(1, m_modes + 1):
        a = abs(rng.normal(0.0, 1.0)) / k
        phi = rng.uniform(0.0, 2.0 * np.pi)
        f += a * np.cos(2.0 * np.pi * k * x + phi)
    return np.clip(f, 0.0, None)


def _fourier_stage(best, bestR, deadline, rng, targetR):
    """Try low-pass Fourier-profile initialisations; return (best, bestR, accepted)."""
    N_coarse = 8192
    modes_list = [3, 8, 16, 32]
    for m_modes in modes_list:
        if time.process_time() >= deadline - 6.0:
            break
        for trial in range(2):
            if time.process_time() >= deadline - 6.0:
                break
            h0 = _fourier_init(N_coarse, m_modes, rng)
            if h0.sum() <= 0:
                continue
            h0 = _rescale_maxL(h0)
            h1 = _exact_lbfgs(h0, 400, 800, deadline)
            r1 = R_of(h1)
            if r1 <= 0:
                continue
            # upsample to incumbent size
            h2 = _interp_to(h1, best.size)
            h2 = _rescale_maxL(h2)
            h2 = _exact_lbfgs(h2, 800, 1600, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-9:
                h3 = _window_polish(h2, deadline)
                r3 = R_of(h3)
                if r3 > bestR + 1e-9:
                    print("fourier m=%d trial=%d R=%.7f" % (m_modes, trial, r3))
                    return h3, r3, True
                if r2 > bestR + 1e-9:
                    print("fourier m=%d trial=%d R=%.7f" % (m_modes, trial, r2))
                    return h2, r2, True
    return best, bestR, False


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0 (experiment): low-pass Fourier-profile multistart.
    # Only accept if it beats the incumbent; otherwise run incumbent pipeline.
    incumbentR = bestR
    fbest, fbestR, accepted = _fourier_stage(best, bestR, deadline, rng, incumbentR)
    if accepted:
        best, bestR = fbest, fbestR
        print("fourier accepted R=%.7f" % bestR)
    else:
        print("fourier rejected; running incumbent pipeline")

    # Stage 1: exact L-BFGS polishing on the given grid.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    # Stage 2: window polish near the flat top.
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Stage 3: fine-grid upsampling refinement.
    if best.size * 2 <= 100000 and time.process_time() < deadline - 3.0:
        fine = _upsample(best, 2)
        fine = _exact_lbfgs(fine, 800, 1600, deadline)
        rf = R_of(fine)
        if rf > bestR:
            best, bestR = fine.copy(), rf
            print("fine R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 4: alternate window polish + exact until budget exhausted.
    while time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline)
        r = R_of(h)
        improved = False
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            improved = True
            print("final window R=%.7f" % bestR)
        if time.process_time() >= deadline - 2.0:
            break
        h2 = _exact_lbfgs(best, 1500, 3000, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            improved = True
            print("final exact R=%.7f" % bestR)
        if not improved:
            break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

