def _smooth(h, w):
    """Moving-average smoothing with window w (odd), edge-preserving via reflect."""
    if w <= 1:
        return h
    if w % 2 == 0:
        w += 1
    k = np.ones(w) / w
    pad = w // 2
    hp = np.concatenate((h[pad:0:-1], h, h[-2:-pad-2:-1])) if pad > 0 else h
    return np.convolve(hp, k, mode='valid')[:h.size]


