        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 1: exact L-BFGS on given grid.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    # Stage 2: alternating window polish + full exact until plateau.
    for _ in range(6):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Stage 3: smoothing-based restart perturbations on the current grid.
    n = best.size
    for w in (3, 5, 9):
        if time.process_time() >= deadline - 3.0:
            break
        cand = _rescale_maxL(_smooth(best, w))
        h2 = _exact_lbfgs(cand, 800, 1600, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("smooth%d R=%.7f" % (w, bestR))

    # Stage 4: fine-grid upsampling.
    if best.size * 2 <= 200000 and time.process_time() < deadline - 3.0:
        fine = _upsample(best, 2)
        fine = _exact_lbfgs(fine, 800, 1600, deadline)
        rf = R_of(fine)
        if rf > bestR:
            best, bestR = fine.copy(), rf
            print("fine R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 5: alternate window/full exact until budget nearly exhausted.
    while time.process_time() < deadline - 2.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
