    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        return _rescale_maxL(h0)
    except Exception:
        return h0


def _peak_window(h, frac, extra):
    """Free index window around the flat-top region of f*f, widened by frac."""
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(n)
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        idx = np.array([m])
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return np.arange(lo, hi + 1)


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    free = _peak_window(h, frac, extra)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _block_avg(h, b):
    n = h.size
    k = n // b
    if k * b != n:
        return None
    return h.reshape(k, b).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    end = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # Phase 2: multigrid escape via block-averaging (various block sizes).
    for b in (2, 3, 4):
        if time.process_time() >= deadline - 3.0:
            break
        if best.size % b != 0:
            continue
        try:
            coarse = _block_avg(best, b)
            coarse = _exact_lbfgs(coarse, 400, 800, t0 + 0.55 * budget_seconds)
            back = np.repeat(coarse, b)
            back = _exact_lbfgs(back, 400, 800, t0 + 0.70 * budget_seconds)
            rback = R_of(back)
            if rback > bestR + 1e-15:
                best, bestR = back, rback
                print("coarse b=%d R=%.7f" % (b, bestR))
        except Exception:
            pass

    # Phase 3: windowed polish with multiple window sizes.
    stall = 0
    while time.process_time() < deadline - 1.5 and stall < 4:
        improved = False
        for frac in (0.1, 0.25, 0.5, 1.0):
            if time.process_time() >= deadline - 1.5:
                break
            cand = _window_polish(best, deadline, frac=frac)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1
    print("phase3 R=%.7f" % bestR)

    # Phase 4: final intensive full polish until near end.
    while time.process_time() < end - 1.0:
        cand = _exact_lbfgs(best, 6000, 12000, end)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            break
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

