    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min(); hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _coarsen_solve(h, factor, deadline, maxiter, maxfun):
    n = h.size
    if n % factor != 0:
        return h
    coarse = h.reshape(-1, factor).mean(axis=1)
    coarse = _rescale_maxL(coarse)
    coarse = _exact_lbfgs(coarse, maxiter, maxfun, deadline)
    return np.repeat(coarse, factor)


def _toggle_loop(best, bestR, deadline, rng, window=6, maxiter=300, maxfun=600):
    """Random single-cell toggle + tiny-window repolish. Accepts only improvements."""
    n = best.size
    if n < 2:
        return best, bestR
    while time.process_time() < deadline - 2.0:
        i = int(rng.integers(0, n))
        h_new = best.copy()
        if h_new[i] > 0.0:
            h_new[i] = 0.0
        else:
            j = -1
            for d in range(1, n):
                if i - d >= 0 and best[i - d] > 0.0:
                    j = i - d; break
                if i + d < n and best[i + d] > 0.0:
                    j = i + d; break
            if j < 0:
                continue
            h_new[i] = h_new[j] * rng.uniform(0.01, 0.3)
        lo = max(0, i - window)
        hi = min(n, i + window + 1)
        free = np.arange(lo, hi)
        cand = _exact_lbfgs(h_new, maxiter, maxfun, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _local_pair_gradient(h, rng, nsample, step):
    n = h.size
    if n < 2:
        return h
    h = h.copy()
    idx = rng.integers(0, n - 1, size=nsample)
    cur = R_of(h)
    for j in idx:
        if h[j] <= 0 and h[j + 1] <= 0:
            continue
        best_delta = 0.0
        best_r = cur
        for sgn in (1.0, -1.0):
            t = sgn * step * (h[j] + h[j + 1] + 1e-12)
            if h[j] - t < 0 or h[j + 1] + t < 0:
                continue
            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
            cur = best_r
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # === Toggle-based local search: try removing/spawning cells near peak ===
    d_tog = t0 + budget_seconds * 0.35
    if time.process_time() < d_tog - 2.0:
        rng_t = np.random.default_rng(24681357)
        cand, cr = _toggle_loop(best, bestR, d_tog, rng_t)
        if cr > bestR + 1e-16:
            best, bestR = cand, cr
            print("toggle R=%.7f" % bestR)

    # === Pair-gradient sweeps (coarse then fine) ===
    d_pg = t0 + budget_seconds * 0.55
    if time.process_time() < d_pg - 2.0:
        rng = np.random.default_rng(987654321)
        hh = best.copy()
        for step in (2e-3, 5e-4, 1e-4):
            if time.process_time() >= d_pg - 2.0:
                break
            hh = _local_pair_gradient(hh, rng, nsample=600, step=step)
        hh = _exact_lbfgs(hh, 1000, 2000, d_pg)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
            print("pairgrad R=%.7f" % bestR)

    # === Final polish loop ===
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish(best, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            if time.process_time() >= deadline - 1.0:
                break
            rng2 = np.random.default_rng(int(time.process_time() * 1e6) & 0xffffffff)
            cand, cr = _toggle_loop(best, bestR, min(deadline - 1.0, time.process_time() + 3.0), rng2, window=4)
            if cr > bestR + 1e-16:
                best, bestR = cand, cr
            else:
                break
    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR < R_of(base):
        best, bestR = base, R_of(base)
    return best

