    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm) + beta * P
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, beta=0.0):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _beta_fun_grad(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    try:
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _intermediate_frac(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    v = Lf / mx
    return float(np.mean((v > 0.05) & (v < 0.95)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 1: exact L-BFGS polishing on the given grid.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    # Stage 2: window polish near the flat top.
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Stage 3: fine-grid upsampling refinement.
    if best.size * 2 <= 100000 and time.process_time() < deadline - 3.0:
        fine = _upsample(best, 2)
        fine = _exact_lbfgs(fine, 800, 1600, deadline)
        rf = R_of(fine)
        if rf > bestR:
            best, bestR = fine.copy(), rf
            print("fine R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 4 (experiment): beta-penalty loop to the deadline.
    betas = (0.5, 2.0, 8.0)
    while time.process_time() < deadline - 2.0:
        improved_any = False
        for beta in betas:
            if time.process_time() >= deadline - 2.0:
                break
            cand = _exact_lbfgs(best, 600, 1200, deadline, beta=beta)
            rc = R_of(cand)
            frac = _intermediate_frac(cand)
            print("beta=%.2f frac=%.4f R=%.7f" % (beta, frac, rc))
            # re-polish with beta=0
            if time.process_time() < deadline - 2.0:
                cand = _exact_lbfgs(cand, 1000, 2000, deadline, beta=0.0)
                rc = R_of(cand)
                frac = _intermediate_frac(cand)
                print("  beta0 frac=%.4f R=%.7f" % (frac, rc))
            if time.process_time() < deadline - 2.0:
                cand2 = _window_polish(cand, deadline)
                rc2 = R_of(cand2)
                if rc2 > rc:
                    cand, rc = cand2, rc2
                    print("  window R=%.7f" % rc)
            if rc > bestR + 1e-12:
                best, bestR = cand.copy(), rc
                improved_any = True
                print("ACCEPT beta=%.2f R=%.7f" % (beta, bestR))
        if not improved_any:
            # one more plain polish attempt before giving up
            if time.process_time() < deadline - 2.0:
                h2 = _exact_lbfgs(best, 1500, 3000, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-12:
                    best, bestR = h2.copy(), r2
                    print("final exact R=%.7f" % bestR)
                    continue
            break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _envelope(h, a1, a2):
    n = h.size
    x = (np.arange(n) + 0.5) / n
    phi1 = x - 0.5
    phi2 = 6.0 * (x - 0.5) ** 2 - 0.5
    return h * np.exp(a1 * phi1 + a2 * phi2)


def _env_scan(base, bestR, deadline):
    """Scan multiplicative envelope params; return best (h, R) found or None."""
    if time.process_time() >= deadline - 3.0:
        return None
    a1s = (-0.6, -0.4, -0.2, 0.0, 0.2, 0.4, 0.6)
    a2s = (-0.4, -0.2, 0.0, 0.2, 0.4)
    cells = []
    for a1 in a1s:
        for a2 in a2s:
            if time.process_time() >= deadline - 3.0:
                break
            hh = _rescale_maxL(_envelope(base, a1, a2))
            r = R_of(hh)
            cells.append((r, a1, a2))
    if not cells:
        return None
    cells.sort(key=lambda t: -t[0])
    print("env grid best (a1=%.2f,a2=%.2f,R=%.7f)" % (cells[0][1], cells[0][2], cells[0][0]))

    # Polish the best 3 cells.
    best_h = None
    best_r = bestR
    for r0, a1, a2 in cells[:3]:
        if time.process_time() >= deadline - 2.0:
            break
        hh = _rescale_maxL(_envelope(base, a1, a2))
        hh = _exact_lbfgs(hh, 800, 1600, deadline)
        hh = _window_polish(hh, deadline)
        r = R_of(hh)
        if r > best_r + 1e-16:
            best_r = r
            best_h = hh.copy()
            print("env polish (a1=%.2f,a2=%.2f) R=%.7f" % (a1, a2, r))

    # Nelder-Mead on -(R) from best cell.
    if time.process_time() < deadline - 2.0:
        a1_0, a2_0 = cells[0][1], cells[0][2]

        def negR(p):
            if time.process_time() >= deadline - 2.0:
                raise TimeoutError
            hh = _rescale_maxL(_envelope(base, p[0], p[1]))
            return -R_of(hh)

        try:
            res = minimize(negR, np.array([a1_0, a2_0]), method='Nelder-Mead',
                           options={'maxiter': 40, 'xatol': 1e-4, 'fatol': 1e-9})
            a1, a2 = res.x
            hh = _rescale_maxL(_envelope(base, a1, a2))
            hh = _exact_lbfgs(hh, 800, 1600, deadline)
            hh = _window_polish(hh, deadline)
            r = R_of(hh)
            print("env NM (a1=%.3f,a2=%.3f) R=%.7f" % (a1, a2, r))
            if r > best_r + 1e-16:
                best_r = r
                best_h = hh.copy()
        except TimeoutError:
            pass
        except Exception:
            pass

    if best_h is None:
        return None
    return best_h, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(12345)

    if start is not None:
