            print("upsample x2 R=%.7f" % bestR)
            # down-sample decision: keep the finer grid
        else:
            pass

    # Phase 5: final exact polish + window polish.
    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 3000, 6000, deadline)
