                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    if factor <= 1 or n < 2 * factor:
        return h
    m = (n - 1) // factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _superpose_scan(g, deadline):
    n = g.size
    delta_fracs = [0.55, 0.65, 0.75, 0.85, 0.95, 1.05, 1.2]
    amps = [0.5, 0.7, 0.85, 1.0, 1.2, 1.5, 2.0]
    results = []
    for df in delta_fracs:
        d = int(df * n)
        if d < 1:
            continue
        for a in amps:
            f = np.zeros(d + n)
            f[:n] += g
            f[d:d + n] += a * g
            r = R_of(f)
            results.append((r, df, a, f))
    results.sort(key=lambda t: -t[0])
    top = results[:3]
    best = None
    bestR = -1.0
    for r0, df, a, f in top:
        if time.process_time() >= deadline - 2.0:
            break
        hp = _exact_lbfgs(f, 600, 1200, deadline)
        rp = R_of(hp)
        if rp > bestR:
            bestR = rp
            best = hp
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: coarse-to-fine. Downsample, optimise coarse, upsample back.
    # This escapes local optima on the dense grid cheaply.
    n0 = best.size
    for f in (8, 4, 2):
        if time.process_time() >= deadline - 3.0:
            break
        if n0 // f < 8:
            continue
        coarse = _downsample(best, f)
        coarse = _exact_lbfgs(coarse, 400, 800, deadline)
        rc = R_of(coarse)
        up = _upsample(coarse, f)
        up = up[:n0] if up.size >= n0 else _upsample(coarse, (n0 - 1) // max(1, coarse.size - 1))
        up = _exact_lbfgs(up, 300, 600, deadline)
        ru = R_of(up)
        print("  coarse f=%d: rc=%.7f up=%.7f" % (f, rc, ru))
        if ru > bestR + 1e-12:
            best, bestR = up.copy(), ru
            print("coarse accepted R=%.7f" % bestR)

    # Stage 1: exact L-BFGS polishing.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    # Stage 1.5: superposition experiment.
    if time.process_time() < deadline - 3.0:
        g = best.copy()
        sup, supR = _superpose_scan(g, deadline)
        if sup is not None and supR > bestR + 1e-12:
            best, bestR = sup.copy(), supR
            print("superpose accepted R=%.7f (N=%d)" % (bestR, best.size))
            for _ in range(3):
                if time.process_time() >= deadline - 2.0:
                    break
                h = _window_polish(best, deadline)
                r = R_of(h)
                if r > bestR + 1e-16:
                    best, bestR = h.copy(), r
                h2 = _exact_lbfgs(best, 1500, 3000, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-16:
                    best, bestR = h2.copy(), r2
                    print("sup exact R=%.7f" % bestR)
                else:
                    break
        else:
            print("superpose rejected")

    # Stage 2: window polish.
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Stage 3: alternate window/exact until budget exhausted.
    while time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline)
        r = R_of(h)
        improved = False
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            improved = True
            print("final window R=%.7f" % bestR)
        if time.process_time() >= deadline - 2.0:
            break
        h2 = _exact_lbfgs(best, 1500, 3000, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            improved = True
            print("final exact R=%.7f" % bestR)
        if not improved:
            break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _trust_ncg_polish(h0, deadline):
    """Trust-region Newton-CG using finite-difference Hessian-vector products."""
    if time.process_time() >= deadline - 2.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    def hessp(u, p):
        pn = np.linalg.norm(p)
        if pn <= 0:
            return np.zeros_like(p)
        delta = 1e-6 * (1.0 + pn) / pn
        _, g0 = f(u)
        _, g1 = f(u + delta * p)
        return (g1 - g0) / delta

    cb = _make_cb(deadline - 2.0)
    try:
        res = minimize(f, u0, jac=True, hessp=hessp, method='trust-ncg',
                       callback=cb,
                       options={'maxiter': 150, 'gtol': 1e-14,
                                'initial_trust_radius': 1e-2,
                                'max_trust_radius': 1.0})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 1: exact L-BFGS polishing on the given grid.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    # Stage 1b: trust-region Newton-CG on active coordinates.
    if time.process_time() < deadline - 4.0:
        ht = _trust_ncg_polish(best, deadline)
        rt = R_of(ht)
        if rt > bestR + 1e-16:
            ht2 = _exact_lbfgs(ht, 1500, 3000, deadline)
            rt2 = R_of(ht2)
            if rt2 > bestR + 1e-16:
                best, bestR = ht2.copy(), rt2
                print("trust-ncg R=%.7f" % bestR)
            elif rt > bestR + 1e-16:
                best, bestR = ht.copy(), rt
                print("trust-ncg(raw) R=%.7f" % bestR)

    # Stage 2: window polish near the flat top.
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Stage 3: fine-grid upsampling refinement.
    if best.size * 2 <= 100000 and time.process_time() < deadline - 3.0:
        fine = _upsample(best, 2)
        fine = _exact_lbfgs(fine, 800, 1600, deadline)
        rf = R_of(fine)
        if rf > bestR:
            best, bestR = fine.copy(), rf
            print("fine R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 4: alternate window polish + exact until budget exhausted.
    while time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline)
        r = R_of(h)
        improved = False
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            improved = True
            print("final window R=%.7f" % bestR)
        if time.process_time() >= deadline - 2.0:
            break
        h2 = _exact_lbfgs(best, 1500, 3000, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            improved = True
            print("final exact R=%.7f" % bestR)
        if not improved:
            break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

