            # (b) three copies
            c = (np.concatenate((h, np.zeros(2 * d)))
                 + a * np.concatenate((np.zeros(d), h, np.zeros(d)))
                 + (a * a) * np.concatenate((np.zeros(2 * d), h)))
            cands.append(c)
            # (c) mirrored copy at offset d
            c = np.concatenate((h, np.zeros(d))) + a * np.concatenate((np.zeros(d), rev))
            cands.append(c)
    return cands


def construct(budget_seconds, start):
