        scored.append((r, c))
    scored.sort(key=lambda t: -t[0])
    top = scored[:3]
    for r0, c in top:
        if time.process_time() >= stage0_deadline - 1.0:
            break
        h = _exact_lbfgs(c, 800, 1600, stage0_deadline)
        if time.process_time() < stage0_deadline - 1.0:
