    # Stage 1: full-grid polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _full_polish(h, deadline, iters=3000):
    """Full-grid L-BFGS on log-parameterisation of all positive entries."""
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _prune_floor_sweep(base, best, bestR, deadline):
    """Prune lowest heights to top-q fraction, repolish; then floor sweep."""
    n = base.size
    pos = np.flatnonzero(base > 0)
    if pos.size == 0:
        return best, bestR
    order = pos[np.argsort(base[pos])]  # ascending by height
    qs = [0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 0.85, 0.95]
    sweep_best = None
    sweep_bestR = -1.0
    for q in qs:
        if time.process_time() >= deadline - 2.0:
            break
        keep = max(1, int(round(q * pos.size)))
        drop = order[:pos.size - keep]
        hq = base.copy()
        hq[drop] = 0.0
        hq = _rescale_maxL(hq)
        hq = _exact_lbfgs(hq, 1200, 2400, deadline)
        hq = _window_polish(hq, deadline)
        r = R_of(hq)
        if r > sweep_bestR:
            sweep_bestR = r
            sweep_best = hq
        if r > bestR + 1e-15:
            best, bestR = hq.copy(), r
            print("prune q=%.2f R=%.7f" % (q, bestR))
    # Floor sweep: add small floor to exactly-zero indices of sweep best.
    if sweep_best is not None and time.process_time() < deadline - 2.0:
        mean_base = base.mean()
        zeros = np.flatnonzero(sweep_best <= 0)
        if zeros.size > 0:
            for frac in (1e-4, 1e-2):
                if time.process_time() >= deadline - 2.0:
                    break
                hf = sweep_best.copy()
                hf[zeros] += frac * mean_base
                hf = _rescale_maxL(hf)
                hf = _exact_lbfgs(hf, 1200, 2400, deadline)
                hf = _window_polish(hf, deadline)
                r = R_of(hf)
                if r > bestR + 1e-15:
                    best, bestR = hf.copy(), r
                    print("floor frac=%.0e R=%.7f" % (frac, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
