    # active set so L-BFGS converges tightly on the important degrees of
    # freedom, then a full re-polish to rebalance.
    for _ in range(6):
        if time.process_time() >= deadline - 1.0:
            break
        hw = _window_polish(best, deadline, frac=0.35, extra=8)
        rw = R_of(hw)
        if rw > bestR + 1e-15:
            best, bestR = hw.copy(), rw
            print("window R=%.7f" % bestR)
        else:
            break
        if time.process_time() < deadline - 2.0:
            hf = _exact_lbfgs(best, 1500, 3000, deadline)
            rf = R_of(hf)
            if rf > bestR + 1e-15:
                best, bestR = hf.copy(), rf

    # Phase 4: tight window polish on the very top of f*f to flatten it.
    for frac in (0.15, 0.08, 0.04):
