    num, dq, Lf = _num_and_dq(h)
    Mx = Lf.max()
    e = Lf - Mx
    w = np.exp(e / eps)
    Z = w.sum()
    sm = Mx + eps * np.log(Z)
    gw = w / Z
    gLf = -dq / num + gw
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, eps=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if eps is None:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _smooth_obj_grad(hh, eps)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    try:
        h2 = np.zeros(n)
        if res is not None and hasattr(res, 'x'):
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        else:
            return h0
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _peak_region(h, thresh_frac=0.999):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = thresh_frac * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return max(0, m - 1), min(n - 1, m - 1)
    lo_k = idx.min(); hi_k = idx.max()
    lo = max(0, lo_k - 1); hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, maxiter=1200, maxfun=2400,
                   eps=None, thresh_frac=0.999):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h, thresh_frac)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, maxiter, maxfun, deadline, free=free, eps=eps)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    def try_update(h, tag):
        nonlocal best, bestR
        if h is None or h.size == 0 or h.sum() <= 0:
            return False
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("%s R=%.7f (N=%d)" % (tag, bestR, best.size))
            return True
        return False

    # Stage 1: smooth-max continuation on the current grid. The start is
    # already a local optimum of the exact objective; smoothing the max
    # lets us escape the flat-top plateau where the exact gradient is stale.
    for eps in (1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 1e-5, 1e-6, None):
        if time.process_time() >= deadline - 4.0:
            break
        h = _exact_lbfgs(best, 1200, 2400, deadline, eps=eps)
        try_update(h, "smooth-%s" % (eps,))

    # Stage 2: alternate window polish around the flat peak with full-grid
    # polish, cycling over smoothing levels. The window allows many more
    # iterations per unit time on the critical region.
    eps_cycle = [None, 1e-6, 1e-4, 1e-3, None, 1e-5]
    k = 0
    stall = 0
    while time.process_time() < deadline - 2.0:
        eps = eps_cycle[k % len(eps_cycle)]
        k += 1
        improved = False
        h = _window_polish(best, deadline, eps=eps, frac=0.4,
                           maxiter=2000, maxfun=4000, thresh_frac=0.998)
        if try_update(h, "win-%s" % (eps,)):
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(best, 1500, 3000, deadline, eps=eps)
        if try_update(h, "exact-%s" % (eps,)):
            improved = True
        if improved:
            stall = 0
        else:
            stall += 1
            if stall >= 2:
                # widen the window to escape a stuck local optimum
                h = _window_polish(best, deadline, eps=None, frac=1.0,
                                   maxiter=1500, maxfun=3000,
                                   thresh_frac=0.99)
                if try_update(h, "wide"):
                    stall = 0
                else:
                    break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _smooth_obj_grad(h, eps):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Mx = Lf.max()
    e = Lf - Mx
    w = np.exp(e / eps)
    Z = w.sum()
    sm = Mx + eps * np.log(Z)
    gw = w / Z
    gLf = -dq / num + gw
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
