    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    if factor <= 1 or n < 2 * factor:
        return h
    m = (n - 1) // factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: smoothing-based approach. The plain max objective has a
    # degenerate gradient; a smooth-max (log-sum-exp) surrogate lets L-BFGS
    # raise several near-tied knots together, which is what actually lifts R.
    eps_list = [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5]
    h = best.copy()
    for eps in eps_list:
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 800, 1600, deadline, eps=eps)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("smooth eps=%.0e R=%.7f" % (eps, bestR))

    # Phase 2: exact polish on the peak region and full vector.
    for _ in range(3):
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)

    # Phase 3: try refining on a finer grid.
    if time.process_time() < deadline - 5.0:
        hu = _rescale_maxL(_upsample(best, 2))
        for eps in [1e-3, 1e-4, 1e-5]:
            if time.process_time() >= deadline - 3.0:
                break
            hu = _exact_lbfgs(hu, 600, 1200, deadline, eps=eps)
            ru = R_of(hu)
            if ru > bestR + 1e-15:
                best, bestR = hu.copy(), ru
                print("upsample x2 eps=%.0e R=%.7f (N=%d)" % (eps, bestR, best.size))
        hu = _exact_lbfgs(best, 800, 1600, deadline)
        ru = R_of(hu)
        if ru > bestR + 1e-15:
            best, bestR = hu.copy(), ru
            print("upsample exact R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 4: alternate window / full / smooth until the deadline.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _window_polish(best, deadline, frac=0.25 + 0.1 * stall, extra=4 + 4 * stall)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("w R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _exact_lbfgs(best, 1200, 2400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("f R=%.7f" % bestR)
        if not improved:
            stall += 1
            if time.process_time() < deadline - 3.0:
                h = _exact_lbfgs(best, 600, 1200, deadline, eps=1e-5)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("s R=%.7f" % bestR)
        else:
            stall = 0

    if R_of(base) > bestR:
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

