def _downsample_sum(h, N):
    """Block-sum downsample to length N (sum consecutive cells, pad)."""
    n = h.size
    if n == N:
        return h.copy()
    # map each coarse cell to a contiguous block of fine cells
    edges = np.linspace(0, n, N + 1)
    out = np.zeros(N)
    for i in range(N):
        lo = int(np.floor(edges[i]))
        hi = int(np.ceil(edges[i + 1]))
        lo = max(0, min(n, lo))
        hi = max(lo, min(n, hi))
        if hi > lo:
            out[i] = h[lo:hi].sum()
        else:
            out[i] = 0.0
    return out


def _sa_coarse(h_coarse, deadline, K=20000, step=0.15,
               T0=1e-4, T1=1e-7, hybrid_every=2000):
