        cand = _rescale_maxL(cand)
        rc = R_of(cand)
        if rc >= bestR - 1e-6:
            h = cand
            # quick full polish on the finer grid
            h = _full_polish(h, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            else:
                # keep the upsampled shape anyway if it's close (finer grid
                # is a better starting point for further polishing)
                if rc > bestR + 1e-15:
                    best, bestR = cand.copy(), rc
                    print("upsample(f=%d,raw) R=%.7f N=%d" % (factor, bestR, best.size))
        else:
            break

    # Final alternating polish on whatever grid we ended on.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _band_size(h, frac=0.99):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1
    return int(np.count_nonzero(Lf >= frac * mx))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: nested top-K-mean max proxy ladder tied to the near-max band size.
    h = best.copy()
    c = _band_size(h, 0.99)
    n = h.size
    Ks = []
    K = min(n, max(1, c))
    while K >= 1:
        Ks.append(K)
        if K == 1:
            break
        K = max(1, K // 2)
    if Ks and Ks[-1] != 1:
        Ks.append(1)
    print("band c=%d ladder=%s" % (c, Ks))

    for K in Ks:
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 300, 600, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        # exact K=1 run after each rung
        if time.process_time() < deadline - 2.0:
            h1 = _exact_lbfgs(h, 200, 400, deadline, K=1)
            r1 = R_of(h1)
            if r1 > bestR + 1e-15:
                best, bestR = h1.copy(), r1
                h = h1
            elif r1 > r:
                h = h1
        # window polish after each rung
        if time.process_time() < deadline - 2.0:
            hw = _window_polish(h, deadline)
            rw = R_of(hw)
            if rw > bestR + 1e-15:
                best, bestR = hw.copy(), rw
                h = hw
            elif rw > r:
                h = hw
        print("K=%d R=%.7f" % (K, bestR))

    # Stage 1: full-grid polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

