    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _tv_fun_grad(h, lam):
    """Objective with TV regulariser: val + lam * sum|diff(Lf)|/max(Lf)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    if lam > 0:
        d = np.diff(Lf)
        sd = np.sign(d)
        tv = np.sum(np.abs(d))
        tvn = tv / Lm
        val += lam * tvn
        # d/dq of sum|diff|: contribution to gLf
        g_tv = np.zeros_like(Lf)
        # diff[j] = Lf[j+1]-Lf[j], j=0..n-2
        # d sum|d| / d Lf[k] = sign(d[k]) (from j=k) - sign(d[k-1]) (from j=k-1)
        g_tv[:-1] += sd
        g_tv[1:] -= sd
        # tvn = tv / Lm ; d/dq = (g_tv * Lm - tv * e_m) / Lm^2
        gLf += lam * (g_tv / Lm)
        gLf[m] -= lam * tv / (Lm * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


