                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

