def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _refine_fine(h, deadline, factor=2, iters=600):
    hu = _rescale_maxL(_upsample(h, factor))
    hu = _exact_lbfgs(hu, iters, 2 * iters, deadline)
    return hu


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # The main new idea: the score is limited by how flat the top of f*f is.
    # Repeatedly upsample onto a finer grid and re-optimise, so the discrete
    # step resolution stops being the bottleneck.
    factor = 1
    while time.process_time() < deadline - 3.0 and best.size * 2 <= 200000:
        factor *= 2
        cand = _refine_fine(best, deadline, factor=2, iters=700)
        rc = R_of(cand)
        print("upsample x%d R=%.7f (N=%d)" % (factor, rc, cand.size))
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
        else:
            # keep the finer grid anyway as a new working point if close,
            # since polishing it can still help
            if rc > bestR - 1e-6:
                best, bestR = cand, rc
            else:
                break

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 3.0:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                if time.process_time() < deadline - 3.0 and best.size * 2 <= 200000:
                    cand = _refine_fine(best, deadline, factor=2, iters=500)
                    rc = R_of(cand)
                    if rc > bestR + 1e-15:
                        best, bestR = cand, rc
                        stall = 0
                        print("upsample R=%.7f (N=%d)" % (bestR, best.size))
        else:
            stall = 0

    if R_of(base) > bestR:
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _obj_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if K <= 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    K = min(K, Lf.size)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mt = top.sum() / K
    if mt <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mt
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mt)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, deadline, maxiter=2000, free=None, K=1):
    if time.process_time() >= deadline - 0.8:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        active = np.flatnonzero(h > 1e-13 * h.max())
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _obj_grad(hh, K)
        return val, g[active] * hh[active]

    res = None
    cb = _make_cb(deadline - 0.4)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h, frac=0.999):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= frac * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m - 1)
    return max(0, idx.min() - 1), min(n - 1, idx.max())


def _window(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.8:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return _lbfgs(h, deadline, free=np.arange(lo, hi + 1), K=K)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    return np.interp(np.linspace(0, n - 1, m), np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)
    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    def upd(h, tag):
        nonlocal best, bestR
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("%s R=%.7f (N=%d)" % (tag, bestR, best.size))
            return True
        return False

    # Upsample early to finer grid (more degrees of freedom helps escape).
    if best.size * 2 <= 160000:
        up = _upsample(best, 2)
        up = _lbfgs(up, deadline, maxiter=1200)
        upd(up, "up2")

    # Continuation on top-K smoothed max with decreasing K, then exact.
    for K in (8, 4, 2, 1):
        if time.process_time() >= deadline - 1.5:
            break
        h = _lbfgs(best, deadline, maxiter=1500, K=K)
        upd(h, "K=%d" % K)

    # Window polish cycles with K-continuation on free set.
    for K in (4, 2, 1, 1, 1):
        if time.process_time() >= deadline - 1.5:
            break
        h = _window(best, deadline, K=K)
        upd(h, "winK=%d" % K)

    # Another upsample round if room.
    if best.size * 2 <= 190000 and time.process_time() < deadline - 3.0:
        up = _upsample(best, 2)
        up = _lbfgs(up, deadline, maxiter=1200)
        upd(up, "up2b")
        for K in (2, 1):
            if time.process_time() >= deadline - 1.5:
                break
            h = _window(best, deadline, K=K)
            upd(h, "winbK=%d" % K)

    # Alternate exact / window until budget.
    k = 0
    while time.process_time() < deadline - 1.5:
        k += 1
        h = _lbfgs(best, deadline, maxiter=1500, K=1)
        if upd(h, "exact#%d" % k):
            continue
        h = _window(best, deadline, K=1)
        if upd(h, "win#%d" % k):
            continue
        # perturb and retry
        rng = np.random.default_rng(k)
        n = best.size
        h = np.clip(best + rng.standard_normal(n) * 1e-6 * best.max(), 0, None)
        h = _rescale_maxL(h)
        h = _lbfgs(h, deadline, maxiter=800, K=2)
        if not upd(h, "kick#%d" % k):
            break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

