            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    # Stage 2: upsample the best shape and refine on the finer grid.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _upsample(best, factor)
        cand = _rescale_maxL(cand)
        rc = R_of(cand)
        if rc >= bestR - 1e-6:
            h = cand
            h = _full_polish(h, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            else:
                if rc > bestR + 1e-15:
                    best, bestR = cand.copy(), rc
                    print("upsample(f=%d,raw) R=%.7f N=%d" % (factor, bestR, best.size))
        else:
            break

    # ===== EXPERIMENT: 4x narrowing test =====
    # Build h4 of length 4*N with each cell's mass in a single 1/4-width
    # sub-cell (positions 4i+1, 4i+2 each get h[i]/2), then refine at 4x,
    # re-coarsen, and re-polish. Accept only if exact R beats bestR.
    if time.process_time() < deadline - 2.0:
        try:
            n = best.size
            h4 = np.zeros(4 * n)
            h4[4 * np.arange(n) + 1] = best / 2.0
            h4[4 * np.arange(n) + 2] = best / 2.0
            h4 = _rescale_maxL(h4)
            r0 = R_of(h4)
            print("narrow4 raw R=%.7f (N=%d)" % (r0, h4.size))

            h4 = _exact_lbfgs(h4, 400, 800, deadline)
            r1 = R_of(h4)
            print("narrow4 lbfgs R=%.7f" % r1)

            if time.process_time() < deadline - 1.5:
                h4 = _window_polish(h4, deadline)
                r2 = R_of(h4)
                print("narrow4 window R=%.7f" % r2)

            # Re-coarsen: average groups of 4
            h2 = h4.reshape(n, 4).mean(axis=1)
            h2 = _rescale_maxL(h2)
            r3 = R_of(h2)
            print("recoarsen R=%.7f (N=%d)" % (r3, h2.size))

            if time.process_time() < deadline - 1.0:
                h2 = _full_polish(h2, deadline, iters=1500)
                r4 = R_of(h2)
                print("recoarsen full R=%.7f" % r4)
                if time.process_time() < deadline - 1.0:
                    h2 = _window_polish(h2, deadline)
                    r5 = R_of(h2)
                    print("recoarsen window R=%.7f" % r5)
                    if r5 > r4:
                        r4 = r5
                if r4 > bestR + 1e-15:
                    best, bestR = h2.copy(), r4
                    print("narrow4 accepted R=%.7f" % bestR)
                else:
                    print("narrow4 rejected (best stays %.7f)" % bestR)
        except Exception as e:
            print("narrow4 failed: %s" % repr(e))

    # Final alternating polish on whatever grid we ended on.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1,
                 ftol=1e-20, gtol=1e-16):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': ftol, 'gtol': gtol})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _taper_free(h):
    """Free set targeting the taper-generating end cells of the support,
    plus cells adjacent to the flat-top knot region."""
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return np.arange(n)
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        k_lo = k_hi = int(np.argmax(Lf))
    else:
        k_lo = int(idx.min())
        k_hi = int(idx.max())
    hmax = h.max()
    sup = np.flatnonzero(h > 1e-13 * hmax)
    if sup.size == 0:
        return np.arange(n)
    support_lo = int(sup.min())
    support_hi = int(sup.max())
    neff = support_hi - support_lo + 1
    w_lo = max(8, int(0.10 * neff))
    w_hi = max(8, int(0.25 * neff))
    parts = []
    lo_end = np.arange(support_lo, min(n, support_lo + w_lo + 1))
    hi_end = np.arange(max(0, support_hi - w_hi), support_hi + 1)
    parts.append(lo_end)
    parts.append(hi_end)
    # cells adjacent to flat-top knot boundaries
    for k in (k_lo, k_hi):
        for d in range(-8, 9):
            i = k - 1 + d
            if 0 <= i < n:
                parts.append(np.array([i]))
    free = np.unique(np.concatenate(parts))
    return free


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder (helps escape flat-top plateaus).
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    # Stage 2: upsample the best shape and refine on the finer grid.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _upsample(best, factor)
        cand = _rescale_maxL(cand)
        rc = R_of(cand)
        if rc >= bestR - 1e-6:
            h = cand
            h = _full_polish(h, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            else:
                if rc > bestR + 1e-15:
                    best, bestR = cand.copy(), rc
                    print("upsample(f=%d,raw) R=%.7f N=%d" % (factor, bestR, best.size))
        else:
            break

    # Final alternating polish on whatever grid we ended on.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    # Stage 3 (experiment): taper-polish / full-polish alternation.
    # The taper-generating end cells have never been the free set; give them
    # a tight-tolerance L-BFGS polish, then a full polish, accept on improvement.
    while time.process_time() < deadline - 1.0:
        free = _taper_free(best)
        if free.size == 0:
            break
        h = _exact_lbfgs(best, 3000, 6000, deadline, free=free,
                         ftol=1e-22, gtol=1e-18)
        r = R_of(h)
        improved = False
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("taper R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("taper-full R=%.7f" % bestR)
        if not improved:
            break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

