    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


# ---- Axis warp machinery ----

def _warp(h, a):
    """Apply a monotone axis warp parametrized by 8 values a.

    Breakpoints y_i = clip((i/8) + 0.03*tanh(a_i)) for i=1..7 (plus 0 and 1),
    forced monotone by sorting. Cell edges in old coordinates are
    x_j = n * y(j/n), and the new height is the mass-conserving cell average
    of h over [x_j, x_{j+1}].
    """
    n = h.size
    if n < 2:
        return h.copy()
    a = np.asarray(a, dtype=float).ravel()
    if a.size < 8:
        a = np.concatenate([a, np.zeros(8 - a.size)])
    # 9 breakpoints in [0,1]: 0, y_1..y_7, 1
    ys = np.empty(9)
    ys[0] = 0.0
    ys[8] = 1.0
    for i in range(1, 8):
        ys[i] = (i / 8.0) + 0.03 * np.tanh(a[i - 1])
    ys = np.sort(np.clip(ys, 0.0, 1.0))
    # ensure strictly increasing with tiny epsilon
    eps = 1e-9
    for i in range(1, 9):
        if ys[i] <= ys[i - 1]:
            ys[i] = ys[i - 1] + eps
    ys = np.clip(ys, 0.0, 1.0)
    ys[8] = 1.0

    # cumulative mass of h (piecewise-constant on unit cells)
    csum = np.concatenate(([0.0], np.cumsum(h)))
    total = csum[-1]
    if total <= 0:
        return h.copy()

    # new cell edges: j -> y(j/n), mapped to old coordinate u = n*y in [0,n]
    j = np.arange(n + 1, dtype=float)
    t = j / n  # in [0,1]
    # piecewise-linear interpolation of ys at t
    y_t = np.interp(t, np.linspace(0.0, 1.0, 9), ys)
    u = n * y_t  # old coordinate in [0, n]
    u = np.clip(u, 0.0, n)
    # mass at those edges via interpolation of csum at u
    mass_edges = np.interp(u, np.arange(n + 1, dtype=float), csum)
    newh = np.diff(mass_edges)
    newh = np.clip(newh, 0.0, None)
    return _rescale_maxL(newh)


def _block_average(h, target):
    n = h.size
    if n <= target:
        return h.copy()
    # average consecutive blocks of size ~ n/target
    factor = int(np.ceil(n / target))
    m = n // factor
    if m < 2:
        return h.copy()
    trimmed = h[:m * factor].reshape(m, factor).mean(axis=1)
    return trimmed


def _warp_optimize(h, deadline, maxiter=300):
    """Optimize the 8 warp parameters on a coarse block-averaged copy."""
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    hc = _block_average(h, 4000)
    if hc.size < 16:
        return h, R_of(h)

    def negR(a):
        try:
            hw = _warp(hc, a)
            r = R_of(hw)
            if not np.isfinite(r):
                return 1.0
            return -r
        except Exception:
            return 1.0

    a0 = np.zeros(8)
    try:
        res = minimize(negR, a0, method='Nelder-Mead',
                       options={'maxiter': maxiter, 'xatol': 1e-3,
                                'fatol': 1e-10})
        a_best = res.x
    except Exception:
        a_best = a0
    # build full-resolution warped h
    hw = _warp(h, a_best)
    return hw, R_of(hw)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Warp rounds first: orthogonal direction to height perturbations ----
    warp_rounds = 0
    while warp_rounds < 2 and time.process_time() < deadline - 6.0:
        hw, rw = _warp_optimize(best, deadline)
        if rw > bestR + 1e-12:
            # refine the warped shape
            hw2 = _full_polish(hw, deadline, iters=1500)
            r2 = R_of(hw2)
            if r2 > rw:
                hw, rw = hw2, r2
            if time.process_time() < deadline - 3.0:
                hw3 = _window_polish(hw, deadline)
                r3 = R_of(hw3)
                if r3 > rw:
                    hw, rw = hw3, r3
            if rw > bestR + 1e-12:
                best, bestR = hw.copy(), rw
                print("warp(%d) R=%.7f" % (warp_rounds, bestR))
            else:
                print("warp(%d) no gain (raw %.7f)" % (warp_rounds, rw))
                break
        else:
            print("warp(%d) no gain (raw %.7f)" % (warp_rounds, rw))
            break
        warp_rounds += 1

    # Stage 0: top-K-mean max proxy ladder (helps escape flat-top plateaus).
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    # Stage 2: upsample the best shape and refine on the finer grid.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _upsample(best, factor)
        cand = _rescale_maxL(cand)
        rc = R_of(cand)
        if rc >= bestR - 1e-6:
            h = cand
            h = _full_polish(h, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            else:
                if rc > bestR + 1e-15:
                    best, bestR = cand.copy(), rc
                    print("upsample(f=%d,raw) R=%.7f N=%d" % (factor, bestR, best.size))
        else:
            break

    # Final alternating polish on whatever grid we ended on.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final-full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, maxiter=1200, maxfun=2400):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, maxiter, maxfun, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85
    rng = np.random.default_rng(424242)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    def try_update(h, tag):
        nonlocal best, bestR
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("%s R=%.7f (N=%d)" % (tag, bestR, best.size))
            return True
        return False

    # Stage A: full exact polish on the current grid.
    h = _exact_lbfgs(best, 3000, 6000, deadline)
    try_update(h, "exact-full")

    # Stage B: window polish near the flat top, several passes.
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, frac=0.35)
        if not try_update(h, "window"):
            break

    # Stage C: fine-grid upsampling refinement, growing the grid.
    while best.size * 2 <= 150000 and time.process_time() < deadline - 3.0:
        fine = _upsample(best, 2)
        fine = _exact_lbfgs(fine, 1500, 3000, deadline)
        if not try_update(fine, "fine2"):
            # polish on fine grid even if not strictly better
            fine = _window_polish(fine, deadline, frac=0.4)
            if not try_update(fine, "fine2w"):
                break

    # Stage D: alternating exact / window / up to budget.
    k = 0
    while time.process_time() < deadline - 2.0:
        k += 1
        improved = False
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        if try_update(h, "exact"):
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, frac=0.30)
        if try_update(h, "win"):
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        # try one more upsample if small enough
        if best.size * 2 <= 150000:
            fine = _upsample(best, 2)
            fine = _exact_lbfgs(fine, 1200, 2400, deadline)
            if try_update(fine, "fine"):
                improved = True
        if not improved:
            n = best.size
            lo, hi = _peak_region(best)
            h = best.copy()
            noise = rng.standard_normal(n) * 1e-5
            h = np.clip(h + noise * np.abs(h).max(), 0, None)
            h = _rescale_maxL(h)
            h = _exact_lbfgs(h, 800, 1600, deadline)
            if not try_update(h, "kick"):
                break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

