    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: alternating K schedules. Raising several near-tied maxima at
    # once is what actually lifts R, since the plain max has a degenerate
    # gradient. Sweep K up and back down.
    h = best.copy()
    for K in [2, 3, 4, 6, 8, 6, 4, 3, 2, 1]:
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, bestR))

    # Phase 2: window polish with top-K, then full exact.
    for rep in range(3):
        if time.process_time() >= deadline - 1.5:
            break
        for K in [4, 2, 1]:
            h = _window_polish(best, deadline, frac=0.3, extra=8, K=K)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("wK=%d R=%.7f" % (K, bestR))
        h = _lbfgs(best, 1500, 3000, deadline, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)

    # Phase 3: upsample and re-optimise on a finer grid.
    if time.process_time() < deadline - 5.0:
        hu = _rescale_maxL(_upsample(best, 2))
        for K in [4, 2, 1]:
            if time.process_time() >= deadline - 3.0:
                break
            hu = _lbfgs(hu, 500, 1000, deadline, K=K)
            ru = R_of(hu)
            if ru > bestR + 1e-15:
                best, bestR = hu.copy(), ru
                print("up2 K=%d R=%.7f (N=%d)" % (K, bestR, best.size))

    # Phase 4: keep alternating until the deadline.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        K = 1 + (stall % 4)
        h = _window_polish(best, deadline, frac=0.25 + 0.1 * stall,
                           extra=4 + 4 * stall, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("w R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _lbfgs(best, 1200, 2400, deadline, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("f R=%.7f" % bestR)
        if not improved:
            stall += 1
            if time.process_time() < deadline - 3.0:
                h = _lbfgs(best, 500, 1000, deadline, K=1 + (stall % 3) + 1)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("s R=%.7f" % bestR)
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


# ---- New: smooth (Gaussian) upsample which better preserves R ----

def _smooth_upsample(h, factor, sigma_cells=0.5):
    """Upsample h by `factor` using linear interp then a small Gaussian blur
    on the fine grid; mass-conserving and keeps the peak smooth."""
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


# ---- New: derivative-free coordinate/pattern search on a coarse shape ----

def _pattern_search(h, deadline, n_evals=200, scale=0.02, block=1):
    """Simple pattern search on blocks of heights (log-space multiplicative)."""
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    n = h.size
    if block > 1:
        m = n // block
        if m < 2:
            return h, R_of(h)
        trimmed = h[:m * block].reshape(m, block).mean(axis=1)
        tail = h[m * block:]
    else:
        m = n
        trimmed = h.copy()
        tail = np.zeros(0)

    def assemble(v):
        if block > 1:
            return np.concatenate([np.repeat(v, block), tail])
        return v

    cur = trimmed.copy()
    curR = R_of(assemble(cur))
    step = scale
    for _ in range(n_evals):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False
        # try global multiplicative bump on the peak region
        for direction in (1.0 + step, 1.0 / (1.0 + step)):
            cand = cur * direction
            cand = _rescale_maxL(assemble(cand))
            if block > 1:
                cand_c = cand[:m * block].reshape(m, block).mean(axis=1)
            else:
                cand_c = cand
            r = R_of(cand)
            if r > curR + 1e-15:
                cur = cand_c
                curR = r
                improved = True
                break
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return _rescale_maxL(assemble(cur)), curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder (helps escape flat-top plateaus).
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    # Stage 2: smooth upsample + refine. This is the main change: use a
    # Gaussian-smoothed upsample which preserves R better than plain linear,
    # and try multiple sigma values.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        # try plain linear and a couple of smoothed versions
        candidates = []
        cand_lin = _rescale_maxL(_upsample(best, factor))
        candidates.append(("lin", cand_lin))
        if factor >= 2:
            for sig in (0.3, 0.6, 1.0):
                c = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=sig))
                candidates.append(("sm%.1f" % sig, c))
        # pick best raw candidate
        tag_best, cand_best, rc_best = None, None, -1.0
        for tag, c in candidates:
            rc = R_of(c)
            if rc > rc_best:
                tag_best, cand_best, rc_best = tag, c, rc
        if rc_best < bestR - 1e-5:
            break
        h = _full_polish(cand_best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("upsample(%s,f=%d) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        elif rc_best > bestR + 1e-15:
            best, bestR = cand_best.copy(), rc_best
            print("upsample(%s,f=%d,raw) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        else:
            break

    # Stage 3: pattern search on a coarse block-averaged copy to nudge the
    # overall shape (a cheap, orthogonal move to L-BFGS).
    if time.process_time() < deadline - 2.0 and best.size >= 64:
        try:
            block = max(1, best.size // 2000)
            hc, rc = _pattern_search(best, deadline, n_evals=60, scale=0.02, block=block)
            # refine the nudged shape
            hc2 = _full_polish(hc, deadline, iters=800)
            r2 = R_of(hc2)
            if r2 > bestR + 1e-15:
                best, bestR = hc2.copy(), r2
                print("pattern R=%.7f" % bestR)
        except Exception:
            pass

    # Final alternating polish.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("fin window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1000)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("fin full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

