import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h, K=1):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    mean_top = Lf[idx].sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _lbfgs(h0, maxiter, deadline, K=1):
    if time.process_time() >= deadline - 0.8:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    thresh = 1e-14 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    n = h.size
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        hh = np.zeros(n)
        hh[active] = np.exp(np.clip(u, -30.0, 30.0))
        val, g = _fun_grad(hh, K)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.8:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-21, 'gtol': 1e-17})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_split(h, frac=0.35):
    n = h.size
    if n < 4:
        return h.copy()
    g = np.abs(_fun_grad(h)[1])
    score = g * (h + 1e-12 * h.max())
    k = max(1, min(int(frac * n), n))
    if n + k > 200000:
        k = max(1, 200000 - n)
    idx = np.argpartition(-score, k - 1)[:k]
    sel = np.zeros(n, dtype=bool)
    sel[idx] = True
    new_n = n + int(sel.sum())
    h2 = np.empty(new_n)
    pos = 0
    for i in range(n):
        if sel[i]:
            h2[pos] = h[i]; h2[pos + 1] = h[i]; pos += 2
        else:
            h2[pos] = h[i]; pos += 1
    return h2


def _perturb(h, rng, scale):
    h = h.copy()
    nz = h > 0
    if not nz.any():
        return h
    h[nz] *= np.exp(rng.normal(0, scale, size=int(nz.sum())))
    return _rescale_maxL(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Refine with top-K smoothing to escape the sharp-peak local optimum.
    for K in [1, 1, 3, 8, 1]:
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs(best, 1200, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, bestR))

    # Resolution growth: split where gradient is large, then re-polish.
    for it in range(8):
        if time.process_time() >= deadline - 2.5:
            break
        frac = 0.30 if it < 3 else 0.18
        hs = _peak_split(best, frac=frac)
        hs = _lbfgs(hs, 800, deadline, K=1)
        r = R_of(hs)
        if r > bestR + 1e-15:
            best, bestR = hs.copy(), r
            print("split %d R=%.7f (N=%d)" % (it, bestR, best.size))

    # Basin hopping on the current best.
    rng = np.random.default_rng(1234567)
    it = 0
    scales = [1e-3, 3e-3, 1e-2, 3e-2, 1e-1]
    while time.process_time() < deadline - 2.0:
        it += 1
        sc = scales[it % len(scales)]
        h_try = _perturb(best, rng, sc)
        h_try = _lbfgs(h_try, 500, deadline, K=1)
        r = R_of(h_try)
        if r > bestR + 1e-16:
            best, bestR = h_try.copy(), r
            print("hop %d sc=%.0e R=%.7f" % (it, sc, bestR))

    # Final tight polish.
    h = _lbfgs(best, 4000, deadline, K=1)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

