        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min(); hi_k = idx.max()
    lo = max(0, lo_k - 1); hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _cumulative_mass_upsample(h, m):
    n = h.size
    if n == m:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(m)
    c /= total
    xo = np.linspace(0.0, 1.0, m + 1)
    co = np.interp(xo, np.linspace(0.0, 1.0, n + 1), c)
    co[0] = 0.0; co[-1] = 1.0
    co = np.maximum.accumulate(co)
    out = np.clip(np.diff(co), 0, None)
    if out.sum() <= 0:
        return np.ones(m)
    return out * (total / out.sum())


def _signed_spectrum_candidates(Nc, deadline):
    M = 2 * Nc
    cands = []
    Ws = [0.30, 0.45, 0.60, 0.75, 0.90]
    ts = [0.02, 0.10, 0.25]
    j = np.arange(M)
    center = M / 2.0
    for wf in Ws:
        W = wf * Nc
        for tf in ts:
            if time.process_time() >= deadline - 2.0:
                break
            t = tf * W
            d = np.abs(j - center)
            L = np.zeros(M)
            half = W / 2.0
            L[d <= half] = 1.0
            if t > 0:
                ramp = (d > half) & (d <= half + t)
                L[ramp] = 1.0 - (d[ramp] - half) / t
            g = np.fft.rfft(L)
            A = np.sign(g) * np.sqrt(np.abs(g))
            hc = np.fft.irfft(A, M)
            c1 = np.clip(hc[:Nc], 0, None)
            if c1.sum() > 0:
                cands.append(_rescale_maxL(c1))
            c2 = np.abs(hc[:Nc])
            if c2.sum() > 0:
                cands.append(_rescale_maxL(c2))
    return cands


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage -1: signed-spectrum candidates at coarse resolution
    Nc = 2657
    try:
        cands = _signed_spectrum_candidates(Nc, deadline)
    except Exception:
        cands = []
    polished = []
    for c in cands:
        if time.process_time() >= deadline - 2.0:
            break
        try:
            hp = _exact_lbfgs(c, 1500, 3000, deadline)
            polished.append((R_of(hp), hp))
        except Exception:
            pass
    polished.sort(key=lambda z: -z[0])
    print("stage-1: %d cands, best coarse R=%.7f" %
          (len(polished), polished[0][0] if polished else -1.0))

    targetN = 42496
    for rank in range(min(2, len(polished))):
        if time.process_time() >= deadline - 2.0:
            break
        r0, h = polished[rank]
        h = h.copy()
        r = r0
        for step in range(3):
            if time.process_time() >= deadline - 2.0:
                break
            n = h.size
            m = min(targetN, n * 2)
            if m <= n:
                break
            try:
                h2 = _cumulative_mass_upsample(h, m)
                h2 = _rescale_maxL(h2)
                h2 = _exact_lbfgs(h2, 1500, 3000, deadline)
                r2 = R_of(h2)
                h, r = h2, r2
            except Exception:
                break
        if time.process_time() < deadline - 2.0:
            try:
                hw = _window_polish(h, deadline)
                rw = R_of(hw)
                if rw > r + 1e-12:
                    h, r = hw, rw
            except Exception:
                pass
        print("stage-1 ladder rank=%d R=%.7f N=%d" % (rank, r, h.size))
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
            print("stage-1 accepted R=%.7f N=%d" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # ---- NEW Stage 2: local smoothing of the sharp peak ----
    # The optimum looks like a plateau whose autoconvolution peak is a
    # sharp triangular spike. Flatten the peak top slightly by moving mass
    # from the very top of h to its neighbours; this broadens the top of
    # f*f and can raise R. We do a small parametric family and keep best.
    def _smooth_peak(h, alpha, width):
        n = h.size
        if alpha <= 0 or width < 1:
            return h
        # Gaussian smoothing of h with small sigma, blended
        s = width
        rad = int(np.ceil(3 * s))
        if rad < 1:
            return h
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), h, np.zeros(rad)])
        hs = np.convolve(hp, k, mode='same')[rad:-rad]
        hs = np.clip(hs, 0, None)
        return (1.0 - alpha) * h + alpha * hs

    if time.process_time() < deadline - 2.0:
        improved = False
        cur = best.copy()
        for width in (0.5, 1.0, 2.0, 3.0, 5.0):
            for alpha in (0.02, 0.05, 0.1, 0.2):
                if time.process_time() >= deadline - 2.0:
                    break
                hc = _smooth_peak(cur, alpha, width)
                hc = _rescale_maxL(hc)
                # short polish of the smoothed candidate
                hc = _exact_lbfgs(hc, 400, 800, deadline)
                rc = R_of(hc)
                if rc > bestR + 1e-12:
                    best, bestR = hc.copy(), rc
                    cur = hc
                    improved = True
                    print("smooth a=%.2f w=%.1f R=%.7f" % (alpha, width, bestR))
        if improved:
            print("after smooth R=%.7f" % bestR)

    # ---- Stage 3: alternating window / full polish until deadline ----
    stall = 0
    lastR = bestR
    while time.process_time() < deadline - 2.0:
        if time.process_time() >= deadline - 2.0:
            break
        hw = _window_polish(best, deadline, frac=0.5, extra=8)
        rw = R_of(hw)
        if rw > bestR + 1e-13:
            best, bestR = hw.copy(), rw
            stall = 0
        else:
            stall += 1
        if time.process_time() >= deadline - 2.0:
            break
        hf = _full_polish(best, deadline, iters=800)
        rf = R_of(hf)
        if rf > bestR + 1e-13:
            best, bestR = hf.copy(), rf
            stall = 0
        else:
            stall += 1
        if stall >= 3:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _pattern_search(h, deadline, n_evals=200, scale=0.02, block=1):
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    n = h.size
    if block > 1:
        m = n // block
        if m < 2:
            return h, R_of(h)
        trimmed = h[:m * block].reshape(m, block).mean(axis=1)
        tail = h[m * block:]
    else:
        m = n
        trimmed = h.copy()
        tail = np.zeros(0)

    def assemble(v):
        if block > 1:
            return np.concatenate([np.repeat(v, block), tail])
        return v

    cur = trimmed.copy()
    curR = R_of(assemble(cur))
    step = scale
    for _ in range(n_evals):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False
        for direction in (1.0 + step, 1.0 / (1.0 + step)):
            cand = cur * direction
            cand = _rescale_maxL(assemble(cand))
            if block > 1:
                cand_c = cand[:m * block].reshape(m, block).mean(axis=1)
            else:
                cand_c = cand
            r = R_of(cand)
            if r > curR + 1e-15:
                cur = cand_c
                curR = r
                improved = True
                break
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return _rescale_maxL(assemble(cur)), curR


def _subblock_shake(best, bestR, deadline, rng):
    """Experiment: change number of nonzero cells inside a small block at
    fixed block mass, then short local polish. Accept only improvements."""
    n = best.size
    accepted = 0
    trials = 0
    while time.process_time() < deadline - 2.0:
        trials += 1
        B = int(rng.choice([8, 16]))
        if B >= n:
            continue
        s = int(rng.integers(0, n - B + 1))
        m = best[s:s + B].sum()
        if m <= 0:
            continue
        p = int(rng.choice([3, 5, 8, 11]))
        if p >= B:
            p = B - 1
        if p < 1:
            continue
        cand = best.copy()
        cand[s:s + B] = 0.0
        if rng.random() < 0.5:
            cells = rng.choice(B, size=p, replace=False)
        else:
            cells = np.linspace(0, B - 1, p).round().astype(int)
            cells = np.unique(cells)
            if cells.size < p:
                continue
        cand[s + cells] = m / p
        cand = _rescale_maxL(cand)
        lo = max(0, s - 3 * B)
        hi = min(n - 1, s + B + 3 * B - 1)
        free = np.arange(lo, hi + 1)
        cand = _exact_lbfgs(cand, 60, 120, deadline, free=free)
        cand = _rescale_maxL(cand)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand
            bestR = r
            accepted += 1
            best = _window_polish(best, deadline)
            bestR = R_of(best)
            print("subblock accept R=%.7f (trials=%d)" % (bestR, trials))
    print("subblock shake: %d accepted / %d trials" % (accepted, trials))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # Stage 2: coarse/fine resample shake-out.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n < 64:
            break
        factor = 2
        m = n // factor
        if m < 16:
            break
        coarse = best[:m * factor].reshape(m, factor).mean(axis=1)
        tail = best[m * factor:]
        cand = np.concatenate([coarse, tail]) if tail.size else coarse
        cand = _rescale_maxL(cand)
        hc = _full_polish(cand, deadline, iters=800)
        rc = R_of(hc)
        back = _rescale_maxL(_smooth_upsample(hc, factor, sigma_cells=0.4))
        if back.size != n:
            xo = np.linspace(0, 1, n)
            xi = np.linspace(0, 1, back.size)
            back = np.interp(xo, xi, back)
            back = _rescale_maxL(back)
        hf = _full_polish(back, deadline, iters=800)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("resample R=%.7f N=%d" % (bestR, best.size))
        elif rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("coarse R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    # Stage 3: smooth upsample to larger N and refine, if budget remains.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        candidates = []
        cand_lin = _rescale_maxL(_upsample(best, factor))
        candidates.append(("lin", cand_lin))
        for sig in (0.3, 0.6, 1.0):
            c = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=sig))
            candidates.append(("sm%.1f" % sig, c))
        tag_best, cand_best, rc_best = None, None, -1.0
        for tag, c in candidates:
            rc = R_of(c)
            if rc > rc_best:
                tag_best, cand_best, rc_best = tag, c, rc
        if rc_best < bestR - 1e-5:
            break
        h = _full_polish(cand_best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("upsample(%s,f=%d) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        elif rc_best > bestR + 1e-15:
            best, bestR = cand_best.copy(), rc_best
            print("upsample(%s,f=%d,raw) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        else:
            break

    # Stage 4: pattern search on blocks.
    for block in (1, 2, 4):
        if time.process_time() >= deadline - 1.0:
            break
        h, r = _pattern_search(best, deadline, n_evals=100, scale=0.01, block=block)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("pattern(block=%d) R=%.7f" % (block, bestR))

    # Stage 5 (experiment): sub-block zero-pattern shake.
    rng = np.random.default_rng(12345)
    if time.process_time() < deadline - 2.0:
        best, bestR = _subblock_shake(best, bestR, deadline, rng)

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _lbfgs_linear(h0, deadline, maxiter=3000, free=None):
    """L-BFGS-B optimising h directly (bounds 0..inf), no log parametrisation."""
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        active = np.arange(n)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = h[active].copy()

    def f(u):
        uu = np.clip(u, 0.0, None)
        hh = np.zeros(n)
        hh[active] = uu
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.clip(res.x, 0.0, None)
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _pattern_search(h, deadline, n_evals=200, scale=0.02, block=1):
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    n = h.size
    if block > 1:
        m = n // block
        if m < 2:
            return h, R_of(h)
        trimmed = h[:m * block].reshape(m, block).mean(axis=1)
        tail = h[m * block:]
    else:
        m = n
        trimmed = h.copy()
        tail = np.zeros(0)

    def assemble(v):
        if block > 1:
            return np.concatenate([np.repeat(v, block), tail])
        return v

    cur = trimmed.copy()
    curR = R_of(assemble(cur))
    step = scale
    for _ in range(n_evals):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False
        for direction in (1.0 + step, 1.0 / (1.0 + step)):
            cand = cur * direction
            cand = _rescale_maxL(assemble(cand))
            if block > 1:
                cand_c = cand[:m * block].reshape(m, block).mean(axis=1)
            else:
                cand_c = cand
            r = R_of(cand)
            if r > curR + 1e-15:
                cur = cand_c
                curR = r
                improved = True
                break
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return _rescale_maxL(assemble(cur)), curR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # NEW Stage 0.5: linear-parametrisation L-BFGS + KKT diagnostics.
    if time.process_time() < deadline - 3.0:
        hl = _lbfgs_linear(best, deadline, maxiter=3000)
        rl = R_of(hl)
        print("linear R=%.7f" % rl)
        if rl > bestR + 1e-15:
            best, bestR = hl.copy(), rl
            print("linear improved R=%.7f" % bestR)

        # KKT diagnostics at best.
        try:
            val, g = _norm_eq_fun_grad(best)
            hmax = best.max()
            zero_mask = best <= 1e-12 * hmax
            I = np.flatnonzero(zero_mask & (g > 0))
            act = np.flatnonzero(~zero_mask)
            maxg_I = float(g[I].max()) if I.size > 0 else 0.0
            maxg_act = float(np.abs(g[act]).max()) if act.size > 0 else 0.0
            print("KKT |I|=%d maxg_I=%.3e max|g|_active=%.3e"
                  % (I.size, maxg_I, maxg_act))
        except Exception:
            I = np.zeros(0, dtype=int)

        if I.size > 0 and time.process_time() < deadline - 2.0:
            hrev = best.copy()
            hrev[I] += 1e-6 * hrev.max()
            hrev = _rescale_maxL(hrev)
            hrev = _lbfgs_linear(hrev, deadline, maxiter=1500)
            hrev = _exact_lbfgs(hrev, 1500, 3000, deadline)
            rrev = R_of(hrev)
            print("revive R=%.7f" % rrev)
            if rrev > bestR + 1e-15:
                best, bestR = hrev.copy(), rrev
                print("revive improved R=%.7f" % bestR)

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # Stage 2: coarse/fine resample shake-out.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n < 64:
            break
        factor = 2
        m = n // factor
        if m < 16:
            break
        coarse = best[:m * factor].reshape(m, factor).mean(axis=1)
        tail = best[m * factor:]
        cand = np.concatenate([coarse, tail]) if tail.size else coarse
        cand = _rescale_maxL(cand)
        hc = _full_polish(cand, deadline, iters=800)
        rc = R_of(hc)
        back = _rescale_maxL(_smooth_upsample(hc, factor, sigma_cells=0.4))
        if back.size != n:
            xo = np.linspace(0, 1, n)
            xi = np.linspace(0, 1, back.size)
            back = np.interp(xo, xi, back)
            back = _rescale_maxL(back)
        hf = _full_polish(back, deadline, iters=800)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("resample R=%.7f N=%d" % (bestR, best.size))
        elif rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("coarse R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    # Stage 3: smooth upsample to larger N and refine, if budget remains.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        candidates = []
        cand_lin = _rescale_maxL(_upsample(best, factor))
        candidates.append(("lin", cand_lin))
        for sig in (0.3, 0.6, 1.0):
            c = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=sig))
            candidates.append(("sm%.1f" % sig, c))
        tag_best, cand_best, rc_best = None, None, -1.0
        for tag, c in candidates:
            rc = R_of(c)
            if rc > rc_best:
                tag_best, cand_best, rc_best = tag, c, rc
        if rc_best < bestR - 1e-5:
            break
        h = _full_polish(cand_best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("upsample(%s,f=%d) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        elif rc_best > bestR + 1e-15:
            best, bestR = cand_best.copy(), rc_best
            print("upsample(%s,f=%d,raw) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        else:
            break

    # Stage 4: pattern search on final best.
    if time.process_time() < deadline - 1.0:
        best, bestR = _pattern_search(best, deadline, n_evals=200, scale=0.02, block=1)
        print("pattern R=%.7f" % bestR)

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

