    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _pattern_search(h, deadline, n_evals=200, scale=0.02, block=1):
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    n = h.size
    if block > 1:
        m = n // block
        if m < 2:
            return h, R_of(h)
        trimmed = h[:m * block].reshape(m, block).mean(axis=1)
        tail = h[m * block:]
    else:
        m = n
        trimmed = h.copy()
        tail = np.zeros(0)

    def assemble(v):
        if block > 1:
            return np.concatenate([np.repeat(v, block), tail])
        return v

    cur = trimmed.copy()
    curR = R_of(assemble(cur))
    step = scale
    for _ in range(n_evals):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False
        for direction in (1.0 + step, 1.0 / (1.0 + step)):
            cand = cur * direction
            cand = _rescale_maxL(assemble(cand))
            if block > 1:
                cand_c = cand[:m * block].reshape(m, block).mean(axis=1)
            else:
                cand_c = cand
            r = R_of(cand)
            if r > curR + 1e-15:
                cur = cand_c
                curR = r
                improved = True
                break
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return _rescale_maxL(assemble(cur)), curR


def _qr_set(v):
    """Quadratic residues mod v (nonzero)."""
    return set((i * i) % v for i in range(1, v))


def _algebraic_candidates(deadline, target_n=42496):
    """Build algebraic-comb candidates and polish them. Returns list of (R, h)."""
    results = []
    primes = [31, 63, 127, 251, 503]
    for v in primes:
        if time.process_time() >= deadline - 3.0:
            break
        A = _qr_set(v)
        if not A:
            continue
        variants = []
        # base residue set and complement
        for base_set in (A, set(range(v)) - A):
            bs = sorted(base_set)
            if not bs:
                continue
            # reflection
            for refl in (False, True):
                variants.append((bs, refl, 1))
        # two adjacent nonzero cells per residue variant
        for base_set in (A,):
            bs = sorted(base_set)
            if bs:
                variants.append((bs, False, 2))

        for bs, refl, width in variants:
            if time.process_time() >= deadline - 3.0:
                break
            m = max(1, 2048 // v)
            N0 = m * v
            if N0 < 2:
                continue
            h = np.zeros(N0)
            for i in range(N0):
                r = i % v
                if refl:
                    r = (v - r) % v
                if r in set(bs):
                    for w in range(width):
                        j = i + w
                        if j < N0:
                            h[j] = 1.0
            if h.sum() <= 0:
                continue
            h = _rescale_maxL(h)
            h = _exact_lbfgs(h, 800, 1600, deadline)
            r = R_of(h)
            results.append((r, h))
    results.sort(key=lambda t: -t[0])
    return results[:3]


def _ladder_up(h, deadline, target_n=42496):
    """Upsample x2, polish, window polish, repeat until target_n."""
    best = h.copy()
    bestR = R_of(best)
    while best.size < target_n and time.process_time() < deadline - 2.0:
        factor = 2
        if best.size * factor > target_n:
            factor = max(1, target_n // best.size)
            if factor < 2:
                break
        cand = _rescale_maxL(_upsample(best, factor))
        cand = _full_polish(cand, deadline, iters=800)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand, r
        else:
            # try smooth upsample
            cand2 = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=0.4))
            cand2 = _full_polish(cand2, deadline, iters=800)
            r2 = R_of(cand2)
            if r2 > bestR + 1e-15:
                best, bestR = cand2, r2
            else:
                break
        if time.process_time() >= deadline - 2.0:
            break
        w = _window_polish(best, deadline)
        rw = R_of(w)
        if rw > bestR + 1e-15:
            best, bestR = w, rw
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage -1: algebraic-comb multistart (Legendre/quadratic-residue combs).
    try:
        alg_cands = _algebraic_candidates(deadline)
    except Exception:
        alg_cands = []
    for r0, h0 in alg_cands:
        if time.process_time() >= deadline - 2.0:
            break
        h_lad, r_lad = _ladder_up(h0, deadline)
        print("alg comb R=%.7f N=%d (raw %.7f)" % (r_lad, h_lad.size, r0))
        if r_lad > bestR + 1e-15:
            best, bestR = h_lad.copy(), r_lad
            print("alg accepted R=%.7f" % bestR)

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # Stage 2: coarse/fine resample shake-out.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n < 64:
            break
        factor = 2
        m = n // factor
        if m < 16:
            break
        coarse = best[:m * factor].reshape(m, factor).mean(axis=1)
        tail = best[m * factor:]
        cand = np.concatenate([coarse, tail]) if tail.size else coarse
        cand = _rescale_maxL(cand)
        hc = _full_polish(cand, deadline, iters=800)
        rc = R_of(hc)
        back = _rescale_maxL(_smooth_upsample(hc, factor, sigma_cells=0.4))
        if back.size != n:
            xo = np.linspace(0, 1, n)
            xi = np.linspace(0, 1, back.size)
            back = np.interp(xo, xi, back)
            back = _rescale_maxL(back)
        hf = _full_polish(back, deadline, iters=800)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("resample R=%.7f N=%d" % (bestR, best.size))
        elif rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("coarse R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    # Stage 3: smooth upsample to larger N and refine, if budget remains.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        candidates = []
        cand_lin = _rescale_maxL(_upsample(best, factor))
        candidates.append(("lin", cand_lin))
        for sig in (0.3, 0.6, 1.0):
            c = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=sig))
            candidates.append(("sm%.1f" % sig, c))
        tag_best, cand_best, rc_best = None, None, -1.0
        for tag, c in candidates:
            rc = R_of(c)
            if rc > rc_best:
                tag_best, cand_best, rc_best = tag, c, rc
        if rc_best < bestR - 1e-5:
            break
        h = _full_polish(cand_best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("upsample(%s,f=%d) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        elif rc_best > bestR + 1e-15:
            best, bestR = cand_best.copy(), rc_best
            print("upsample(%s,f=%d,raw) R=%.7f N=%d" % (tag_best, factor, bestR, best.size))
        else:
            break

    # Stage 4: pattern search on block-averaged representation.
    while time.process_time() < deadline - 1.0:
        h, r = _pattern_search(best, deadline, n_evals=200, scale=0.02, block=1)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("pattern R=%.7f" % bestR)
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.5:
            raise TimeoutError

    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    try:
        h2 = np.zeros(n)
        if res is not None:
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        else:
            h2[active] = np.exp(u0)
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    return max(0, idx.min() - 1), min(n - 1, idx.max())


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1000, 2000, deadline, free=free)


def _full_polish(h, deadline, iters=2500):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.clip(np.interp(xo, np.arange(n), h), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 1: window polish on the start, then full polish.
    h = _window_polish(best, deadline)
    r = R_of(h)
    if r > bestR + 1e-15:
        best, bestR = h.copy(), r
        print("window R=%.7f" % bestR)

    h = _full_polish(best, deadline, iters=2500)
    r = R_of(h)
    if r > bestR + 1e-15:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage 2: try upsampling the grid (finer resolution) and re-polish.
    # Only if there is time left for a meaningful refinement.
    while time.process_time() < deadline - 6.0 and best.size < 120000:
        n = best.size
        factor = 2 if 2 * n <= 120000 else 1
        if factor == 1:
            break
        up = _upsample(best, factor)
        up = _rescale_maxL(up)
        r0 = R_of(up)
        # polish the upsampled version, first window then full
        h = _window_polish(up, deadline, frac=0.4)
        r = R_of(h)
        if r < r0 - 1e-9:
            h = up
            r = r0
        h2 = _full_polish(h, deadline, iters=1500)
        r2 = R_of(h2)
        if r2 > r:
            h, r = h2, r2
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
            print("upsample x%d R=%.7f (N=%d)" % (factor, bestR, best.size))
        else:
            break

    # Stage 3: alternating window/full polish until time runs out.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.0:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.0:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    rbase = R_of(base)
    if rbase > bestR:
        best = base
        bestR = rbase

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, K=1, maxiter=1200):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs(h, maxiter, 2 * maxiter, deadline, free=free, K=K)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: alternating K schedules.
    h = best.copy()
    for K in [2, 3, 4, 6, 8, 6, 4, 3, 2, 1]:
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, bestR))

    # Phase 2: window polish with top-K, then full exact.
    for rep in range(3):
        if time.process_time() >= deadline - 1.5:
            break
        for K in [4, 2, 1]:
            h = _window_polish(best, deadline, frac=0.3, extra=8, K=K)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("wK=%d R=%.7f" % (K, bestR))
        h = _lbfgs(best, 1500, 3000, deadline, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)

    # Phase 3: smooth upsample and re-optimise on a finer grid.
    if time.process_time() < deadline - 5.0:
        hu = _rescale_maxL(_smooth_upsample(best, 2, sigma_cells=0.5))
        for K in [4, 2, 1]:
            if time.process_time() >= deadline - 3.0:
                break
            hu = _lbfgs(hu, 600, 1200, deadline, K=K)
            ru = R_of(hu)
            if ru > bestR + 1e-15:
                best, bestR = hu.copy(), ru
                print("up2 K=%d R=%.7f (N=%d)" % (K, bestR, best.size))

    # Phase 4: keep alternating until the deadline with varied windows.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        K = 1 + (stall % 4)
        h = _window_polish(best, deadline, frac=0.25 + 0.1 * stall,
                           extra=4 + 4 * stall, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("w R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _lbfgs(best, 1200, 2400, deadline, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("f R=%.7f" % bestR)
        if not improved:
            stall += 1
            if time.process_time() < deadline - 3.0:
                h = _lbfgs(best, 500, 1000, deadline, K=1 + (stall % 3) + 1)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("s R=%.7f" % bestR)
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 0.8:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 0.8:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 0.8:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # Stage 2: smooth upsample to larger N and refine, if budget remains.
    while time.process_time() < deadline - 0.8:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=0.4))
        if cand.size > 200000:
            cand = cand[:200000]
        cand = _rescale_maxL(cand)
        hf = _full_polish(cand, deadline, iters=800)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("upsample R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

