    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _pattern_search(h, deadline, n_evals=200, scale=0.02, block=1):
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    n = h.size
    if block > 1:
        m = n // block
        if m < 2:
            return h, R_of(h)
        trimmed = h[:m * block].reshape(m, block).mean(axis=1)
        tail = h[m * block:]
    else:
        m = n
        trimmed = h.copy()
        tail = np.zeros(0)

    def assemble(v):
        if block > 1:
            return np.concatenate([np.repeat(v, block), tail])
        return v

    cur = trimmed.copy()
    curR = R_of(assemble(cur))
    step = scale
    for _ in range(n_evals):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False
        for direction in (1.0 + step, 1.0 / (1.0 + step)):
            cand = cur * direction
            cand = _rescale_maxL(assemble(cand))
            if block > 1:
                cand_c = cand[:m * block].reshape(m, block).mean(axis=1)
            else:
                cand_c = cand
            r = R_of(cand)
            if r > curR + 1e-15:
                cur = cand_c
                curR = r
                improved = True
                break
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return _rescale_maxL(assemble(cur)), curR


def _subblock_shake(best, bestR, deadline, rng):
    """Experiment: change number of nonzero cells inside a small block at
    fixed block mass, then short local polish. Accept only improvements."""
    n = best.size
    accepted = 0
    trials = 0
    while time.process_time() < deadline - 2.0:
        trials += 1
        B = int(rng.choice([8, 16]))
        if B >= n:
            continue
        s = int(rng.integers(0, n - B + 1))
        m = best[s:s + B].sum()
        if m <= 0:
            continue
        p = int(rng.choice([3, 5, 8, 11]))
        if p >= B:
            p = B - 1
        if p < 1:
            continue
        cand = best.copy()
        cand[s:s + B] = 0.0
        if rng.random() < 0.5:
            cells = rng.choice(B, size=p, replace=False)
        else:
            cells = np.linspace(0, B - 1, p).round().astype(int)
            cells = np.unique(cells)
            if cells.size < p:
                continue
        cand[s + cells] = m / p
        cand = _rescale_maxL(cand)
        lo = max(0, s - 3 * B)
        hi = min(n - 1, s + B + 3 * B - 1)
        free = np.arange(lo, hi + 1)
        cand = _exact_lbfgs(cand, 60, 120, deadline, free=free)
        cand = _rescale_maxL(cand)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand
            bestR = r
            accepted += 1
            best = _window_polish(best, deadline)
            bestR = R_of(best)
            print("subblock accept R=%.7f (trials=%d)" % (bestR, trials))
    print("subblock shake: %d accepted / %d trials" % (accepted, trials))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 0b: theta homotopy on the max-term exponent.
    h = best.copy()
    for theta in (1.6, 1.3, 1.1, 1.0, 0.95, 1.0):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 1500, 3000, deadline, theta=theta)
        h = _rescale_maxL(h)
        r = R_of(h)
        print("theta=%.2f R=%.7f" % (theta, r))
        if theta == 1.0 and r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("theta accept R=%.7f" % bestR)

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # Stage 2: coarse/fine resample shake-out.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n < 64:
            break
        factor = 2
        m = n // factor
        if m < 16:
            break
        coarse = best[:m * factor].reshape(m, factor).mean(axis=1)
        tail = best[m * factor:]
        cand = np.concatenate([coarse, tail]) if tail.size else coarse
        cand = _rescale_maxL(cand)
        hc = _full_polish(cand, deadline, iters=800)
        rc = R_of(hc)
        back = _rescale_maxL(_smooth_upsample(hc, factor, sigma_cells=0.4))
        if back.size != n:
            xo = np.linspace(0, 1, n)
            xi = np.linspace(0, 1, back.size)
            back = np.interp(xo, xi, back)
            back = _rescale_maxL(back)
        hf = _full_polish(back, deadline, iters=800)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("resample R=%.7f N=%d" % (bestR, best.size))
        elif rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("coarse R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    # Stage 3: smooth upsample to larger N and refine, if budget remains.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        candidates = []
        cand_lin = _rescale_maxL(_upsample(best, factor))
        cand_sm = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=0.4))
        for cand in (cand_lin, cand_sm):
            if time.process_time() >= deadline - 1.0:
                break
            hc = _full_polish(cand, deadline, iters=600)
            rc = R_of(hc)
            candidates.append((rc, hc))
        if not candidates:
            break
        rc, hc = max(candidates, key=lambda t: t[0])
        if rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("upsample R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _window_polish(h, deadline, frac=0.10):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    c = m - 1
    half = max(4, int(frac * n))
    lo = max(0, c - half)
    hi = min(n, c + half + 1)
    free = np.arange(lo, hi)
    if free.size >= n:
        return h
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    hard = t0 + budget_seconds * 0.97
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Try upsampling; also try a mild smoothing to escape grid artifacts.
    if best.size < 120000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR + 1e-9:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    # Alternate full exact polish with windowed polish, repeatedly
    # until the budget runs out. Keep whichever improves.
    while time.process_time() < deadline - 1.0:
        improved = False
        h2 = _exact_lbfgs(best, 4000, 8000, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            improved = True
            print("full polish R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        for frac in (0.03, 0.08, 0.20):
            if time.process_time() >= deadline - 1.0:
                break
            h3 = _window_polish(best, deadline, frac=frac)
            r3 = R_of(h3)
            if r3 > bestR + 1e-16:
                best, bestR = h3.copy(), r3
                improved = True
        if not improved:
            break

    # Final long exact polish on remaining budget.
    while time.process_time() < hard - 0.5:
        h2 = _exact_lbfgs(best, 5000, 10000, deadline=hard)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _below_max_fun_grad(h, delta):
    """Objective that pushes ALL near-max knots up to the max (mean of near-max),
    which effectively flattens the peak -> more mass near the top -> higher R."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    thr = mx * (1.0 - delta)
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        idx = np.array([int(np.argmax(Lf))])
    K = idx.size
    mean_top = Lf[idx].sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, delta=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if delta is not None:
            val, g = _below_max_fun_grad(hh, delta)
        else:
            val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, delta=None):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, delta=delta)


def _full_polish(h, deadline, iters=3000, delta=None):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, delta=delta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: delta-continuation. Start smoothing the peak (large delta = many
    # near-max knots share the max), gradually tighten. This flattens the top of
    # f*f which is what raises R beyond the plain max-knot objective.
    h = best.copy()
    for delta in (0.02, 0.01, 0.003, 0.001, 0.0):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 300, 600, deadline, delta=(delta if delta > 0 else None))
        r = R_of(h)
        print("delta=%.3f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        if time.process_time() < deadline - 2.0:
            h2 = _window_polish(h, deadline, delta=(delta if delta > 0 else None))
            r2 = R_of(h2)
            if r2 > r:
                h = h2
                if r2 > bestR + 1e-15:
                    best, bestR = h2.copy(), r2
                    print("delta+win=%.3f R=%.7f" % (delta, r2))

    # Stage 1: alternating window / full polish with the plain objective.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                # one more attempt with a small delta push then a wide window
                h = _full_polish(best, deadline, iters=800, delta=0.0005)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("delta-push R=%.7f" % bestR)
                else:
                    h = _window_polish(best, deadline, frac=0.6, extra=16)
                    r = R_of(h)
                    if r > bestR + 1e-15:
                        best, bestR = h.copy(), r
                        stall = 0
                        print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _build_modes(n, K=64, seed=777):
    rng = np.random.default_rng(seed)
    x = (np.arange(n) + 0.5) / n
    Phi = np.zeros((K, n))
    for k in range(K):
        nb = 8
        bp = np.sort(rng.uniform(0.0, 1.0, nb))
        vals = rng.standard_normal(nb)
        phi = np.interp(x, bp, vals)
        phi = phi - phi.mean()
        nrm = np.linalg.norm(phi)
        if nrm > 0:
            phi = phi / nrm
        Phi[k] = phi
    return Phi


def _subspace_restarts(best, bestR, deadline, K=64, n_restarts=6):
    n = best.size
    Phi = _build_modes(n, K=K, seed=777)
    rng = np.random.default_rng(2024)
    base = best.copy()

    def make_fun(base_h):
        def f(z):
            z = np.clip(z, -1.0, 1.0)
            hh = _rescale_maxL(base_h * np.exp(Phi.T @ z))
            val, g = _norm_eq_fun_grad(hh)
            gz = Phi @ (g * hh)
            return val, gz
        return f

    for r in range(n_restarts):
        if time.process_time() >= deadline - 2.0:
            break
        f = make_fun(base)
        z0 = rng.standard_normal(K) * 0.02
        cb = _make_cb(deadline - 1.0)
        try:
            res = minimize(f, z0, jac=True, method='L-BFGS-B',
                           bounds=[(-1.0, 1.0)] * K,
                           callback=cb,
                           options={'maxiter': 300, 'maxfun': 600,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            z = np.clip(res.x, -1.0, 1.0)
        except TimeoutError:
            try:
                z = np.clip(res.x, -1.0, 1.0)
            except Exception:
                z = z0
        except Exception:
            z = z0
        hnew = _rescale_maxL(base * np.exp(Phi.T @ z))
        if time.process_time() < deadline - 1.5:
            hnew = _exact_lbfgs(hnew, 300, 600, deadline)
        rnew = R_of(hnew)
        if rnew > bestR + 1e-16:
            best = hnew.copy()
            bestR = rnew
            base = best.copy()
            print("subspace restart %d R=%.7f" % (r, bestR))
        else:
            print("subspace restart %d no gain (R=%.7f)" % (r, rnew))
    return best, bestR


def _resample_shift(h, shift, factor=1):
    # shift in units of original steps, then optionally upsample
    n = h.size
    x = np.arange(n)
    xo = np.arange(n) - shift
    h2 = np.interp(xo, x, h, left=0.0, right=0.0)
    if factor > 1:
        h2 = _upsample(h2, factor)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 1: exact polishing on the given grid, then window polish.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Stage 2: fine-grid upsampling refinement (a genuine resolution increase).
    if best.size * 2 <= 100000 and time.process_time() < deadline - 3.0:
        fine = _upsample(best, 2)
        fine = _exact_lbfgs(fine, 800, 1600, deadline)
        rf = R_of(fine)
        if rf > bestR:
            best, bestR = fine.copy(), rf
            print("fine R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 3: subpixel shift search, then re-polish.  This is the new move:
    # the optimum is typically not aligned to the current grid, so a
    # fractional shift followed by re-optimisation can escape a grid-locked
    # local optimum.
    if time.process_time() < deadline - 4.0:
        shifts = [0.5, -0.5, 0.25, -0.25, 0.75, -0.75]
        for sh in shifts:
            if time.process_time() >= deadline - 3.0:
                break
            hs = _resample_shift(best, sh)
            hs = _exact_lbfgs(hs, 600, 1200, deadline)
            rs = R_of(hs)
            if rs > bestR + 1e-16:
                best, bestR = hs.copy(), rs
                print("shift %.2f R=%.7f" % (sh, bestR))

    # Stage 4: random-subspace restarts on whatever is best now.
    best, bestR = _subspace_restarts(best, bestR, deadline, K=64, n_restarts=6)

    # Final window polish if time remains.
    if time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("final window R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
