    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    mask = Lf >= thr
    idx = np.flatnonzero(mask)
    if idx.size == 0:
        return max(0, m - 1 - (n - 1)), min(n - 1, m - 1)
    lo_k = idx.min()
    hi_k = idx.max()
    lo = max(0, lo_k - 1)
    hi = min(n - 1, hi_k)
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _pattern_search(h, deadline, n_evals=200, scale=0.02, block=1):
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    n = h.size
    if block > 1:
        m = n // block
        if m < 2:
            return h, R_of(h)
        trimmed = h[:m * block].reshape(m, block).mean(axis=1)
        tail = h[m * block:]
    else:
        m = n
        trimmed = h.copy()
        tail = np.zeros(0)

    def assemble(v):
        if block > 1:
            return np.concatenate([np.repeat(v, block), tail])
        return v

    cur = trimmed.copy()
    curR = R_of(assemble(cur))
    step = scale
    for _ in range(n_evals):
        if time.process_time() >= deadline - 1.0:
            break
        improved = False
        for direction in (1.0 + step, 1.0 / (1.0 + step)):
            cand = cur * direction
            cand = _rescale_maxL(assemble(cand))
            if block > 1:
                cand_c = cand[:m * block].reshape(m, block).mean(axis=1)
            else:
                cand_c = cand
            r = R_of(cand)
            if r > curR + 1e-15:
                cur = cand_c
                curR = r
                improved = True
                break
        if not improved:
            step *= 0.5
            if step < 1e-5:
                break
    return _rescale_maxL(assemble(cur)), curR


def _subblock_shake(best, bestR, deadline, rng):
    n = best.size
    accepted = 0
    trials = 0
    while time.process_time() < deadline - 2.0:
        trials += 1
        B = int(rng.choice([8, 16]))
        if B >= n:
            continue
        s = int(rng.integers(0, n - B + 1))
        m = best[s:s + B].sum()
        if m <= 0:
            continue
        p = int(rng.choice([3, 5, 8, 11]))
        if p >= B:
            p = B - 1
        if p < 1:
            continue
        cand = best.copy()
        cand[s:s + B] = 0.0
        if rng.random() < 0.5:
            cells = rng.choice(B, size=p, replace=False)
        else:
            cells = np.linspace(0, B - 1, p).round().astype(int)
            cells = np.unique(cells)
            if cells.size < p:
                continue
        cand[s + cells] = m / p
        cand = _rescale_maxL(cand)
        lo = max(0, s - 3 * B)
        hi = min(n - 1, s + B + 3 * B - 1)
        free = np.arange(lo, hi + 1)
        cand = _exact_lbfgs(cand, 60, 120, deadline, free=free)
        cand = _rescale_maxL(cand)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best = cand
            bestR = r
            accepted += 1
            best = _window_polish(best, deadline)
            bestR = R_of(best)
            print("subblock accept R=%.7f (trials=%d)" % (bestR, trials))
    print("subblock shake: %d accepted / %d trials" % (accepted, trials))
    return best, bestR


# ---------------- Rectangle-family stage ----------------

def _rect_profile(N, K, rho, align, cs, spike_w=None, ridge_w=None):
    """Build rectangle-sum profile on N cells. Widths W_k = S*rho**k, S=N."""
    h = np.zeros(N)
    S = float(N)
    for k in range(K):
        W = max(1.0, S * (rho ** k))
        if spike_w is not None and k == 0:
            W = max(1.0, S * spike_w)
        if ridge_w is not None and k == 1:
            W = max(1.0, S * ridge_w)
        w = int(round(W))
        w = max(1, min(N, w))
        if align == 'left':
            lo = 0
        elif align == 'right':
            lo = N - w
        else:  # centered
            lo = (N - w) // 2
        lo = max(0, min(N - w, lo))
        h[lo:lo + w] += cs[k]
    return h


def _rect_R(params, N, K, rho, align, extra_knobs):
    cs = np.array(params[:K], dtype=float)
    cs = np.clip(cs, 1e-6, None)
    if extra_knobs:
        sw = float(np.clip(params[K], 0.005, 0.5))
        rw = float(np.clip(params[K + 1], 0.01, 0.5))
    else:
        sw = rw = None
    h = _rect_profile(N, K, rho, align, cs, sw, rw)
    return R_of(h)


def _rect_stage(best, bestR, deadline, t_stage_end, rng):
    from scipy.optimize import minimize as _min
    N_small = 2048
    N_big = 42496
    results = []  # (R_small, K, rho, align, params, extra_knobs)
    for K in (3, 4, 5):
        for rho in (0.08, 0.12, 0.18, 0.25):
            for align in ('left', 'right', 'centered'):
                if time.process_time() >= t_stage_end:
                    break
                extra = (K == 4 and align == 'left')
                # initial heights: decreasing geometric-ish
                cs0 = np.array([1.0 / (1.0 + k) for k in range(K)])
                x0 = list(cs0)
                if extra:
                    x0 += [rho * 0.5, rho]
                x0 = np.array(x0, dtype=float)

                def obj(x):
                    return -_rect_R(x, N_small, K, rho, align, extra)

                try:
                    res = _min(obj, x0, method='Nelder-Mead',
                               options={'maxiter': 400, 'xatol': 1e-4,
                                        'fatol': 1e-7})
                    Rs = -res.fun
                    params = res.x
                except Exception:
                    continue
                results.append((Rs, K, rho, align, params, extra))
                print("rect K=%d rho=%.2f %s R2048=%.6f" % (K, rho, align, Rs))
            if time.process_time() >= t_stage_end:
                break
        if time.process_time() >= t_stage_end:
            break

    if not results:
        return best, bestR

    results.sort(key=lambda t: -t[0])
    top = results[:3]
    for Rs, K, rho, align, params, extra in top:
        if time.process_time() >= deadline - 3.0:
            break
        cs = np.clip(params[:K], 1e-6, None)
        if extra:
            sw = float(np.clip(params[K], 0.005, 0.5))
            rw = float(np.clip(params[K + 1], 0.01, 0.5))
        else:
            sw = rw = None
        h_big = _rect_profile(N_big, K, rho, align, cs, sw, rw)
        h_big = _rescale_maxL(h_big)
        h_big = _exact_lbfgs(h_big, 1500, 3000, deadline)
        h_big = _window_polish(h_big, deadline)
        r = R_of(h_big)
        print("rect ladder K=%d rho=%.2f %s R42496=%.7f" % (K, rho, align, r))
        if r > bestR + 1e-15:
            best, bestR = h_big.copy(), r
            print("rect accept R=%.7f" % bestR)
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage -1: rectangle-family multistart (at most half budget).
    t_rect_end = t0 + budget_seconds * 0.45
    try:
        best, bestR = _rect_stage(best, bestR, deadline, t_rect_end, rng)
    except Exception as e:
        print("rect stage failed: %s" % e)

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish, then alternating window/full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # Stage 2: coarse/fine resample shake-out.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n < 64:
            break
        factor = 2
        m = n // factor
        if m < 16:
            break
        coarse = best[:m * factor].reshape(m, factor).mean(axis=1)
        tail = best[m * factor:]
        cand = np.concatenate([coarse, tail]) if tail.size else coarse
        cand = _rescale_maxL(cand)
        hc = _full_polish(cand, deadline, iters=800)
        rc = R_of(hc)
        back = _rescale_maxL(_smooth_upsample(hc, factor, sigma_cells=0.4))
        if back.size != n:
            xo = np.linspace(0, 1, n)
            xi = np.linspace(0, 1, back.size)
            back = np.interp(xo, xi, back)
            back = _rescale_maxL(back)
        hf = _full_polish(back, deadline, iters=800)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("resample R=%.7f N=%d" % (bestR, best.size))
        elif rc > bestR + 1e-15:
            best, bestR = hc.copy(), rc
            print("coarse R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    # Stage 3: smooth upsample to larger N and refine, if budget remains.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        candidates = []
        cand_lin = _rescale_maxL(_upsample(best, factor))
        candidates.append(cand_lin)
        cand_sm = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=0.4))
        candidates.append(cand_sm)
        best_try = None
        best_tryR = bestR
        for cand in candidates:
            if time.process_time() >= deadline - 1.0:
                break
            hf = _full_polish(cand, deadline, iters=600)
            rf = R_of(hf)
            if rf > best_tryR + 1e-15:
                best_try = hf
                best_tryR = rf
        if best_try is not None:
            best, bestR = best_try, best_tryR
            print("upsample R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    # Final safety polish.
    if time.process_time() < deadline - 0.5:
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    best = _rescale_maxL(np.clip(best, 0, None))
    if best.size > 200000:
        best = best[:200000]
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.5)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-22, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return 0, n - 1
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _cum_mass_resample(h, N1):
    n = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N1)
    xo = np.linspace(0.0, total, N1 + 1)
    pos = np.interp(xo, c, np.arange(n + 1) - 0.5)
    pos = np.clip(pos, 0.0, n - 1.0)
    hi = np.interp(pos[:-1] + 0.5, np.arange(n), h)
    return np.clip(hi, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Upsample the start to a finer grid to give optimization more freedom,
    # then polish on the finer grid. If it helps, keep it.
    if best.size < 80000 and time.process_time() < deadline - 8.0:
        try:
            factor = max(2, min(4, 80000 // best.size))
            hu = _cum_mass_resample(best, best.size * factor)
            hu = _rescale_maxL(hu)
            hu = _full_polish(hu, deadline - 4.0, iters=1500)
            ru = R_of(hu)
            print("upsampled polish R=%.7f (N=%d)" % (ru, hu.size))
            if ru > bestR + 1e-12:
                best, bestR = hu, ru
        except Exception as e:
            print("upsample failed: %s" % str(e))

    # Alternating full/window polish, spending remaining budget.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _lbfgs_linear(h0, deadline, maxiter=3000, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        active = np.arange(n)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = h[active].copy()

    def f(u):
        uu = np.clip(u, 0.0, None)
        hh = np.zeros(n)
        hh[active] = uu
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.clip(res.x, 0.0, None)
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    m = int(np.argmax(Lf))
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _smooth_upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.clip(np.interp(xo, np.arange(n), h), 0, None)


def _resample(h, m):
    n = h.size
    if m == n:
        return h.copy()
    xo = np.linspace(0.0, n - 1, m)
    return np.clip(np.interp(xo, np.arange(n), h), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Top-K ladder to smooth the max proxy.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Linear-parametrisation polish.
    if time.process_time() < deadline - 2.0:
        hl = _lbfgs_linear(best, deadline, maxiter=2000)
        rl = R_of(hl)
        if rl > bestR + 1e-15:
            best, bestR = hl.copy(), rl
            print("linear R=%.7f" % bestR)

    # Main loop: alternate fine resample (upsample) + full polish, plus window.
    cur = best.copy()
    curR = bestR
    resample_cycle = 0
    while time.process_time() < deadline - 1.0:
        improved = False

        # Fine resample: upsample by 2 then full polish (refines shape).
        if time.process_time() < deadline - 1.5 and cur.size < 100000:
            up = _smooth_upsample(cur, 2)
            up = _full_polish(up, deadline, iters=800)
            ru = R_of(up)
            if ru > curR + 1e-15:
                cur, curR = up, ru
                improved = True
                print("upsample R=%.7f (N=%d)" % (curR, cur.size))

        if time.process_time() >= deadline - 1.5:
            break

        # Full polish at current resolution.
        h = _full_polish(cur, deadline, iters=1500)
        r = R_of(h)
        if r > curR + 1e-15:
            cur, curR = h, r
            improved = True
            print("full R=%.7f" % curR)

        if time.process_time() >= deadline - 1.5:
            break

        # Window polish.
        h = _window_polish(cur, deadline)
        r = R_of(h)
        if r > curR + 1e-15:
            cur, curR = h, r
            improved = True
            print("window R=%.7f" % curR)

        # Coarsen occasionally to escape local minima.
        resample_cycle += 1
        if not improved and resample_cycle % 3 == 0 and cur.size > 200:
            m = cur.size // 2
            co = _resample(cur, m)
            co = _full_polish(co, deadline, iters=800)
            rc = R_of(co)
            if rc > curR + 1e-15:
                cur, curR = co, rc
                print("coarsen R=%.7f (N=%d)" % (curR, cur.size))

    if curR > bestR:
        best, bestR = cur, curR

    # Final: make sure it's the best we have.
    best = _rescale_maxL(best)
    bestR = R_of(best)
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_average(h, target):
    n = h.size
    if n <= target:
        return h.copy()
    factor = int(np.ceil(n / target))
    m = n // factor
    if m < 2:
        return h.copy()
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _warp(h, a):
    n = h.size
    if n < 2:
        return h.copy()
    a = np.asarray(a, dtype=float).ravel()
    if a.size < 8:
        a = np.concatenate([a, np.zeros(8 - a.size)])
    ys = np.empty(9)
    ys[0] = 0.0
    ys[8] = 1.0
    for i in range(1, 8):
        ys[i] = (i / 8.0) + 0.03 * np.tanh(a[i - 1])
    ys = np.sort(np.clip(ys, 0.0, 1.0))
    for i in range(1, 9):
        if ys[i] <= ys[i - 1]:
            ys[i] = ys[i - 1] + 1e-9
    ys[8] = 1.0

    csum = np.concatenate(([0.0], np.cumsum(h)))
    if csum[-1] <= 0:
        return h.copy()
    j = np.arange(n + 1, dtype=float)
    t = j / n
    y_t = np.interp(t, np.linspace(0.0, 1.0, 9), ys)
    u = np.clip(n * y_t, 0.0, n)
    mass_edges = np.interp(u, np.arange(n + 1, dtype=float), csum)
    newh = np.clip(np.diff(mass_edges), 0.0, None)
    return _rescale_maxL(newh)


def _warp_optimize(h, deadline, maxiter=300):
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    hc = _block_average(h, 4000)
    if hc.size < 16:
        return h, R_of(h)

    def negR(a):
        try:
            r = R_of(_warp(hc, a))
            return -r if np.isfinite(r) else 1.0
        except Exception:
            return 1.0

    a0 = np.zeros(8)
    try:
        res = minimize(negR, a0, method='Nelder-Mead',
                       options={'maxiter': maxiter, 'xatol': 1e-3, 'fatol': 1e-10})
        a_best = res.x
    except Exception:
        a_best = a0
    hw = _warp(h, a_best)
    return hw, R_of(hw)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Warp rounds (orthogonal to height perturbations).
    wr = 0
    while wr < 2 and time.process_time() < deadline - 6.0:
        hw, rw = _warp_optimize(best, deadline)
        if rw > bestR + 1e-12:
            hw = _full_polish(hw, deadline, iters=1500)
            r2 = R_of(hw)
            if time.process_time() < deadline - 3.0:
                hw3 = _window_polish(hw, deadline)
                r3 = R_of(hw3)
                if r3 > r2:
                    hw, r2 = hw3, r3
            if r2 > bestR + 1e-12:
                best, bestR = hw.copy(), r2
                print("warp(%d) R=%.7f" % (wr, bestR))
            else:
                print("warp(%d) no gain (raw %.7f)" % (wr, r2))
                break
        else:
            print("warp(%d) no gain (raw %.7f)" % (wr, rw))
            break
        wr += 1

    # Top-K mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    # Upsampling stage.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_upsample(best, factor))
        rc = R_of(cand)
        if rc >= bestR - 1e-6:
            h = _full_polish(cand, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            elif rc > bestR + 1e-15:
                best, bestR = cand.copy(), rc
                print("upsample(f=%d,raw) R=%.7f N=%d" % (factor, bestR, best.size))
        else:
            break

    # Final alternating polish.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("final wide R=%.7f" % bestR)
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

