    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _band_free_cells(h, lo_frac, hi_frac, topn):
    """Select topn cells by sensitivity to the shoulder band of knots."""
    n = h.size
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(n)
    band = np.flatnonzero((Lf >= lo_frac * M) & (Lf <= hi_frac * M))
    if band.size == 0:
        return np.arange(n)
    # dLf_j/dh_i = 2*h_{j-i} for valid indices; sensitivity s_i = h_i * sum_j |dLf_j/dh_i|
    # Build sensitivity via correlation: for each i, sum over j in band of 2*h[j-i].
    # This equals 2 * sum_{k} h[k] * indicator(band at i+k) = 2 * correlate(h, mask_band)
    mask = np.zeros(Lf.size)
    mask[band] = 1.0
    # sens_i = h_i * 2 * sum_k h_k * mask[i+k]  (with j = i+k)
    # correlate(h, mask) gives sum_k h_k * mask[i+k] for i in [0, n-1]
    if n > 1500:
        corr = fftconvolve(h, mask[::-1], mode='valid')[:n]
    else:
        corr = np.correlate(h, mask, mode='valid')[:n]
    sens = h * 2.0 * corr
    topn = min(topn, n)
    idx = np.argpartition(sens, -topn)[-topn:]
    return np.sort(idx)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage 2 (NEW): shoulder-band free-set polish.
    def band_round(lo_frac, hi_frac, topn, iters, funs):
        nonlocal best, bestR
        if time.process_time() >= deadline - 2.0:
            return False
        Lf = _knots(best)
        M = Lf.max()
        band_size = int(np.sum((Lf >= lo_frac * M) & (Lf <= hi_frac * M)))
        free = _band_free_cells(best, lo_frac, hi_frac, topn)
        print("band [%.1f,%.1f]M size=%d cells=%d" %
              (lo_frac, hi_frac, band_size, free.size))
        h = _exact_lbfgs(best, iters, 2 * iters, deadline, free=free)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("band R=%.7f" % bestR)
            return True
        return False

    while time.process_time() < deadline - 2.0:
        improved = band_round(0.3, 0.7, 3000, 2000, 4000)
        if time.process_time() >= deadline - 2.0:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            improved = band_round(0.1, 0.9, 5000, 2000, 4000)
            if time.process_time() >= deadline - 2.0:
                break
            h = _full_polish(best, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                improved = True
                print("full R=%.7f" % bestR)
        if not improved:
            # fall back to window polish to keep making progress
            h = _window_polish(best, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("window R=%.7f" % bestR)
            else:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: quick top-K ladder from start
    h = best.copy()
    for K in (10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish + alternating window/full polish
    h = _full_polish(best, deadline, iters=1500)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 0.8:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 0.8:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 0.8:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # Stage 2: upsample and refine
    while time.process_time() < deadline - 0.8:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=0.4))
        if cand.size > 200000:
            cand = cand[:200000]
        cand = _rescale_maxL(cand)
        hf = _full_polish(cand, deadline, iters=600)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("upsample R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

