def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _box_smooth(h, w):
    if w <= 1:
        return h.copy()
    k = np.ones(w) / float(w)
    hs = np.convolve(h, k, mode='same')
    return _rescale_maxL(np.clip(hs, 0, None))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 3.0 and stall < 2:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # Phase 2: multiscale -- upsample, polish, downsample. This is the main
    # new idea: escape the local optimum at native resolution by smoothing
    # and refining at higher resolutions, then resample back.
    for factor in (2, 3, 4):
        if time.process_time() >= deadline - 4.0:
            break
        hu = _smooth_upsample(best, factor, sigma_cells=0.7)
        hu = _rescale_maxL(hu)
        if hu.size > 200000:
            break
        cand = _exact_lbfgs(hu, 800, 1600, deadline)
        if time.process_time() < deadline - 3.0:
            cand = _window_polish(cand, deadline, frac=0.35)
        cand = _exact_lbfgs(cand, 800, 1600, deadline)
        cand_d = _resample_cum(cand, best.size)
        cand_d = _rescale_maxL(cand_d)
        cand_d = _exact_lbfgs(cand_d, 1500, 3000, deadline)
        r = R_of(cand_d)
        if r > bestR + 1e-16:
            best, bestR = cand_d, r
            print("upsample x%d R=%.7f (GAIN)" % (factor, bestR))
        else:
            print("upsample x%d R=%.7f (no gain)" % (factor, bestR))

    # Phase 3: box-smoothing escape attempts at native resolution.
    for w in (2, 4, 8, 16):
        if time.process_time() >= deadline - 4.0:
            break
        hs = _box_smooth(best, w)
        cand = _exact_lbfgs(hs, 1500, 3000, deadline)
        if time.process_time() < deadline - 3.0:
            cand = _window_polish(cand, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("smooth w=%d R=%.7f (GAIN)" % (w, bestR))

    # Final polish.
    if time.process_time() < deadline - 2.0:
        cand = _exact_lbfgs(best, 4000, 8000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

