    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


def _lanczos_min_eig(h, deadline, m=25):
    """Estimate smallest eigenvalue of Hessian of val on log-active coords."""
    n = h.size
    thresh = 1e-12 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size < 2:
        return None, None, active
    u0 = np.log(np.clip(h[active], 1e-300, None))
    na = active.size

    def grad_u(u):
        hh = np.zeros(n)
        hh[active] = np.exp(np.clip(u, -30.0, 30.0))
        val, g = _norm_eq_fun_grad(hh)
        return g[active] * hh[active]

    g0 = grad_u(u0)
    # Lanczos with full reorthogonalisation
    Q = np.zeros((na, m))
    alpha = np.zeros(m)
    beta = np.zeros(m)
    q = g0.copy()
    nrm = np.linalg.norm(q)
    if nrm <= 0:
        return None, None, active
    q /= nrm
    Q[:, 0] = q
    k_used = 0
    for j in range(m):
        if time.process_time() > deadline - 2.0:
            break
        v = Q[:, j]
        vn = np.linalg.norm(v)
        if vn <= 0:
            break
        eps = 1e-6 / vn
        gp = grad_u(u0 + eps * v)
        gm = grad_u(u0 - eps * v)
        Hv = (gp - gm) / (2.0 * eps)
        alpha[j] = np.dot(v, Hv)
        w = Hv - alpha[j] * v
        if j > 0:
            w -= beta[j - 1] * Q[:, j - 1]
        # full reorthogonalisation
        for _ in range(2):
            w -= Q[:, :j + 1] @ (Q[:, :j + 1].T @ w)
        b = np.linalg.norm(w)
        k_used = j + 1
        if j + 1 >= m or b < 1e-12:
            break
        beta[j] = b
        Q[:, j + 1] = w / b
    if k_used == 0:
        return None, None, active
    T = np.diag(alpha[:k_used])
    for i in range(k_used - 1):
        T[i, i + 1] = beta[i]
        T[i + 1, i] = beta[i]
    evals, evecs = np.linalg.eigh(T)
    lam_min = evals[0]
    w_ritz = Q[:, :k_used] @ evecs[:, 0]
    return lam_min, w_ritz, active


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # ---------------- Stage 1b: quotient (stop-grad rescale) stage ----------------
    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 3000, 6000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        print("quot R=%.7f" % rq)
        if rq > bestR + 1e-15:
            best, bestR = hq.copy(), rq
            print("quot accepted R=%.7f" % bestR)
        if time.process_time() < deadline - 1.0:
            hw = _window_polish(best, deadline, fun_grad=_quot_fun_grad)
            rw = R_of(hw)
            print("quot window R=%.7f" % rw)
            if rw > bestR + 1e-15:
                best, bestR = hw.copy(), rw
                print("quot window accepted R=%.7f" % bestR)

    # ---------------- Stage 1c: Lanczos negative-curvature probe ----------------
    lam_min = None
    if time.process_time() < deadline - 3.0:
        lam_min, w_ritz, active = _lanczos_min_eig(best, deadline, m=25)
        if lam_min is not None:
            print("lambda_min=%.3e (active=%d)" % (lam_min, active.size))
        if lam_min is not None and lam_min < -1e-9 and w_ritz is not None:
            n = best.size
            u0 = np.log(np.clip(best[active], 1e-300, None))
            wmax = np.max(np.abs(w_ritz))
            if wmax > 0:
                wdir = w_ritz / wmax
                for s in (0.02, 0.05, 0.1, 0.2):
                    if time.process_time() >= deadline - 2.0:
                        break
                    for sign in (1.0, -1.0):
                        hh = np.zeros(n)
                        hh[active] = np.exp(np.clip(u0 + sign * s * wdir, -30.0, 30.0))
                        hh = _rescale_maxL(hh)
                        rr = R_of(hh)
                        if rr > bestR + 1e-15:
                            best, bestR = hh.copy(), rr
                            print("lanczos accept s=%.3f sign=%+.0f R=%.7f" % (s, sign, bestR))
                            break
                    else:
                        continue
                    break
            if time.process_time() < deadline - 1.0:
                h = _full_polish(best, deadline, iters=1500)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    print("post-lanczos full R=%.7f" % bestR)
                if time.process_time() < deadline - 1.0:
                    h = _window_polish(best, deadline)
                    r = R_of(h)
                    if r > bestR + 1e-15:
                        best, bestR = h.copy(), r
                        print("post-lanczos window R=%.7f" % bestR)

    # ---------------- Stage 2: alternating full/window polish to deadline ----------------
    w0 = _plateau_halfwidth(best)
    print("plateau halfwidth w0=%.2f" % w0)
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _quot_fun_grad(h):
    h = np.clip(h, 0, None)
    s0 = h.sum()
    if s0 <= 0:
        return 1e18, np.zeros(h.size)
    mx = _knots(h).max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    r = 1.0 / np.sqrt(mx)
    hr = h * r
    num, dq, Lf = _num_and_dq(hr)
    s = hr.sum()
    if num <= 0 or s <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, hr) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad * hr


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            if K == 1:
                val, g = _norm_eq_fun_grad(hh)
            else:
                val, g = _topk_fun_grad(hh, K)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


def _band_relevance(h):
    """Cells that generate the mid band 0.30*M <= L <= 0.70*M."""
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.ones(n)
    band = ((Lf >= 0.30 * M) & (Lf <= 0.70 * M)).astype(float)
    if h.size > 1500:
        rel = fftconvolve(band, h, mode='full')[:n]
    else:
        rel = np.convolve(band, h, mode='full')[:n]
    mx = rel.max()
    if mx <= 0:
        return np.ones(n)
    return rel / mx


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # ---------------- Stage 1b: quotient (stop-grad rescale) stage ----------------
    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 3000, 6000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        print("quot R=%.7f" % rq)
        if rq > bestR + 1e-15:
            best, bestR = hq.copy(), rq
            print("quot accepted R=%.7f" % bestR)
        if time.process_time() < deadline - 1.0:
            hw = _window_polish(best, deadline, fun_grad=_quot_fun_grad)
            rw = R_of(hw)
            print("quot window R=%.7f" % rw)
            if rw > bestR + 1e-15:
                best, bestR = hw.copy(), rw
                print("quot window accepted R=%.7f" % bestR)

    # ---------------- Stage 2: alternating full/window polish ----------------
    w0 = _plateau_halfwidth(best)
    print("plateau halfwidth w0=%.2f" % w0)
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # ---------------- Stage 3: randomised joint mid-band perturbations ----------------
    rng = np.random.default_rng(12345)
    rel = _band_relevance(best)
    free_pool = np.flatnonzero(rel > 0.05)
    if free_pool.size == 0:
        free_pool = np.arange(best.size)
    print("band pool size=%d" % free_pool.size)

    startR = bestR
    k = 0
    since_polish = 0
    while time.process_time() < deadline - 0.5:
        k += 1
        sigma = float(rng.choice([0.02, 0.05, 0.10]))
        m = max(1, int(0.30 * free_pool.size))
        S = rng.choice(free_pool, size=m, replace=False)
        cand = best.copy()
        cand[S] = cand[S] * np.exp(rng.normal(0.0, sigma, size=S.size))
        cand = _rescale_maxL(cand)
        lo = int(S.min()); hi = int(S.max())
        if hi - lo + 1 > 8000:
            # cap window around the median of S
            mid = int(np.median(S))
            lo = max(0, mid - 4000)
            hi = min(best.size - 1, mid + 4000)
        free = np.arange(lo, hi + 1)
        cand = _exact_lbfgs(cand, 150, 300, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand.copy(), r
            print("restart %d R=%.7f (sigma=%.2f)" % (k, bestR, sigma))
        since_polish += 1
        if since_polish >= 20 and time.process_time() < deadline - 1.0:
            since_polish = 0
            h = _full_polish(best, deadline, iters=800)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("full R=%.7f" % bestR)
            if time.process_time() < deadline - 1.0:
                h = _window_polish(best, deadline)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    print("window R=%.7f" % bestR)
            # refresh band pool after polishing
            rel = _band_relevance(best)
            free_pool = np.flatnonzero(rel > 0.05)
            if free_pool.size == 0:
                free_pool = np.arange(best.size)

    best = _rescale_maxL(best)
    print("randomised loop: %d restarts, total gain=%.3e" % (k, bestR - startR))
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

