# ---------------- Global smooth-family multistart stage ----------------

_NC = 1024
_NP = 24  # a0 + linear + 23 cosines


def _params_to_h(p, n=_NC):
    p = np.clip(p, -3.0, 3.0)
    x = np.arange(n, dtype=float)
    logh = np.full(n, p[0])
    logh += p[1] * (x / n)
    for k in range(1, _NP - 1):
        logh += p[k + 1] * np.cos(np.pi * k * x / n)
    h = np.exp(np.clip(logh, -30.0, 30.0))
    s = h.sum()
    if s <= 0:
        return np.ones(n)
    return h * (n / s)


def _coarse_R(p):
    h = _params_to_h(p, _NC)
    return -R_of(h)


def _upsample2(h):
    n = h.size
    xo = np.arange(2 * n, dtype=float)
    xi = np.arange(n, dtype=float)
    return np.interp(xo / 2.0, xi, h)


def _ladder(h, deadline, target_N=42496):
    """Upsample x2 with polish, keeping only exact-R improvements."""
    best = h.copy()
    bestR = R_of(best)
    while best.size < target_N and time.process_time() < deadline - 1.0:
        h2 = _upsample2(best)
        h2 = _exact_lbfgs(h2, 800, 1600, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-15:
            best, bestR = h2, r2
        else:
            # still adopt the upsampled shape as base for next level, but keep bestR
            best = h2
        if time.process_time() >= deadline - 1.0:
            break
        hw = _window_polish(best, deadline)
        rw = R_of(hw)
        if rw > bestR + 1e-15:
            best, bestR = hw, rw
        else:
            best = hw
    return best, bestR


def _global_stage(start, deadline, t_global_cap):
    """Run DE on smooth 24-param family, ladder best 3, return best candidate or None."""
    t_stop = min(deadline, time.process_time() + t_global_cap)

    def de_cb(xk, convergence=None):
        if time.process_time() > t_stop - 0.5:
            raise TimeoutError

    bounds = [(-3.0, 3.0)] * _NP
    try:
        res = differential_evolution(
            _coarse_R, bounds, seed=12345, popsize=8, maxiter=40,
            polish=False, tol=0.0, callback=de_cb, updating='immediate',
            workers=1)
        pop = res.population
    except TimeoutError:
        pop = None
    except Exception:
        pop = None

    # Collect best coarse candidates from population if available
    cands = []
    if pop is not None and len(pop) > 0:
        scored = [(_coarse_R(p), p) for p in pop]
        scored.sort(key=lambda t: t[0])
        for _, p in scored[:3]:
            cands.append(_params_to_h(p, _NC))
    if not cands:
        # fallback: a few simple seeds
        for s in (0.0, 1.0, -1.0):
            p = np.zeros(_NP)
            p[0] = s
            cands.append(_params_to_h(p, _NC))

    best = None
    bestR = -1.0
    for c in cands:
        if time.process_time() >= deadline - 1.0:
            break
        rc = R_of(c)
        print("global coarse R=%.7f" % rc)
