    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---------------- Global smooth-family stage (before Stage 0) ----------------
    if time.process_time() < deadline - 2.0:
        gbest, gR = _global_stage(base, deadline, t_global_cap=10.0)
        if gbest is not None and gR > bestR + 1e-15:
            best, bestR = gbest.copy(), gR
            print("global accepted R=%.7f" % bestR)
        else:
            print("global best R=%.7f (no improvement)" % (gR if gbest is not None else bestR))

