    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
    else:
        N = 4000
        h = np.ones(N)

    if h.sum() <= 0:
        h = np.ones(4000)

    best_h = h.copy()
    best_R = R_of(best_h)

    def consider(hcand):
        nonlocal best_h, best_R
        hcand = _rescale_maxL(hcand)
        r = R_of(hcand)
        if r > best_R:
            best_R = r
            best_h = hcand.copy()
        return r

    consider(h)

    # Phase 1: full polish at current resolution (short, since start is near-optimal)
    h = _exact_lbfgs(best_h, 600, 1200, min(deadline, t0 + 0.30 * budget_seconds))
    consider(h)

    # Phase 2: upsampling refinement passes with full polish
    # Interleave upsampling and full optimisation to escape coarse-grid plateaus.
    for factor, frac in [(2, 0.30), (2, 0.35)]:
        if time.process_time() >= deadline - 0.5:
            break
        n = best_h.size
        if n * factor > 200000:
            break
        hu = _smooth_upsample(best_h, factor, sigma_cells=0.5)
        # scale check: R is scale-invariant, but rescale for numerical stability
        hu = _rescale_maxL(hu)
        sub_deadline = min(deadline, time.process_time() + frac * budget_seconds)
        hu = _exact_lbfgs(hu, 4000, 8000, sub_deadline)
        r = consider(hu)

    # Phase 3: peak-region polish at final resolution (most impactful)
    # The plateau is where L is near its max; refining that window can raise R.
    for frac, extra in [(0.20, 8), (0.20, 8), (0.15, 16)]:
        if time.process_time() >= deadline - 0.5:
            break
        n = best_h.size
        lo, hi = _peak_region(best_h)
        span = max(1, hi - lo)
        pad = max(extra, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(n - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        sub_deadline = min(deadline, time.process_time() + 0.25 * budget_seconds)
        hp = _exact_lbfgs(best_h, 3000, 6000, sub_deadline, free=free)
        consider(hp)

    # Phase 4: final full polish with remaining budget
    if time.process_time() < deadline - 0.5:
        hf = _exact_lbfgs(best_h, 5000, 10000, deadline - 0.2)
        consider(hf)

    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


def _fit_target(h0, w, tau, deadline, maxiter=1500):
    if time.process_time() >= deadline - 0.5:
        return h0, 1e9
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0, 1e9
    n = h.size
    Lf0 = _knots(h)
    M = Lf0.max()
    if M <= 0:
        return h0, 1e9
    m = Lf0.size
    c = (m - 1) / 2.0
    j = np.arange(m, dtype=float)
    T = M / (1.0 + np.exp(np.clip((np.abs(j - c) - w) / tau, -60, 60)))
    Tn = np.linalg.norm(T)
    if Tn <= 0:
        return h0, 1e9

    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0, 1e9
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        Lf = _knots(hh)
        res = Lf - T
        val = 0.5 * np.sum(res * res)
        grad = _backprop(res, hh)
        return val, grad[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        except Exception:
            return h0, 1e9
    except Exception:
        return h0, 1e9
    h2 = _rescale_maxL(h2)
    Lf2 = _knots(h2)
    resid = np.linalg.norm(Lf2 - T) / Tn
    return h2, resid


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    if start is None or np.asarray(start).size == 0:
        N = 2000
        h = np.ones(N)
    else:
        h = np.clip(np.asarray(start, dtype=float), 0, None)

    best = h.copy()
    bestR = R_of(best)

    def consider(cand):
        nonlocal best, bestR
        if cand is None:
            return
        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            return
        if cand.size > 200000:
            cand = cand[:200000]
        r = R_of(cand)
        if r > bestR:
            bestR = r
            best = cand.copy()

    consider(h)

    # Stage 1: fit the plateau target (this is the big lever).
    try:
        w0 = _plateau_halfwidth(best)
    except Exception:
        w0 = best.size / 4.0

    # Try several tau values, keep the best.  Each fit is bounded by a fraction
    # of remaining time.
    taus = [max(1.0, best.size * 0.01), max(1.0, best.size * 0.02),
            max(1.0, best.size * 0.005)]
    for tau in taus:
        if time.process_time() > deadline - 4.0:
            break
        sub_deadline = min(deadline - 2.0,
                           time.process_time() + (deadline - time.process_time()) * 0.35)
        try:
            h2, resid = _fit_target(best, w0, tau, sub_deadline, maxiter=800)
            consider(h2)
        except Exception:
            pass

    # Stage 2: local polish of the peak region.
    if time.process_time() < deadline - 2.0:
        try:
            h3 = _window_polish(best, min(deadline - 1.0,
                                          time.process_time() + 3.0))
            consider(h3)
        except Exception:
            pass

    # Stage 3: full L-BFGS polish if time remains.
    if time.process_time() < deadline - 1.5:
        try:
            h4 = _exact_lbfgs(best, 400, 800, min(deadline - 0.5,
                                                  time.process_time() + 4.0))
            consider(h4)
        except Exception:
            pass

    # Stage 4: upsample + polish if time remains and we're small.
    if time.process_time() < deadline - 1.5 and best.size < 100000:
        try:
            factor = 2 if best.size < 40000 else 1
            if factor > 1:
                up = _smooth_upsample(best, factor, sigma_cells=0.5)
                up = _rescale_maxL(up)
                consider(up)
                if time.process_time() < deadline - 1.0:
                    up2 = _exact_lbfgs(up, 300, 600,
                                       min(deadline - 0.5,
                                           time.process_time() + 3.0))
                    consider(up2)
        except Exception:
            pass

    # Stage 5: final safety polish on the winner.
    if time.process_time() < deadline - 0.8:
        try:
            hf = _window_polish(best, min(deadline - 0.3,
                                          time.process_time() + 2.0),
                                frac=0.4, extra=8)
            consider(hf)
        except Exception:
            pass

    if best.sum() <= 0:
        best = np.ones(1)
    if best.size > 200000:
        best = best[:200000]
    return best

