    n = h.size
    lo, hi = _peak_region(h)
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


# ---- Windowed eigendecomposition (Hessian-free) polish ----
# Near a local max of R, the high-curvature directions live in the peak window.
# We do a few steps of a Newton-like update restricted to that window using
# a numerically-built Hessian via finite differences on a reduced basis.

def _window_newton(h, deadline, rounds=6, win_frac=0.5):
    """Newton polish in the peak window using explicit Hessian of -log R."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    n = h.size
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(4, int(span * win_frac))
        lo = max(0, lo - pad)
        hi = min(n - 1, hi + pad)
        idx = np.arange(lo, hi + 1)
        p = idx.size
        if p < 3:
            break
        # param in log-space of the window; hold outside fixed
        base = h.copy()
        u = np.log(np.clip(h[idx], 1e-300, None))
        # numerical Hessian of val(u) in this window
        def val(uu):
            hh = base.copy()
            hh[idx] = np.exp(np.clip(uu, -30, 30))
            v, g = _norm_eq_fun_grad(hh)
            return v, g[idx] * hh[idx]
        v0, g0 = val(u)
        if not np.isfinite(v0):
            break
        eps = 1e-4
        H = np.zeros((p, p))
        try:
            for k in range(p):
                e = np.zeros(p); e[k] = eps
                vp, _ = val(u + e)
                vm, _ = val(u - e)
                H[:, k] = (vp - vm) / (2 * eps)  # d val / du_k? no, need grad
            # Actually we need Hessian of val; approximate via grad differences
        except Exception:
            break
        # Redo properly: H[:,k] = (grad(u+eps e_k) - grad(u-eps e_k))/(2eps)
        H = np.zeros((p, p))
        ok = True
        for k in range(p):
            if time.process_time() >= deadline - 0.5:
                ok = False; break
            e = np.zeros(p); e[k] = eps
            _, gp = val(u + e)
            _, gm = val(u - e)
            H[:, k] = (gp - gm) / (2 * eps)
        if not ok:
            break
        H = 0.5 * (H + H.T)
        # regularize
        H += 1e-6 * (np.trace(H) / p + 1e-12) * np.eye(p)
        try:
            step = np.linalg.solve(H, g0)
        except np.linalg.LinAlgError:
            break
        # line search
        best_h = base.copy()
        best_v = v0
        alpha = 1.0
        improved = False
        for _ in range(12):
            un = u - alpha * step
            vn, _ = val(un)
            if np.isfinite(vn) and vn < best_v - 1e-15:
                hh = base.copy()
                hh[idx] = np.exp(np.clip(un, -30, 30))
                best_h = hh
                best_v = vn
                improved = True
                break
            alpha *= 0.5
        if not improved:
            break
        h = _rescale_maxL(best_h)
    return h


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    return np.clip(np.diff(co), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        h = np.clip(np.asarray(start, dtype=float).ravel(), 0, None)
        if h.size == 0 or h.sum() <= 0:
            h = None
    else:
        h = None

    if h is None:
        # fallback seed: a simple smooth bump
        N = 20000
        x = np.linspace(0, 1, N)
        h = np.exp(-((x - 0.5) ** 2) / 0.02)

    h = _rescale_maxL(h)
    best = h.copy()
    bestR = R_of(best)

    def consider(cand):
        nonlocal best, bestR
        if cand is None:
            return False
        c = np.clip(np.asarray(cand, dtype=float), 0, None)
        if c.size == 0 or c.size > 200000 or c.sum() <= 0:
            return False
        r = R_of(c)
        if np.isfinite(r) and r > bestR:
            best = c.copy()
            bestR = r
            return True
        return False

    # Phase 1: alternating full + windowed polish at current resolution
    for _ in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(best, 400, 800, deadline)
        consider(h)
        h = _window_polish(best, deadline, frac=0.4, K=1)
        consider(h)
        h = _window_polish(best, deadline, frac=0.15, K=1)
        consider(h)

    # Phase 2: upsample (cumulative resampling preserves mass distribution),
    # then polish at larger N with windowed + full passes.
    curN = best.size
    while curN < 200000 and time.process_time() < deadline - 5.0:
        fac = 2 if curN * 2 <= 200000 else 0
        if fac == 0:
            newN = 200000
        else:
            newN = curN * 2
        if newN <= curN:
            break
        cand = _resample_cum(best, newN)
        cand = _rescale_maxL(cand)
        if R_of(cand) < bestR * 0.999:
            # resampling lost too much; try interpolation
            cand2 = _upsample(best, max(2, newN // curN))
            cand2 = _rescale_maxL(cand2)
            if R_of(cand2) > R_of(cand):
                cand = cand2
        curN = newN
        # quick polish to recover
        h = _exact_lbfgs(cand, 200, 400, deadline)
        consider(h)
        h = _window_polish(best, deadline, frac=0.3, K=1)
        consider(h)
        if time.process_time() >= deadline - 4.0:
            break

    # Phase 3: spend the remaining time on aggressive windowed Newton-like polish
    for _ in range(6):
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline, frac=0.2, K=1)
        consider(h)
        h = _window_polish(best, deadline, frac=0.05, K=1)
        consider(h)
        h = _exact_lbfgs(best, 300, 600, deadline)
        consider(h)

    # final safety
    b = np.clip(best, 0, None)
    if b.sum() <= 0:
        b = np.ones(max(1, min(200000, best.size)))
    if b.size > 200000:
        b = _resample_cum(b, 200000)
    return b

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _quot_fun_grad(h):
    h = np.clip(h, 0, None)
    s0 = h.sum()
    if s0 <= 0:
        return 1e18, np.zeros(h.size)
    mx = _knots(h).max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    r = 1.0 / np.sqrt(mx)
    hr = h * r
    num, dq, Lf = _num_and_dq(hr)
    s = hr.sum()
    if num <= 0 or s <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, hr) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad * hr


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            if K == 1:
                val, g = _norm_eq_fun_grad(hh)
            else:
                val, g = _topk_fun_grad(hh, K)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


def _singular_profile(N2, a, delta, K):
    """Cell-average of (t+delta)^-a * raised-cosine taper on [0,N2)."""
    k = np.arange(N2, dtype=float)
    # 4-point Gauss-Legendre on [0,1]
    gx, gw = np.polynomial.legendre.leggauss(4)
    gx = 0.5 * (gx + 1.0)
    gw = 0.5 * gw
    taper_start = K - 0.15 * N2
    h = np.zeros(N2)
    for xi, wi in zip(gx, gw):
        t = k + xi
        base = (t + delta) ** (-a)
        tap = np.ones(N2)
        m1 = t <= taper_start
        m2 = (t > taper_start) & (t < K)
        tap[m2] = 0.5 * (1.0 + np.cos(np.pi * (t[m2] - taper_start) / (0.15 * N2)))
        tap[t >= K] = 0.0
        h += wi * base * tap
    return h


def _coarse_search(deadline):
    N2 = 199999
    a_list = [0.35, 0.45, 0.5, 0.55]
    delta_list = 10.0 ** np.linspace(-5, -1.5, 5)
    K_fracs = [0.55, 0.7, 0.85, 1.0]
    results = []
    for a in a_list:
        for delta in delta_list:
            for kf in K_fracs:
                if time.process_time() >= deadline:
                    break
                K = kf * N2
                h = _singular_profile(N2, a, delta, K)
                if h.sum() <= 0:
                    continue
                h = _rescale_maxL(h)
                r = R_of(h)
                results.append((r, a, delta, K, h))
            else:
                continue
            break
        else:
            continue
        break
    results.sort(key=lambda x: -x[0])
    return results[:3]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---------------- Stage -1: fresh high-res singular profile search ----------------
    try:
        coarse_deadline = min(deadline - 1.0, t0 + budget_seconds * 0.35)
        top = _coarse_search(coarse_deadline)
        if top:
            print("coarse best R=%.7f (a=%.2f delta=%.2e K=%.3f)" %
                  (top[0][0], top[0][1], top[0][2], top[0][3] / 199999.0))
        # polish top candidates at N2 with a short slice each
        for i, (r0, a, delta, K, hc) in enumerate(top):
            if time.process_time() >= deadline - 2.0:
                break
            slice_end = min(deadline - 1.0, time.process_time() + 4.0)
            hp = _exact_lbfgs(hc, 400, 800, slice_end)
            rp = R_of(hp)
            print("N2 polish[%d] R=%.7f" % (i, rp))
            if rp > bestR + 1e-15:
                best, bestR = hp.copy(), rp
                print("N2 accepted R=%.7f" % bestR)
    except Exception as e:
        print("stage -1 error:", e)

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # ---------------- Stage 1b: quotient (stop-grad rescale) stage ----------------
    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 3000, 6000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        print("quot R=%.7f" % rq)
        if rq > bestR + 1e-15:
            best, bestR = hq.copy(), rq
            print("quot accepted R=%.7f" % bestR)
        if time.process_time() < deadline - 1.0:
            hw = _window_polish(best, deadline, fun_grad=_quot_fun_grad)
            rw = R_of(hw)
            print("quot window R=%.7f" % rw)
            if rw > bestR + 1e-15:
                best, bestR = hw.copy(), rw
                print("quot window accepted R=%.7f" % bestR)

    # ---------------- Stage 2: alternating full/window polish to deadline ----------------
    w0 = _plateau_halfwidth(best)
    print("plateau halfwidth w0=%.2f" % w0)
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

