def _quot_fun_grad(h):
    """Scale-quotient objective with stop-gradient through the max(L)=1 rescale."""
    h = np.clip(h, 0, None)
    s0 = h.sum()
    if s0 <= 0:
        return 1e18, np.zeros(h.size)
    mx = _knots(h).max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    r = 1.0 / np.sqrt(mx)
    hr = h * r
    num, dq, Lf = _num_and_dq(hr)
    s = hr.sum()
    if num <= 0 or s <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, hr) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad * hr


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            if K == 1:
                val, g = _norm_eq_fun_grad(hh)
            else:
                val, g = _topk_fun_grad(hh, K)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


# ---------------- New: asymmetric target family stage ----------------

def _build_target(M, r, w, q):
    """Build asymmetric target T of length 2M-1: short ramp, plateau, power decay."""
    n = 2 * M - 1
    T = np.zeros(n)
    T[0] = 1e-6 * M
    r = float(r); w = float(w); q = float(q)
    rw = r + w
    tail_len = max(1.0, (2 * M) - rw)
    for i in range(1, n):
        if i < rw:
            T[i] = max(0.0, min(1.0, i / r))
        else:
            T[i] = max(0.0, 1.0 - ((i - rw) / tail_len)) ** q
    mx = T.max()
    if mx > 0:
        T = T / mx
    return T


def _recover_h_from_T(T):
    """Forward recursion: T[k] = sum_{i+j=k} h_i h_j (with h_0 = sqrt(T[0]))."""
    n = T.size
    h = np.zeros(n)
    T0 = max(T[0], 1e-300)
    h0 = np.sqrt(T0)
    h[0] = h0
    if h0 <= 0:
        return h
    for k in range(1, n):
        s = 0.0
        for i in range(1, k):
            s += h[i] * h[k - i]
        h[k] = (T[k] - s) / (2.0 * h0)
        if h[k] < 0:
            h[k] = 0.0
    return h


def _ladder_to_N(h, N):
    """Mass-conserving repeat ladder of h to length N."""
    n = h.size
    if n == N:
        return h.copy()
    if n <= 0:
        return np.ones(N)
    # cumulative mass interpolation
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.ones(N)
    # target edges in original index space
    edges = np.linspace(0.0, n, N + 1)
    out = np.zeros(N)
    for j in range(N):
        a = edges[j]; b = edges[j + 1]
        # integrate h over [a, b] using cumulative mass (piecewise linear in index)
        def F(x):
            i = int(np.floor(x))
            if i >= n:
                return total
            if i < 0:
                return 0.0
            frac = x - i
            return cum[i] + frac * h[i]
        out[j] = F(b) - F(a)
    return np.clip(out, 0, None)


def _asym_target_stage(best, bestR, deadline):
    """Stage before Stage 0: asymmetric target family (ramp + plateau + power decay)."""
    M = 1024
    rs = [0.005 * M, 0.02 * M, 0.05 * M]
    ws = [0.6 * M, 0.8 * M, 1.0 * M, 1.2 * M]
    qs = [0.5, 1.0, 2.0, 4.0]
    N = 42496

    candidates = []
    for r in rs:
        for w in ws:
            for q in qs:
                if time.process_time() >= deadline - 2.0:
                    break
                T = _build_target(M, r, w, q)
                h = _recover_h_from_T(T)
                s = h.sum()
                if s <= 0:
                    continue
                h = h / s
                r_val = R_of(h)
                candidates.append((r_val, r, w, q, h))
            else:
                continue
            break
        else:
            continue
        break

    if not candidates:
        return best, bestR

    candidates.sort(key=lambda t: -t[0])
    top3 = candidates[:3]
    print("asym targets top: " + ", ".join("%.5f(r=%.1f,w=%.1f,q=%.1f)" % (c[0], c[1], c[2], c[3]) for c in top3))

    for (r_val, r, w, q, h) in top3:
        if time.process_time() >= deadline - 1.5:
            break
        hN = _ladder_to_N(h, N)
        hN = _rescale_maxL(hN)
        hN = _full_polish(hN, deadline, iters=800)
        r1 = R_of(hN)
        if time.process_time() < deadline - 1.0:
            hW = _window_polish(hN, deadline)
            r2 = R_of(hW)
            if r2 > r1:
                hN, r1 = hW, r2
        print("asym r=%.1f w=%.1f q=%.1f -> R=%.7f" % (r, w, q, r1))
        if r1 > bestR + 1e-15:
            best, bestR = hN.copy(), r1
            print("asym accepted R=%.7f" % bestR)

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # New Stage: asymmetric target family (ramp + plateau + power-law decay).
    best, bestR = _asym_target_stage(best, bestR, deadline)

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # ---------------- Stage 1b: quotient (stop-grad rescale) stage ----------------
    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 3000, 6000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        print("quot R=%.7f" % rq)
        if rq > bestR + 1e-15:
            best, bestR = hq.copy(), rq
            print("quot accepted R=%.7f" % bestR)
        # window polish with quotient objective, accept only on exact gain
        if time.process_time() < deadline - 1.0:
            hw = _window_polish(best, deadline, fun_grad=_quot_fun_grad)
            rw = R_of(hw)
            print("quot window R=%.7f" % rw)
            if rw > bestR + 1e-15:
                best, bestR = hw.copy(), rw
                print("quot window accepted R=%.7f" % bestR)

    # ---------------- Stage 2: alternating full/window polish to deadline ----------------
    w0 = _plateau_halfwidth(best)
    print("plateau halfwidth w0=%.2f" % w0)
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            if K == 1:
                val, g = _norm_eq_fun_grad(hh)
            else:
                val, g = _topk_fun_grad(hh, K)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: top-K-mean max proxy ladder (smooths the max, escapes kinks).
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage B: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage C: alternate window-polish and full-polish, keeping best.
    # The peak region is where mass concentrates; refining it locally
    # with a full-scale max objective tightens the max constraint, then
    # full polish re-balances the global ||f*f||_2^2.
    while time.process_time() < deadline - 1.0:
        h = _window_polish(best, deadline, frac=0.20, extra=6)
        r = R_of(h)
        print("window R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        print("full2 R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            # no improvement in a full round: stop alternating
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

