        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


def _upsample_pl(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = np.arange(n, dtype=float)
    x = np.linspace(0.0, n - 1, N)
    return np.interp(x, xp, h)


def _downsample_block(h, N):
    n = h.size
    if n == N:
        return h.copy()
    edges = np.linspace(0, n, N + 1)
    out = np.empty(N)
    for i in range(N):
        a = int(np.floor(edges[i]))
        b = int(np.ceil(edges[i + 1]))
        a = min(a, n - 1)
        b = max(b, a + 1)
        b = min(b, n)
        out[i] = h[a:b].mean()
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # --- Improved: adaptive refinement ladder instead of fixed 200k jump. ---
    # Work at increasing resolutions, polishing each, keeping the best globally.
    # The key change: refine the *peak plateau* region with more steps, where
    # the structure lives, using the plateau halfwidth as the guide.
    h = best.copy()

    # Stage 0: top-K-mean max proxy ladder (cheap, quick).
    for K in (10, 4, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
    print("K ladder R=%.7f" % bestR)

    # Stage 1: full polish at current resolution.
    if time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR:
            best, bestR = h.copy(), r
    print("full R=%.7f" % bestR)

    # Stage 1b: quotient.
    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 2000, 4000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        if rq > bestR + 1e-15:
            best, bestR = hq.copy(), rq
    print("quot R=%.7f" % bestR)

    # --- New main stage: geometric resolution ladder up to 200k, only
    # upsampling when it helps, and locally refining the peak window. ---
    target_N = 200000
    ladder = []
    n = best.size
    while n < target_N:
        n = min(target_N, max(n * 2, n + 1000))
        ladder.append(n)
    if not ladder or ladder[-1] != target_N:
        ladder.append(target_N)

    cur = best.copy()
    curR = bestR
    for N in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        hu = _upsample_pl(cur, N)
        hu = _rescale_maxL(hu)
        ru = R_of(hu)
        # Only accept upsample if it doesn't lose too much (PL interp is exact-ish)
        # then polish locally around the peak.
        if time.process_time() < deadline - 1.0:
            hw = _window_polish(hu, deadline, frac=0.5, extra=8)
            rw = R_of(hw)
            if rw > ru:
                hu, ru = hw, rw
        if ru >= curR - 1e-9:
            cur, curR = hu, ru
            if curR > bestR + 1e-15:
                best, bestR = cur.copy(), curR
        print("ladder N=%d R=%.7f best=%.7f" % (N, ru, bestR))

    # --- Final phase: alternate full + peak-window polish at the top
    # resolution, always keeping the best. Use whatever time remains. ---
    cur = best.copy()
    if cur.size < target_N and time.process_time() < deadline - 1.0:
        cur = _rescale_maxL(_upsample_pl(cur, target_N))
    while time.process_time() < deadline - 0.8:
        before = time.process_time()
        hf = _full_polish(cur, deadline, iters=300)
        rf = R_of(hf)
        if rf > R_of(cur) + 1e-15:
            cur = hf
        if time.process_time() >= deadline - 0.8:
            break
        hw = _window_polish(cur, deadline, frac=0.35, extra=6)
        rw = R_of(hw)
        if rw > R_of(cur) + 1e-15:
            cur = hw
        rc = R_of(cur)
        if rc > bestR + 1e-15:
            best, bestR = cur.copy(), rc
            print("polish R=%.7f" % bestR)
        if time.process_time() - before < 1e-3:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

