    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


def _ladder_up(h, target_N, deadline, accept_fn):
    """Grow h by 2x linear interpolation with exact L-BFGS polish, accepting gains."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    h = _rescale_maxL(h)
    best = h
    bestR = R_of(best)
    while best.size < target_N:
        if time.process_time() >= deadline - 1.0:
            break
        n = best.size
        n2 = min(target_N, n * 2)
        x_old = np.linspace(0.0, 1.0, n)
        x_new = np.linspace(0.0, 1.0, n2)
        h2 = np.interp(x_new, x_old, best)
        h2 = _rescale_maxL(h2)
        # polish at this scale
        hp = _exact_lbfgs(h2, 800, 1600, deadline)
        rp = R_of(hp)
        if rp > bestR:
            best, bestR = hp.copy(), rp
        else:
            best = h2
        # also try full polish occasionally
        if time.process_time() < deadline - 1.0:
            hf = _full_polish(best, deadline, iters=600)
            rf = R_of(hf)
            if rf > bestR:
                best, bestR = hf.copy(), rf
    return best


def _toeplitz_round_candidates(M):
    """Build plateau+shoulder targets, PSD-project via Toeplitz eigen-decomposition,
    return list of candidate h vectors of length M."""
    cands = []
    Llen = 2 * M - 1
    for rf in (0.02, 0.05, 0.10):
        r = max(1, int(rf * M))
        for wf in (0.40, 0.50, 0.60, 0.70):
            w = max(1, int(wf * M))
            Ltar = np.zeros(Llen)
            # plateau on [r, r+w]
            lo = r
            hi = min(Llen, r + w)
            if hi <= lo:
                continue
            Ltar[lo:hi] = 1.0
            # raised-cosine shoulders of width r on both sides
            for k in range(1, r + 1):
                val = 0.5 * (1.0 + np.cos(np.pi * k / r))
                if lo - k >= 0:
                    Ltar[lo - k] = max(Ltar[lo - k], val)
                if hi - 1 + k < Llen:
                    Ltar[hi - 1 + k] = max(Ltar[hi - 1 + k], val)
            # central part: indices M-1 .. 2M-2 correspond to T_ij = L[M-1+i-j]
            # build symmetric Toeplitz T of size MxM: T[i,j] = L[M-1 + i - j]
            # for i-j in [-(M-1), M-1] -> index M-1+(i-j) in [0, 2M-2]
            idx = np.arange(M)
            diff = idx[:, None] - idx[None, :]
            T = Ltar[M - 1 + diff]
            T = 0.5 * (T + T.T)
            try:
                lam, V = np.linalg.eigh(T)
            except np.linalg.LinAlgError:
                continue
            lam = np.maximum(lam, 0.0)
            Tp = (V * lam) @ V.T
            Tp = 0.5 * (Tp + Tp.T)
            Tp = Tp + 1e-12 * np.eye(M)
            try:
                C = np.linalg.cholesky(Tp)
            except np.linalg.LinAlgError:
                continue
            h0 = C[:, 0].copy()
            cands.append(np.clip(h0, 0, None))
            if M >= 2:
                cands.append(np.clip(C[:, 0] + C[:, 1], 0, None))
            cands.append(np.abs(h0))
    return cands


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---------------- Stage -1: Toeplitz-Cholesky rounding exploration ----------------
    try:
        M = 512
        target_N = best.size if best.size > 0 else 42496
        cands = _toeplitz_round_candidates(M)
        scored = []
        for c in cands:
            if c.size == 0 or c.sum() <= 0:
                continue
            rc = R_of(c)
            scored.append((rc, c))
        scored.sort(key=lambda t: -t[0])
        # keep top 3 distinct
        top = []
        seen = set()
        for rc, c in scored:
            key = (round(rc, 10), c.size)
            if key in seen:
                continue
            seen.add(key)
            top.append((rc, c))
            if len(top) >= 3:
                break
        print("toeplitz top scores: %s" % ", ".join("%.6f" % rc for rc, _ in top))
        for rc, c in top:
            if time.process_time() >= deadline - 2.0:
                break
            hl = _ladder_up(c, target_N, deadline, None)
            rl = R_of(hl)
            print("toeplitz ladder R=%.7f (N=%d)" % (rl, hl.size))
            if rl > bestR + 1e-15:
                best, bestR = hl.copy(), rl
                print("toeplitz accepted R=%.7f" % bestR)
    except Exception as e:
        print("toeplitz stage skipped: %s" % e)

    # Stage 0: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # ---------------- Stage 1b: quotient (stop-grad rescale) stage ----------------
    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 3000, 6000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        print("quot R=%.7f" % rq)
        if rq > bestR + 1e-15:
            best, bestR = hq.copy(), rq
            print("quot accepted R=%.7f" % bestR)
        # window polish with quotient objective, accept only on exact gain
        if time.process_time() < deadline - 1.0:
            hw = _window_polish(best, deadline, fun_grad=_quot_fun_grad)
            rw = R_of(hw)
            print("quot window R=%.7f" % rw)
            if rw > bestR + 1e-15:
                best, bestR = hw.copy(), rw
                print("quot window accepted R=%.7f" % bestR)

    # ---------------- Stage 2: alternating full/window polish to deadline ----------------
    w0 = _plateau_halfwidth(best)
    print("plateau halfwidth w0=%.2f" % w0)
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _softmax_fun_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    # soft-max surrogate: log( (1/K) sum exp(beta*(Lf-M)) ) + M, differentiable
    z = beta * (Lf - M)
    w = np.exp(z)
    W = w.sum()
    # logsumexp + M approx log(sum exp(beta Lf))/beta
    # But we want log(max). Use log( (1/beta) * logsumexp(beta*Lf) )
    # d/dh of log(maxapprox) = (1/W) * sum_j w_j * dLf_j/dh
    gLf = -dq / num
    gLf += (w / W)
    grad = _backprop(gLf, h) + 2.0 / s
    Lse = M + np.log(W) / beta
    val = -np.log(num) + 2.0 * np.log(s) + Lse
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, beta=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if beta is None:
            # hard max via top-1
            val, g = _softmax_fun_grad(hh, 1e4)
        else:
            val, g = _softmax_fun_grad(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _band_free_cells(h, lo_frac, hi_frac, topn):
    n = h.size
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(n)
    band = np.flatnonzero((Lf >= lo_frac * M) & (Lf <= hi_frac * M))
    if band.size == 0:
        return np.arange(n)
    mask = np.zeros(Lf.size)
    mask[band] = 1.0
    if n > 1500:
        corr = fftconvolve(h, mask[::-1], mode='valid')[:n]
    else:
        corr = np.correlate(h, mask, mode='valid')[:n]
    sens = h * 2.0 * corr
    topn = min(topn, n)
    idx = np.argpartition(sens, -topn)[-topn:]
    return np.sort(idx)


def _full_polish(h, deadline, iters=3000, beta=None):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: softmax ladder (smooth max approximation -> exact)
    h = best.copy()
    for beta in (20.0, 50.0, 100.0, 300.0, 1000.0, 3000.0):
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(h, deadline, iters=400, beta=beta)
        r = R_of(h)
        print("beta=%.0f R=%.7f" % (beta, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: exact polish
    h = _full_polish(best, deadline, iters=1500, beta=5000.0)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage 2: shoulder-band free-set polish
    def band_round(lo_frac, hi_frac, topn, iters):
        nonlocal best, bestR
        if time.process_time() >= deadline - 2.0:
            return False
        Lf = _knots(best)
        M = Lf.max()
        band_size = int(np.sum((Lf >= lo_frac * M) & (Lf <= hi_frac * M)))
        free = _band_free_cells(best, lo_frac, hi_frac, topn)
        print("band [%.1f,%.1f]M size=%d cells=%d" %
              (lo_frac, hi_frac, band_size, free.size))
        h = _exact_lbfgs(best, iters, 2 * iters, deadline, free=free, beta=5000.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("band R=%.7f" % bestR)
            return True
        return False

    rounds = 0
    while time.process_time() < deadline - 2.0:
        rounds += 1
        improved = band_round(0.3, 0.7, 3000, 1500)
        if time.process_time() >= deadline - 2.0:
            break
        h = _full_polish(best, deadline, iters=1000, beta=5000.0)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            improved = band_round(0.1, 0.9, 5000, 1500)
            if time.process_time() >= deadline - 2.0:
                break
            h = _full_polish(best, deadline, iters=1000, beta=5000.0)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                improved = True
                print("full R=%.7f" % bestR)
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
