    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _quot_fun_grad(h):
    h = np.clip(h, 0, None)
    s0 = h.sum()
    if s0 <= 0:
        return 1e18, np.zeros(h.size)
    mx = _knots(h).max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    r = 1.0 / np.sqrt(mx)
    hr = h * r
    num, dq, Lf = _num_and_dq(hr)
    s = hr.sum()
    if num <= 0 or s <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, hr) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad * hr


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            if K == 1:
                val, g = _norm_eq_fun_grad(hh)
            else:
                val, g = _topk_fun_grad(hh, K)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample_pl(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = np.arange(n, dtype=float)
    x = np.linspace(0.0, n - 1, N)
    return np.interp(x, xp, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # The start is already excellent. The dominant remaining gains come from
    # working at a HIGHER resolution than the start (which is 42496), where
    # the smooth optimal profile can be represented more finely. We upsample
    # the start to a large N and then do a full L-BFGS polish there, which
    # is a much more direct path to improving R than the previous ladder that
    # tried many intermediate resolutions and rarely beat the start.
    n0 = best.size

    # Choose a large working resolution (but keep FFT cost manageable).
    # 100k-150k is a good sweet spot: finer than start, still fast per iter.
    target_N = 120000
    if n0 >= target_N:
        target_N = n0

    if n0 != target_N and time.process_time() < deadline - 2.0:
        hu = _upsample_pl(best, target_N)
        hu = _rescale_maxL(hu)
        ru = R_of(hu)
        print("upsample N=%d R=%.7f" % (target_N, ru))
        # Full polish at high resolution. This is the main attack.
        hp = _full_polish(hu, deadline, iters=4000)
        rp = R_of(hp)
        print("hi-res full R=%.7f" % rp)
        if rp > bestR:
            best, bestR = hp.copy(), rp
        cur = best.copy()
    else:
        cur = best.copy()

    # Alternate: peak-window polish (cheap, sharpens plateau) plus occasional
    # full polish, plus quotient polish. Keep whichever is best.
    if time.process_time() < deadline - 1.0:
        hw = _window_polish(cur, deadline, frac=0.4, extra=8)
        rw = R_of(hw)
        if rw > bestR:
            best, bestR = hw.copy(), rw
            cur = best.copy()
        print("window R=%.7f" % bestR)

    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 2000, 4000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        if rq > bestR:
            best, bestR = hq.copy(), rq
            cur = best.copy()
        print("quot R=%.7f" % bestR)

    # Final loop: keep polishing until deadline.
    while time.process_time() < deadline - 0.8:
        before = time.process_time()
        hf = _full_polish(cur, deadline, iters=400)
        rf = R_of(hf)
        if rf > R_of(cur) + 1e-15:
            cur = hf
        if time.process_time() >= deadline - 0.8:
            break
        hw = _window_polish(cur, deadline, frac=0.35, extra=6)
        rw = R_of(hw)
        if rw > R_of(cur) + 1e-15:
            cur = hw
        rc = R_of(cur)
        if rc > bestR + 1e-15:
            best, bestR = cur.copy(), rc
            print("polish R=%.7f" % bestR)
        if time.process_time() - before < 1e-3:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

