def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _box_smooth(v, s):
    if s <= 1:
        return v
    k = np.ones(s) / s
    return np.convolve(v, k, mode='same')


def _direction_ladder(h, bestR, deadline, budget_seconds):
    """Exact 1-D maximization of true nonsmooth R along large dense directions."""
    rng = np.random.RandomState(12345)
    n = h.size
    hnorm = np.linalg.norm(h)
    if hnorm <= 0:
        return h, bestR
    ts = np.array([-0.5, -0.2, -0.05, -0.01, -0.002,
                   0.002, 0.01, 0.05, 0.2, 0.5])
    ndir = 0
    best = h.copy()

    def try_dir(v):
        nonlocal best, bestR, ndir
        vn = np.linalg.norm(v)
        if vn <= 0:
            return
        v = v * (hnorm / vn)
        best_t = 0.0
        best_r = bestR
        for t in ts:
            cand = best + t * v
            np.clip(cand, 0, None, out=cand)
            r = R_of(cand)
            if r > best_r:
                best_r = r
                best_t = t
        if best_t != 0.0 and best_r > bestR + 1e-9:
            cand = best + best_t * v
            np.clip(cand, 0, None, out=cand)
            cand = _rescale_maxL(cand)
            polished = _window_polish(cand, deadline, frac=0.20, extra=6, iters=20)
            rp = R_of(polished)
            if rp > bestR + 1e-9:
                best = polished
                bestR = rp
                print("  dir accept t=%.4f R=%.7f" % (best_t, bestR))
            elif best_r > bestR + 1e-9:
                best = _rescale_maxL(cand)
                bestR = best_r
                print("  dir raw t=%.4f R=%.7f" % (best_t, bestR))
        ndir += 1
        if ndir % 25 == 0:
            print("  ladder ndir=%d bestR=%.7f" % (ndir, bestR))

    # (i) reversal
    try_dir(h[::-1] - h)

    # (ii) multiscale smoothed random walks
    for s in (4, 16, 64, 256, 1024):
        for _ in range(8):
            if time.process_time() >= deadline - 1.0:
                return best, bestR
            w = rng.randn(n)
            v = np.cumsum(w)
            v = v - v.mean()
            v = _box_smooth(v, s)
            try_dir(v)

    # (iii) taper-localized around peak band
    try:
        Lf = _knots(h)
        mx = Lf.max()
        if mx > 0:
            band = (Lf > 0.5 * mx).astype(float)
            # map knot band to height support (approx same length n+1)
            band_h = band[1:-1] if band.size == n + 2 else band[:n]
            if band_h.size != n:
                band_h = np.interp(np.linspace(0, 1, n),
                                   np.linspace(0, 1, band_h.size), band_h)
            w = fftconvolve(band_h, h, mode='same')
            for _ in range(8):
                if time.process_time() >= deadline - 1.0:
                    return best, bestR
                try_dir(w * rng.randn(n))
    except Exception:
        pass

    # (iv) exact gradient of log R
    try:
        if time.process_time() < deadline - 1.0:
            _, g = _norm_eq_fun_grad(best)
            try_dir(-g)  # descent direction of -logR is -g
    except Exception:
        pass

    # (v) random block indicators
    for _ in range(8):
        if time.process_time() >= deadline - 1.0:
            return best, bestR
        w = int(rng.randint(64, 513))
        start_i = int(rng.randint(0, max(1, n - w)))
        v = np.zeros(n)
        v[start_i:start_i + w] = 1.0
        try_dir(v)

    # loop freshly drawn directions until deadline
    while time.process_time() < deadline - 1.0:
        s = int(rng.choice([4, 16, 64, 256, 1024]))
        w = rng.randn(n)
        v = np.cumsum(w)
        v = v - v.mean()
        v = _box_smooth(v, s)
        try_dir(v)

    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage B: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage B2: direction ladder (exact 1-D nonsmooth maximization).
    if time.process_time() < deadline - 1.0:
        print("ladder begin R=%.7f" % bestR)
        h, r = _direction_ladder(best, bestR, deadline, budget_seconds)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        print("ladder end R=%.7f" % bestR)

    # Stage C: alternate window-polish and full-polish, keeping best.
    while time.process_time() < deadline - 1.0:
        h = _window_polish(best, deadline, frac=0.20, extra=6)
        r = R_of(h)
        print("window R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        print("full2 R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

