    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, maxiter=1500, maxfun=3000, eps=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, maxiter, maxfun, deadline, free=free, eps=eps)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _box_smooth(h, w):
    if w <= 0:
        return h.copy()
    n = h.size
    c = np.concatenate(([0.0], np.cumsum(h)))
    lo = np.maximum(np.arange(n) - w, 0)
    hi = np.minimum(np.arange(n) + w + 1, n)
    return (c[hi] - c[lo]) / (hi - lo)


def _box_adjoint(g, w):
    if w <= 0:
        return g.copy()
    n = g.size
    lo = np.maximum(np.arange(n) - w, 0)
    hi = np.minimum(np.arange(n) + w + 1, n)
    wgt = g / (hi - lo)
    c = np.concatenate(([0.0], np.cumsum(wgt)))
    j = np.arange(n)
    lo2 = np.maximum(j - w, 0)
    hi2 = np.minimum(j + w + 1, n)
    return c[hi2] - c[lo2]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.82
    rng = np.random.default_rng(2024)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    def try_update(h, tag):
        nonlocal best, bestR
        if h is None or h.size == 0:
            return False
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("%s R=%.7f (N=%d)" % (tag, bestR, best.size))
            return True
        return False

    # Stage 1: fine upsample + polish (the big structural win: more resolution)
    # Try 2x upsample once; if it improves, try again.
    for factor in (2, 2):
        if time.process_time() >= deadline - 4.0:
            break
        if best.size * factor > 190000:
            break
        fine = _upsample(best, factor)
        fine = _exact_lbfgs(fine, 2000, 4000, deadline)
        ok = try_update(fine, "up%d" % factor)
        if not ok:
            # try smoother ramp then polish
            fine2 = _upsample(best, factor)
            fine2 = _exact_lbfgs(fine2, 2000, 4000, deadline, eps=1e-4)
            if not try_update(fine2, "up%d-s" % factor):
                break

    # Stage 2: exact polish with peak-region window (cheap, high yield)
    for _ in range(2):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline)
        if not try_update(h, "win"):
            h = _window_polish(best, deadline, frac=0.5, extra=8)
            if not try_update(h, "win-wide"):
                break

    # Stage 3: alternate smooth-max continuation and exact
    eps_cycle = [1e-3, 1e-4, 1e-6, None]
    k = 0
    while time.process_time() < deadline - 2.0:
        eps = eps_cycle[k % len(eps_cycle)]
        k += 1
        improved = False
        h = _exact_lbfgs(best, 2000, 4000, deadline, eps=eps)
        if try_update(h, "exact-%s" % (eps,)):
            improved = True
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, eps=eps)
        if try_update(h, "win-%s" % (eps,)):
            improved = True
        if not improved:
            # small kick on peak region
            n = best.size
            lo, hi = _peak_region(best)
            pad = max(4, int((hi - lo) * 0.5))
            lo = max(0, lo - pad); hi = min(n - 1, hi + pad)
            h = best.copy()
            noise = rng.standard_normal(n) * 1e-6
            h[lo:hi + 1] = np.clip(h[lo:hi + 1] + noise[lo:hi + 1] * h.max(), 0, None)
            h = _rescale_maxL(h)
            h = _exact_lbfgs(h, 1500, 3000, deadline, eps=1e-4)
            if not try_update(h, "kick"):
                break

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

