def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _smooth(h, sigma):
    if sigma <= 0:
        return h.copy()
    r = int(np.ceil(3 * sigma))
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    hp = np.concatenate((h[r:0:-1], h, h[-2:-r-2:-1])) if r > 0 else h
    if hp.size < h.size + 2 * r:
        hp = np.concatenate((h[:r][::-1], h, h[-r:][::-1]))
    out = np.convolve(hp, k, mode='valid')
    if out.size != h.size:
        out = out[:h.size]
        if out.size < h.size:
            out = np.concatenate((out, h[out.size:]))
    return np.clip(out, 0, None)


def _perturb_smooth(h, deadline, sigma, amp, rng):
    n = h.size
    eps = rng.standard_normal(n) * amp
    eps = _smooth(eps, sigma)
    h2 = h * np.exp(eps)
    h2 = _rescale_maxL(h2)
    h2 = _full_polish(h2, deadline, iters=1500)
    return h2


def _invert_target(T):
    """Invert interior knot values T[1:-1] to heights h with h*h ~ T.
    Recursion: h_0 = sqrt(T[1]); h_k = (T[1+k] - sum_{i=1}^{k-1} h_i h_{k-i})/(2 h_0).
    Returns h of length len(T)-1 or None if infeasible."""
    m = T.size - 2  # number of interior knots -> h length m
    if m < 1:
        return None
    if T[1] <= 0:
        return None
    h0 = np.sqrt(T[1])
    h = np.zeros(m)
    h[0] = h0
    # We need h_0..h_{m-1}; knot T[1+k] = sum_{i=0}^{k} h_i h_{k-i} for k=0..m-1.
    # For k=0: T[1] = h_0^2 -> h_0 = sqrt(T[1]).
    # For k>=1: T[1+k] = 2 h_0 h_k + sum_{i=1}^{k-1} h_i h_{k-i}
    for k in range(1, m):
        s = 0.0
        for i in range(1, k):
            s += h[i] * h[k - i]
        val = (T[1 + k] - s) / (2.0 * h0)
        if not np.isfinite(val) or val < 0:
            return None
        h[k] = val
    if not np.all(np.isfinite(h)):
        return None
    return h


def _one_sided_target(Lf, side, d):
    """Build target T by moving plateau boundary on `side` outward by d knots,
    compressing that side's taper. side in {'left','right'}."""
    n = Lf.size
    M = Lf.max()
    idx = np.flatnonzero(Lf >= 0.999 * M)
    if idx.size == 0:
        return None
    i0 = int(idx.min()); i1 = int(idx.max())
    T = Lf.copy()
    if side == 'left':
        # left taper is Lf[0..i0], plateau starts at i0
        new_i0 = i0 - d
        if new_i0 < 1:
            return None
        # old taper values Lf[0..i0] resampled onto [0..new_i0]
        old = Lf[0:i0 + 1]
        old_x = np.linspace(0.0, 1.0, old.size)
        new_x = np.linspace(0.0, 1.0, new_i0 + 1)
        T[0:new_i0 + 1] = np.interp(new_x, old_x, old)
        T[new_i0:i0 + 1] = M
    else:
        new_i1 = i1 + d
        if new_i1 > n - 2:
            return None
        old = Lf[i1:n]
        old_x = np.linspace(0.0, 1.0, old.size)
        new_x = np.linspace(0.0, 1.0, (n - 1 - new_i1) + 1)
        T[new_i1:n] = np.interp(new_x, old_x, old)
        T[i1:new_i1 + 1] = M
    return T


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage B: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage C: alternate window-polish and full-polish, keeping best.
    while time.process_time() < deadline - 1.0:
        h = _window_polish(best, deadline, frac=0.20, extra=6)
        r = R_of(h)
        print("window R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        print("full2 R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            break

    # Stage D: one-sided knot-target inversion scan, alternating with window polish.
    ds = [2, 5, 10, 20, 40, 80]
    while time.process_time() < deadline - 1.0:
        Lf = _knots(best)
        M = Lf.max()
        idx = np.flatnonzero(Lf >= 0.999 * M)
        if idx.size == 0:
            break
        i0 = int(idx.min()); i1 = int(idx.max())
        left_len = i0
        right_len = Lf.size - 1 - i1
        sides = []
        if left_len >= right_len:
            sides.append('left')
        if right_len >= left_len:
            sides.append('right')
        improved = False
        for side in sides:
            for d in ds:
                if time.process_time() >= deadline - 1.0:
                    break
                T = _one_sided_target(Lf, side, d)
                if T is None:
                    print("target %s d=%d infeasible" % (side, d))
                    continue
                hcand = _invert_target(T)
                if hcand is None:
                    print("target %s d=%d invert-fail" % (side, d))
                    continue
                hcand = _rescale_maxL(hcand)
                hcand = _full_polish(hcand, deadline, iters=800)
                r = R_of(hcand)
                print("target %s d=%d R=%.7f" % (side, d, r))
                if r > bestR + 1e-15:
                    best, bestR = hcand.copy(), r
                    improved = True
                    print("  ACCEPT %s d=%d R=%.7f" % (side, d, bestR))
                    break
            if improved:
                break
        if not improved:
            # try window polish to nudge, then loop
            h = _window_polish(best, deadline, frac=0.15, extra=4)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("window2 R=%.7f" % bestR)
            else:
                # no progress: do a smooth-perturbation hop to escape
                rng = np.random.default_rng(int(time.process_time() * 1e6) & 0xffffffff)
                n = best.size
                sig = max(2.0, n * 0.03)
                amp = 0.02
                cand = _perturb_smooth(best, deadline, sig, amp, rng)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best, bestR = cand.copy(), r
                    print("hop R=%.7f" % bestR)
                else:
                    print("hop no gain (R=%.7f)" % r)
                    if time.process_time() >= deadline - 1.0:
                        break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _quot_fun_grad(h):
    h = np.clip(h, 0, None)
    s0 = h.sum()
    if s0 <= 0:
        return 1e18, np.zeros(h.size)
    mx = _knots(h).max()
    if mx <= 0:
        return 1e18, np.zeros(h.size)
    r = 1.0 / np.sqrt(mx)
    hr = h * r
    num, dq, Lf = _num_and_dq(hr)
    s = hr.sum()
    if num <= 0 or s <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    grad = _backprop(gLf, hr) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s)
    return val, grad * hr


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _norm_eq_fun_grad(hh)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample_pl(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = np.arange(n, dtype=float)
    x = np.linspace(0.0, n - 1, N)
    return np.interp(x, xp, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Small refinement pass at the SAME resolution as the start. The start is
    # already near a local optimum, but L-BFGS with a fresh history often
    # squeezes a few more digits out. Cheaper than upsampling.
    if time.process_time() < deadline - 0.5:
        hs = _full_polish(best, min(deadline, t0 + budget_seconds * 0.55), iters=1500)
        rs = R_of(hs)
        print("same-res R=%.7f" % rs)
        if rs > bestR:
            best, bestR = hs.copy(), rs

    # Upsample to a finer grid and polish there.
    n0 = best.size
    target_N = 120000
    if n0 >= target_N:
        target_N = n0
    if n0 != target_N and time.process_time() < deadline - 2.0:
        hu = _upsample_pl(best, target_N)
        hu = _rescale_maxL(hu)
        print("upsample N=%d R=%.7f" % (target_N, R_of(hu)))
        hp = _full_polish(hu, deadline, iters=4000)
        rp = R_of(hp)
        print("hi-res full R=%.7f" % rp)
        if rp > bestR:
            best, bestR = hp.copy(), rp

    cur = best.copy()

    if time.process_time() < deadline - 1.0:
        hw = _window_polish(cur, deadline, frac=0.4, extra=8)
        rw = R_of(hw)
        if rw > bestR:
            best, bestR = hw.copy(), rw
            cur = best.copy()
        print("window R=%.7f" % bestR)

    if time.process_time() < deadline - 1.0:
        hq = _exact_lbfgs(best, 2000, 4000, deadline, fun_grad=_quot_fun_grad)
        rq = R_of(hq)
        if rq > bestR:
            best, bestR = hq.copy(), rq
            cur = best.copy()
        print("quot R=%.7f" % bestR)

    while time.process_time() < deadline - 0.8:
        before = time.process_time()
        hf = _full_polish(cur, deadline, iters=400)
        rf = R_of(hf)
        if rf > R_of(cur) + 1e-15:
            cur = hf
        if time.process_time() >= deadline - 0.8:
            break
        hw = _window_polish(cur, deadline, frac=0.35, extra=6)
        rw = R_of(hw)
        if rw > R_of(cur) + 1e-15:
            cur = hw
        rc = R_of(cur)
        if rc > bestR + 1e-15:
            best, bestR = cur.copy(), rc
            print("polish R=%.7f" % bestR)
        if time.process_time() - before < 1e-3:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
