    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            if K == 1:
                val, g = _norm_eq_fun_grad(hh)
            else:
                val, g = _topk_fun_grad(hh, K)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _central_binom_seq(K):
    h = np.empty(K)
    v = 1.0
    h[0] = v
    for k in range(1, K):
        v = v * (2.0 * k - 1.0) / (2.0 * k)
        h[k] = v
    return h


def _make_seed(N, K, kind, param):
    h = np.zeros(N)
    K = max(1, min(K, N))
    base = _central_binom_seq(K)
    x = np.arange(K) / float(K)
    if kind == 'exp':
        E = np.exp(-(x ** param))
    elif kind == 'pow':
        E = np.maximum(0.0, 1.0 - x) ** param
    else:
        E = np.ones(K)
    h[:K] = base * E
    return h


def _upsample2(h):
    n = h.size
    xo = np.arange(2 * n)
    xi = np.arange(n) * 2.0
    return np.interp(xo, xi, h)


def _stage0(best, bestR, deadline, target_N):
    N0 = 8192
    seeds = []
    for Kfrac in (0.25, 0.40, 0.55):
        K = int(Kfrac * N0)
        for p in (2, 4, 8, 16):
            seeds.append((K, 'exp', p))
        for q in (0.5, 1, 2, 4):
            seeds.append((K, 'pow', q))
        seeds.append((K, 'hard', 0))
    cands = []
    for (K, kind, param) in seeds:
        if time.process_time() >= deadline - 2.0:
            break
        h = _make_seed(N0, K, kind, param)
        h = _rescale_maxL(h)
        h = _exact_lbfgs(h, 300, 600, deadline)
        r = R_of(h)
        cands.append((r, h, kind, param, K))
    if not cands:
        return best, bestR
    cands.sort(key=lambda t: -t[0])
    top = cands[:3]
    print("stage0 best raw: " + ", ".join("%s/%s:%.6f" % (c[2], c[3], c[0]) for c in top))
    best_cand = None
    best_cand_R = -1.0
    for (r, h, kind, param, K) in top:
        if time.process_time() >= deadline - 2.0:
            break
        hh = h.copy()
        while hh.size < target_N:
            hh = _rescale_maxL(_upsample2(hh))
            if hh.size > target_N:
                hh = hh[:target_N]
        if hh.size != target_N:
            # pad or trim to target
            if hh.size < target_N:
                hh = np.concatenate([hh, np.zeros(target_N - hh.size)])
            else:
                hh = hh[:target_N]
        hh = _rescale_maxL(hh)
        hh = _exact_lbfgs(hh, 800, 1600, deadline)
        rr = R_of(hh)
        print("stage0 up %s/%s R=%.7f" % (kind, param, rr))
        if rr > best_cand_R:
            best_cand_R = rr
            best_cand = hh
    if best_cand is not None and best_cand_R > bestR + 1e-15:
        print("stage0 ACCEPT %.7f -> %.7f" % (bestR, best_cand_R))
        return best_cand, best_cand_R
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: central-binomial seeds with multiplicative envelopes.
    target_N = best.size
    best, bestR = _stage0(best, bestR, deadline, target_N)

    # Stage A: top-K-mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage B: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage C: alternate window-polish and full-polish.
    while time.process_time() < deadline - 1.0:
        h = _window_polish(best, deadline, frac=0.20, extra=6)
        r = R_of(h)
        print("window R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        print("full2 R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    fg = _norm_eq_fun_grad if fun_grad is None else fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample_pl(h, N):
    n = h.size
    if n == N:
        return h.copy()
    xp = np.arange(n, dtype=float)
    x = np.linspace(0.0, n - 1, N)
    return np.interp(x, xp, h)


def _refine_res(h, target_N, deadline, iters=1500):
    """Upsample to target_N then L-BFGS polish; return best of (h, refined)."""
    if time.process_time() >= deadline - 1.0:
        return h
    hu = _upsample_pl(h, target_N)
    hu = _rescale_maxL(hu)
    hp = _exact_lbfgs(hu, iters, 2 * iters, deadline)
    if R_of(hp) > R_of(h):
        return hp
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    n0 = base.size

    # Strategy: the optimum is a smooth limiting profile. Gains come from
    # representing it on a finer grid AND from polishing the peak window
    # (where the max constraint is active) on the finer grid. We do a
    # resolution ladder upward, refining at each step, keeping the best.
    # Then alternate full + window polishes on the finest grid until deadline.

    cur = best.copy()
    # Ladder of increasing resolutions; only go up, each step refines.
    ladder = []
    for N in (60000, 90000, 130000, 180000):
        if N > n0:
            ladder.append(N)
    if n0 >= 180000:
        ladder = []

    for N in ladder:
        if time.process_time() >= deadline - 4.0:
            break
        hn = _refine_res(cur, N, deadline, iters=1500)
        rn = R_of(hn)
        if rn > bestR:
            best, bestR = hn.copy(), rn
            cur = best.copy()
        else:
            cur = hn if R_of(hn) > R_of(cur) else cur
        print("ladder N=%d R=%.7f" % (cur.size, bestR))

    # Now on the current (finest) grid, alternate full and window polishes.
    while time.process_time() < deadline - 0.8:
        before = time.process_time()
        hf = _exact_lbfgs(cur, 600, 1200, deadline)
        if R_of(hf) > R_of(cur) + 1e-15:
            cur = hf
        if time.process_time() >= deadline - 0.8:
            break
        hw = _window_polish(cur, deadline, frac=0.4, extra=8)
        if R_of(hw) > R_of(cur) + 1e-15:
            cur = hw
        rc = R_of(cur)
        if rc > bestR + 1e-15:
            best, bestR = cur.copy(), rc
            print("polish R=%.7f" % bestR)
        if time.process_time() - before < 1e-3:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

