    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _window_polish_shift(h, deadline, shift, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    """Add small smooth multiplicative noise, renormalize."""
    n = h.size
    # smooth noise via low-frequency convolution
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # Stage 1: full exact polish with K=1.
    h = _exact_lbfgs(best, 4000, 8000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Stage 2: windowed polish on peak.
    if time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline, frac=0.30, extra=8, iters=2000)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 3: top-K soft-max flattening.
    for K in (3, 5, 8):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(best, 1500, 3000, deadline, K=K)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 4: alternating shifted window polishes + perturbation restarts.
    shifts = [0, -1, 1, -2, 2, -4, 4]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish_shift(best, deadline, sh, frac=0.20, extra=6, iters=1500)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0:
            h = _exact_lbfgs(best, 800, 1600, deadline, K=1)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        # Occasionally try a perturbed restart to escape local optima.
        if si % 5 == 0 and time.process_time() < deadline - 6.0:
            for scale in (0.02, 0.05):
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1500, 3000, deadline, K=1)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp

    # Final full polish.
    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline, K=1)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


# Log-sum-exp soft-max objective (differentiable surrogate for max L)
def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-18, 'gtol': 1e-14})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


# Top-K soft-max: average of K largest knots, differentiable
def _topk_obj_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def run_topk(h0, K, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, K)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-18, 'gtol': 1e-14})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _peak_window(h, frac=0.35, extra=6):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        lo, hi = max(0, m - 1), min(n - 1, m)
    else:
        lo = max(0, idx.min() - 1)
        hi = min(n - 1, idx.max())
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    return lo, hi


# Polish only the window around the peak (where max L lives) — cheap and
# concentrates resolution exactly where it matters for the max term.
def window_polish(h, deadline, beta=300.0, iters=800):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    lo, hi = _peak_window(h)
    free = np.arange(lo, hi + 1)
    hh = np.clip(h, 0, None).copy()

    def f(x):
        hh[:] = 0.0
        hh[free] = np.clip(x, 0, None)
        o, g = _direct_obj_grad(hh, beta)
        return o, g[free] * (x > 0)
    try:
        res = minimize(f, hh[free].copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * free.size,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-18, 'gtol': 1e-14})
        out = hh.copy()
        out[free] = np.clip(res.x, 0, None)
        return _rescale_maxL(out)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.86

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # ---- Phase 1: fine-grid search on window around peak ----
    # The peak of L sits in ~17% of the support; most of the resolution
    # budget should be spent sharpening that region, not the tails.
    h = best.copy()
    cur = bestR
    for beta in [200.0, 600.0, 1500.0, 4000.0]:
        if time.process_time() >= deadline - 2.0:
            break
        h2 = window_polish(h, deadline, beta=beta, iters=1000)
        r2 = R_of(h2)
        if r2 > cur + 1e-13:
            h, cur = h2, r2
            print("win beta=%.0f R=%.6f" % (beta, cur))

    # ---- Phase 2: top-K smoothing to flatten the max plateau ----
    # The true optimum likely has a plateau of near-max knots; top-K
    # encourages a flat top which is what maximizes the ratio.
    for K in [2, 4, 8, 16, 32]:
        if time.process_time() >= deadline - 2.0:
            break
        h2 = run_topk(h, K, 600, 1200, deadline)
        r2 = R_of(h2)
        if r2 > cur + 1e-13:
            h, cur = h2, r2
            print("topk K=%d R=%.6f" % (K, cur))

    # ---- Phase 3: full direct polish with increasing beta ----
    for beta, mi, mf in [(300, 500, 1000), (1500, 400, 800),
                         (5000, 300, 600), (20000, 200, 400)]:
        if time.process_time() >= deadline - 1.5:
            break
        h2 = run_direct(h, beta, mi, mf, deadline)
        r2 = R_of(h2)
        if r2 > cur + 1e-13:
            h, cur = h2, r2
            print("direct beta=%.0f R=%.6f" % (beta, cur))

    # ---- Phase 4: alternate window-polish / top-K / direct until deadline ----
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        improved = False

        h2 = window_polish(h, deadline, beta=8000.0, iters=600)
        r2 = R_of(h2)
        if r2 > cur + 1e-13:
            h, cur, improved = h2, r2, True

        if time.process_time() < deadline - 1.0:
            h2 = run_topk(h, 4, 300, 600, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-13:
                h, cur, improved = h2, r2, True

        if time.process_time() < deadline - 1.0:
            h2 = run_direct(h, 10000.0, 250, 500, deadline)
            r2 = R_of(h2)
            if r2 > cur + 1e-13:
                h, cur, improved = h2, r2, True

        if cur > bestR + 1e-13:
            best, bestR = h.copy(), cur
            print("iter%d R=%.6f (N=%d)" % (it, bestR, best.size))
        if not improved:
            # small random perturbation around peak to break out of local min
            nz = h > 1e-9 * h.max()
            if np.any(nz):
                h2 = h.copy()
                rng = np.random.default_rng(it)
                h2[nz] *= (1.0 + 3e-4 * rng.standard_normal(nz.sum()))
                h2 = _rescale_maxL(np.clip(h2, 0, None))
                r2 = R_of(h2)
                if r2 > cur + 1e-13:
                    h, cur = h2, r2
                    continue
            break

    if cur > bestR + 1e-13:
        best, bestR = h.copy(), cur
    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            if K == 1:
                val, g = _norm_eq_fun_grad(hh)
            else:
                val, g = _topk_fun_grad(hh, K)
            return val, g[active] * hh[active]
    else:
        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = fun_grad(hh)
            return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _window_polish_shift(h, deadline, shift, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _block_average(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _signature(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return (0.0, 0.0, 0.0)
    m = int(np.argmax(Lf))
    pos = m / (2.0 * n)
    frac95 = float(np.mean(Lf >= 0.95 * mx))
    meanh = h.mean()
    fracpos = float(np.mean(h > 0.1 * meanh)) if meanh > 0 else 0.0
    return (pos, frac95, fracpos)


def _sig_dist(a, b):
    return abs(a[0] - b[0]) + abs(a[1] - b[1]) + abs(a[2] - b[2])


def _random_coarse_start(rng, N):
    nk = 8
    knots = np.sort(rng.uniform(0, N, nk))
    vals = rng.uniform(-3, 3, nk)
    x = np.arange(N)
    prof = np.interp(x, knots, vals)
    h = np.exp(prof)
    return h


def _coarse_lbfgs(h, iters, deadline):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    active = np.flatnonzero(h > 1e-13 * max(h.max(), 1e-300))
    if active.size == 0:
        return h
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-18, 'gtol': 1e-14})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)
    startR = bestR

    # ---- Stage 0: coarse exhaustive search at N=384 ----
    Nc = 384
    coarse_inc = _block_average(best, Nc)
    coarse_inc = _rescale_maxL(coarse_inc)
    incR_c = R_of(coarse_inc)
    inc_sig = _signature(coarse_inc)

    # time budget for coarse search: up to ~40% of remaining budget
    coarse_deadline = min(deadline - 0.5,
                          t0 + 0.4 * (deadline - t0))
    rng = np.random.default_rng(12345)

    candidates = []  # (R, sig, h)
    n_tries = 0
    while time.process_time() < coarse_deadline:
        h0 = _random_coarse_start(rng, Nc)
        h0 = _rescale_maxL(h0)
        hc = _coarse_lbfgs(h0, 300, coarse_deadline)
        n_tries += 1
        rc = R_of(hc)
        if rc > 0.90:
            candidates.append((rc, _signature(hc), hc))

    # cluster by signature, discard incumbent cluster
    alt_best = None
    alt_bestR = -1.0
    if candidates:
        candidates.sort(key=lambda t: -t[0])
        kept = []
        for rc, sig, hc in candidates:
            if _sig_dist(sig, inc_sig) < 0.05:
                continue
            # cluster: skip if close to an already-kept candidate
            dup = False
            for _, ksig, _ in kept:
                if _sig_dist(sig, ksig) < 0.05:
                    dup = True
                    break
            if dup:
                continue
            kept.append((rc, sig, hc))
            if rc > alt_bestR:
                alt_bestR = rc
                alt_best = hc

    print(f"coarse: incR={incR_c:.5f} tries={n_tries} cands={len(candidates)} "
          f"altR={alt_bestR:.5f}")

    # ---- Stage 0b: polish the alternative candidate at full resolution ----
    if alt_best is not None and time.process_time() < deadline - 1.0:
        hcand = _resample_cum(alt_best, best.size)
        hcand = _rescale_maxL(hcand)
        rcand = R_of(hcand)
        shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8]
        si = 0
        while time.process_time() < deadline - 1.0:
            hcand = _exact_lbfgs(hcand, 1500, 3000, deadline, K=1)
            rcand = R_of(hcand)
            if rcand > bestR:
                best, bestR = hcand.copy(), rcand
            if time.process_time() >= deadline - 1.0:
                break
            sh = shifts[si % len(shifts)]
            si += 1
            hcand = _window_polish_shift(hcand, deadline, sh,
                                         frac=0.20, extra=6, iters=1500)
            rcand = R_of(hcand)
            if rcand > bestR:
                best, bestR = hcand.copy(), rcand

    # ---- Existing pipeline on the best-so-far ----
    h = _exact_lbfgs(best, 4000, 8000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    if time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline, frac=0.30, extra=8, iters=2000)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    for K in (3, 5, 8):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(best, 1500, 3000, deadline, K=K)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    shifts = [0, -1, 1, -2, 2, -4, 4]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish_shift(best, deadline, sh, frac=0.20, extra=6, iters=1500)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0:
            h = _exact_lbfgs(best, 800, 1600, deadline, K=1)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline, K=1)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # never return worse than start
    if bestR < startR:
        best = np.clip(np.asarray(start, dtype=float), 0, None)
        bestR = startR

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Main new idea: refine on a finer grid. Upsample, polish, then keep if better.
    # Also try a shifted/whole-grid polish. Repeat until deadline.
    d_ups = t0 + budget_seconds * 0.55
    if best.size <= 60000 and time.process_time() < d_ups - 3.0:
        for factor in (2,):
            if time.process_time() >= d_ups - 3.0:
                break
            hi = _upsample(best, factor)
            hi = _rescale_maxL(hi)
            hi = _exact_lbfgs(hi, 600, 1200, d_ups)
            r = R_of(hi)
            if r > bestR + 1e-16:
                best, bestR = hi, r
                print("upsample x%d R=%.7f (N=%d)" % (factor, bestR, best.size))

    # Final polish loop: alternate full and window polish.
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if time.process_time() >= deadline - 1.0:
            break
        cand = _window_polish(best, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            if time.process_time() >= deadline - 1.0:
                break
            # try upsampling once more if budget allows
            if best.size <= 90000 and time.process_time() < deadline - 5.0:
                hi = _upsample(best, 2)
                hi = _rescale_maxL(hi)
                hi = _exact_lbfgs(hi, 400, 800, deadline)
                r2 = R_of(hi)
                if r2 > bestR + 1e-16:
                    best, bestR = hi, r2
                    print("late upsample R=%.7f (N=%d)" % (bestR, best.size))
                    continue
            break
    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR < R_of(base):
        best, bestR = base, R_of(base)
    return best

