    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def _perturb(h, rng, scale=0.02):
    """Multiplicative random perturbation on log scale."""
    n = h.size
    noise = rng.standard_normal(n) * scale
    return np.clip(h * np.exp(noise), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: quick top-K ladder from start
    h = best.copy()
    for K in (10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Stage 1: full polish
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage 2: alternating window/full polish with top-K tricks
    stall = 0
    round_no = 0
    while time.process_time() < deadline - 0.8:
        round_no += 1
        improved = False

        # top-K polish to widen the flat peak (helps escape local opt)
        if round_no % 3 == 1:
            hK = _exact_lbfgs(best, 500, 1000, deadline, K=3)
            r = R_of(hK)
            if r > bestR + 1e-15:
                best, bestR = hK.copy(), r
                improved = True
                print("topK3 R=%.7f" % bestR)

        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 0.8:
            break
        h = _exact_lbfgs(best, 1200, 2400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2:
                # perturb and retry
                if time.process_time() < deadline - 0.8:
                    cand = _rescale_maxL(_perturb(best, rng, scale=0.015))
                    hc = _exact_lbfgs(cand, 600, 1200, deadline)
                    rc = R_of(hc)
                    if rc > bestR + 1e-15:
                        best, bestR = hc.copy(), rc
                        stall = 0
                        print("perturb R=%.7f" % bestR)
                    else:
                        hw = _window_polish(best, deadline, frac=0.6, extra=16)
                        rw = R_of(hw)
                        if rw > bestR + 1e-15:
                            best, bestR = hw.copy(), rw
                            stall = 0
                            print("wide window R=%.7f" % bestR)
                        else:
                            break
        else:
            stall = 0

    # Stage 3: upsample and refine
    while time.process_time() < deadline - 0.8:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=0.4))
        if cand.size > 200000:
            cand = cand[:200000]
        cand = _rescale_maxL(cand)
        hf = _exact_lbfgs(cand, 800, 1600, deadline)
        rf = R_of(hf)
        if rf > bestR + 1e-15:
            best, bestR = hf.copy(), rf
            print("upsample R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

