    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _deconvolve(Tgt):
    """Forward recursion: given knot vector Tgt (length n+1), recover h (length n)."""
    Tgt = np.clip(np.asarray(Tgt, dtype=float), 0, None)
    n = Tgt.size - 1
    if n < 1:
        return np.zeros(max(n, 1))
    h = np.zeros(n)
    h0sq = Tgt[0]
    if h0sq <= 1e-300:
        return h
    h0 = np.sqrt(h0sq)
    h[0] = h0
    for k in range(1, n):
        # Tgt[k] = sum_{i=0}^{k} h_i h_{k-i}  (with h index < n)
        # terms i=0..k, but only h_i with i<n
        s = 0.0
        for i in range(1, k):
            if i < n and (k - i) < n:
                s += h[i] * h[k - i]
        # Tgt[k] = 2*h0*h[k] + s
        h[k] = (Tgt[k] - s) / (2.0 * h0)
    return np.clip(h, 0, None)


def _taper_spline_trial(h, K, deadline):
    """Reparameterise taper band of L via monotone cubic spline, deconvolve."""
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return None
    n = h.size
    lo_thr = 0.005 * M
    hi_thr = 0.995 * M
    T = np.flatnonzero((Lf > lo_thr) & (Lf < hi_thr))
    if T.size < K + 2:
        return None
    u = Lf[T] / M
    # control points evenly spaced in index of T
    idx = np.linspace(0, T.size - 1, K).astype(int)
    # dedupe
    idx = np.unique(idx)
    if idx.size < 3:
        return None
    xc = idx.astype(float)
    yc = u[idx]
    # enforce monotone: PchipInterpolator preserves monotonicity of data
    try:
        spl = PchipInterpolator(xc, yc, extrapolate=True)
    except Exception:
        return None
    xs = np.arange(T.size, dtype=float)
    u_new = spl(xs)
    u_new = np.clip(u_new, 0.0, 1.0)
    Tgt = Lf.copy()
    Tgt[T] = M * u_new
    Tgt = np.clip(Tgt, 0, None)
    Tgt[0] = 0.0
    Tgt[-1] = 0.0
    # deconvolve: Tgt has length n+1 (knots), h has length n
    h_new = _deconvolve(Tgt)
    if h_new.sum() <= 0:
        return None
    h_new = _rescale_maxL(h_new)
    return h_new


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    def try_higher_res(h_base, factor, deadline, iters):
        h_up = _resample_cum(h_base, h_base.size * factor)
        h_up = _rescale_maxL(h_up)
        h_up = _exact_lbfgs(h_up, iters, 2 * iters, deadline)
        return h_up

    # Stage 1: modest full polish at current res.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # NEW EXPERIMENT: taper-band spline reparameterisation + deconvolution.
    # Try all K, short polish, accept only strict improvement.
    for K in (6, 8, 10, 12):
        if time.process_time() >= deadline - 4.0:
            break
        trial = _taper_spline_trial(best, K, deadline)
        if trial is None:
            continue
        trial = _exact_lbfgs(trial, 400, 800, deadline)
        rt = R_of(trial)
        if rt > bestR + 1e-9:
            best, bestR = trial, rt

    # Stage 2: window polish on peak.
    if time.process_time() < deadline - 3.0:
        h = _window_polish(best, deadline, frac=0.30, extra=8, iters=1500)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 3: resolution escalation.
    cur = best
    for factor in (2, 2):
        if time.process_time() >= deadline - 6.0:
            break
        if cur.size * factor > 200000:
            break
        h_up = try_higher_res(cur, factor, deadline, 1200)
        r = R_of(h_up)
        if r > bestR:
            best, bestR = h_up, r
            cur = h_up
        else:
            cur = best

    # Stage 4: alternating shifted window polishes + perturbations.
    shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.20, extra=6,
                           iters=1200, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0:
            h = _exact_lbfgs(best, 800, 1600, deadline)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        if si % 5 == 0 and time.process_time() < deadline - 6.0:
            for scale in (0.02, 0.05):
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1200, 2400, deadline)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

