    Lp = np.clip(Lf, 0, None)
    Sp = np.sum(Lp ** p)
    if Sp <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf += (Lp ** (p - 1)) / Sp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 / p) * np.log(Sp)
