    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _window_free(n, lo, hi):
    lo = max(0, int(lo)); hi = min(n - 1, int(hi))
    if hi < lo:
        return np.arange(0)
    return np.arange(lo, hi + 1)


def _downsample(h, n_out):
    """Area-preserving downsample of step function to n_out steps."""
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    xo = np.linspace(0.0, c[-1], n_out + 1)
    xp = np.linspace(0.0, c[-1], n + 1)
    co = np.interp(xo, xp, c)
    return np.clip(np.diff(co), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)
    n = best.size

    # New idea: the peak of f*f is the binding constraint. Rather than only
    # polishing a fixed window around it, we solve for a *strictly lower*
    # target peak using a continuation scheme: temporarily replace the max
    # term by a smoothed/relaxed max (softmax over top-k knots). This lets
    # mass migrate to flatten a cluster of near-peak knots, then we tighten
    # back to the true max. Flattening the peak region is what raises R
    # (numerator) without raising the denominator.

    def topk_fun_grad(hh, K):
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(hh.size)
        num, dq, Lf = _num_and_dq(hh)
        K = max(1, min(K, Lf.size))
        idx = np.argpartition(Lf, -K)[-K:]
        top = Lf[idx]
        mt = top.sum() / K
        if mt <= 0:
            return 1e18, np.zeros(hh.size)
        gLf = -dq / num
        gLf[idx] += (1.0 / K) / mt
        grad = _backprop(gLf, hh) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mt)
        return val, grad

    def lbfgs_topk(h0, K, iters, dl, free=None):
        if time.process_time() >= dl - 0.5:
            return h0
        hh = np.clip(h0, 0, None)
        if hh.sum() <= 0:
            return h0
        nn = hh.size
        if free is None:
            active = np.flatnonzero(hh > 1e-13 * hh.max())
        else:
            active = np.asarray(free, dtype=int)
        if active.size == 0:
            return h0
        u0 = np.log(np.clip(hh[active], 1e-300, None))

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            x = np.zeros(nn)
            x[active] = np.exp(uu)
            val, g = topk_fun_grad(x, K)
            return val, g[active] * x[active]

        cb = _make_cb(dl - 0.3)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           callback=cb,
                           options={'maxiter': iters, 'maxfun': 2 * iters,
                                    'ftol': 1e-20, 'gtol': 1e-16})
            x = np.zeros(nn)
            x[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(x)
        except TimeoutError:
            try:
                x = np.zeros(nn)
                x[active] = np.exp(np.clip(res.x, -30.0, 30.0))
                return _rescale_maxL(x)
            except Exception:
                return h0
        except Exception:
            return h0

    # Find peak location for windowing.
    Lf = _knots(best)
    peak = int(np.argmax(Lf))
    span = max(8, n // 6)
    lo0 = max(0, peak - span)
    hi0 = min(n - 1, peak + span)
    win = _window_free(n, lo0, hi0)

    # Stage 1: baseline single-max polish on the peak window.
    h = _exact_lbfgs(best, 2000, 4000, deadline, free=win)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Stage 2: continuation on top-k to flatten near-peak cluster.
    for K in (3, 6, 12):
        if time.process_time() >= deadline - 4.0:
            break
        h = lbfgs_topk(best, K, 800, deadline, free=win)
        # Re-tighten with true max.
        h = _exact_lbfgs(h, 600, 1200, deadline, free=win)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 3: widen the window progressively.
    for frac in (0.5, 0.8, 1.0):
        if time.process_time() >= deadline - 3.0:
            break
        extra = int(span * frac)
        lo = max(0, peak - span - extra)
        hi = min(n - 1, peak + span + extra)
        w = _window_free(n, lo, hi)
        h = lbfgs_topk(best, 4, 600, deadline, free=w)
        h = _exact_lbfgs(h, 800, 1600, deadline, free=w)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 4: full polish at current resolution if time remains.
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 5: resolution escalation downward (coarser but smoother) then
    # back up; coarse representation can escape the fine-grid peak locking.
    if time.process_time() < deadline - 3.0 and n > 8000:
        for fac in (2, 2):
            if time.process_time() >= deadline - 3.0:
                break
            m = max(1000, n // fac)
            hc = _rescale_maxL(_downsample(best, m))
            hc = _exact_lbfgs(hc, 1500, 3000, deadline)
            rc = R_of(hc)
            if rc > bestR:
                best, bestR = hc, rc
                n = best.size

    # Stage 6: final top-k continuation + true-max polish until deadline.
    Lf = _knots(best)
    peak = int(np.argmax(Lf))
    span = max(8, best.size // 6)
    w = _window_free(best.size, peak - span, peak + span)
    while time.process_time() < deadline - 1.0:
        h = lbfgs_topk(best, 6, 400, deadline, free=w)
        h = _exact_lbfgs(h, 400, 800, deadline, free=w)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        else:
            break

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _peak_region(h, thr_frac=0.999):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = thr_frac * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, thr_frac=0.999):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h, thr_frac)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _plateau_halfwidth(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1.0
    cnt = np.count_nonzero(Lf >= 0.99 * mx)
    return max(1.0, cnt / 2.0)


def _resample(h, N):
    """Mass-conserving resample of h to length N via cumulative mass."""
    n = h.size
    if n == N:
        return h.copy()
    if n <= 0:
        return np.ones(N)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.ones(N)
    edges = np.linspace(0.0, n, N + 1)
    idx = np.floor(edges).astype(int)
    frac = edges - idx
    idx = np.clip(idx, 0, n)
    F = cum[idx] + frac * np.where(idx < n, h[np.clip(idx, 0, n - 1)], 0.0)
    F = np.clip(F, 0, total)
    out = np.diff(F)
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage 0: top-K-mean max proxy ladder (helps reshape toward a flat max region).
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
    print("after K-ladder R=%.7f" % bestR)

    # Stage 1: full polish.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage 2: alternating full/window polish with multiple window widths.
    w0 = _plateau_halfwidth(best)
    print("plateau halfwidth w0=%.2f" % w0)
    thr_fracs = [0.999, 0.99, 0.95, 0.999]
    k = 0
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        tf = thr_fracs[k % len(thr_fracs)]
        h = _window_polish(best, deadline, thr_frac=tf,
                           extra=max(4, int(0.02 * w0)))
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window tf=%.3f R=%.7f" % (tf, bestR))
        k += 1

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

