    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _block_move(h, rng):
    """Swap two disjoint windows, or reverse one window."""
    n = h.size
    if n < 8:
        return h.copy()
    frac = np.exp(rng.uniform(np.log(0.02), np.log(0.15)))
    L = int(round(frac * n))
    L = max(2, min(L, n // 2))
    # choose start positions for two disjoint windows
    if 2 * L > n:
        L = n // 2
    a0 = int(rng.integers(0, n - 2 * L + 1))
    b0 = int(rng.integers(a0 + L, n - L + 1))
    h2 = h.copy()
    if rng.random() < 0.5:
        # swap
        h2[a0:a0 + L], h2[b0:b0 + L] = h[b0:b0 + L].copy(), h[a0:a0 + L].copy()
    else:
        # reverse one of the two windows
        if rng.random() < 0.5:
            h2[a0:a0 + L] = h[a0:a0 + L][::-1]
        else:
            h2[b0:b0 + L] = h[b0:b0 + L][::-1]
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # Stage 1: full polish at current resolution.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Stage 2 (experiment): block-rearrangement escape loop.
    tries = 0
    while time.process_time() < deadline - 1.5:
        h = _block_move(best, rng)
        h = _exact_lbfgs(h, 1200, 2400, deadline)
        if time.process_time() < deadline - 1.0:
            h = _window_polish(h, deadline, frac=0.20, extra=6, iters=800)
        r = R_of(h)
        tries += 1
        if r > bestR:
            best, bestR = h, r
            print(f"  block improvement R={bestR:.7f} after {tries} tries")

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size}) block_tries={tries}")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _exact_topk_lbfgs(h0, k, beta, maxiter, maxfun, deadline):
    """Exact-norm L-BFGS with top-K-mean surrogate for max, analytic grad."""
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        o, g = _topk_obj_grad(hh, k, beta)
        return o, g[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _peak_window_lbfgs(h0, shift, maxiter, maxfun, deadline):
    """L-BFGS restricted to a window around the argmax knot, shifted by `shift`."""
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    band = np.flatnonzero(Lf >= 0.99 * M)
    if band.size == 0:
        span = 2
    else:
        span = int(band[-1] - band[0])
    pad = 1 + span + 8
    lo = max(0, m - pad + shift)
    hi = min(h.size, m + pad + shift + 1)
    if hi <= lo:
        return h0
    free = np.arange(lo, hi)
    return _exact_lbfgs(h, maxiter, maxfun, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Step 1: exact K=1 L-BFGS on start.
    h = _exact_lbfgs(best, 3000, 6000, deadline)
    r = R_of(h)
    if r > bestR + 1e-15:
        best, bestR = h.copy(), r
        print("exact R=%.7f" % bestR)

    shifts = [0, 1, -1, 2, -2]
    rungs = [1, 2, 3, 4, 6, 8, 12]

    cycle = 0
    while time.process_time() < deadline - 4.0:
        cycle += 1
        any_improved = False
        for K in rungs:
            if time.process_time() >= deadline - 4.0:
                break
            hk = _exact_topk_lbfgs(best, K, 1e5, 1200, 2400, deadline)
            rk = R_of(hk)
            if rk > bestR + 1e-15:
                best, bestR = hk.copy(), rk
                any_improved = True
                print("cycle %d K=%d topk R=%.7f" % (cycle, K, bestR))
            for sh in shifts:
                if time.process_time() >= deadline - 4.0:
                    break
                hw = _peak_window_lbfgs(best, sh, 600, 1200, deadline)
                rw = R_of(hw)
                if rw > bestR + 1e-15:
                    best, bestR = hw.copy(), rw
                    any_improved = True
                    print("cycle %d K=%d shift %d win R=%.7f" % (cycle, K, sh, bestR))

        if cycle % 2 == 0:
            if time.process_time() >= deadline - 4.0:
                break
            he = _exact_lbfgs(best, 2000, 4000, deadline)
            re = R_of(he)
            if re > bestR + 1e-15:
                best, bestR = he.copy(), re
                any_improved = True
                print("cycle %d exact R=%.7f" % (cycle, bestR))

        if not any_improved:
            if time.process_time() >= deadline - 4.0:
                break
            hd = run_direct(best, 3e5, 400, 800, deadline)
            rd = R_of(hd)
            if rd > bestR + 1e-15:
                best, bestR = hd.copy(), rd
                print("cycle %d direct R=%.7f" % (cycle, bestR))
            else:
                break

    # Final exact polish.
    hard = t0 + budget_seconds - 0.5
    while time.process_time() < hard - 1.0:
        h2 = _exact_lbfgs(best, 5000, 10000, hard)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h, K=1):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    K = max(1, min(K, Lf.size))
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, K=1):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free, K=K)


def _shift_polish(h, deadline, shifts, iters=600):
    """Try window polish on shifted copies to escape; keep best."""
    best = h
    bestR = R_of(h)
    n = h.size
    for sh in shifts:
        if time.process_time() >= deadline - 0.5:
            break
        hs = np.roll(h, sh)
        hs2 = _window_polish(hs, deadline, iters=iters)
        r = R_of(hs2)
        if r > bestR:
            best, bestR = hs2, r
    return best


def _resample_cum(h, factor):
    """Mass-conserving upsample by factor using cumulative mass interpolation."""
    if factor <= 1:
        return h
    n = h.size
    m = n * factor
    c = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, n, m + 1)
    cs = np.interp(xs, np.arange(n + 1), c)
    g = np.diff(cs)
    # preserve total mass
    s0 = h.sum()
    s1 = g.sum()
    if s1 > 0:
        g *= s0 / s1
    return np.clip(g, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    def try_accept(h, tag):
        nonlocal best, bestR
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("%s R=%.7f" % (tag, bestR))
            return True
        return False

    # 3 cycles over K ladder [1,2,3,4,5,6,8,10]
    K_ladder = [1, 2, 3, 4, 5, 6, 8, 10]
    shifts = [0, 1, -1, 2, -2, 4, -4]

    for cycle in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        for K in K_ladder:
            if time.process_time() >= deadline - 1.0:
                break
            h = _exact_lbfgs(best, 1200, 2400, deadline, K=K)
            try_accept(h, "cyc%d K=%d" % (cycle + 1, K))
            # window polish with shifts
            for sh in shifts:
                if time.process_time() >= deadline - 1.0:
                    break
                hs = np.roll(best, sh)
                hp = _window_polish(hs, deadline, frac=0.3, iters=1000, K=K)
                try_accept(hp, "cyc%d K=%d sh=%d" % (cycle + 1, K, sh))
        # full exact K=1 after cycle
        if time.process_time() < deadline - 1.0:
            h = _exact_lbfgs(best, 2000, 4000, deadline, K=1)
            try_accept(h, "cyc%d full K=1" % (cycle + 1))

    # Final: 2x cumulative-mass upsample then full exact K=1 + window polish
    if time.process_time() < deadline - 1.0:
        hu = _resample_cum(best, 2)
        hu = _rescale_maxL(hu)
        h1 = _exact_lbfgs(hu, 2000, 4000, deadline, K=1)
        r1 = R_of(h1)
        if r1 > bestR + 1e-15:
            best, bestR = h1.copy(), r1
            print("upsample full K=1 R=%.7f (N=%d)" % (bestR, best.size))
            hp = _window_polish(best, deadline, frac=0.3, iters=1500, K=1)
            try_accept(hp, "upsample window")

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.5:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _refine_fine(h0, deadline, verbose=True):
    """Improve a fine-grid solution using direct softmax polish + stiff penalty."""
    best = h0.copy()
    bestR = R_of(best)

    def time_ok(margin=2.0):
        return time.process_time() < deadline - margin

    # Alternate between very stiff penalty (to enforce max region) and
    # direct softmax polish at increasing betas.
    betas = [100, 300, 1000, 3000, 10000]
    for beta in betas:
        if not time_ok(2.5):
            break
        h = run_direct(best, beta, 150, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h, r
            if verbose:
                print("refine direct beta=%d R=%.9f" % (beta, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.9f (N=%d)" % (bestR, best.size))

    # Primary path: aggressively polish the start at its native resolution,
    # then try the ZOH-doubled grid and polish that too.
    candidates = [best]

    # Native-resolution direct polish
    h = best.copy()
    for beta in [200, 1000, 5000, 20000]:
        if time.process_time() >= deadline - 3.0:
            break
        h2 = run_direct(h, beta, 200, 400, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-14:
            h, bestR = h2, r2
            print("native direct beta=%d R=%.9f" % (beta, bestR))
    candidates.append((h.copy(), bestR))

    # ZOH-doubled grid polish
    if base.size <= 100000 and time.process_time() < deadline - 6.0:
        h2 = np.repeat(base, 2)
        r2 = R_of(h2)
        print("doubled R=%.9f vs base R=%.9f (diff=%.2e)"
              % (r2, R_of(base), r2 - R_of(base)))
        if r2 >= R_of(base) - 1e-12:
            h3, r3 = _refine_fine(h2, deadline)
            candidates.append((h3, r3))
            if r3 > bestR + 1e-14:
                best, bestR = h3.copy(), r3

    # Pick best candidate
    for hc, rc in candidates:
        if rc > bestR + 1e-14:
            best, bestR = hc.copy(), rc

    # If time remains, run additional direct polish on the best
    while time.process_time() < deadline - 3.0:
        prev = bestR
        h = run_direct(best, 20000, 150, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h, r
            print("final direct R=%.9f" % bestR)
        if bestR - prev < 1e-12:
            break

    print("final R=%.9f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _pnorm_fun_grad(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None)
    Sp = np.sum(Lp ** p)
    if Sp <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf += (Lp ** (p - 1)) / Sp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 / p) * np.log(Sp)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun_grad, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    return _lbfgs(h0, _norm_eq_fun_grad, maxiter, maxfun, deadline, free)


def _pnorm_lbfgs(h0, p, maxiter, maxfun, deadline, free=None):
    return _lbfgs(h0, lambda hh: _pnorm_fun_grad(hh, p), maxiter, maxfun,
                  deadline, free)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _pnorm_homotopy(h, deadline, iters=300):
    p_ladder = (2, 4, 8, 16, 32, 64, 128)
    cur = h
    for p in p_ladder:
        if time.process_time() >= deadline - 1.0:
            break
        cur = _pnorm_lbfgs(cur, p, iters, 2 * iters, deadline)
    return cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(999)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)
    print(f"start R={bestR:.7f} N={best.size}")

    # Stage 1: full exact polish on start.
    h = _exact_lbfgs(best, 2000, 4000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r
        print(f"  S1 R={bestR:.7f}")

    # Stage 2: p-norm homotopy ladder to sharpen peak, then exact polish.
    if time.process_time() < deadline - 5.0:
        hh = _pnorm_homotopy(best, deadline, iters=400)
        hh = _exact_lbfgs(hh, 2000, 4000, deadline)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh, r
            print(f"  S2 R={bestR:.7f}")

    # Stage 3: resolution escalation with exact polish at each level.
    cur = best
    while cur.size < 200000 and time.process_time() < deadline - 8.0:
        factor = 2
        if cur.size * factor > 200000:
            break
        h_up = _resample_cum(cur, cur.size * factor)
        h_up = _rescale_maxL(h_up)
        h_up = _exact_lbfgs(h_up, 1500, 3000, deadline)
        r = R_of(h_up)
        if r > bestR:
            best, bestR = h_up, r
            cur = h_up
            print(f"  S3 N={best.size} R={bestR:.7f}")
        else:
            break

    # Stage 4: alternating shifted window polishes.
    shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8, -16, 16]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.20, extra=6,
                           iters=1200, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
            print(f"  S4[{si}] R={bestR:.7f}")
        if si % 3 == 0:
            h = _exact_lbfgs(best, 800, 1600, deadline)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        if si % 5 == 0 and time.process_time() < deadline - 6.0:
            for scale in (0.02, 0.05):
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1200, 2400, deadline)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp
                    print(f"  S4p R={bestR:.7f}")

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h, p=1.0):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


# ---------------- NEW: direct R maximisation via finite differences is
# too slow, so we use an exact-gradient ascent on R itself. ----------------

def _R_fun_grad_unnorm(h):
    """Returns (R, dR/dh) with normalization max L = 1 and sum h = 1 fixed
    handled implicitly by gradient of R (scale-invariant)."""
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if num <= 0 or Lm <= 0:
        return 0.0, np.zeros(h.size)
    R = num / (s * s * Lm)
    # dR/dh = dnum/(s^2 Lm) - num*(2s Lm ds + s^2 dLm)/(s^4 Lm^2)
    g_num = _backprop(dq, h) / (s * s * Lm)
    # dLm via backprop of a unit pulse at m
    gLf = np.zeros_like(Lf)
    gLf[m] = 1.0
    g_Lm = _backprop(gLf, h)
    g_den = (2.0 * s * Lm) / (s ** 4 * Lm ** 2) * num
    term_ds = -g_den * np.ones(h.size)
    term_dLm = -(num / (s * s * Lm * Lm)) * g_Lm
    return R, g_num + term_ds + term_dLm


def _R_ascend(h0, deadline, iters, free=None, lr=1e-3):
    """Projected gradient ascent on R directly (scale invariant)."""
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        active = np.arange(n)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x = h.copy()
    best = x.copy()
    bestR = R_of(best)
    step = lr
    for it in range(iters):
        if time.process_time() >= deadline - 0.4:
            break
        R, g = _R_fun_grad_unnorm(x)
        if R > bestR:
            bestR = R
            best = x.copy()
        gn = np.zeros(n)
        gn[active] = g[active]
        gnorm = np.linalg.norm(gn)
        if gnorm <= 0:
            break
        # normalise step by max abs height for stability
        x = x + step * gn / gnorm * x.max()
        x = np.clip(x, 0, None)
        if x.sum() <= 0:
            x = best.copy()
            step *= 0.5
        # occasionally shrink step
        if it % 50 == 49:
            step *= 0.9
    R = R_of(x)
    if R > bestR:
        best = x
    return _rescale_maxL(best)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # Stage A: refine the start with a full log-coordinate polish (K=1).
    h = _exact_lbfgs(best, 3000, 6000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Stage B: NEW - direct R ascent on full vector (small number of iters,
    # but each call is cheap because it's just gradient evaluation).
    h = _R_ascend(best, deadline, iters=4000, lr=2e-2)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Stage C: windowed polish on the peak region.
    if time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline, frac=0.30, extra=8, iters=1500)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage D: top-K soft-max flattening.
    for K in (3, 5):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(best, 1200, 2400, deadline, K=K)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage E: alternate shifted window polishes + R ascent on window.
    shifts = [0, -1, 1, -2, 2]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.20, extra=6,
                           iters=1000, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 2 == 0 and time.process_time() < deadline - 4.0:
            # R ascent on the peak window
            lo, hi = _peak_region(best)
            span = hi - lo
            pad = max(6, int(span * 0.25))
            lo = max(0, lo - pad)
            hi = min(best.size - 1, hi + pad)
            free = np.arange(lo, hi + 1)
            h2 = _R_ascend(best, deadline, iters=1500, free=free, lr=1e-2)
            r2 = R_of(h2)
            if r2 > bestR:
                best, bestR = h2, r2

    # Final full polish.
    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _topk_obj_grad(h, k, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    kk = min(k, n)
    idx = np.argpartition(Lf, n - kk)[n - kk:]
    top = Lf[idx]
    mx = top.max()
    e = np.exp(np.clip(beta * (top - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = np.zeros(n)
    w[idx] = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def run_topk(h0, k, maxiter, maxfun, deadline, beta=1e5):
    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _topk_obj_grad(xc, k, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _exact_topk_lbfgs(h0, k, beta, maxiter, maxfun, deadline):
    """Exact-norm L-BFGS with top-K-mean surrogate for max, analytic grad.
    Small maxiter, deadline-checked via callback; returns last iterate."""
    if time.process_time() >= deadline:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    state = {'last': None, 'stop': False}

    def f(u):
        if state['stop'] or time.process_time() >= deadline:
            state['stop'] = True
            # Return current value/grad but signal stop via callback
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            state['last'] = hh.copy()
            o, g = _topk_obj_grad(hh, k, beta)
            return o, g[active] * hh[active]
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        state['last'] = hh.copy()
        o, g = _topk_obj_grad(hh, k, beta)
        return o, g[active] * hh[active]

    def cb(xk):
        if time.process_time() >= deadline:
            state['stop'] = True
            raise StopIteration

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except StopIteration:
        if state['last'] is not None:
            return _rescale_maxL(state['last'])
        return h0
    except Exception:
        if state['last'] is not None:
            return _rescale_maxL(state['last'])
        return h0


def _peak_window_lbfgs(h0, shift, maxiter, maxfun, deadline):
    """L-BFGS restricted to a window around the argmax knot, shifted by `shift`.
    Small maxiter, deadline-checked; returns last iterate."""
    if time.process_time() >= deadline:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    band = np.flatnonzero(Lf >= 0.99 * M)
    if band.size == 0:
        span = 2
    else:
        span = int(band[-1] - band[0])
    pad = 1 + span + 8
    lo = max(0, m - pad + shift)
    hi = min(h.size, m + pad + shift + 1)
    if hi <= lo:
        return h0
    free = np.arange(lo, hi)
    return _exact_lbfgs(h, maxiter, maxfun, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 6.0

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Step 1: exact K=1 L-BFGS on start (small maxiter).
    if time.process_time() < deadline:
        h = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("exact R=%.7f" % bestR)

    shifts = [0, 1, -1, 2, -2]
    rungs = [1, 2, 3, 4, 5, 6, 8, 12]

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        any_improved = False
        for K in rungs:
            if time.process_time() >= deadline:
                break
            hk = _exact_topk_lbfgs(best, K, 1e5, 250, 500, deadline)
            rk = R_of(hk)
            if rk > bestR + 1e-15:
                best, bestR = hk.copy(), rk
                any_improved = True
                print("cycle %d K=%d topk R=%.7f" % (cycle, K, bestR))
            for sh in shifts:
                if time.process_time() >= deadline:
                    break
                hw = _peak_window_lbfgs(best, sh, 200, 400, deadline)
                rw = R_of(hw)
                if rw > bestR + 1e-15:
                    best, bestR = hw.copy(), rw
                    any_improved = True
                    print("cycle %d K=%d shift %d win R=%.7f" % (cycle, K, sh, bestR))

        if cycle % 2 == 0:
            if time.process_time() >= deadline:
                break
            he = _exact_lbfgs(best, 800, 1600, deadline)
            re = R_of(he)
            if re > bestR + 1e-15:
                best, bestR = he.copy(), re
                any_improved = True
                print("cycle %d exact R=%.7f" % (cycle, bestR))

        if not any_improved:
            break

    # Final exact polish.
    hard = t0 + budget_seconds - 1.5
    if time.process_time() < hard:
        h2 = _exact_lbfgs(best, 1500, 3000, hard)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
