    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _binomial_h(N, alpha):
    h = np.empty(N)
    h[0] = 1.0
    # h[k] = h[k-1] * (k-1+alpha)/k
    for k in range(1, N):
        h[k] = h[k - 1] * (k - 1 + alpha) / k
        if not np.isfinite(h[k]) or h[k] > 1e250:
            h[k:] = h[k - 1]
            break
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    # Candidate pool
    best = None
    bestR = -1.0
    best_desc = None

    # Start as a candidate
    if start is not None and np.asarray(start).size > 0:
        hs = np.clip(np.asarray(start, dtype=float), 0, None)
        if hs.sum() > 0:
            rs = R_of(hs)
            if rs > bestR:
                best, bestR, best_desc = hs, rs, ("start", hs.size, None)

    # Analytic binomial family scan
    Ns = [42496, 65000, 90000, 130000, 180000, 200000]
    alphas = np.linspace(0.35, 0.65, 13)
    for N in Ns:
        if time.process_time() >= deadline - 8.0:
            break
        for alpha in alphas:
            if time.process_time() >= deadline - 8.0:
                break
            h = _binomial_h(N, float(alpha))
            if h.sum() <= 0:
                continue
            r = R_of(h)
            if r > bestR:
                best, bestR, best_desc = h, r, ("binom", N, float(alpha))

    if best is None:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        best = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        best = _rescale_maxL(best)
        bestR = R_of(best)
        best_desc = ("fallback", N, None)

    # Short full L-BFGS on best analytic candidate
    if time.process_time() < deadline - 6.0:
        h = _exact_lbfgs(best, 300, 600, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # One peak-window polish
    if time.process_time() < deadline - 4.0:
        h = _window_polish(best, deadline, frac=0.25, extra=6, iters=200)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # If time remains, do the base's proven escalation/polish loop
    if time.process_time() < deadline - 3.0:
        cur = best
        for factor in (2, 2):
            if time.process_time() >= deadline - 6.0:
                break
            if cur.size * factor > 200000:
                break
            h_up = _resample_cum(cur, cur.size * factor)
            h_up = _rescale_maxL(h_up)
            h_up = _exact_lbfgs(h_up, 1200, 2400, deadline)
            r = R_of(h_up)
            if r > bestR:
                best, bestR, cur = h_up, r, h_up
            else:
                cur = best

        shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8]
        si = 0
        while time.process_time() < deadline - 1.0:
            sh = shifts[si % len(shifts)]
            si += 1
            h = _window_polish(best, deadline, frac=0.20, extra=6,
                               iters=1200, shift=sh)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
            if si % 3 == 0:
                h = _exact_lbfgs(best, 800, 1600, deadline)
                r = R_of(h)
                if r > bestR:
                    best, bestR = h, r
            if si % 5 == 0 and time.process_time() < deadline - 6.0:
                for scale in (0.02, 0.05):
                    if time.process_time() >= deadline - 6.0:
                        break
                    hp = _local_perturb(best, rng, scale)
                    hp = _exact_lbfgs(hp, 1200, 2400, deadline)
                    rp = R_of(hp)
                    if rp > bestR:
                        best, bestR = hp, rp

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    if best_desc is not None:
        kind, N, alpha = best_desc
        if alpha is None:
            print(f"best R={bestR:.7f} N={N} alpha=None src={kind}")
        else:
            print(f"best R={bestR:.7f} N={N} alpha={alpha:.4f} src={kind}")
    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        return val, grad
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _log_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.4:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        active = np.flatnonzero(h > 1e-13 * h.max())
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _linear_lbfgs(h0, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.4:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        xx = np.clip(x, 0.0, None)
        val, g = _topk_fun_grad(xx, 1)
        return val, g

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        return _rescale_maxL(np.clip(res.x, 0, None))
    except TimeoutError:
        try:
            return _rescale_maxL(np.clip(res.x, 0, None))
        except Exception:
            return h0
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = base / base.max()

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Smooth-max objective (soft-max of top values) with decreasing temperature.
    # This bridges between max and mean-of-top, giving a smoother landscape
    # than directly optimizing against a single argmax knot.
    def run_K(h, K, maxiter, maxfun):
        if time.process_time() >= deadline - 0.5:
            return h, R_of(h)
        h2 = _log_lbfgs(h, maxiter, maxfun, deadline, K=K)
        r2 = R_of(h2)
        if r2 > R_of(h):
            return h2, r2
        return h, R_of(h)

    # Main loop: polish in log-coordinates with growing K (smooth max),
    # then finish with plain linear argmax L-BFGS.
    it = 0
    while time.process_time() < deadline - 0.6:
        it += 1
        h = best.copy()
        cur = bestR

        # Coarse-to-fine topk smoothing.
        for K in (1, 2, 4, 8, 16, 32, 64):
            if time.process_time() >= deadline - 0.6:
                break
            h, r = run_K(h, K, 400, 800)
            if r > cur:
                cur = r
                best, bestR = h.copy(), cur

        # Linear polish against single argmax.
        if time.process_time() < deadline - 0.6:
            h2 = _linear_lbfgs(best, 400, 800, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
                print("lin R=%.7f (N=%d)" % (bestR, best.size))

        # Log polish on free support.
        if time.process_time() < deadline - 0.6:
            h3 = _log_lbfgs(best, 600, 1200, deadline, K=1)
            r3 = R_of(h3)
            if r3 > bestR + 1e-13:
                best, bestR = h3, r3
                print("log R=%.7f (N=%d)" % (bestR, best.size))

        # If no gain, try a small perturbation and re-polish.
        if time.process_time() < deadline - 0.6 and it % 3 == 0:
            rng = np.random.default_rng(it)
            h2 = best.copy()
            nz = h2 > 1e-9 * h2.max()
            if np.any(nz):
                h2[nz] *= np.exp(1e-4 * rng.standard_normal(nz.sum()))
            h2 = _rescale_maxL(h2)
            h2 = _log_lbfgs(h2, 400, 800, deadline, K=1)
            r2 = R_of(h2)
            if r2 > bestR + 1e-13:
                best, bestR = h2, r2
                print("perturb R=%.7f (N=%d)" % (bestR, best.size))

        if time.process_time() >= deadline - 0.6:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _pnorm_fun_grad(h, p):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lp = np.clip(Lf, 0, None)
    Sp = np.sum(Lp ** p)
    if Sp <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf += (Lp ** (p - 1)) / Sp
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + (1.0 / p) * np.log(Sp)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _optimize(h0, maxiter, maxfun, deadline, free=None, fun_grad=None):
    if time.process_time() >= deadline - 0.5 or fun_grad is None:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    return _optimize(h0, maxiter, maxfun, deadline, free=free,
                     fun_grad=_norm_eq_fun_grad)


def _pnorm_lbfgs(h0, p, maxiter, maxfun, deadline, free=None):
    def fg(hh):
        return _pnorm_fun_grad(hh, p)
    return _optimize(h0, maxiter, maxfun, deadline, free=free, fun_grad=fg)


def _smooth(h, sigma):
    if sigma <= 0:
        return h.copy()
    r = int(np.ceil(3 * sigma))
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    hp = np.concatenate((h[r:0:-1], h, h[-2:-r-2:-1])) if r > 0 else h
    if hp.size < h.size + 2 * r:
        hp = np.concatenate((h[:r][::-1], h, h[-r:][::-1]))
    out = np.convolve(hp, k, mode='valid')
    if out.size != h.size:
        out = out[:h.size]
        if out.size < h.size:
            out = np.concatenate((out, h[out.size:]))
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: p-norm smoothing ladder on max proxy (escapes kinks).
    h = best.copy()
    for p in (16.0, 8.0, 4.0, 2.0, 1.0):
        if time.process_time() >= deadline - 1.0:
            break
        h = _pnorm_lbfgs(h, p, 400, 800, deadline)
        r = R_of(h)
        print("p=%.0f R=%.7f" % (p, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            h = best.copy()

    # Stage B: full exact polish.
    h = _exact_lbfgs(best, 2000, 4000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage C: adaptive basin hopping with shrinking perturbations.
    rng = np.random.default_rng(2024)
    n = best.size
    scale = 1.0
    tries = 0
    stall = 0
    while time.process_time() < deadline - 0.8:
        sig = max(1.5, n * 0.03 * scale * (0.5 + 0.5 * rng.random()))
        amp = (0.008 + 0.05 * rng.random()) * scale
        eps = rng.standard_normal(n) * amp
        eps = _smooth(eps, sig)
        h2 = best * np.exp(eps)
        h2 = _rescale_maxL(h2)
        h2 = _exact_lbfgs(h2, 800, 1600, deadline)
        r = R_of(h2)
        tries += 1
        if r > bestR + 1e-16:
            best, bestR = h2.copy(), r
            stall = 0
            scale = 1.0
            print("hop #%d R=%.7f sig=%.1f amp=%.3f" % (tries, bestR, sig, amp))
        else:
            stall += 1
            if stall % 3 == 0:
                scale *= 0.7
            if scale < 0.15:
                scale = 1.0

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

