        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _binomial_h(N, alpha):
    k = np.arange(1, N, dtype=float)
    logh = np.concatenate(([0.0], np.cumsum(np.log((k - 1 + alpha) / k))))
    logh = np.clip(logh, -700, 700)
    return np.exp(logh)


def _smooth_spline(h, factor=2):
    """Resample via cumulative-mass interpolation (smoother than plain binning)."""
    return _resample_cum(h, h.size * factor)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    best = None
    bestR = -1.0
    best_desc = None

    if start is not None and np.asarray(start).size > 0:
        hs = np.clip(np.asarray(start, dtype=float), 0, None)
        if hs.sum() > 0:
            rs = R_of(hs)
            if rs > bestR:
                best, bestR, best_desc = hs, rs, ("start", hs.size, None)

    # Analytic binomial family scan (cheap, only if no good start)
    if best is None or bestR < 0.93:
        Ns = [42496, 65000, 90000, 130000, 180000, 200000]
        alphas = np.linspace(0.35, 0.65, 13)
        for N in Ns:
            if time.process_time() >= deadline - 8.0:
                break
            for alpha in alphas:
                if time.process_time() >= deadline - 8.0:
                    break
                h = _binomial_h(N, float(alpha))
                if h.sum() <= 0:
                    continue
                r = R_of(h)
                if r > bestR:
                    best, bestR, best_desc = h, r, ("binom", N, float(alpha))

    if best is None:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        best = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        best = _rescale_maxL(best)
        bestR = R_of(best)
        best_desc = ("fallback", N, None)

    # KEY IMPROVEMENT: immediately polish the start with a targeted peak-window
    # L-BFGS.  The start is already near a local optimum; a full L-BFGS tends to
    # stall, but a peak-window refine on the max-knot region can nudge R up.
    if time.process_time() < deadline - 4.0:
        h = _window_polish(best, deadline, frac=0.30, extra=8, iters=2000)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        # Then a full L-BFGS as a follow-up.
        if time.process_time() < deadline - 3.0:
            h = _exact_lbfgs(best, 1500, 3000, deadline)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r

    # Escalation: upsample and refine.  Try higher resolution since start is
    # already at N=42496; the true optimum likely wants many more steps.
    cur = best
    for factor in (2, 2):
        if time.process_time() >= deadline - 6.0:
            break
        if cur.size * factor > 200000:
            break
        h_up = _smooth_spline(cur, factor)
        h_up = _rescale_maxL(h_up)
        h_up = _exact_lbfgs(h_up, 1500, 3000, deadline)
        r = R_of(h_up)
        if r > bestR:
            best, bestR, cur = h_up, r, h_up
        else:
            cur = best
        # Polish peak after upsampling.
        if time.process_time() < deadline - 4.0:
            h = _window_polish(best, deadline, frac=0.25, extra=6, iters=1500)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r

    # Main loop: alternating peak-window shifts, full L-BFGS, and perturbations.
    shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8, -16, 16]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.22, extra=6,
                           iters=1500, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0 and time.process_time() < deadline - 3.0:
            h = _exact_lbfgs(best, 1000, 2000, deadline)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        if si % 5 == 0 and time.process_time() < deadline - 5.0:
            for scale in (0.015, 0.04):
                if time.process_time() >= deadline - 5.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1200, 2400, deadline)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    if best_desc is not None:
        kind, N, alpha = best_desc
        if alpha is None:
            print(f"best R={bestR:.7f} N={N} alpha=None src={kind}")
        else:
            print(f"best R={bestR:.7f} N={N} alpha={alpha:.4f} src={kind}")
    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _family_shape(N, aL, aR, dL, dR, ratio, clip_frac, clip_level):
    j = np.arange(N)
    x = j / N
    y = 1.0 - x
    left = (x + dL) ** (-aL)
    right = (y + dR) ** (-aR)
    h = left + ratio * right
    if clip_frac > 0:
        mx = h.max()
        lvl = clip_level * mx
        thr = np.quantile(h, 1.0 - clip_frac)
        cut = max(lvl, thr)
        h = np.minimum(h, cut)
    return h


def _search_family(budget_deadline, rng):
    N = 1024
    n_samples = 1000
    results = []
    aL_grid = rng.uniform(0.30, 0.75, n_samples)
    aR_grid = rng.uniform(0.30, 0.75, n_samples)
    d_grid = 10.0 ** rng.uniform(-4, 0, (n_samples, 2))
    ratio_grid = np.exp(rng.uniform(np.log(0.05), np.log(20.0), n_samples))
    clip_frac_choices = np.array([0.0, 0.5, 0.8])
    clip_frac_grid = clip_frac_choices[rng.integers(0, 3, n_samples)]
    clip_level_grid = rng.uniform(0.05, 0.8, n_samples)
    for i in range(n_samples):
        if time.process_time() > budget_deadline:
            break
        h = _family_shape(N, aL_grid[i], aR_grid[i], d_grid[i, 0], d_grid[i, 1],
                          ratio_grid[i], clip_frac_grid[i], clip_level_grid[i])
        if h.sum() <= 0:
            continue
        r = R_of(h)
        results.append((r, i, h))
    results.sort(key=lambda t: -t[0])
    return results[:3]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # EXPERIMENT: asymmetric sum-of-two-singular-arcs family search.
    # Reserve up to ~35% of budget for the family exploration + refinement.
    fam_deadline = t0 + 0.35 * budget_seconds
    try:
        top = _search_family(fam_deadline, rng)
    except Exception:
        top = []

    for (r0, idx, hc) in top:
        if time.process_time() >= deadline - 2.0:
            break
        # Upsample to N=21248 then short L-BFGS
        h_up = _resample_cum(hc, 21248)
        h_up = _rescale_maxL(h_up)
        h_up = _exact_lbfgs(h_up, 500, 1000, deadline)
        r = R_of(h_up)
        if r <= bestR:
            # try next candidate
            continue
        # Upsample to N=42496 with 800-iter L-BFGS
        h_up2 = _resample_cum(h_up, 42496)
        h_up2 = _rescale_maxL(h_up2)
        h_up2 = _exact_lbfgs(h_up2, 800, 1600, deadline)
        r2 = R_of(h_up2)
        # One peak-window polish
        if time.process_time() < deadline - 1.0:
            h_up3 = _window_polish(h_up2, deadline, frac=0.25, extra=6, iters=800)
            r3 = R_of(h_up3)
            if r3 > r2:
                h_up2, r2 = h_up3, r3
        if r2 > bestR:
            best, bestR = h_up2, r2

    # Keep what the base does well: polish the current best.
    if time.process_time() < deadline - 3.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    if time.process_time() < deadline - 3.0:
        h = _window_polish(best, deadline, frac=0.30, extra=8, iters=1500)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Alternating shifted window polishes + perturbations (as base).
    shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.20, extra=6,
                           iters=1200, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0:
            h = _exact_lbfgs(best, 800, 1600, deadline)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        if si % 5 == 0 and time.process_time() < deadline - 6.0:
            for scale in (0.02, 0.05):
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1200, 2400, deadline)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

