def _full_polish(h, deadline, iters=2000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Padding experiment: extend support with exponential tails, re-optimise.
    # The true optimum likely has slowly-decaying tails beyond the current
    # support; padding lets L-BFGS discover them.
    for K in (1024, 4096):
        if time.process_time() >= deadline - 3.0:
            break
        n_old = best.size
        h_pad = np.concatenate((np.zeros(K), best, np.zeros(K)))
        tau = max(8.0, K / 50.0)
        j = np.arange(K)
        h_pad[:K] = best[0] * np.exp(-(K - j) / tau)
        h_pad[K + n_old:] = best[-1] * np.exp(-j / tau)
        h_pad = _rescale_maxL(h_pad)
        slice_deadline = min(deadline - 1.5,
                             time.process_time() + (deadline - time.process_time()) * 0.5)
        hp = _full_polish(h_pad, slice_deadline, iters=600)
        rp = R_of(hp)
        print("K=%d padded R=%.7f (N=%d)" % (K, rp, hp.size))
        if rp > bestR + 1e-12:
            best, bestR = hp.copy(), rp
            print("K=%d adopted R=%.7f" % (K, bestR))

    # Alternating full / window polish until deadline.
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0
    if res is None:
        return h0
    try:
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    bestR = -1.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float), 0, None)
        if s.size > 0 and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    if best is None:
        n0 = 2000
        c = (n0 - 1) / 2.0
        k = np.arange(n0, dtype=float)
        d = np.abs(k - c)
        h = 1.0 / np.sqrt(np.maximum(d * (c - d) + 1e-9, 1e-9))
        h = _rescale_maxL(np.clip(h, 0, None))
        best = h
        bestR = R_of(h)

    def consider(h):
        nonlocal best, bestR
        if h is None or h.size == 0:
            return False
        h = np.clip(h, 0, None)
        if h.sum() <= 0:
            return False
        r = R_of(h)
        if r > bestR + 1e-13:
            bestR = r
            best = h.copy()
            return True
        return False

    def budget_frac(f):
        return min(deadline, time.process_time() + f * budget_seconds)

    # Stage 1: window polish of start
    h = _window_polish(best, budget_frac(0.20), frac=0.25)
    consider(h)

    # Stage 2: full polish at current resolution
    h = _full_polish(best, budget_frac(0.25), iters=800)
    consider(h)

    # Stage 3: repeated upsample + window polish until ~200k or time out,
    # but keep polishing the existing best aggressively: the start is already
    # high resolution, so upsampling rarely helps — prefer polishing.
    while time.process_time() < deadline - budget_seconds * 0.20:
        n_cur = best.size
        if n_cur >= 200000:
            # continue polishing; try alternating window and full
            h = _window_polish(best, budget_frac(0.30), frac=0.30)
            if not consider(h):
                h = _full_polish(best, budget_frac(0.30), iters=400)
                if not consider(h):
                    break
            continue
        factor = 2
        if n_cur * factor > 200000:
            factor = max(1, 200000 // n_cur)
        if factor <= 1:
            break
        hu = _smooth_upsample(best, factor, sigma_cells=0.4)
        hu = _rescale_maxL(hu)
        consider(hu)
        if best.size <= 20000 or time.process_time() < deadline - budget_seconds * 0.35:
            hp = _window_polish(best, budget_frac(0.22), frac=0.30)
            consider(hp)
            hp = _full_polish(best, budget_frac(0.15), iters=400)
            consider(hp)
        if best.size <= n_cur:
            hu2 = _smooth_upsample(best, factor, sigma_cells=0.8)
            hu2 = _rescale_maxL(hu2)
            if not consider(hu2):
                # can't grow: just keep polishing to the end
                break

    # Stage 4: spend remaining time polishing best (window then full),
    # alternating until time runs out.
    while time.process_time() < deadline - 0.5:
        before = bestR
        h = _window_polish(best, min(deadline - 0.4,
                                     time.process_time() + budget_seconds * 0.30),
                           frac=0.30)
        consider(h)
        if time.process_time() >= deadline - 0.5:
            break
        h = _full_polish(best, min(deadline - 0.4,
                                   time.process_time() + budget_seconds * 0.30),
                         iters=600)
        consider(h)
        if bestR <= before + 1e-14:
            # no progress; try a slightly larger window polish
            h = _window_polish(best, min(deadline - 0.4,
                                         time.process_time() + budget_seconds * 0.30),
                               frac=0.60)
            consider(h)
            if bestR <= before + 1e-14:
                break

    if best is None:
        best = np.ones(100)
    return np.clip(np.asarray(best, dtype=float), 0, None)

