        h_up = _rescale_maxL(h_up)
        h_up = _exact_lbfgs(h_up, 1500, 3000, deadline)
        r = R_of(h_up)
        if r > bestR:
            best, bestR = h_up, r
        else:
            break

    # Window polishes at fine scale (peak region), alternating shifts.
    shifts = [0, -1, 1, -2, 2, -4, 4]
    si = 0
    while time.process_time() < deadline - 1.5:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.15, extra=4,
                           iters=1500, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 4 == 0 and time.process_time() < deadline - 6.0:
            hp = _local_perturb(best, rng, 0.01)
            hp = _window_polish(hp, deadline, frac=0.15, extra=4,
                                iters=1000, shift=0)
