def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.4:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _smooth_upsample(h, factor, sigma_cells=0.5):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    hi = np.interp(xo, np.arange(n), h)
    s = sigma_cells * factor
    if s > 0.5:
        rad = int(np.ceil(3 * s))
        x = np.arange(-rad, rad + 1, dtype=float)
        k = np.exp(-0.5 * (x / s) ** 2)
        k /= k.sum()
        hp = np.concatenate([np.zeros(rad), hi, np.zeros(rad)])
        hi = np.convolve(hp, k, mode='same')[rad:-rad]
    return np.clip(hi, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0

    best = None
    bestR = -1.0
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float), 0, None)
        if s.size > 0 and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    if best is None:
        n0 = 2000
        c = (n0 - 1) / 2.0
        k = np.arange(n0, dtype=float)
        d = np.abs(k - c)
        h = 1.0 / np.sqrt(np.maximum(d * (c - d) + 1e-9, 1e-9))
        best = _rescale_maxL(np.clip(h, 0, None))
        bestR = R_of(best)

    def consider(h):
        nonlocal best, bestR
        if h is None or h.size == 0:
            return False
        h = np.clip(h, 0, None)
        if h.sum() <= 0:
            return False
        r = R_of(h)
        if r > bestR + 1e-12:
            bestR = r
            best = h.copy()
            return True
        return False

    def bf(f):
        return min(deadline, time.process_time() + f * budget_seconds)

    # Focused iterative refinement at current resolution: alternate
    # window polish around the peak with full polish. This is the main
    # driver of gains when the start is already well-resolved.
    n_cur = best.size
    target_n = 200000
    # First, polish the start's peak region aggressively.
    for _ in range(2):
        if time.process_time() >= deadline - budget_seconds * 0.6:
            break
        consider(_window_polish(best, bf(0.12), frac=0.35, iters=1500))
        consider(_exact_lbfgs(best, 400, 800, bf(0.08)))

    # Grow resolution toward 200k, polishing at each stage.
    while time.process_time() < deadline - budget_seconds * 0.30:
        n_cur = best.size
        if n_cur >= target_n:
            break
        factor = max(1, target_n // n_cur)
        factor = min(factor, 8)
        if factor <= 1:
            break
        hu = _rescale_maxL(_smooth_upsample(best, factor, sigma_cells=0.5))
        grew = consider(hu)
        # Polish the upsampled version (window + a short full pass).
        consider(_window_polish(best, bf(0.10), frac=0.30, iters=800))
        if best.size <= 40000 or time.process_time() < deadline - budget_seconds * 0.45:
            consider(_exact_lbfgs(best, 300, 600, bf(0.08)))
        if not grew and best.size <= n_cur:
            break

    # Final sustained polishing: many window polish passes near the peak,
    # then a full pass, alternating until the deadline.
    while time.process_time() < deadline - 0.5:
        consider(_window_polish(best, deadline - 0.4, frac=0.30, iters=2000))
        if time.process_time() < deadline - 0.5:
            consider(_exact_lbfgs(best, 500, 1000, deadline - 0.4))
        else:
            break

    if best is None:
        best = np.ones(100)
    return np.clip(np.asarray(best, dtype=float), 0, None)

