# ---------- smoothed-knot machinery (Stage 1b) ----------

def _box_filter_apply(x, w):
    if w <= 1:
        return x.copy()
    n = x.size
    half = w // 2
    pad_l = half
    pad_r = w - 1 - half
    xp = np.concatenate((np.full(pad_l, x[0]), x, np.full(pad_r, x[-1])))
    c = np.concatenate(([0.0], np.cumsum(xp)))
    return (c[w:] - c[:-w]) / w


def _box_filter_adjoint(y, w):
    if w <= 1:
        return y.copy()
    n = y.size
    half = w // 2
    pad_l = half
    pad_r = w - 1 - half
    ones = np.ones(w) / w
    g_full = np.convolve(y, ones, mode='full')
    g = g_full[pad_l:pad_l + n].copy()
    if pad_l > 0:
        g[0] += g_full[:pad_l].sum()
    if pad_r > 0:
        g[-1] += g_full[pad_l + n:].sum()
    return g


def _smoothed_fun_grad(h, w):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lw = _box_filter_apply(Lf, w)
    a = Lw[:-1]; b = Lw[1:]
    num_w = np.sum(a * a + a * b + b * b) / 3.0
    if num_w <= 0:
        return 1e18, np.zeros(h.size)
    m = int(np.argmax(Lw))
    Lm = Lw[m]
    if Lm <= 0:
        return 1e18, np.zeros(h.size)
    dq_w = np.zeros_like(Lw)
    dq_w[:-1] += (2 * a + b)
    dq_w[1:] += (a + 2 * b)
    dq_w /= 3.0
    gLw = -dq_w / num_w
    gLw[m] += 1.0 / Lm
    gLf = _box_filter_adjoint(gLw, w)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num_w) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _stage1b(h, deadline, rungs=(64, 32, 16, 8, 4, 2, 1)):
    best = h.copy()
    bestR = R_of(best)
    for w in rungs:
        if time.process_time() >= deadline - 1.0:
            break
        def fg(hh, _w=w):
            return _smoothed_fun_grad(hh, _w)
        h = _exact_lbfgs(best, 300, 600, deadline, fun_grad=fg)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(best, 150, 300, deadline, K=1)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
    return best, bestR


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _window_polish_shift(h, deadline, shift, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)
    print(f"start R={bestR:.7f} (N={best.size})")

    # Stage 1: full exact polish with K=1.
    h = _exact_lbfgs(best, 4000, 8000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Stage 1b: smoothed-knot multi-scale polish.
    if time.process_time() < deadline - 2.0:
        h, r = _stage1b(best, deadline)
        if r > bestR:
            best, bestR = h, r

    # Stage 2: windowed polish on peak.
    if time.process_time() < deadline - 2.0:
        h = _window_polish(best, deadline, frac=0.30, extra=8, iters=2000)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 3: top-K soft-max flattening.
    for K in (3, 5, 8):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(best, 1500, 3000, deadline, K=K)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    # Stage 4: alternating shifted window polishes + perturbation restarts.
    shifts = [0, -1, 1, -2, 2, -4, 4]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish_shift(best, deadline, sh, frac=0.20, extra=6, iters=1500)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0:
            h = _exact_lbfgs(best, 800, 1600, deadline, K=1)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        if si % 5 == 0 and time.process_time() < deadline - 6.0:
            for scale in (0.02, 0.05):
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1500, 3000, deadline, K=1)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp

    # Stage 5: refinement at higher resolution (resample up, polish, keep if better).
    if time.process_time() < deadline - 2.0:
        n0 = best.size
        # try modest upsampling
        for fac in (2,):
            if time.process_time() >= deadline - 2.0:
                break
            n1 = min(200000, n0 * fac)
            if n1 <= n0:
                continue
            hu = _resample_cum(best, n1)
            hu = _exact_lbfgs(hu, 2000, 4000, deadline)
            ru = R_of(hu)
            if ru > bestR + 1e-9:
                best, bestR = hu, ru
            else:
                # try downsampling back polish in case upsample hurt
                hd = _resample_cum(best, n0)
                hd = _exact_lbfgs(hd, 1500, 3000, deadline)
                rd = R_of(hd)
                if rd > bestR:
                    best, bestR = hd, rd

    # Stage 6: fine windowed polish with small shifts around peak.
    if time.process_time() < deadline - 1.0:
        for extra in (2, 4, 8, 16):
            if time.process_time() >= deadline - 1.0:
                break
            h = _window_polish(best, deadline, frac=0.10, extra=extra, iters=2000)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r

    # Final full polish.
    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline, K=1)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_average(h, target):
    n = h.size
    if n <= target:
        return h.copy()
    factor = int(np.ceil(n / target))
    m = n // factor
    if m < 2:
        return h.copy()
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _warp(h, a):
    n = h.size
    if n < 2:
        return h.copy()
    a = np.asarray(a, dtype=float).ravel()
    if a.size < 8:
        a = np.concatenate([a, np.zeros(8 - a.size)])
    ys = np.empty(9)
    ys[0] = 0.0
    ys[8] = 1.0
    for i in range(1, 8):
        ys[i] = (i / 8.0) + 0.03 * np.tanh(a[i - 1])
    ys = np.sort(np.clip(ys, 0.0, 1.0))
    for i in range(1, 9):
        if ys[i] <= ys[i - 1]:
            ys[i] = ys[i - 1] + 1e-9
    ys[8] = 1.0

    csum = np.concatenate(([0.0], np.cumsum(h)))
    if csum[-1] <= 0:
        return h.copy()
    j = np.arange(n + 1, dtype=float)
    t = j / n
    y_t = np.interp(t, np.linspace(0.0, 1.0, 9), ys)
    u = np.clip(n * y_t, 0.0, n)
    mass_edges = np.interp(u, np.arange(n + 1, dtype=float), csum)
    newh = np.clip(np.diff(mass_edges), 0.0, None)
    return _rescale_maxL(newh)


def _warp_optimize(h, deadline, maxiter=300):
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    hc = _block_average(h, 4000)
    if hc.size < 16:
        return h, R_of(h)

    def negR(a):
        try:
            r = R_of(_warp(hc, a))
            return -r if np.isfinite(r) else 1.0
        except Exception:
            return 1.0

    a0 = np.zeros(8)
    try:
        res = minimize(negR, a0, method='Nelder-Mead',
                       options={'maxiter': maxiter, 'xatol': 1e-3, 'fatol': 1e-10})
        a_best = res.x
    except Exception:
        a_best = a0
    hw = _warp(h, a_best)
    return hw, R_of(hw)


def _anneal_peak(h, deadline, iters=400):
    """Randomly perturb the peak of f*f and accept improvements.

    This explores the flat directions of the max constraint that L-BFGS
    cannot move through: shifting mass between the several near-equal
    knots of the plateau can raise ||f*f||_2^2 without lowering the max.
    """
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    # knots within 0.5% of max form the plateau; vary the h-support around them
    idx = np.flatnonzero(Lf >= 0.995 * mx)
    if idx.size == 0:
        return h
    lo = max(0, idx.min() - 2)
    hi = min(n - 1, idx.max() + 1)
    lo = max(0, lo - (hi - lo) // 2)
    hi = min(n - 1, hi + (hi - lo) // 2)
    span = hi - lo + 1
    if span < 4:
        return h
    rng = np.random.default_rng(12345)
    cur = h.copy()
    curR = R_of(cur)
    best = cur.copy()
    bestR = curR
    sigma = 0.06
    step = 0
    while time.process_time() < deadline - 0.5 and step < iters:
        step += 1
        cand = cur.copy()
        # bump a random contiguous block inside the window
        bw = max(2, int(span * (0.02 + 0.1 * rng.random())))
        p = lo + int(rng.integers(0, max(1, span - bw)))
        amp = sigma * (rng.standard_normal() + 0.3)
        cand[p:p + bw] *= np.exp(amp)
        cand = _rescale_maxL(cand)
        r = R_of(cand)
        if r > curR + 1e-13:
            cur, curR = cand, r
            if r > bestR + 1e-13:
                best, bestR = cand.copy(), r
        elif rng.random() < 0.02:
            cur, curR = cand, r  # rare downhill to escape
        if step % 80 == 0:
            sigma *= 0.92
            if sigma < 0.005:
                sigma = 0.02
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Warp rounds (orthogonal to height perturbations).
    wr = 0
    while wr < 2 and time.process_time() < deadline - 6.0:
        hw, rw = _warp_optimize(best, deadline)
        if rw > bestR + 1e-12:
            hw = _full_polish(hw, deadline, iters=1500)
            r2 = R_of(hw)
            if time.process_time() < deadline - 3.0:
                hw3 = _window_polish(hw, deadline)
                r3 = R_of(hw3)
                if r3 > r2:
                    hw, r2 = hw3, r3
            if r2 > bestR + 1e-12:
                best, bestR = hw.copy(), r2
                print("warp(%d) R=%.7f" % (wr, bestR))
            else:
                print("warp(%d) no gain (raw %.7f)" % (wr, r2))
                break
        else:
            print("warp(%d) no gain (raw %.7f)" % (wr, rw))
            break
        wr += 1

    # Top-K mean max proxy ladder.
    h = best.copy()
    for K in (20, 10, 5, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide window R=%.7f" % bestR)
        else:
            stall = 0

    # Upsampling stage.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_upsample(best, factor))
        rc = R_of(cand)
        if rc >= bestR - 1e-6:
            h = _full_polish(cand, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            elif rc > bestR + 1e-15:
                best, bestR = cand.copy(), rc
                print("upsample(f=%d,raw) R=%.7f N=%d" % (factor, bestR, best.size))
        else:
            break

    # Simulated-annealing escape on the peak plateau (uses remaining budget).
    if time.process_time() < deadline - 1.0:
        h = _anneal_peak(best, deadline - 1.0, iters=600)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("anneal R=%.7f" % bestR)

    # Final alternating polish.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2 and time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("final wide R=%.7f" % bestR)
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
