import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_grad(h):
    s = h.sum()
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    return grad


def _norm_eq_fun(h):
    s = h.sum()
    if s <= 0:
        return 1e18
    num, dq, Lf = _num_and_dq(h)
    return -np.log(num) + 2.0 * np.log(s) + np.log(Lf.max())


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val = _norm_eq_fun(hh)
        g = _norm_eq_grad(hh)[active] * hh[active]
        return val, g

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _kth_lbfgs(h0, k, maxiter, deadline):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(active.size)
        num, dq, Lf = _num_and_dq(hh)
        nn = Lf.size
        kk = min(k, nn)
        idx = np.argpartition(Lf, nn - kk)[nn - kk:]
        m = idx[np.argmin(Lf[idx])]
        Lm = Lf[m]
        if Lm <= 0:
            return 1e18, np.zeros(active.size)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        grad = _backprop(gLf, hh) + 2.0 / s
        return val, grad[active] * hh[active]

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 2,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except Exception:
        return h0


def _window_polish(h0, deadline, frac=0.25, extra=8, iters=900, shift=0):
    if time.process_time() >= deadline - 1.0:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    M = Lf[m]
    band = np.flatnonzero(Lf >= 0.99 * M)
    if band.size == 0:
        span = 2
    else:
        span = int(band[-1] - band[0])
    pad = 1 + span + extra
    lo = max(0, m - pad + shift)
    hi = min(h.size, m + pad + shift + 1)
    if hi <= lo:
        return h0
    free = np.arange(lo, hi)
    return _exact_lbfgs(h, iters, iters * 2, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.5

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    def try_accept(h, tag):
        nonlocal best, bestR
        r = R_of(h)
        if r > bestR + 1e-12:
            best = h.copy()
            bestR = r
            print("%s R=%.7f" % (tag, bestR))
            return True
        return False

    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        try_accept(h, "init exact")

    cycle = 0
    while time.process_time() < deadline - 1.5:
        k = 2 + (cycle % 5)
        if time.process_time() >= deadline - 1.5:
            break
        hk = _kth_lbfgs(best, k, 1500, deadline)
        if time.process_time() >= deadline - 1.5:
            break
        hk = _exact_lbfgs(hk, 1200, 2400, deadline)
        if time.process_time() >= deadline - 1.5:
            break
        hk = _window_polish(hk, deadline, frac=0.25, extra=8, iters=900,
                            shift=(cycle % 5) - 2)
        try_accept(hk, "k=%d" % k)

        if cycle % 3 == 2 and time.process_time() < deadline - 1.5:
            he = _exact_lbfgs(best, 1000, 2000, deadline)
            try_accept(he, "full exact")

        cycle += 1

    if time.process_time() < deadline - 1.0:
        hf = _exact_lbfgs(best, 2500, 5000, deadline)
        try_accept(hf, "final exact")

    if R_of(base) > bestR:
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

