def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _floor(h, f):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    m = h.mean()
    if m <= 0:
        return h
    return h + f * m * (h <= 0)


def _prune(h, eps):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    mx = h.max()
    if mx <= 0:
        return h
    h2 = np.where(h <= eps * mx, 0.0, h)
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.5
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    floors = (1e-5, 3e-5, 1e-4, 3e-4, 1e-3, 3e-3, 1e-2)
    prunes = (1e-7, 1e-6, 1e-5, 1e-4, 3e-4)

    def try_candidate(hh, tag):
        nonlocal best, bestR
        if time.process_time() >= deadline - 1.5:
            return False
        hh = _exact_lbfgs(hh, 1200, 2400, deadline)
        if time.process_time() < deadline - 1.0:
            hh = _window_polish(hh, deadline, frac=0.25, extra=8, iters=800)
        r = R_of(hh)
        if r > bestR + 1e-12:
            best, bestR = hh, r
            print(f"gain {tag} R={bestR:.7f}")
            return True
        return False

    def sweep():
        gained = False
        for f in floors:
            if time.process_time() >= deadline - 1.5:
                return gained
            hh = _floor(best, f)
            if try_candidate(hh, f"floor={f:g}"):
                gained = True
        for eps in prunes:
            if time.process_time() >= deadline - 1.5:
                return gained
            hh = _prune(best, eps)
            if try_candidate(hh, f"prune={eps:g}"):
                gained = True
        return gained

    while time.process_time() < deadline - 1.5:
        if sweep():
            continue
        # No gain in a full sweep: perturb small/zero cells and retry.
        if time.process_time() >= deadline - 1.5:
            break
        hp = best.copy()
        mx = hp.max()
        if mx <= 0:
            break
        mask = hp < 1e-3 * mx
        if not np.any(mask):
            break
        noise = rng.standard_normal(hp.size)
        k = max(3, hp.size // 200)
        kern = np.ones(k) / k
        noise = np.convolve(noise, kern, mode='same')
        hp[mask] = hp[mask] * np.exp(1e-3 * noise[mask])
        hp = _rescale_maxL(hp)
        hh = _exact_lbfgs(hp, 1200, 2400, deadline)
        r = R_of(hh)
        if r > bestR + 1e-12:
            best, bestR = hh, r
            print(f"gain noise R={bestR:.7f}")

    if time.process_time() < deadline - 0.5:
        hh = _exact_lbfgs(best, 2500, 5000, deadline)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

