    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    e = np.exp(np.clip(beta * (Lf - mx), -50, 0))
    Z = e.sum()
    logM = mx + np.log(Z) / beta
    w = e / Z
    obj = -np.log(num) + 2.0 * np.log(s) + logM
    gLf = -dq / num + w
    grad = _backprop(gLf, h)
    grad += 2.0 / s
    return obj, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0

    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_avg(h, k):
    n = (h.size // k) * k
    return h[:n].reshape(-1, k).sum(1)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.15, extra=6, iters=2000):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _coarse_escape(best, bestR, deadline):
    if time.process_time() >= deadline - 1.5:
        return best, bestR
    try:
        hc = _block_avg(best, 2)
        for beta in [500, 3000, 20000]:
            if time.process_time() >= deadline - 1.5:
                break
            hc = run_direct(hc, beta, 800, 1600, deadline)
            hc = _exact_lbfgs(hc, 400, 800, deadline)
        hb = np.repeat(hc, 2)
        if hb.size != best.size:
            xo = np.linspace(0.0, hb.size - 1, best.size)
            hb = np.interp(xo, np.arange(hb.size), hb)
        hb = _rescale_maxL(hb)
        hb = _exact_lbfgs(hb, 600, 1200, deadline)
        for beta in [1e5, 5e5]:
            if time.process_time() >= deadline - 1.5:
                break
            hb = run_direct(hb, beta, 800, 1600, deadline)
        r = R_of(hb)
        if r > bestR + 1e-12:
            print("coarse escape R=%.7f (N=%d)" % (r, hb.size))
            return hb, r
    except Exception:
        pass
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.8

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    if best.size < 100000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR + 1e-9:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    betas = [1e5, 3e5, 1e6, 3e6, 1e7]
    cycle = 0
    coarse_count = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        any_improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.0:
                break
            h = run_direct(best, beta, 800, 1600, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                any_improved = True
            if time.process_time() >= deadline - 1.0:
                break
            # Peak-window polish: focus compute where the max lives.
            h2 = _window_polish(best, deadline)
            r2 = R_of(h2)
            if r2 > bestR + 1e-15:
                best, bestR = h2.copy(), r2
                any_improved = True
                print("cycle %d window R=%.7f" % (cycle, bestR))
        if not any_improved:
            if coarse_count < 2:
                coarse_count += 1
                best, bestR = _coarse_escape(best, bestR, deadline)
                if time.process_time() < deadline - 1.0:
                    continue
            # Stall: do windowed polish sweeps.
            while time.process_time() < deadline - 1.0:
                h2 = _window_polish(best, deadline)
                r2 = R_of(h2)
                if r2 > bestR + 1e-16:
                    best, bestR = h2.copy(), r2
                    print("polish R=%.7f" % bestR)
                else:
                    break

    # Final exact polish, alternating full and windowed.
    while time.process_time() < deadline - 0.3:
        h2 = _exact_lbfgs(best, 3000, 6000, deadline)
        r2 = R_of(h2)
        if r2 > bestR + 1e-16:
            best, bestR = h2.copy(), r2
            print("final polish R=%.7f" % bestR)
        else:
            h3 = _window_polish(best, deadline)
            r3 = R_of(h3)
            if r3 > bestR + 1e-16:
                best, bestR = h3.copy(), r3
                print("final window R=%.7f" % bestR)
            else:
                break

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


# ---------- signed-f machinery (new experiment) ----------

def _signed_obj_grad(x):
    num, dq, Lf = _num_and_dq(x)
    s = x.sum()
    if abs(s) < 1e-9:
        return 1e18, np.zeros(x.size)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(x.size)
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / mx
    grad = _backprop(gLf, x) + 2.0 * np.sign(s) / abs(s)
    obj = -np.log(num) + 2.0 * np.log(abs(s)) + np.log(mx)
    return obj, grad


def _signed_lbfgs(x0, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return x0
    A = 4.0 * float(np.max(np.abs(x0))) + 1e-12
    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(_signed_obj_grad, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-A, A)] * x0.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        return res.x
    except TimeoutError:
        try:
            return res.x
        except Exception:
            return x0
    except Exception:
        return x0


def _signed_R(x):
    s = x.sum()
    if abs(s) < 1e-12:
        return 0.0
    Lf = _knots(x)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return num / (s * s * mx)


def _flat_band_width(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1
    idx = np.flatnonzero(Lf >= 0.99 * mx)
    if idx.size < 2:
        return 1
    return max(1, int(idx.max() - idx.min()))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # Build signed seeds from start.
    s0 = np.asarray(best, dtype=float)
    d = _flat_band_width(s0)
    seeds = []
    seeds.append(s0.copy())
    seeds.append(s0 - np.roll(s0, d))
    seeds.append(2.0 * s0 - np.roll(s0, d) - np.roll(s0, -d))
    # extra: a couple of shifted variants for diversity
    seeds.append(s0 - np.roll(s0, -d))
    seeds.append(s0 - np.roll(s0, max(1, d // 2)))

    def project_and_polish(x):
        nonlocal best, bestR
        cands = []
        cands.append(np.clip(x, 0, None))
        cands.append(np.abs(x))
        shift = 0.5 * max(0.0, -float(x.min()))
        cands.append(np.clip(x + shift, 0, None))
        for xp in cands:
            if time.process_time() >= deadline - 1.0:
                return
            xp = _rescale_maxL(xp)
            if xp.sum() <= 0:
                continue
            xp = _exact_lbfgs(xp, 2500, 5000, deadline)
            r = R_of(xp)
            if r > bestR:
                best, bestR = xp.copy(), r
            if time.process_time() >= deadline - 1.0:
                return
            xp = _window_polish(xp, deadline, frac=0.30, extra=8, iters=1500)
            r = R_of(xp)
            if r > bestR:
                best, bestR = xp.copy(), r
            if time.process_time() >= deadline - 1.0:
                return
            xp = _exact_lbfgs(xp, 1500, 3000, deadline)
            r = R_of(xp)
            if r > bestR:
                best, bestR = xp.copy(), r

    si = 0
    while time.process_time() < deadline - 1.0:
        seed = seeds[si % len(seeds)].copy()
        si += 1
        # small random perturbation of the seed for diversity on later rounds
        if si > len(seeds):
            seed = seed + 0.05 * np.max(np.abs(seed)) * rng.standard_normal(seed.size)
        xs = _signed_lbfgs(seed, 2500, deadline)
        rs = _signed_R(xs)
        print(f"signed seed {si} R_signed={rs:.6f}")
        if time.process_time() >= deadline - 1.0:
            break
        project_and_polish(xs)
        if si > 3 * len(seeds):
            break

    if time.process_time() < deadline - 0.5:
        hh = _exact_lbfgs(best, 2500, 5000, deadline)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

