    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _taper_free_set(h, M, lo_frac=0.001, hi_frac=0.995):
    """Indices k (original cells) whose knot pair straddles the taper band."""
    Lf = _knots(h)
    n = h.size
    # knot j corresponds to boundary between cells j-1 and j; Lf has n+1 entries
    # (indices 0..n). Cell k has knots k and k+1.
    lo_thr = lo_frac * M
    hi_thr = hi_frac * M
    in_band = (Lf > lo_thr) & (Lf < hi_thr)
    # free cell k if either of its knots is in band
    free_cells = []
    for k in range(n):
        if in_band[k] or in_band[k + 1]:
            free_cells.append(k)
    return np.array(free_cells, dtype=int)


def _refine_taper(h, deadline, iters=3000):
    """Split all cells in two (mass conserved), freeze flat region, polish taper."""
    if time.process_time() >= deadline - 1.0:
        return h, False
    n = h.size
    if 2 * n > 200000:
        return h, False
    M = _knots(h).max()
    if M <= 0:
        return h, False
    # frozen cells: knots 2k, 2k+1, 2k+2 all in band (>=0.995*M)
    Lf = _knots(h)
    band_thr = 0.995 * M
    frozen = np.zeros(n, dtype=bool)
    for k in range(n):
        if Lf[k] >= band_thr and Lf[k + 1] >= band_thr and Lf[k + 2] >= band_thr:
            frozen[k] = True
    h2 = np.repeat(h, 2) / 2.0
    r_orig = R_of(h)
    r_new = R_of(h2)
    if abs(r_new - r_orig) > 1e-9:
        # fall back, shouldn't happen
        return h, False
    # free refined indices: 2k and 2k+1 where k not frozen
    free = []
    for k in range(n):
        if not frozen[k]:
            free.append(2 * k)
            free.append(2 * k + 1)
    free = np.array(free, dtype=int)
    if free.size == 0:
        return h, False
    h2p = _exact_lbfgs(h2, iters, 2 * iters, deadline, free=free)
    r2 = R_of(h2p)
    if r2 > r_orig:
        return h2p, True
    return h, False


def _taper_window_polish(h, deadline, shift=0, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    M = _knots(h).max()
    if M <= 0:
        return h
    Lf = _knots(h)
    lo_thr = 0.001 * M
    hi_thr = 0.995 * M
    in_band = (Lf > lo_thr) & (Lf < hi_thr)
    idx = np.flatnonzero(in_band)
    if idx.size == 0:
        return h
    # free cells adjacent to band knots
    free_cells = set()
    for j in idx:
        for k in (j - 1, j):
            if 0 <= k < n:
                free_cells.add(k)
    free = np.array(sorted(free_cells), dtype=int)
    if shift != 0:
        free = np.clip(free + shift, 0, n - 1)
        free = np.unique(free)
    if free.size == 0:
        return h
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


