    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad) + shift
    hi = min(n - 1, hi + pad) + shift
    lo = max(0, min(n - 1, lo))
    hi = max(0, min(n - 1, hi))
    if hi < lo:
        lo, hi = 0, n - 1
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_average(h, target):
    n = h.size
    if n <= target:
        return h.copy()
    factor = int(np.ceil(n / target))
    m = n // factor
    if m < 2:
        return h.copy()
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    h = best.copy()
    c = 0
    Ks = [1, 2, 3, 4, 6, 8, 12]
    while time.process_time() < deadline - 1.0:
        # Multi-cycle small-K ladder
        for K in Ks:
            if time.process_time() >= deadline - 1.0:
                break
            h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("cycle %d ladder R=%.7f" % (c, bestR))
        else:
            h = best.copy()

        # Shift-cycled peak window polish
        if time.process_time() < deadline - 1.0:
            n = h.size
            lo, hi = _peak_region(h)
            span = hi - lo
            shift = int(0.10 * span * c)
            h = _window_polish(h, deadline, frac=0.15, extra=4, shift=shift)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("cycle %d window R=%.7f" % (c, bestR))
            else:
                h = best.copy()

        # Exact K=1 polish
        if time.process_time() < deadline - 1.0:
            h = _exact_lbfgs(h, 300, 600, deadline, K=1)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("cycle %d K1 R=%.7f" % (c, bestR))
            else:
                h = best.copy()

        # Every third cycle: upsample refine
        if c % 3 == 2 and time.process_time() < deadline - 2.0:
            n = best.size
            if n * 2 <= 200000:
                cand = _rescale_maxL(_upsample(best, 2))
                cand = _exact_lbfgs(cand, 800, 1600, deadline, K=1)
                rc = R_of(cand)
                if rc >= bestR - 1e-12:
                    back = _block_average(cand, n)
                    back = _rescale_maxL(back)
                    rb = R_of(back)
                    if rb > bestR + 1e-15:
                        best, bestR = back, rb
                        print("cycle %d upsample R=%.7f" % (c, bestR))
                    elif rc > bestR + 1e-15:
                        best, bestR = cand, rc
                        print("cycle %d upsample(full) R=%.7f" % (c, bestR))
                h = best.copy()

        c += 1

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def _block_average(h, M):
    n = h.size
    if n == M:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0, n, M + 1)
    co = np.interp(edges, np.arange(n + 1), c)
    return np.clip(np.diff(co), 0, None)


def _sqrt_deconv(g2):
    """Invert g2 = h*h for non-negative h via positive square-root recursion."""
    n = g2.size
    h2 = np.zeros(n)
    if n == 0:
        return h2
    v = float(g2[0])
    if v <= 0:
        return h2
    h2[0] = np.sqrt(v)
    for k in range(1, n):
        if h2[0] <= 0:
            break
        # dot(h2[1:k], h2[k-1:0:-1])
        if k > 1:
            d = float(np.dot(h2[1:k], h2[k - 1:0:-1]))
        else:
            d = 0.0
        h2[k] = (g2[k] - 2.0 * d) / (2.0 * h2[0])
    return np.clip(h2, 0, None)


def _gspace_reshape(hc, p):
    g = np.convolve(hc, hc)
    Mx = g.max()
    if Mx <= 0:
        return hc.copy()
    g2 = Mx * np.power(np.clip(g / Mx, 0, None), p)
    s_g = g.sum()
    s_g2 = g2.sum()
    if s_g2 <= 0:
        return hc.copy()
    g2 *= s_g / s_g2
    h2 = _sqrt_deconv(g2)
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.85 * budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # g-space reshaping experiment
    M = 2048
    hc = _block_average(best, M)
    hc = _rescale_maxL(hc)

    ladder = [4096, 8192, 16384, 32768, 42496]

    def polish_candidate(hcand, slice_deadline):
        hcur = hcand
        for n_out in ladder:
            if time.process_time() >= slice_deadline - 0.5:
                break
            hup = _resample_cum(hcur, n_out)
            hup = _rescale_maxL(hup)
            hup = _exact_lbfgs(hup, 400, 800, slice_deadline)
            r = R_of(hup)
            if r >= R_of(hcur) - 1e-9:
                hcur = hup
            else:
                hcur = hup  # still continue ladder from polished
        return hcur

    ps = [0.92, 0.85, 0.70]
    for i, p in enumerate(ps):
        if time.process_time() >= deadline - 2.0:
            break
        # time slice for this p
        remaining = deadline - time.process_time()
        slice_deadline = time.process_time() + remaining / (len(ps) - i)
        hcand = _gspace_reshape(hc, p)
        hcand = polish_candidate(hcand, slice_deadline)
        r = R_of(hcand)
        if r > bestR:
            best, bestR = hcand, r

        # alternate window polish / full polish on this candidate
        cur = hcand
        while time.process_time() < slice_deadline - 1.0:
            hw = _window_polish(cur, slice_deadline, frac=0.20, extra=6, iters=800)
            rw = R_of(hw)
            if rw > bestR:
                best, bestR = hw, rw
            cur = hw
            if time.process_time() >= slice_deadline - 1.0:
                break
            hf = _exact_lbfgs(cur, 400, 800, slice_deadline)
            rf = R_of(hf)
            if rf > bestR:
                best, bestR = hf, rf
            cur = hf

    # If time remains, continue polishing the global best
    while time.process_time() < deadline - 1.0:
        hw = _window_polish(best, deadline, frac=0.20, extra=6, iters=800)
        rw = R_of(hw)
        if rw > bestR:
            best, bestR = hw, rw
        if time.process_time() >= deadline - 1.0:
            break
        hf = _exact_lbfgs(best, 600, 1200, deadline)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

