    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _smooth(h, k):
    if k <= 1:
        return h
    kern = np.ones(k) / k
    hs = np.convolve(h, kern, mode='same')
    hs = np.clip(hs, 0, None)
    return _rescale_maxL(hs)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
    else:
        # Arcsine-like seed
        Nc = 4096
        K = int(0.45 * Nc)
        k = np.arange(K + 1, dtype=float)
        j = np.arange(1, K + 1, dtype=float)
        logc = np.concatenate(([0.0], np.cumsum(np.log((j - 1.0 + 0.5) / j))))
        c = np.exp(logc)
        base = np.zeros(Nc)
        base[:K + 1] = c
        base = _rescale_maxL(base)

    if base.sum() <= 0:
        base = np.ones(1024)

    best = base.copy()
    bestR = R_of(best)

    # Polish at native resolution (full problem)
    h = _exact_lbfgs(best, 3000, 6000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Repeatedly upsample + smooth + re-optimize, keeping the best.
    # This is the key improvement: finer discretization sharpens the plateau
    # and roundoff-reduces the discrete-vs-continuous gap.
    for factor in (2, 2):
        if time.process_time() >= deadline - 1.0:
            break
        n_cur = best.size
        if n_cur * factor > 200000:
            break
        cand = _smooth(_upsample(best, factor), 2)
        cand = _rescale_maxL(cand)
        # quick window polish first, then full
        cand = _window_polish(cand, deadline, frac=0.15, extra=8)
        if time.process_time() < deadline - 1.0:
            cand = _exact_lbfgs(cand, 2500, 5000, deadline)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc

    # Final full polish at whichever resolution we ended on
    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 4000, 8000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    return np.clip(best, 0, None)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # Stage 1: full polish at current resolution.
    h = _exact_lbfgs(best, 1500, 3000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    # Stage 2: resolution escalation, with polish at each level.
    cur = best
    for factor in (2, 2):
        if time.process_time() >= deadline - 6.0:
            break
        if cur.size * factor > 200000:
            break
        h_up = _resample_cum(cur, cur.size * factor)
        h_up = _rescale_maxL(h_up)
        h_up = _exact_lbfgs(h_up, 1200, 2400, deadline)
        r = R_of(h_up)
        if r > bestR:
            best, bestR = h_up, r
            cur = h_up
        else:
            cur = best

    # Stage 3: alternating shifted window polishes + perturbations.
    shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8]
    si = 0
    while time.process_time() < deadline - 1.0:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.20, extra=6,
                           iters=1200, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0:
            h = _exact_lbfgs(best, 800, 1600, deadline)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        if si % 5 == 0 and time.process_time() < deadline - 6.0:
            for scale in (0.02, 0.05):
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1200, 2400, deadline)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

