    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


# ---------------- coarse-escape helpers (from p0234) ----------------

def _block_avg(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _softmax_direct(h_low, beta, deadline, iters=600):
    """Optimize a low-res height vector directly via softmax parametrization."""
    n = h_low.size
    if n == 0:
        return h_low
    z0 = np.log(np.clip(h_low, 1e-12, None))
    z0 = z0 - z0.mean()

    def f(z):
        zz = z - z.max()
        e = np.exp(zz)
        hh = e / e.sum()
        val, g = _norm_eq_fun_grad(hh)
        # chain rule through softmax
        gz = hh * (g - np.dot(g, hh))
        return val, gz

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, z0, jac=True, method='L-BFGS-B',
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
        z = res.x
    except TimeoutError:
        return h_low
    except Exception:
        return h_low
    zz = z - z.max()
    e = np.exp(zz)
    return e / e.sum()


def _zoh_double(h):
    """Zero-order-hold upsampling: each sample becomes two equal samples."""
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out


def _targeted_zoh(h_low, deadline, rounds=3):
    """Low-res exact polish interleaved with targeted refinement."""
    h = h_low.copy()
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        h = _exact_lbfgs(h, 800, 1600, deadline, K=1)
    return h


def _coarse_escape(h_rev, deadline):
    """Run the coarse-escape pipeline on the reversed incumbent."""
    h_low = _block_avg(h_rev, 4)
    best_low = h_low.copy()
    bestR = R_of(_rescale_maxL(best_low)) if best_low.size else -1
    for beta in (200, 1000, 5000, 20000):
        if time.process_time() >= deadline - 2.0:
            break
        cand = _softmax_direct(h_low, beta, deadline)
        cand = _targeted_zoh(cand, deadline, rounds=3)
        r = R_of(_rescale_maxL(cand))
        if r > bestR:
            best_low = cand.copy()
            bestR = r
    # upsample back to original resolution
    h_hi = best_low.copy()
    target_n = h_rev.size
    while h_hi.size < target_n:
        h_hi = _zoh_double(h_hi)
    if h_hi.size > target_n:
        h_hi = h_hi[:target_n]
    return h_hi


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---- coarse escape on the reversed incumbent ----
    try:
        h_rev = best[::-1].copy()
        h_hi = _coarse_escape(h_rev, deadline)
        # polish at high res
        if time.process_time() < deadline - 2.0:
            h_hi = _exact_lbfgs(h_hi, 1500, 3000, deadline, K=1)
        if time.process_time() < deadline - 1.5:
            h_hi = _window_polish(h_hi, deadline)
        # compare both orientations
        for cand in (h_hi, h_hi[::-1].copy()):
            r = R_of(cand)
            if r > bestR + 1e-15:
                best = cand.copy()
                bestR = r
                print("coarse R=%.7f" % bestR)
    except Exception as e:
        print("coarse failed: %s" % e)

    # K ladder only if we have a rough start (tiny R gap to close).
    h = best.copy()
    for K in (20, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))
        else:
            h = best.copy()

    # Alternating polish loop.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _full_polish(best, deadline, iters=2500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

