# ---------- p0234 helpers ----------

def _block_avg(h, f):
    n = h.size
    m = n // f
    if m < 1:
        return h.copy()
    return h[:m * f].reshape(m, f).mean(axis=1)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lm = Lf.max()
    if Lm <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    # softmax over knots
    z = beta * (Lf - Lm)
    z -= z.max()
    e = np.exp(z)
    Z = e.sum()
    p = e / Z
    # softmax approx of log Lm -> log(sum p*Lf) ... use log-mean-exp
    log_soft = np.log(Z) / beta + Lm
    # grad of log_soft wrt Lf: p
    gLf = -dq / num
    gLf += p
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + log_soft
    return val, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _direct_obj_grad(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _targeted_zoh(h, deadline, split_frac=0.5):
    """Split each block into two halves; free the second half (ZOH refinement)."""
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    m = 2 * n
    h2 = np.repeat(h, 2) * 0.5
    # free odd indices (second half of each block)
    free = np.arange(1, m, 2)
    h2 = _exact_lbfgs(h2, 600, 1200, deadline, free=free, K=1)
    return h2


def _zoh_double(h):
    return np.repeat(h, 2) * 0.5


# ---------- construct ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---- p0234 coarse escape attempt ----
    try:
        h_low = _block_avg(best, 4)
        h_low = _rescale_maxL(h_low)
        lowR = R_of(h_low)
        print("low start R=%.7f (N=%d)" % (lowR, h_low.size))
        for beta in (200, 1000, 5000, 20000):
            if time.process_time() >= deadline - 3.0:
                break
            h_try = run_direct(h_low, beta, 400, 800, deadline)
            r = R_of(h_try)
            if r > lowR + 1e-15:
                h_low = h_try
                lowR = r
                print("beta=%d lowR=%.7f" % (beta, lowR))
            else:
                h_low = h_try if r >= lowR else h_low
        # targeted ZOH rounds
        for rnd in range(3):
            if time.process_time() >= deadline - 3.0:
                break
            h_try = _targeted_zoh(h_low, deadline)
            r = R_of(h_try)
            if r > lowR + 1e-15:
                h_low = h_try
                lowR = r
                print("zoh%d lowR=%.7f (N=%d)" % (rnd, lowR, h_low.size))
            else:
                break
        # redouble back to full resolution
        h_hi = h_low
        while h_hi.size < best.size:
            h_hi = _zoh_double(h_hi)
        if h_hi.size != best.size:
            # resize to best.size via interp
            xo = np.linspace(0.0, h_hi.size - 1, best.size)
            h_hi = np.interp(xo, np.arange(h_hi.size), h_hi)
        h_hi = _rescale_maxL(h_hi)
        if time.process_time() < deadline - 2.0:
            h_hi = _exact_lbfgs(h_hi, 800, 1600, deadline, K=1)
        if time.process_time() < deadline - 2.0:
            h_hi = _window_polish(h_hi, deadline)
        r = R_of(h_hi)
        print("hi R=%.7f" % r)
        if r > bestR + 1e-15:
            best, bestR = h_hi.copy(), r
            print("coarse-escape accepted R=%.7f" % bestR)
    except Exception as e:
        print("coarse escape failed:", e)

    # ---- p0645 K ladder ----
    h = best.copy()
    for K in (20, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))
        else:
            h = best.copy()

    # ---- alternating polish ----
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _full_polish(best, deadline, iters=2500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=8):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    it = 0
    # Phase 1: full polish with exact max
    h = _exact_lbfgs(best, 4000, 8000, deadline)
    r = R_of(h)
    if r > bestR + 1e-14:
        best, bestR = h.copy(), r
        print("full%d R=%.7f" % (it, bestR))

    # Phase 2: K>1 topk smoothing to escape single-knot max
    for K in (2, 3, 5, 8):
        if time.process_time() >= deadline - 0.5:
            break
        it += 1
        h = _exact_lbfgs(best, 1500, 3000, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h.copy(), r
            print("topk%d K=%d R=%.7f" % (it, K, bestR))
        # re-polish exact
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-14:
            best, bestR = h.copy(), r
            print("polish%d R=%.7f" % (it, bestR))

    # Phase 3: window polish loop on nonzeros around peak
    while time.process_time() < deadline - 0.5:
        it += 1
        h = _window_polish(best, deadline, frac=0.35)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("win%d R=%.7f" % (it, bestR))
        else:
            # try full polish
            h = _exact_lbfgs(best, 1500, 3000, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("full%d R=%.7f" % (it, bestR))
            else:
                break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

