    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _block_avg(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _zoh_double(h):
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out


def _window_lbfgs_free(h, free, deadline, iters=1500):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.86

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Strategy: split the budget between
    # (a) targeted refinement of a low-res version, then doubling up,
    # (b) K-ladder + alternating full/window polish at full resolution.
    # The key improvement over the incumbent: try *upsampling* the start
    # (double resolution) and polishing there, since finer discretisation
    # can reveal extra structure that the coarse grid cannot.
    mid = t0 + budget_seconds * 0.42

    # --- Phase 1: upsampled refinement ---
    try:
        if best.size < 100000:
            h_up = _zoh_double(best)
            h_up = _exact_lbfgs(h_up, 2000, 4000, mid, K=1)
            r = R_of(h_up)
            if r > bestR + 1e-15:
                best, bestR = h_up.copy(), r
                print("up R=%.7f (N=%d)" % (bestR, best.size))
            # try reversing the upsampled version too
            h_rev = h_up[::-1].copy()
            h_rev = _exact_lbfgs(h_rev, 1500, 3000, mid, K=1)
            r = R_of(h_rev)
            if r > bestR + 1e-15:
                best, bestR = h_rev.copy(), r
                print("up-rev R=%.7f" % bestR)
    except Exception as e:
        print("up failed: %s" % e)

    # --- Phase 2: K ladder ---
    h = best.copy()
    for K in (20, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))
        else:
            h = best.copy()

    # --- Phase 3: alternating polish loop ---
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _full_polish(best, deadline, iters=2500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize

# ---------- exact R and gradient machinery ----------
def _knots(h):
    return np.concatenate(([0.0], np.convolve(h, h), [0.0]))

def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s*s*L.max()
    return num/den if den > 0 else 0.0

def _num_and_dq(h):
    L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf

def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]

def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)

# ---------- smooth objective: log R ----------
# Instead of maximizing R directly (with a max in denominator, non-smooth),
# we minimize -log(R) = -log(num) + 2 log(s) + log(max L).
def _logR_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    if num <= 0 or Lm <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0*np.log(s) + np.log(Lm)
    return val, grad

# ---------- top-K softmax of largest knots: pushes flat plateau ----------
# R is maximized when many knots sit at the max (flat top of f*f).
# Smooth proxy: log(mean of top-K knots) instead of log(max).
def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _logR_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0*np.log(s) + np.log(mean_top)
    return val, grad

def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb

def _lbfgs(h0, deadline, maxiter=2000, free=None, K=1):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _topk_fun_grad(hh, K) if K > 1 else _logR_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2*maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except (TimeoutError, Exception):
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)

# ---------- peak region (where f*f is near its maximum) ----------
def _peak_region(h, tol=0.999):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    return (lo, hi) if hi >= lo else (0, n - 1)

def _window_polish(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.3:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs(h, deadline, maxiter=1500, free=free, K=K)

def _full_polish(h, deadline, iters=2500, K=1):
    return _lbfgs(h, deadline, maxiter=iters, free=None, K=K)

def _upsample(h, factor):
    n = h.size
    if factor == 1:
        return h.copy()
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)

# ---------- Main ----------
def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(60)
    else:
        base = np.ones(60)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Phase 1: polish existing construction with smooth top-K objective
    # K grows to force a wider flat plateau near the maximum of f*f.
    for K in (1, 2, 4, 8, 16, 32):
        if time.process_time() >= deadline - 0.3:
            break
        cand = _lbfgs(best, deadline, maxiter=1200, free=None, K=K)
        rc = R_of(cand)
        if rc > bestR:
            best, bestR = cand, rc
            print("  K=%d R=%.6f" % (K, bestR))

    # Phase 2: resolution refinement. Upsample, polish, accept if better.
    # A finer grid can only help: it allows a closer approximation to
    # the true optimum shape, especially near the flat plateau of f*f.
    fac = 2
    while time.process_time() < deadline - 0.6 and best.size * fac <= 200000:
        up = _upsample(best, fac)
        up = _rescale_maxL(up)
        # Window polish first (cheap, targets the flat-top region)
        up = _window_polish(up, deadline, frac=0.3, K=8)
        up = _window_polish(up, deadline, frac=0.15, K=1)
        # Full polish
        up = _full_polish(up, deadline, iters=1500, K=1)
        rc = R_of(up)
        print("  up x%d R=%.6f (N=%d)" % (fac, rc, up.size))
        if rc > bestR:
            best, bestR = up.copy(), rc
            fac = 2
        else:
            # If upsampling didn't help, try triple then give up on this scale
            if fac == 2:
                fac = 3
            else:
                break

    # Phase 3: final intensive polish on the best, alternating window/full
    # with increasing top-K to squeeze out last bits of plateau flatness.
    while time.process_time() < deadline - 0.3:
        improved = False
        for K in (1, 4, 16):
            if time.process_time() >= deadline - 0.3:
                break
            cand = _window_polish(best, deadline, frac=0.2, K=K)
            rc = R_of(cand)
            if rc > bestR + 1e-13:
                best, bestR = cand, rc
                improved = True
        cand = _full_polish(best, deadline, iters=800, K=1)
        rc = R_of(cand)
        if rc > bestR + 1e-13:
            best, bestR = cand, rc
            improved = True
        if not improved:
            break

    print("final R=%.6f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_average(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _coarse_escape(best, bestR, deadline):
    """Block-average by 4, optimize at coarse grid, ZOH back, polish, accept if better."""
    n = best.size
    if n < 8:
        return best, bestR
    # Only attempt if there's enough time.
    if time.process_time() >= deadline - 6.0:
        return best, bestR
    try:
        h_low = _block_average(best, 4)
        h_low = _rescale_maxL(h_low)
        r_low_start = R_of(h_low)
        # Coarse exact-R L-BFGS.
        h_low_opt = _exact_lbfgs(h_low, 5000, 10000, deadline, K=1)
        r_low_opt = R_of(h_low_opt)
        print("coarse R=%.7f (start %.7f, N=%d)" % (r_low_opt, r_low_start, h_low_opt.size))
        if r_low_opt <= r_low_start:
            return best, bestR
        # ZOH back up to full resolution.
        h_full = np.repeat(h_low_opt, 4)
        # Match original length if needed (pad/truncate).
        if h_full.size < n:
            h_full = np.concatenate([h_full, np.full(n - h_full.size, h_full[-1])])
        elif h_full.size > n:
            h_full = h_full[:n]
        h_full = _rescale_maxL(h_full)
        r_full = R_of(h_full)
        print("zoh R=%.7f (N=%d)" % (r_full, h_full.size))
        # One full L-BFGS at full resolution.
        if time.process_time() < deadline - 3.0:
            h_full = _exact_lbfgs(h_full, 1500, 3000, deadline, K=1)
            r_full = R_of(h_full)
            print("zoh-polish R=%.7f" % r_full)
        # Window polish.
        if time.process_time() < deadline - 2.0:
            h_full = _window_polish(h_full, deadline)
            r_full = R_of(h_full)
            print("zoh-window R=%.7f" % r_full)
        if r_full > bestR + 1e-15:
            print("coarse escape ACCEPTED: %.7f -> %.7f" % (bestR, r_full))
            return h_full, r_full
        else:
            print("coarse escape rejected (%.7f <= %.7f)" % (r_full, bestR))
    except Exception as e:
        print("coarse escape failed: %s" % e)
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Coarse escape attempt (block-average 4x, optimize, ZOH back, polish).
    best, bestR = _coarse_escape(best, bestR, deadline)

    # K ladder only if we have a rough start (tiny R gap to close).
    h = best.copy()
    for K in (20, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))
        else:
            h = best.copy()

    # Alternating polish loop.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _full_polish(best, deadline, iters=2500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                # wider window polish from the best
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

