def _coord_pass(h, rng, ncoords=64):
    """One stochastic exact-R coordinate pass. Returns (h, R)."""
    n = h.size
    best = h.copy()
    bestR = R_of(best)
    idxs = rng.integers(0, n, size=ncoords)
    for j in idxs:
        hj = best[j]
        if hj <= 0:
            hi = max(1e-6, best.mean())
            lo = 0.0
        else:
            lo = 0.0
            hi = 5.0 * hj

        def negR(x):
            trial = best.copy()
            trial[j] = x
            return -R_of(trial)

        try:
            res = minimize_scalar(negR, bounds=(lo, hi), method='bounded',
                                  options={'xatol': 1e-9, 'maxiter': 40})
