    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _block_avg(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _zoh_double(h):
    n = h.size
    out = np.empty(2 * n)
    out[0::2] = h
    out[1::2] = h
    return out


def _window_lbfgs_free(h, free, deadline, iters=1500):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _pair_ascent(h, deadline):
    """Exact 2-coordinate multiplicative ascent using incremental L updates."""
    h = np.clip(np.asarray(h, dtype=float), 0, None).copy()
    n = h.size
    if n < 6:
        return h
    s = h.sum()
    if s <= 0:
        return h

    # Precompute full knot array and num.
    Lf = _knots(h)  # length n+1
    a_ = Lf[:-1]; b_ = Lf[1:]
    num = float(np.sum(a_ * a_ + a_ * b_ + b_ * b_) / 3.0)
    s = float(h.sum())
    mx = float(Lf.max())
    if mx <= 0 or num <= 0:
        return h
    Rcur = num / (s * s * mx)

    # Taper band: cells whose generated knots lie in 0.05M < Lf < 0.95M.
    M = mx
    band_knots = np.flatnonzero((Lf > 0.05 * M) & (Lf < 0.95 * M))
    if band_knots.size >= 2:
        # map knot index to cell index roughly (knot i ~ between cells i-1,i)
        band_cells = np.unique(np.clip(
            np.concatenate([band_knots - 1, band_knots]), 0, n - 1))
    else:
        band_cells = np.arange(n)

    rng = np.random.default_rng(12345)

    def eval_pair(j, k, a, b):
        """Return (R, num, s, Lf_new) for h with h[j]*=a, h[k]*=b."""
        delta = np.zeros(n)
        delta[j] = h[j] * (a - 1.0)
        delta[k] = h[k] * (b - 1.0)
        # L_new = L + 2*conv(h,delta) + conv(delta,delta)
        # conv(h,delta): length 2n-1 -> knots Lf indices 1..2n-1
        if n > 1500:
            chd = fftconvolve(h, delta)
            cdd = fftconvolve(delta, delta)
        else:
            chd = np.convolve(h, delta)
            cdd = np.convolve(delta, delta)
        Lnew_inner = Lf[1:-1] + 2.0 * chd + cdd
        Lf_new = np.concatenate(([0.0], Lnew_inner, [0.0]))
        aa = Lf_new[:-1]; bb = Lf_new[1:]
        num_new = float(np.sum(aa * aa + aa * bb + bb * bb) / 3.0)
        s_new = s + delta.sum()
        mx_new = float(Lf_new.max())
        if s_new <= 0 or mx_new <= 0 or num_new <= 0:
            return -1.0, num_new, s_new, Lf_new
        return num_new / (s_new * s_new * mx_new), num_new, s_new, Lf_new

    # Grid search in (a,b) in [0.7,1.4]^2.
    grid = np.linspace(0.7, 1.4, 5)
    accepts = 0
    last_rebuild = 0

    while time.process_time() < deadline - 0.6:
        # pick pair
        if rng.random() < 0.5 and band_cells.size >= 2:
            j = int(rng.choice(band_cells))
            k = int(rng.choice(band_cells))
        else:
            j = int(rng.integers(0, n))
            k = int(rng.integers(0, n))
        if j == k or abs(j - k) <= 4:
            continue

        # coarse 5x5 grid
        bestR = Rcur
        besta = 1.0; bestb = 1.0
        best_num = num; best_s = s; best_Lf = None
        for a in grid:
            for b in grid:
                if a == 1.0 and b == 1.0:
                    continue
                r, nn, ss, LL = eval_pair(j, k, a, b)
                if r > bestR:
                    bestR = r; besta = a; bestb = b
                    best_num = nn; best_s = ss; best_Lf = LL
        if best_Lf is None:
            continue
        # 3 rounds of 3x3 shrinking
        ca, cb = besta, bestb
        step = 0.175
        for _ in range(3):
            step *= 0.5
            for a in (ca - step, ca, ca + step):
                for b in (cb - step, cb, cb + step):
                    a = min(1.4, max(0.7, a))
                    b = min(1.4, max(0.7, b))
                    if a == 1.0 and b == 1.0:
                        continue
                    r, nn, ss, LL = eval_pair(j, k, a, b)
                    if r > bestR:
                        bestR = r; ca = a; cb = b
                        best_num = nn; best_s = ss; best_Lf = LL
        if best_Lf is not None and bestR > Rcur + 1e-15:
            h[j] *= ca
            h[k] *= cb
            Lf = best_Lf
            num = best_num
            s = best_s
            Rcur = bestR
            accepts += 1
            if accepts - last_rebuild >= 300:
                # rebuild from scratch
                Lf = _knots(h)
                aa = Lf[:-1]; bb = Lf[1:]
                num = float(np.sum(aa * aa + aa * bb + bb * bb) / 3.0)
                s = float(h.sum())
                last_rebuild = accepts

    # Final rebuild & rescale check
    h = np.clip(h, 0, None)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.86

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    mid = t0 + budget_seconds * 0.42

    # --- Phase 1: upsampled refinement ---
    try:
        if best.size < 100000:
            h_up = _zoh_double(best)
            h_up = _exact_lbfgs(h_up, 2000, 4000, mid, K=1)
            r = R_of(h_up)
            if r > bestR + 1e-15:
                best, bestR = h_up.copy(), r
                print("up R=%.7f (N=%d)" % (bestR, best.size))
            h_rev = h_up[::-1].copy()
            h_rev = _exact_lbfgs(h_rev, 1500, 3000, mid, K=1)
            r = R_of(h_rev)
            if r > bestR + 1e-15:
                best, bestR = h_rev.copy(), r
                print("up-rev R=%.7f" % bestR)
    except Exception as e:
        print("up failed: %s" % e)

    # --- Phase 2: K ladder ---
    h = best.copy()
    for K in (20, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))
        else:
            h = best.copy()

    # --- Phase 3: alternating polish loop ---
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _full_polish(best, deadline, iters=2500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    # --- Phase 4: pair ascent on the polished best ---
    try:
        if time.process_time() < deadline - 1.0:
            h_pair = _pair_ascent(best, deadline)
            r = R_of(h_pair)
            if r > bestR + 1e-15:
                best, bestR = h_pair.copy(), r
                print("pair R=%.7f" % bestR)
            else:
                print("pair no gain (R=%.7f)" % r)
    except Exception as e:
        print("pair failed: %s" % e)

    # --- Phase 5: final L-BFGS polish ---
    try:
        if time.process_time() < deadline - 0.5:
            h_fin = _exact_lbfgs(best, 1200, 2400, deadline, K=1)
            r = R_of(h_fin)
            if r > bestR + 1e-15:
                best, bestR = h_fin.copy(), r
                print("final-lbfgs R=%.7f" % bestR)
    except Exception as e:
        print("final lbfgs failed: %s" % e)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1, log_coord=True):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    def fg(hh):
        if K == 1:
            return _norm_eq_fun_grad(hh)
        return _topk_fun_grad(hh, K)

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        if log_coord:
            u0 = np.log(np.clip(h[active], 1e-300, None))

            def f(u):
                uu = np.clip(u, -30.0, 30.0)
                hh = np.zeros(n)
                hh[active] = np.exp(uu)
                val, g = fg(hh)
                return val, g[active] * hh[active]

            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        else:
            x0 = h[active].copy()

            def f(x):
                hh = np.zeros(n)
                hh[active] = np.clip(x, 0.0, None)
                val, g = fg(hh)
                return val, g[active]

            res = minimize(f, x0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * active.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': maxfun,
                                    'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    if log_coord:
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Primary attack: soften the max via top-K surrogate, then return to K=1.
    # A near-degenerate max makes the K=1 gradient ill-conditioned; smoothing
    # it lets L-BFGS raise the numerator before re-pinning the max.
    while time.process_time() < deadline - 2.0:
        progressed = False
        for K in (8, 4, 2, 1):
            if time.process_time() >= deadline - 2.0:
                break
            slice_dl = min(deadline - 1.5,
                           time.process_time() + (deadline - time.process_time()) * 0.35)
            h = _exact_lbfgs(best, 800, 1600, slice_dl, K=K)
            r = R_of(h)
            if r > bestR + 1e-13:
                best, bestR = h.copy(), r
                progressed = True
                print("K=%d R=%.7f" % (K, bestR))
            elif K == 1:
                # try linear-coordinate polish as alternate local descent
                if time.process_time() < deadline - 2.0:
                    slice_dl2 = min(deadline - 1.5,
                                    time.process_time() + (deadline - time.process_time()) * 0.3)
                    h2 = _exact_lbfgs(best, 600, 1200, slice_dl2, K=1, log_coord=False)
                    r2 = R_of(h2)
                    if r2 > bestR + 1e-13:
                        best, bestR = h2.copy(), r2
                        progressed = True
                        print("lin R=%.7f" % bestR)
        if not progressed:
            # window polish around peak
            if time.process_time() < deadline - 1.5:
                h = _window_polish(best, deadline, K=1)
                r = R_of(h)
                if r > bestR + 1e-14:
                    best, bestR = h.copy(), r
                    print("window R=%.7f" % bestR)
                    continue
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

