    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _local_perturb(h, rng, scale):
    n = h.size
    k = max(3, n // 200)
    noise = rng.standard_normal(n)
    kern = np.ones(k) / k
    noise = np.convolve(noise, kern, mode='same')
    mult = np.exp(scale * noise)
    h2 = h * mult
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.8
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(40000)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # Strategy: spend the whole budget refining the given start.
    # 1) A full high-res pass on a fresh upsample to escape grid artifacts.
    if time.process_time() < deadline - 8.0:
        # Try working at higher resolution: upsample then full L-BFGS.
        for n_try in (best.size, 60000, 80000):
            if time.process_time() >= deadline - 8.0:
                break
            if n_try < best.size:
                continue
            h_up = _resample_cum(best, n_try) if n_try != best.size else best.copy()
            h_up = _rescale_maxL(h_up)
            h_up = _exact_lbfgs(h_up, 2000, 4000, deadline)
            r = R_of(h_up)
            if r > bestR:
                best, bestR = h_up, r

    # 2) Alternating shifted peak-window polishes at whatever resolution we have.
    shifts = [0, -1, 1, -2, 2, -4, 4, -8, 8, -16, 16]
    si = 0
    while time.process_time() < deadline - 1.5:
        sh = shifts[si % len(shifts)]
        si += 1
        h = _window_polish(best, deadline, frac=0.20, extra=6,
                           iters=1500, shift=sh)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r
        if si % 3 == 0:
            h = _exact_lbfgs(best, 1000, 2000, deadline)
            r = R_of(h)
            if r > bestR:
                best, bestR = h, r
        if si % 6 == 0 and time.process_time() < deadline - 6.0:
            for scale in (0.01, 0.03):
                if time.process_time() >= deadline - 6.0:
                    break
                hp = _local_perturb(best, rng, scale)
                hp = _exact_lbfgs(hp, 1500, 3000, deadline)
                rp = R_of(hp)
                if rp > bestR:
                    best, bestR = hp, rp

    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


def _full_polish(h, deadline, iters=3000, K=1):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, K=K)


def _block_avg(h, f):
    n = h.size
    m = n // f
    if m < 1:
        return h.copy()
    return h[:m * f].reshape(m, f).mean(axis=1)


def _resample(h, m):
    """Resample step function h (n steps) to m steps preserving mass density."""
    n = h.size
    if m == n:
        return h.copy()
    # treat h as piecewise-constant density on [0, n]; average over m equal bins
    edges = np.linspace(0.0, n, m + 1)
    cum = np.concatenate(([0.0], np.cumsum(h)))  # integral from 0
    out = (np.interp(edges[1:], np.arange(n + 1), cum)
           - np.interp(edges[:-1], np.arange(n + 1), cum))
    out = out / (edges[1:] - edges[:-1])
    return np.clip(out, 0, None)


def _direct_obj_grad(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    Lm = Lf.max()
    if Lm <= 0 or num <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - Lm)
    z -= z.max()
    e = np.exp(z)
    Z = e.sum()
    p = e / Z
    log_soft = np.log(Z) / beta + Lm
    gLf = -dq / num
    gLf += p
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + log_soft
    return val, grad


def run_direct(h0, beta, maxiter, maxfun, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _direct_obj_grad(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Coarse-to-fine escape: downsample, re-optimize with soft-max, upsample ----
    try:
        n = best.size
        for factor in (8, 4, 2):
            if time.process_time() >= deadline - 4.0:
                break
            m = max(20, n // factor)
            h_low = _resample(best, m)
            h_low = _rescale_maxL(h_low)
            lowR = R_of(h_low)
            for beta in (300, 1500, 6000, 25000):
                if time.process_time() >= deadline - 4.0:
                    break
                h_try = run_direct(h_low, beta, 400, 800, deadline)
                r = R_of(h_try)
                if r > lowR + 1e-15:
                    h_low, lowR = h_try, r
            if time.process_time() < deadline - 3.5:
                h_low = _exact_lbfgs(h_low, 500, 1000, deadline, K=1)
                lowR = R_of(h_low)
            print("factor=%d lowR=%.7f" % (factor, lowR))
            # Upsample back to full and polish
            h_hi = _resample(h_low, n)
            h_hi = _rescale_maxL(h_hi)
            if time.process_time() < deadline - 3.0:
                h_hi = _exact_lbfgs(h_hi, 600, 1200, deadline, K=1)
            if time.process_time() < deadline - 2.5:
                h_hi = _window_polish(h_hi, deadline)
            r = R_of(h_hi)
            print("  up R=%.7f" % r)
            if r > bestR + 1e-15:
                best, bestR = h_hi.copy(), r
                print("coarse-escape accepted R=%.7f (factor=%d)" % (bestR, factor))
    except Exception as e:
        print("coarse escape failed:", e)

    # ---- K ladder on best ----
    h = best.copy()
    for K in (20, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))
        else:
            h = best.copy()

    # ---- alternating polish ----
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _full_polish(best, deadline, iters=2500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

