    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


def _full_polish(h, deadline, iters=3000, K=1):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, K=K)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth(h, k):
    if k <= 1:
        return h
    kern = np.ones(k) / k
    hs = np.convolve(h, kern, mode='same')
    hs = np.clip(hs, 0, None)
    return _rescale_maxL(hs)


def _anneal(h, deadline, iters=2000, seed=0):
    rng = np.random.RandomState(seed)
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    cur = best.copy()
    curR = bestR
    for it in range(iters):
        if time.process_time() > deadline - 0.6:
            break
        cand = cur.copy()
        mode = rng.randint(3)
        if mode == 0:
            k = int(rng.randint(2, 7))
            cand = _smooth(cand, k)
        elif mode == 1:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 4))))
            factor = np.exp(rng.normal(0, 0.05))
            cand[a:b] *= factor
        else:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 6))))
            cand[a:b] += rng.normal(0, 1e-3 * (cand.max() + 1e-12), b - a)
        cand = _rescale_maxL(np.clip(cand, 0, None))
        rc = R_of(cand)
        if rc > curR or rng.rand() < 0.05:
            cur, curR = cand, rc
        if rc > bestR:
            best, bestR = cand.copy(), rc
    return best, bestR


def _edge_refine(h, deadline, iters=800, K=1):
    if time.process_time() >= deadline - 0.6:
        return h
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    w = max(8, int((idx.max() - idx.min() + 1) * 0.5))
    left = np.arange(0, min(n, w))
    right = np.arange(max(0, n - w), n)
    free = np.unique(np.concatenate((left, right)))
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free, K=K)


def _power_seed(N, alpha):
    i = np.arange(N, dtype=float)
    if abs(alpha - 0.5) < 1e-12:
        return 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
    return (N ** alpha) / (1.0 - alpha) * ((i + 1.0) ** (1.0 - alpha) - i ** (1.0 - alpha))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    # --- EXPERIMENT: scan cell-averaged power-law exponent alpha ---
    N = 200000
    best = None
    bestR = -1.0
    best_alpha = 0.5
    for alpha in np.linspace(0.35, 0.65, 13):
        if time.process_time() >= deadline - 2.0:
            break
        h = _power_seed(N, float(alpha))
        r = R_of(h)
        print("alpha=%.4f R=%.7f" % (alpha, r))
        if r > bestR:
            bestR = r
            best = h
            best_alpha = float(alpha)
    if best is None:
        best = _power_seed(N, 0.5)
        bestR = R_of(best)
        best_alpha = 0.5
    best = _rescale_maxL(best)
    bestR = R_of(best)
    print("best alpha=%.4f raw R=%.7f" % (best_alpha, bestR))

    # --- EXPERIMENT: polish only first/last 128 indices ---
    free = np.unique(np.concatenate((np.arange(0, 128),
                                     np.arange(N - 128, N))))
    h = _exact_lbfgs(best, 150, 300, deadline, free=free, K=1)
    r = R_of(h)
    if r > bestR + 1e-15:
        best, bestR = h.copy(), r
        print("edge128 R=%.7f" % bestR)

    # --- Keep base's strong polishing machinery on the incumbent ---
    for K in (40, 25, 15, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, frac=0.35, extra=8, K=K)
        h = _full_polish(h, deadline, iters=800, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))

    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _window_polish(best, deadline, frac=0.25, extra=4, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _edge_refine(best, deadline, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("edge R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _full_polish(best, deadline, iters=1500, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                ha, ra = _anneal(best, deadline, iters=400, seed=stall)
                if ra > bestR + 1e-15:
                    h2 = _full_polish(ha, deadline, iters=800, K=1)
                    r2 = R_of(h2)
                    if r2 > bestR + 1e-15:
                        best, bestR = h2.copy(), r2
                        stall = 0
                        print("anneal R=%.7f" % bestR)
                if stall >= 4:
                    break
        else:
            stall = 0

    while time.process_time() < deadline - 0.8:
        h = _full_polish(best, deadline, iters=1500, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("final R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


def _full_polish(h, deadline, iters=3000, K=1):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, K=K)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth(h, k):
    if k <= 1:
        return h
    kern = np.ones(k) / k
    hs = np.convolve(h, kern, mode='same')
    hs = np.clip(hs, 0, None)
    return _rescale_maxL(hs)


def _anneal(h, deadline, iters=2000, seed=0):
    rng = np.random.RandomState(seed)
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    cur = best.copy()
    curR = bestR
    for it in range(iters):
        if time.process_time() > deadline - 0.6:
            break
        cand = cur.copy()
        mode = rng.randint(3)
        if mode == 0:
            k = int(rng.randint(2, 7))
            cand = _smooth(cand, k)
        elif mode == 1:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 4))))
            factor = np.exp(rng.normal(0, 0.05))
            cand[a:b] *= factor
        else:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 6))))
            cand[a:b] += rng.normal(0, 1e-3 * (cand.max() + 1e-12), b - a)
        cand = _rescale_maxL(np.clip(cand, 0, None))
        rc = R_of(cand)
        if rc > curR or rng.rand() < 0.05:
            cur, curR = cand, rc
        if rc > bestR:
            best, bestR = cand.copy(), rc
    return best, bestR


def _edge_refine(h, deadline, iters=800, K=1):
    if time.process_time() >= deadline - 0.6:
        return h
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    w = max(8, int((idx.max() - idx.min() + 1) * 0.5))
    left = np.arange(0, min(n, w))
    right = np.arange(max(0, n - w), n)
    free = np.unique(np.concatenate((left, right)))
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free, K=K)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    # --- NEW: cell-averaged t^{-1/2} seed at N=200000 ---
    N = 200000
