        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


def _full_polish(h, deadline, iters=3000, K=1):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, K=K)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth(h, k):
    if k <= 1:
        return h
    kern = np.ones(k) / k
    hs = np.convolve(h, kern, mode='same')
    hs = np.clip(hs, 0, None)
    return _rescale_maxL(hs)


def _anneal(h, deadline, iters=2000, seed=0):
    rng = np.random.RandomState(seed)
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    cur = best.copy()
    curR = bestR
    for it in range(iters):
        if time.process_time() > deadline - 0.6:
            break
        cand = cur.copy()
        mode = rng.randint(3)
        if mode == 0:
            k = int(rng.randint(2, 7))
            cand = _smooth(cand, k)
        elif mode == 1:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 4))))
            factor = np.exp(rng.normal(0, 0.05))
            cand[a:b] *= factor
        else:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 6))))
            cand[a:b] += rng.normal(0, 1e-3 * (cand.max() + 1e-12), b - a)
        cand = _rescale_maxL(np.clip(cand, 0, None))
        rc = R_of(cand)
        if rc > curR or rng.rand() < 0.05:
            cur, curR = cand, rc
        if rc > bestR:
            best, bestR = cand.copy(), rc
    return best, bestR


def _edge_refine(h, deadline, iters=800, K=1):
    if time.process_time() >= deadline - 0.6:
        return h
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    w = max(8, int((idx.max() - idx.min() + 1) * 0.5))
    left = np.arange(0, min(n, w))
    right = np.arange(max(0, n - w), n)
    free = np.unique(np.concatenate((left, right)))
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free, K=K)


def _power_law_seed(N):
    i = np.arange(N, dtype=float)
    h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
    return h


def _taper(h, L):
    if L <= 0:
        return h.copy()
    hL = h.copy()
    n = h.size
    L = min(L, n)
    ramp = 0.5 * (1.0 + np.cos(np.pi * np.arange(L) / L))
    hL[n - L:n] *= ramp
    return hL


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # --- Experiment: power-law seed with right-edge taper sweep, then
    #     boundary-layer reoptimization. ---
    N = 200000
    hseed = _rescale_maxL(_power_law_seed(N))
    seedR = R_of(hseed)
    print("power-law seed R=%.7f (N=%d)" % (seedR, N))

    taper_best = hseed.copy()
    taper_bestR = seedR
    taper_bestL = 0
    for L in (0, 16, 64, 256, 1024, 4096):
        hL = _rescale_maxL(_taper(hseed, L))
        rL = R_of(hL)
        print("L=%d R=%.7f" % (L, rL))
        if rL > taper_bestR + 1e-15:
            taper_best = hL
            taper_bestR = rL
            taper_bestL = L

    print("best taper L=%d R=%.7f" % (taper_bestL, taper_bestR))

    # Boundary-layer reoptimization on the best taper.
    hcur = taper_best.copy()
    curR = taper_bestR
    Luse = max(256, taper_bestL)
    free = np.unique(np.concatenate((np.arange(0, 256),
                                     np.arange(N - Luse, N))))
    h2 = _exact_lbfgs(hcur, 150, 300, deadline, free=free, K=1)
    r2 = R_of(h2)
    print("boundary polish R=%.7f (was %.7f)" % (r2, curR))
    if r2 > curR + 1e-15:
        hcur, curR = h2, r2

    if curR > bestR + 1e-15:
        best, bestR = hcur.copy(), curR
        print("new best from power-law R=%.7f" % bestR)

    # Spend remaining time polishing the same boundary set again.
    while time.process_time() < deadline - 1.0:
        h3 = _exact_lbfgs(best, 200, 400, deadline, free=free, K=1)
        r3 = R_of(h3)
        if r3 > bestR + 1e-15:
            best, bestR = h3.copy(), r3
            print("boundary repolish R=%.7f" % bestR)
        else:
            break

    # If the power-law branch didn't beat the base start, fall back to the
    # base's own polishing loop to avoid losing ground.
    if bestR <= R_of(base) + 1e-15:
        h = base.copy()
        for K in (40, 25, 15, 10, 6, 4, 3, 2, 1):
            if time.process_time() >= deadline - 2.0:
                break
            h = _window_polish(h, deadline, frac=0.35, extra=8, K=K)
            h = _full_polish(h, deadline, iters=800, K=K)
            r = R_of(h)
            print("K=%d R=%.7f" % (K, r))
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r

        stall = 0
        while time.process_time() < deadline - 1.5:
            improved = False
            h = _window_polish(best, deadline, frac=0.25, extra=4, K=1)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                improved = True
                print("window R=%.7f" % bestR)
            if time.process_time() >= deadline - 1.5:
                break
            h = _edge_refine(best, deadline, K=1)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                improved = True
                print("edge R=%.7f" % bestR)
            if time.process_time() >= deadline - 1.5:
                break
            h = _full_polish(best, deadline, iters=1500, K=1)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                improved = True
                print("full R=%.7f" % bestR)
            if not improved:
                stall += 1
                if stall >= 2:
                    ha, ra = _anneal(best, deadline, iters=400, seed=stall)
                    if ra > bestR + 1e-15:
                        h2 = _full_polish(ha, deadline, iters=800, K=1)
                        r2 = R_of(h2)
                        if r2 > bestR + 1e-15:
                            best, bestR = h2.copy(), r2
                            stall = 0
                            print("anneal R=%.7f" % bestR)
                    if stall >= 4:
                        h = _window_polish(best, deadline, frac=0.6, extra=16, K=1)
                        r = R_of(h)
                        if r > bestR + 1e-15:
                            best, bestR = h.copy(), r
                            stall = 0
                            print("wide R=%.7f" % bestR)
                        else:
                            break
            else:
                stall = 0

    # Upsampling stage (only if we still have time and room).
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_upsample(best, factor))
        rc = R_of(cand)
        h = _exact_lbfgs(cand, 400, 800, deadline, K=1)
        r = R_of(h)
        print("upsample x%d R=%.7f (raw %.7f)" % (factor, r, rc))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            break

    # Final fine polish with remaining time.
    while time.process_time() < deadline - 0.8:
        h = _full_polish(best, deadline, iters=1500, K=1)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("final R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, K=1):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, K=K)


def _full_polish(h, deadline, iters=3000, K=1):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, K=K)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth(h, k):
    if k <= 1:
        return h
    kern = np.ones(k) / k
    hs = np.convolve(h, kern, mode='same')
    hs = np.clip(hs, 0, None)
    return _rescale_maxL(hs)


def _anneal(h, deadline, iters=2000, seed=0):
    rng = np.random.RandomState(seed)
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    cur = best.copy()
    curR = bestR
    for it in range(iters):
        if time.process_time() > deadline - 0.6:
            break
        cand = cur.copy()
        mode = rng.randint(3)
        if mode == 0:
            k = int(rng.randint(2, 7))
            cand = _smooth(cand, k)
        elif mode == 1:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 4))))
            factor = np.exp(rng.normal(0, 0.05))
            cand[a:b] *= factor
        else:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 6))))
            cand[a:b] += rng.normal(0, 1e-3 * (cand.max() + 1e-12), b - a)
        cand = _rescale_maxL(np.clip(cand, 0, None))
        rc = R_of(cand)
        if rc > curR or rng.rand() < 0.05:
            cur, curR = cand, rc
        if rc > bestR:
            best, bestR = cand.copy(), rc
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Gentle top-K relaxation ladder to escape the sharp-max optimum.
    h = best.copy()
    for K in (20, 10, 5, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 500, 1000, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Alternating polish loop.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                ha, ra = _anneal(best, deadline, iters=400, seed=stall)
                if ra > bestR + 1e-15:
                    h2 = _full_polish(ha, deadline, iters=800)
                    r2 = R_of(h2)
                    if r2 > bestR + 1e-15:
                        best, bestR = h2.copy(), r2
                        stall = 0
                        print("anneal R=%.7f" % bestR)
                if stall >= 4:
                    h = _window_polish(best, deadline, frac=0.6, extra=16)
                    r = R_of(h)
                    if r > bestR + 1e-15:
                        best, bestR = h.copy(), r
                        stall = 0
                        print("wide R=%.7f" % bestR)
                    else:
                        break
        else:
            stall = 0

    # Upsampling stage.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_upsample(best, factor))
        rc = R_of(cand)
        if rc >= bestR - 1e-5:
            h = _full_polish(cand, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            else:
                best, bestR = cand.copy(), rc
                print("upsample(keep) R=%.7f N=%d" % (bestR, best.size))
        else:
            break

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


# --- refinement: insert new steps near the peak by splitting, then polish ---

def _split_region(h, lo, hi):
    """Double the resolution of h[lo:hi+1] by splitting each step into two."""
    n = h.size
    interior = h[lo:hi + 1]
    new_mid = 0.5 * (interior[:-1] + interior[1:])
    out = np.empty(n + interior.size - 1)
    k = 0
    # copy before lo
    out[:lo] = h[:lo]
    k = lo
    for i in range(interior.size):
        out[k] = interior[i]
        k += 1
        if i < interior.size - 1:
            out[k] = new_mid[i]
            k += 1
    out[k:] = h[hi + 1:]
    return out


def _split_refine(h, deadline, factor_window=0.15):
    """Split the peak region into finer steps, then polish."""
    n = h.size
    if n >= 190000:
        return h
    lo, hi = _peak_region(h)
    span = hi - lo
    if span < 2:
        return h
    # widen a bit
    pad = max(2, int(span * factor_window))
    lo2 = max(0, lo - pad)
    hi2 = min(n - 1, hi + pad)
    if hi2 - lo2 < 2:
        return h
    hs = _split_region(h, lo2, hi2)
    if hs.size > 200000:
        hs = hs[:200000]
    hs = _rescale_maxL(hs)
    return _exact_lbfgs(hs, 1500, 3000, deadline, K=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.87

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # ---- key new phase: increase resolution near the peak, then re-optimize ----
    # This is the main lever: a finer grid near the top of f*f can represent
    # the optimal shape more faithfully and improve R.
    for round_i in range(6):
        if time.process_time() >= deadline - 2.0:
            break
        cand = _split_refine(best, deadline)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r
            print("split R=%.7f (N=%d)" % (bestR, best.size))
        else:
            # try a bigger split window once
            lo, hi = _peak_region(best)
            span = hi - lo
            n = best.size
            pad = max(4, int(span * 0.4))
            lo2 = max(0, lo - pad); hi2 = min(n - 1, hi + pad)
            if hi2 - lo2 >= 2 and n < 190000:
                hs = _split_region(best, lo2, hi2)
                if hs.size <= 200000:
                    hs = _rescale_maxL(hs)
                    hs = _exact_lbfgs(hs, 1500, 3000, deadline, K=1)
                    r = R_of(hs)
                    if r > bestR + 1e-12:
                        best, bestR = hs, r
                        print("split-wide R=%.7f (N=%d)" % (bestR, best.size))
                        continue
            break

    # ---- K ladder to smooth the peak ----
    h = best.copy()
    for K in (20, 10, 6, 4, 3, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("K=%d R=%.7f" % (K, r))
        else:
            h = best.copy()

    # ---- polish loop ----
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _full_polish(best, deadline, iters=2500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                # one more split attempt before giving up
                cand = _split_refine(best, deadline)
                r = R_of(cand)
                if r > bestR + 1e-12:
                    best, bestR = cand, r
                    stall = 0
                    print("split2 R=%.7f (N=%d)" % (bestR, best.size))
                else:
                    break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

