    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    w = max(8, int((idx.max() - idx.min() + 1) * 0.5))
    left = np.arange(0, min(n, w))
    right = np.arange(max(0, n - w), n)
    free = np.unique(np.concatenate((left, right)))
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free, K=K)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    # --- NEW: cell-averaged t^{-1/2} seed at N=200000 ---
    N = 200000
    i = np.arange(N, dtype=float)
    h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
    rawR = R_of(h)
    print("raw cell-avg power-law R=%.7f (N=%d)" % (rawR, N))

    # First-cell amplitude scan.
    best_lam = 1.0
    best_seed = h.copy()
    best_seedR = rawR
    for lam in np.linspace(0.30, 1.00, 29):
        h2 = h.copy()
        h2[0] = lam * h[0]
        r2 = R_of(h2)
        if r2 > best_seedR:
            best_seedR = r2
            best_lam = lam
            best_seed = h2
    print("best lam=%.4f R=%.7f" % (best_lam, best_seedR))

    best = best_seed.copy()
    bestR = best_seedR

    # Limited polish on first 256 cells, keep only if exact R improves.
    if time.process_time() < deadline - 2.0:
        free = np.arange(0, 256)
        h3 = _exact_lbfgs(best, 100, 200, deadline, free=free, K=1)
        r3 = R_of(h3)
        print("head polish R=%.7f" % r3)
