    if time.process_time() < deadline - 2.0:
        free = np.arange(N - 256, N)
        h4 = _exact_lbfgs(best, 100, 200, deadline, free=free, K=1)
        r4 = R_of(h4)
        print("tail polish R=%.7f" % r4)
        if r4 > bestR + 1e-15:
