        h = _exact_lbfgs(best, 1500, 3000, deadline, K=64)
        r = R_of(h)
        print("cyc%d K=64 R=%.7f" % (cyc, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True

        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(best, 1500, 3000, deadline, K=96)
        r = R_of(h)
        print("cyc%d K=96 R=%.7f" % (cyc, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True

        if time.process_time() >= deadline - 2.0:
            break
        h = _full_polish(best, deadline, iters=2000, K=1)
        r = R_of(h)
        print("cyc%d K=1 R=%.7f" % (cyc, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True

        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, frac=0.30, extra=8, K=1)
        r = R_of(h)
        print("cyc%d win R=%.7f" % (cyc, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True

        if not improved:
            # no strict improvement this cycle; keep going until deadline
            # but avoid burning the whole budget on a frozen plateau
            if cyc >= 3:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    if factor <= 1:
        return h.copy()
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: coarse multiscale polish — downsample, polish, upsample.
    # A coarser representation has fewer free variables so L-BFGS makes
    # faster global progress; then we lift back up.
    n0 = best.size
    for f in (8, 4, 2):
        if time.process_time() >= deadline - 2.0:
            break
        hc = _downsample(best, f)
        hc = _rescale_maxL(hc)
        hc = _exact_lbfgs(hc, 1500, 3000, deadline)
        hc = _window_polish(hc, deadline, frac=0.4, iters=1500)
        hu = _upsample(hc, f)
        if hu.size != n0:
            # remap back to n0 via mass-preserving interp
            hu = _upsample(_downsample(hu, max(1, hu.size // n0)), max(1, hu.size // n0))
            if hu.size < n0:
                hu = np.interp(np.linspace(0, hu.size - 1, n0),
                               np.arange(hu.size), hu)
            else:
                hu = hu[:n0]
        hu = _rescale_maxL(hu)
        r = R_of(hu)
        print("coarse f=%d R=%.7f" % (f, r))
        if r > bestR - 1e-6:
            h = _exact_lbfgs(hu, 800, 1600, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("lift f=%d R=%.7f" % (f, bestR))

    # Phase 2: alternating full / window polish, but each time also try
    # a slightly upsampled version to give the peak more degrees of freedom.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False

        h = _exact_lbfgs(best, 2500, 5000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline, frac=0.2, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)

        # upsampled window polish: expand peak region by 2x and refine.
        if time.process_time() < deadline - 2.0:
            n = best.size
            if n <= 100000:
                hu = _upsample(best, 2)
                hu = _rescale_maxL(hu)
                hu = _window_polish(hu, deadline, frac=0.15, iters=1200)
                # downsample back
                hd = _downsample(hu, 2)
                r = R_of(hd)
                if r > bestR + 1e-15:
                    best, bestR = hd.copy(), r
                    improved = True
                    print("upsample R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 3:
                break

    final = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(final), final.size))
    return final

