        factor *= 2

    # Stage 3: full polish at final resolution with remaining time.
    hf = _exact_lbfgs(best, 1500, 3000, deadline)
    rf = R_of(hf)
    if rf > bestR:
        best, bestR = hf, rf
        print("full polish: R=%.7f" % bestR)

    # Stage 4: alternating window/full polish until deadline.
    while time.process_time() < deadline - 0.5:
        hw = _window_polish(best, deadline)
        rw = R_of(hw)
        if rw > bestR:
            best, bestR = hw, rw
            print("final window: R=%.7f" % bestR)
        hf = _exact_lbfgs(best, 800, 1600, deadline)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf
            print("final full: R=%.7f" % bestR)
        if time.process_time() >= deadline - 0.5:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _block_average(h, N):
    n = h.size
    if n == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, n, N + 1)
    vals = np.interp(edges, np.arange(n + 1), c)
    out = np.diff(vals)
    return np.clip(out, 0, None)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _prolong_free(h, deadline, maxiter, maxfun):
    """Double resolution with free split fractions, then refine heights."""
    n = h.size
    m = 2 * n
    if time.process_time() >= deadline - 0.5:
        return np.repeat(h, 2) * 0.5

    def build(sv):
        s = 1.0 / (1.0 + np.exp(-np.clip(sv, -30, 30)))
        h2 = np.empty(m)
        h2[0::2] = h * (1.0 - s)
        h2[1::2] = h * s
        return h2, s

    def f(sv):
        h2, s = build(sv)
        val, g = _norm_eq_fun_grad(h2)
        # chain rule: dh2/ds_i
        gs = np.empty(n)
        gs = g[1::2] * (h * s * (1 - s)) - g[0::2] * (h * s * (1 - s))
        return val, gs

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, np.zeros(n), jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2, _ = build(res.x)
    except Exception:
        h2 = np.repeat(h, 2) * 0.5
    h2 = _rescale_maxL(h2)
    return _exact_lbfgs(h2, maxiter, maxfun, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: full polish on the start.
    h = _exact_lbfgs(best, 3000, 6000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
    print("polish R=%.7f" % bestR)

    # Stage B: prolongation (resolution refinement) loop.
    while time.process_time() < deadline - 2.0 and best.size < 200000:
        if best.size * 2 > 200000:
            break
        h = _prolong_free(best, deadline, 800, 1600)
        r = R_of(h)
        tag = "gain" if r > bestR + 1e-15 else "no gain"
        print("prolong N=%d R=%.7f %s" % (h.size, r, tag))
        if r > bestR - 1e-12:
            best, bestR = h.copy(), max(r, bestR)
        else:
            break

    # Stage C: window polish + full polish alternation.
    for _ in range(6):
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline, frac=0.20, extra=6)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        if time.process_time() >= deadline - 1.5:
            break
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        tag = "gain" if r > bestR + 1e-15 else "no gain"
        print("full R=%.7f %s" % (r, tag))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        else:
            break

    # Stage D: occasional extra prolongation if time remains.
    while time.process_time() < deadline - 3.0 and best.size * 2 <= 200000:
        h = _prolong_free(best, deadline, 600, 1200)
        r = R_of(h)
        tag = "gain" if r > bestR + 1e-15 else "no gain"
        print("prolong2 N=%d R=%.7f %s" % (h.size, r, tag))
        if r > bestR - 1e-12:
            best, bestR = h.copy(), max(r, bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

