    if time.process_time() >= deadline - 1.0:
        return h0
    def f(x):
        xc = np.clip(x, 0, None)
        o, g = _direct_obj_grad(xc, beta)
        return o, g * (x > 0)
    try:
        res = minimize(f, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * h0.size,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-17, 'gtol': 1e-13})
        return _rescale_maxL(res.x)
    except Exception:
        return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    N = base.size

    # 1) Sliding-window polishing around the peak with varying widths.
    # This is cheap and reliably squeezes out small gains.
    for frac in [0.15, 0.30, 0.5]:
        if time.process_time() >= deadline - 1.0:
            break
        h = _window_polish(best, deadline, frac=frac, extra=6)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window frac=%.2f R=%.7f" % (frac, bestR))

    # 2) Full-res exact L-BFGS from current best.
    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 1000, 2000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full exact R=%.7f" % bestR)

    # 3) Direct softmax pass to break free of the argmax choice.
    for beta in [5000, 20000, 100000]:
        if time.process_time() >= deadline - 1.0:
            break
        h = run_direct(best, beta, 300, 600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("lse beta=%d R=%.7f" % (beta, bestR))

    # 4) Refine window again after softmax.
    if time.process_time() < deadline - 1.0:
        h = _window_polish(best, deadline, frac=0.2, extra=6)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window2 R=%.7f" % bestR)

    # 5) Try a small-delta perturbation to escape a local optimum,
    #    then polish. Uses remaining time.
    rng = np.random.default_rng(999)
    for scale in [0.02, 0.05]:
        if time.process_time() >= deadline - 2.0:
            break
        hp = _perturb(best, scale, rng)
        hp = _window_polish(hp, deadline, frac=0.2, extra=6)
        hp = _exact_lbfgs(hp, 600, 1200, deadline)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp.copy(), r
            print("perturb scale=%.2f R=%.7f" % (scale, bestR))

    # 6) Final full exact pass with remaining time.
    if time.process_time() < deadline - 0.5:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("final exact R=%.7f" % bestR)

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

