    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _resample_to(h, N2):
    """Mass-preserving resample of step heights h (length N) to length N2."""
    h = np.asarray(h, dtype=float)
    n = h.size
    if n == N2:
        return h.copy()
    M = np.concatenate(([0.0], np.cumsum(h)))
    # knots at i/n for i=0..n
    xk = np.arange(n + 1, dtype=float) / n
    # target edges at j/N2 for j=0..N2
    xe = np.arange(N2 + 1, dtype=float) / N2
    Me = np.interp(xe, xk, M)
    h2 = np.diff(Me) * N2
    return np.clip(h2, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- N-sweep experiment: try nearby/moderate N, mass-preserving resample ---
    sweep_N = [40000, 44000, 48000, 52000, 56000, 60000, 64000, 65536, 72000, 84992, 96000]
    sweep_best = best
    sweep_bestR = bestR
    sweep_bestN = best.size
    # Reserve roughly 40% of budget for sweep, rest for polish pipeline.
    sweep_deadline = t0 + budget_seconds * 0.40
    for N2 in sweep_N:
        if time.process_time() >= sweep_deadline - 0.5:
            break
        if N2 > 200000:
            continue
        try:
            h2 = _resample_to(base if start is not None else best, N2)
        except Exception:
            continue
        if h2.size < 1 or h2.sum() <= 0:
            continue
        h2 = _rescale_maxL(h2)
        r0 = R_of(h2)
        h2 = _exact_lbfgs(h2, 800, 1600, sweep_deadline)
        h2 = _window_polish(h2, sweep_deadline, frac=0.3, extra=6)
        r = R_of(h2)
        if r > sweep_bestR + 1e-15:
            sweep_best, sweep_bestR, sweep_bestN = h2, r, N2
            print("sweep N=%d R=%.7f" % (N2, r))
        else:
            print("sweep N=%d R=%.7f (r0=%.7f)" % (N2, r, r0))

    best, bestR = sweep_best, sweep_bestR
    print("after sweep R=%.7f (N=%d)" % (bestR, best.size))

    # --- Existing p0674 pipeline from the best point ---
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False

        n = best.size
        for factor in (2, 3, 4):
            if n // factor < 64:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            hc = _downsample(best, factor)
            hc = _rescale_maxL(hc)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hc = _window_polish(hc, deadline, frac=0.4, extra=6)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hu = _rescale_maxL(_upsample(hc, factor))
            if hu.size != n:
                xo = np.linspace(0.0, hu.size - 1, n)
                hu = np.interp(xo, np.arange(hu.size), hu)
                hu = _rescale_maxL(hu)
            hu = _window_polish(hu, deadline, frac=0.35, extra=8)
            r = R_of(hu)
            if r > bestR + 1e-15:
                best, bestR = hu, r
                improved = True
                print("ds%d R=%.7f" % (factor, bestR))
                break

        if time.process_time() >= deadline - 1.5:
            break

        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if time.process_time() < deadline - 0.8:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final R=%.7f" % bestR)

    # Return whichever of {best, start} has higher exact R.
    if start is not None:
        s = np.clip(np.asarray(start, dtype=float), 0, None)
        if s.size > 0 and s.sum() > 0:
            rs = R_of(s)
            if rs > bestR + 1e-15:
                best, bestR = s, rs

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

