        base = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Consolidate at current resolution.
    h = _exact_lbfgs(best, 600, 1200, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("consolidate R=%.7f" % bestR)

    # Resample ladder: try coarser and finer grids to escape grid-locked
    # local optima.  Alternate directions so we get varied local optima.
    n0 = best.size
    targets = []
    for f in (0.5, 0.75, 1.5, 2.0, 0.33, 3.0, 0.25, 4.0):
        m = int(n0 * f)
        if 30 <= m <= 200000:
            targets.append(m)
    for m in (2000, 5000, 10000, 20000, 40000, 80000, 160000):
        if 30 <= m <= 200000 and m not in targets:
            targets.append(m)
    targets.sort(key=lambda m: abs(m - n0))

    for m in targets:
        if time.process_time() >= deadline - 5.0:
            break
        h_r = _resample(best, m)
        h_r = _rescale_maxL(h_r)
        h_r = _exact_lbfgs(h_r, 1500, 3000, deadline)
        r = R_of(h_r)
        if r > bestR + 1e-15:
            best, bestR = h_r.copy(), r
            print("resample m=%d R=%.7f (N=%d)" % (m, bestR, best.size))

    # Final polish loop: alternate full and windowed refinement.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                h = _window_polish(best, deadline, frac=0.6, extra=16)
                r = R_of(h)
                if r > bestR + 1e-15:
                    best, bestR = h.copy(), r
                    stall = 0
                    print("wide R=%.7f" % bestR)
                else:
                    break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = min(K, n)
    if K >= n:
        Lm = Lf.mean()
        gLf = -dq / num + (1.0 / (n * Lm)) * np.ones(n)
    else:
        idx = np.argpartition(Lf, n - K)[n - K:]
        Lm = Lf[idx].mean()
        gLf = -dq / num
        gLf[idx] += 1.0 / (K * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_lin(h0, K, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        return _topk_fun_grad(x, K)

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.clip(res.x, 0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


# ---------- prolongation with free split fractions ----------

def _prolong_free(h, deadline, maxiter=400, maxfun=800):
    """Double resolution; optimise split fractions s_i in (0,1) with
    h2[2i] = h[i]*(1-s_i), h2[2i+1] = h[i]*s_i."""
    n = h.size
    m = 2 * n
    if time.process_time() >= deadline - 0.5:
        return np.repeat(h, 2) * 0.5

    def build(sv):
        s = 1.0 / (1.0 + np.exp(-np.clip(sv, -30, 30)))
        h2 = np.empty(m)
        h2[0::2] = h * (1.0 - s)
        h2[1::2] = h * s
        return h2, s

    def f(sv):
        h2, s = build(sv)
        val, g = _norm_eq_fun_grad(h2)
        gs = g[0::2] * (-h) + g[1::2] * h
        # chain rule through sigmoid: ds/dsv = s(1-s)
        return val, gs * s * (1.0 - s)

    s0 = np.zeros(n)
    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, s0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    if res is None:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    h2, _ = build(res.x)
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Top-K surrogate sweep in linear coordinates.
    for K in (2000, 1000, 500, 200, 64, 20, 8, 3, 1):
        if time.process_time() >= deadline - 1.5:
            break
        h = _topk_lin(best, K, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("topk%d R=%.7f" % (K, bestR))

    if time.process_time() < deadline - 1.5:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)

    if time.process_time() < deadline - 1.5:
        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False

        # Free-split prolongation: double resolution, optimise splits then heights.
        if best.size * 2 <= 200000 and time.process_time() < deadline - 2.0:
            hp = _prolong_free(best, deadline)
            hp = _window_polish(hp, deadline, frac=0.3, extra=8)
            r = R_of(hp)
            if r > bestR + 1e-15:
                best, bestR = hp, r
                improved = True
                print("prol R=%.7f" % bestR)

        n = best.size
        for factor in (2, 3, 4):
            if n // factor < 64:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            hc = _downsample(best, factor)
            hc = _rescale_maxL(hc)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hc = _window_polish(hc, deadline, frac=0.4, extra=6)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hu = _rescale_maxL(_upsample(hc, factor))
            if hu.size != n:
                xo = np.linspace(0.0, hu.size - 1, n)
                hu = np.interp(xo, np.arange(hu.size), hu)
                hu = _rescale_maxL(hu)
            hu = _window_polish(hu, deadline, frac=0.35, extra=8)
            r = R_of(hu)
            if r > bestR + 1e-15:
                best, bestR = hu, r
                improved = True
                print("ds%d R=%.7f" % (factor, bestR))
                break

        if time.process_time() >= deadline - 1.5:
            break

        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if time.process_time() < deadline - 0.8:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

