def _jump_fun_grad(h, lam):
    """Objective using num = sum y_j^2 + (1/12) sum (dL_j)^2 with jump weight lam.
    y_j = (L_j + L_{j+1})/2 mid-values; dL_j = L_{j+1}-L_j.
    We use surrogate num_lam = sum y^2 + lam/12 * sum dL^2, and keep the
    exact normalization terms (sum h)^2 and max L."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    y = 0.5 * (a + b)
    d = b - a
    num = np.sum(y * y) + (lam / 12.0) * np.sum(d * d)
    if num <= 0:
        return 1e18, np.zeros(h.size)
    # d num / d Lf
    dq = np.zeros_like(Lf)
    # d/d a of y^2 = 2 y * 0.5 = y ; of d^2 = -2 d
    # d/d b of y^2 = y ; of d^2 = 2 d
    dq[:-1] += y - (lam / 6.0) * d
    dq[1:] += y + (lam / 6.0) * d
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


