import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h, frac=0.999):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= frac * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, peak_frac=0.999):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h, peak_frac)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _upsample_to(h, m):
    n = h.size
    if m == n:
        return h.copy()
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _polish(h, bestR, deadline, iters=2000):
    cand = _exact_lbfgs(h, iters, 2 * iters, deadline)
    r = R_of(cand)
    if r > bestR + 1e-16:
        return cand, r
    return h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase A: full exact polish at native resolution.
    best, bestR = _polish(best, bestR, deadline, iters=3000)
    print("phaseA R=%.7f" % bestR)

    # Phase B: multi-scale refinement. Coarsen, polish, upsample, polish.
    # This explores a different scale where local minima differ.
    n0 = best.size
    scales = []
    f = 2
    while n0 // f >= 64:
        scales.append(f)
        f *= 2
    for fac in reversed(scales):
        if time.process_time() >= deadline - 2.0:
            break
        coarse = _downsample(best, fac)
        coarse = _rescale_maxL(coarse)
        coarse, rc = _polish(coarse, R_of(coarse), deadline, iters=1500)
        up = _upsample_to(coarse, n0)
        up, ru = _polish(up, bestR, deadline, iters=1500)
        if ru > bestR + 1e-16:
            best, bestR = up, ru
            print("multiscale fac=%d R=%.7f" % (fac, bestR))

    # Phase C: windowed polish around the peak at several widths.
    for width in (0.1, 0.25, 0.5, 1.0, 2.0):
        if time.process_time() >= deadline - 2.0:
            break
        for pf in (0.999, 0.99):
            if time.process_time() >= deadline - 2.0:
                break
            cand = _window_polish(best, deadline, frac=width, peak_frac=pf)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("window w=%.2f pf=%.3f R=%.7f" % (width, pf, bestR))

    # Phase D: final full polish until deadline, then windowed polish.
    while time.process_time() < deadline - 1.5:
        prev = bestR
        best, bestR = _polish(best, bestR, deadline, iters=3000)
        if bestR <= prev + 1e-16:
            break
    while time.process_time() < deadline - 1.0:
        prev = bestR
        cand = _window_polish(best, deadline, frac=0.5, peak_frac=0.999)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.clip(best, 0, None)

