    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Try upsampling once; keep only if it does not hurt.
    if best.size < 100000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR - 1e-7:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    # Main loop: alternate exact L-BFGS (normalized) with top-K smoothing.
    # Top-K smoothing lets the peak region broaden slightly, escaping the
    # exact-maximum's zero-gradient trap, then exact L-BFGS re-sharpens.
    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        # exact polish
        h = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        # top-K smoothing with growing K to widen the peak support
        for K in (3, 5, 8, 13):
            if time.process_time() >= deadline - 2.0:
                break
            h = _topk_lin(best, K, 800, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
            h = _exact_lbfgs(best, 1500, 3000, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
        if bestR > prevR + 1e-16:
            print("cycle %d R=%.7f" % (cycle, bestR))
        else:
            break

    # Window polish on the peak region (fine local refinement).
    hard = t0 + budget_seconds * 0.97
    while time.process_time() < hard - 1.0:
        h = _window_polish(best, hard - 0.5, frac=0.35)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    # Final exact polish until the bell.
    while time.process_time() < hard - 0.5:
        h = _exact_lbfgs(best, 4000, 8000, hard - 0.3)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

