    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _signed_obj_grad(x):
    num, dq, Lf = _num_and_dq(x)
    s = x.sum()
    if abs(s) < 1e-9:
        return 1e18, np.zeros(x.size)
    mx = Lf.max()
    if mx <= 0:
        return 1e18, np.zeros(x.size)
    gLf = -dq / num
    m = int(np.argmax(Lf))
    gLf[m] += 1.0 / mx
    grad = _backprop(gLf, x) + 2.0 * np.sign(s) / abs(s)
    obj = -np.log(num) + 2.0 * np.log(abs(s)) + np.log(mx)
    return obj, grad


def _signed_lbfgs(x0, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return x0
    A = 4.0 * float(np.max(np.abs(x0))) + 1e-12
    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(_signed_obj_grad, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-A, A)] * x0.size, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
        return res.x
    except TimeoutError:
        try:
            return res.x
        except Exception:
            return x0
    except Exception:
        return x0


def _signed_R(x):
    s = x.sum()
    if abs(s) < 1e-12:
        return 0.0
    Lf = _knots(x)
    mx = Lf.max()
    if mx <= 0:
        return 0.0
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    return num / (s * s * mx)


def _flat_band_width(h):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 1
    idx = np.flatnonzero(Lf >= 0.99 * mx)
    if idx.size < 2:
        return 1
    return max(1, int(idx.max() - idx.min()))


def _upsample(h, n_out):
    return _resample_cum(h, n_out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(20240630)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)
    print(f"start R={bestR:.7f} (N={best.size})")

    # Baseline: pure non-negative polish of the start.
    hb = _exact_lbfgs(best, 4000, 8000, deadline)
    rb = R_of(hb)
    if rb > bestR:
        best, bestR = hb.copy(), rb
    hb = _window_polish(best, deadline, frac=0.35, extra=8, iters=3000)
    rb = R_of(hb)
    if rb > bestR:
        best, bestR = hb.copy(), rb
    print(f"after nonneg polish R={bestR:.7f}")

    s0 = best.copy()
    d = _flat_band_width(s0)
    seeds = [s0.copy(),
             s0 - np.roll(s0, d),
             s0 - np.roll(s0, -d),
             2.0 * s0 - np.roll(s0, d) - np.roll(s0, -d),
             s0 - np.roll(s0, max(1, d // 2))]

    def project_and_polish(x):
        nonlocal best, bestR
        cands = [np.clip(x, 0, None), np.abs(x)]
        shift = 0.5 * max(0.0, -float(x.min()))
        cands.append(np.clip(x + shift, 0, None))
        for xp in cands:
            if time.process_time() >= deadline - 1.0:
                return
            xp = _rescale_maxL(xp)
            if xp.sum() <= 0:
                continue
            xp = _exact_lbfgs(xp, 3000, 6000, deadline)
            r = R_of(xp)
            if r > bestR:
                best, bestR = xp.copy(), r
            if time.process_time() >= deadline - 1.0:
                return
            xp = _window_polish(xp, deadline, frac=0.35, extra=8, iters=2000)
            r = R_of(xp)
            if r > bestR:
                best, bestR = xp.copy(), r
            if time.process_time() >= deadline - 1.0:
                return
            xp = _exact_lbfgs(xp, 2000, 4000, deadline)
            r = R_of(xp)
            if r > bestR:
                best, bestR = xp.copy(), r

    si = 0
    max_rounds = 40
    while time.process_time() < deadline - 1.0 and si < max_rounds:
        seed = seeds[si % len(seeds)].copy()
        si += 1
        if si > len(seeds):
            amp = 0.03 * float(np.max(np.abs(seed)))
            seed = seed + amp * rng.standard_normal(seed.size)
        xs = _signed_lbfgs(seed, 3000, deadline)
        rs = _signed_R(xs)
        print(f"signed round {si} R_signed={rs:.6f}")
        if time.process_time() >= deadline - 1.0:
            break
        project_and_polish(xs)

    # Final full polish of the best, and a couple of window refinements.
    if time.process_time() < deadline - 0.5:
        hh = _exact_lbfgs(best, 4000, 8000, deadline)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh, r
    for sh in (-2, 0, 2):
        if time.process_time() >= deadline - 0.5:
            break
        hh = _window_polish(best, deadline, frac=0.25, extra=6, iters=2500, shift=sh)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

