def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Initial exact K=1 polish.
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    # Taper-band random-window loop.
    loop_deadline = t0 + budget_seconds * 0.95
    it = 0
    while time.process_time() < loop_deadline - 1.0:
        it += 1
        n = best.size
        Lf = _knots(best)
        M = Lf.max()
        if M <= 0:
            break
        idx = np.flatnonzero((Lf > 0.05 * M) & (Lf < 0.95 * M))
        if idx.size == 0:
            c = int(np.argmax(Lf))
        else:
            c = int(idx[rng.integers(0, idx.size)])
        w = int(n * rng.uniform(0.02, 0.20))
        if w < 4:
            w = 4
        lo = max(0, c - w // 2)
        hi = min(n - 1, c + w // 2)
        free = np.arange(lo, hi + 1)

        if time.process_time() >= loop_deadline - 1.0:
            break
        cand = _exact_lbfgs(best, 500, 1000, deadline, free=free)
        if time.process_time() < loop_deadline - 1.0:
            cand = _window_polish(cand, deadline, frac=0.30, extra=8)
        r = R_of(cand)
        if r > bestR + 1e-15:
            best, bestR = cand, r
            print("taper it%d c=%d w=%d R=%.7f" % (it, c, w, bestR))

        if it % 5 == 0 and time.process_time() < loop_deadline - 1.5:
            cand = _exact_lbfgs(best, 800, 1600, deadline)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                print("full it%d R=%.7f" % (it, bestR))

    if time.process_time() < deadline - 0.8:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

