    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = min(K, n)
    if K >= n:
        Lm = Lf.mean()
        gLf = -dq / num + (1.0 / (n * Lm)) * np.ones(n)
    else:
        idx = np.argpartition(Lf, n - K)[n - K:]
        Lm = Lf[idx].mean()
        gLf = -dq / num
        gLf[idx] += 1.0 / (K * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_lin(h0, K, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        return _topk_fun_grad(x, K)

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.clip(res.x, 0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _prolong_free(h, deadline, maxiter=400, maxfun=800):
    n = h.size
    m = 2 * n
    if time.process_time() >= deadline - 0.5:
        return np.repeat(h, 2) * 0.5

    def build(sv):
        s = 1.0 / (1.0 + np.exp(-np.clip(sv, -30, 30)))
        h2 = np.empty(m)
        h2[0::2] = h * (1.0 - s)
        h2[1::2] = h * s
        return h2, s

    def f(sv):
        h2, s = build(sv)
        val, g = _norm_eq_fun_grad(h2)
        gs = g[0::2] * (-h) + g[1::2] * h
        return val, gs * s * (1.0 - s)

    s0 = np.zeros(n)
    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, s0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    if res is None:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    h2, _ = build(res.x)
    return _rescale_maxL(h2)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _cum_mass_prolong(h, m):
    """Mass-preserving prolongation to m cells via cumulative-mass interpolation."""
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0.0, float(n), m + 1)
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _singular_seed(N0):
    """Cell-averaged t^-1/2 profile."""
    i = np.arange(N0, dtype=float)
    return 2.0 * np.sqrt(N0) * (np.sqrt(i + 1.0) - np.sqrt(i))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    # Fallback = start.
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ---- Experiment: spike-tail seeds ----
    N0 = 8192
    prof = _singular_seed(N0)
    idx = np.arange(N0, dtype=float)

    candidates = []
    for w in (1, 2, 4):
        for p in (0.50, 0.75, 0.90, 1.00):
            center = p * (N0 - 1)
            for A in (0.5, 1.0, 2.0, 4.0):
                # local profile height at center
                ci = int(round(center))
                ci = min(max(ci, 0), N0 - 1)
                local = prof[ci]
                spike = A * local * np.exp(-((idx - center) / float(w)) ** 2)
                h = prof + spike
                h = _rescale_maxL(h)
                candidates.append((h, w, p, A))

    # Score all at N0 with exact R, keep top few.
    scored = []
    for h, w, p, A in candidates:
        if time.process_time() >= deadline - 20.0:
            break
        scored.append((R_of(h), w, p, A, h))
    scored.sort(key=lambda t: -t[0])
    print("seed best R=%.7f (w=%d p=%.2f A=%.2f)" %
          (scored[0][0], scored[0][1], scored[0][2], scored[0][3]))

    # Polish top few at N0.
    polished = []
    for r0, w, p, A, h in scored[:4]:
        if time.process_time() >= deadline - 16.0:
            break
        hp = _exact_lbfgs(h, 2000, 4000, deadline)
        hp = _window_polish(hp, deadline, frac=0.3, extra=8)
        r = R_of(hp)
        polished.append((r, w, p, A, hp))
        print("polish w=%d p=%.2f A=%.2f R=%.7f" % (w, p, A, r))
    polished.sort(key=lambda t: -t[0])

    # Prolongate best two to N=42496.
    Ntarget = 42496
    for r, w, p, A, hp in polished[:2]:
        if time.process_time() >= deadline - 8.0:
            break
        hb = _cum_mass_prolong(hp, Ntarget)
        hb = _rescale_maxL(hb)
        hb = _exact_lbfgs(hb, 2000, 4000, deadline)
        hb = _window_polish(hb, deadline, frac=0.3, extra=8)
        r2 = R_of(hb)
        print("prolong w=%d p=%.2f A=%.2f R=%.7f" % (w, p, A, r2))
        if r2 > bestR + 1e-15:
            best, bestR = hb, r2
            print("spike-best R=%.7f" % bestR)

    # ---- Base pipeline (kept) ----
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 3.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale_maxL(hp)
        if hp.sum() <= 0:
            continue
        hp = _exact_lbfgs(hp, 1500, 3000, deadline)
        hp = _window_polish(hp, deadline, frac=0.3, extra=8)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("phase-best R=%.7f" % bestR)

    for K in (2000, 1000, 500, 200, 64, 20, 8, 3, 1):
        if time.process_time() >= deadline - 1.5:
            break
        h = _topk_lin(best, K, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("topk%d R=%.7f" % (K, bestR))

    if time.process_time() < deadline - 1.5:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)

    if time.process_time() < deadline - 1.5:
        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False

        if best.size * 2 <= 200000 and time.process_time() < deadline - 2.0:
            hp = _prolong_free(best, deadline)
            hp = _window_polish(hp, deadline, frac=0.3, extra=8)
            r = R_of(hp)
            if r > bestR + 1e-15:
                best, bestR = hp, r
                improved = True
                print("prol R=%.7f" % bestR)

        n = best.size
        for factor in (2, 3, 4):
            if n // factor < 64:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            hc = _downsample(best, factor)
            hc = _rescale_maxL(hc)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hc = _window_polish(hc, deadline, frac=0.4, extra=6)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hu = _rescale_maxL(_upsample(hc, factor))
            if hu.size != n:
                xo = np.linspace(0.0, hu.size - 1, n)
                hu = np.interp(xo, np.arange(hu.size), hu)
                hu = _rescale_maxL(hu)
            hu = _window_polish(hu, deadline, frac=0.35, extra=8)
            r = R_of(hu)
            if r > bestR + 1e-15:
                best, bestR = hu, r
                improved = True
                print("ds%d R=%.7f" % (factor, bestR))
                break

        if time.process_time() >= deadline - 1.5:
            break

        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if time.process_time() < deadline - 0.8:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _softmax_fun_grad(h, beta):
    """Smooth max via logsumexp with sharpness beta (stabilised)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    # logsumexp
    z = beta * Lf
    zmax = z.max()
    ez = np.exp(z - zmax)
    S = ez.sum()
    lse = zmax + np.log(S)
    # d/dx logsumexp(beta*L) = sum(softmax_i * beta * dL_i)
    w = ez / S
    gLf = -dq / num + (beta / (lse / beta)) * w  # careful scaling below
    # Actually we want d/dh [ log(mean_max) ] where mean_max ~ (1/beta) logsumexp(beta L)
    # d/dh log( (1/beta) lse ) = (1/lse) * beta * sum(w_i dL_i)
    gLf = -dq / num + (beta / lse) * w
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(lse / beta)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    if fun_grad is None:
        fg = _norm_eq_fun_grad
    else:
        fg = fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, fun_grad=None):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, fun_grad=fun_grad)


def _full_polish(h, deadline, iters=3000, fun_grad=None):
    return _exact_lbfgs(h, iters, 2 * iters, deadline, fun_grad=fun_grad)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage A: soft-max smoothing sweeps (new): progressively sharpen beta.
    # This escapes the hard-max kink that traps plain max-gradient polishing.
    for beta in (2.0, 10.0, 60.0, 300.0, 1500.0, 8000.0):
        if time.process_time() >= deadline - 1.0:
            break
        fg = (lambda h, b=beta: _softmax_fun_grad(h, b))
        h = _exact_lbfgs(best, 600, 1200, deadline, fun_grad=fg)
        r = R_of(h)
        print("soft beta=%.0f R=%.7f" % (beta, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        if time.process_time() >= deadline - 1.0:
            break
        hw = _window_polish(best, deadline, fun_grad=fg)
        rw = R_of(hw)
        if rw > bestR + 1e-15:
            best, bestR = hw.copy(), rw
            print("soft window R=%.7f" % bestR)

    # Stage B: alternating full/window polish with hard max until deadline.
    while time.process_time() < deadline - 1.0:
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
