import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad) + shift
    hi = min(n - 1, hi + pad) + shift
    lo = max(0, min(n - 1, lo))
    hi = max(0, min(n - 1, hi))
    if hi < lo:
        lo, hi = 0, n - 1
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _block_average(h, target):
    n = h.size
    if n <= target:
        return h.copy()
    factor = int(np.ceil(n / target))
    m = n // factor
    if m < 2:
        return h.copy()
    return h[:m * factor].reshape(m, factor).mean(axis=1)


def _resample_smooth(h, factor):
    n = h.size
    m = max(2, int(round(n * factor)))
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _sharpen(h, p):
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return h
    i = np.arange(n)
    q = 0.5 * (Lf[i + 1] + Lf[i + n])
    q = np.clip(q, 1e-300, None)
    alpha = (p - 1.0) / 2.0
    return h * (q / M) ** alpha


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    h = best.copy()
    c = 0
    Ks = [1, 2, 3, 4, 6, 8, 12]
    while time.process_time() < deadline - 1.0:
        for K in Ks:
            if time.process_time() >= deadline - 1.0:
                break
            h = _exact_lbfgs(h, 400, 800, deadline, K=K)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("cycle %d ladder R=%.7f" % (c, bestR))
        else:
            h = best.copy()

        if time.process_time() < deadline - 1.0:
            lo, hi = _peak_region(h)
            span = hi - lo
            shift = int(0.10 * span * c)
            h = _window_polish(h, deadline, frac=0.15, extra=4, shift=shift)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("cycle %d window R=%.7f" % (c, bestR))
            else:
                h = best.copy()

        if time.process_time() < deadline - 1.0:
            h = _exact_lbfgs(h, 300, 600, deadline, K=1)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("cycle %d K1 R=%.7f" % (c, bestR))
            else:
                h = best.copy()

        # Sharpen: modulate by local autoconvolution (p>1 sharpens peak plateau)
        if time.process_time() < deadline - 1.5:
            for p in (1.5, 2.0):
                cand = _rescale_maxL(_sharpen(best, p))
                cand = _exact_lbfgs(cand, 400, 800, deadline, K=1)
                rc = R_of(cand)
                if rc > bestR + 1e-15:
                    best, bestR = cand, rc
                    print("cycle %d sharpen p=%.1f R=%.7f" % (c, p, bestR))
                    break
            h = best.copy()

        if c % 3 == 2 and time.process_time() < deadline - 2.0:
            n = best.size
            if n * 2 <= 200000:
                cand = _rescale_maxL(_upsample(best, 2))
                cand = _exact_lbfgs(cand, 800, 1600, deadline, K=1)
                rc = R_of(cand)
                if rc >= bestR - 1e-12:
                    back = _rescale_maxL(_block_average(cand, n))
                    rb = R_of(back)
                    if rb > bestR + 1e-15:
                        best, bestR = back, rb
                        print("cycle %d upsample R=%.7f" % (c, bestR))
                    elif rc > bestR + 1e-15:
                        best, bestR = cand, rc
                        print("cycle %d upsample(full) R=%.7f" % (c, bestR))
                h = best.copy()

        if c % 5 == 4 and time.process_time() < deadline - 2.0:
            n = best.size
            if int(n * 1.5) <= 200000:
                cand = _rescale_maxL(_resample_smooth(best, 1.5))
                cand = _exact_lbfgs(cand, 600, 1200, deadline, K=1)
                rc = R_of(cand)
                if rc > bestR + 1e-15:
                    best, bestR = cand, rc
                    print("cycle %d fine15 R=%.7f" % (c, bestR))
                h = best.copy()

        c += 1

    if time.process_time() < deadline - 0.5:
        cand = _exact_lbfgs(best, 2000, 4000, deadline, K=1)
        rc = R_of(cand)
        if rc > bestR + 1e-15:
            best, bestR = cand, rc
            print("final polish R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

