    """Prolongate to a finer grid and re-optimise; keeps best."""
    n = h.size
    N2 = min(200000, n * factor)
    if N2 <= n:
        return h
    h2 = _prolongate(h, N2)
    h2 = _rescale_maxL(h2)
    h2 = _exact_lbfgs(h2, 1500, 3000, deadline)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Main new idea: refine resolution. The achievable R rises with N, so
    # repeatedly doubling the grid and re-optimising gives real gains.
    # Each refinement is cheap (prolongation is exact) and the L-BFGS pass
    # on the finer grid can find structure the coarse grid cannot.
    while best.size < 200000 and time.process_time() < deadline - 4.0:
        h = _refine_resolution(best, deadline, factor=2)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine N=%d R=%.7f" % (best.size, bestR))
        else:
            break

    # Window polish rounds on the (now finer) grid.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, frac=frac, extra=extra)
        h = _exact_lbfgs(h, 800, 1600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win(%.2f) R=%.7f" % (frac, bestR))

    # Final alternating full / window polish loop until time runs out.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _exact_lbfgs(best, 1200, 2400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline, frac=0.40, extra=24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

