    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _refine(h, deadline, rounds, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds

    if start is not None and len(start) > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(max(1, len(h)))
    else:
        h = np.ones(2000)

    best = h.copy()
    bestR = R_of(best)

    # Phase 1: full polish (all active heights), keeping the best.
    cand, r = _refine(best, deadline, rounds=6, free=None, maxiter=2000)
    if r > bestR:
        best, bestR = cand, r

    # Phase 2: window polish around the peak plateau.
    while time.process_time() < deadline - 2.0:
        cand = _window_polish(best, deadline)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
        else:
            break

    # Phase 3: alternate full and window refinement until near deadline.
    while time.process_time() < deadline - 1.5:
        cand = _exact_lbfgs(best, 2000, 4000, deadline, free=None)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        cand = _window_polish(best, deadline)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        else:
            if time.process_time() >= deadline - 3.0:
                break

    best = np.clip(best, 0, None)
    if best.sum() <= 0:
        best = np.ones(max(1, len(best)))
    return best

