    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _upsample(h, factor):
    if factor <= 1:
        return h
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    m = n * factor
    edges = np.arange(m + 1, dtype=float) / factor
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    h2 = np.diff(Cq) * factor
    return np.clip(h2, 0, None)


def _downsample(h, factor):
    if factor <= 1:
        return h
    n = h.size
    m = n // factor
    if m <= 0:
        return h
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: refine the inherited construction heavily.
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    for frac, extra in ((0.15, 6), (0.30, 12), (0.50, 24), (0.75, 48)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, frac=frac, extra=extra)
        h = _exact_lbfgs(h, 800, 1600, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win(%.2f) R=%.7f" % (frac, bestR))

    # Phase 2: upsample to a finer grid and re-optimise there. This is the
    # substantial new move: a finer discretisation can resolve the peak
    # plateau better, unlocking R that the coarse grid cannot represent.
    for factor in (2, 2):
        if time.process_time() >= deadline - 2.0:
            break
        if best.size * factor > 200000:
            break
        up = _upsample(best, factor)
        up = _rescale_maxL(up)
        # few Polish iterations on the finer grid.
        up = _exact_lbfgs(up, 1500, 3000, deadline)
        r = R_of(up)
        if r > bestR + 1e-15:
            best, bestR = up, r
            print("upsample x%d R=%.7f (N=%d)" % (factor, bestR, best.size))
        # window polish around the peak on the finer grid.
        if time.process_time() < deadline - 2.0:
            up2 = _window_polish(up, deadline, frac=0.35, extra=24)
            r2 = R_of(up2)
            if r2 > bestR + 1e-15:
                best, bestR = up2, r2
                print("upsample win R=%.7f" % bestR)

    # Phase 3: phase exploration on current best.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale_maxL(hp)
        if hp.sum() <= 0:
            continue
        hp = _exact_lbfgs(hp, 1000, 2000, deadline)
        hp = _window_polish(hp, deadline, frac=0.35, extra=16)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Phase 4: alternate full/wide-window polish until stall.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _exact_lbfgs(best, 1200, 2400, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline, frac=0.40, extra=24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _refine(h, deadline, rounds, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _loss_runs(h, top_cells=300, max_run=12):
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return []
    w = np.zeros(n)
    idx1 = np.arange(1, n + 1)
    idx1 = idx1[idx1 < Lf.size]
    w[idx1 - 1] += Lf[idx1] * (M - Lf[idx1])
    idx2 = np.arange(n, 2 * n)
    valid2 = idx2 < Lf.size
    idx2v = idx2[valid2]
    w[idx2v - n] += Lf[idx2v] * (M - Lf[idx2v])
    if top_cells < n:
        order = np.argsort(w)[::-1][:top_cells]
        sel = np.zeros(n, dtype=bool)
        sel[order] = True
    else:
        sel = np.ones(n, dtype=bool)
    cells = np.flatnonzero(sel)
    runs = []
    if cells.size == 0:
        return runs
    start = cells[0]
    prev = cells[0]
    for c in cells[1:]:
        if c == prev + 1 and (c - start + 1) <= max_run:
            prev = c
        else:
            runs.append(np.arange(start, prev + 1))
            start = c
            prev = c
    runs.append(np.arange(start, prev + 1))
    return runs


def _perturb_zero_add(h, frac, c):
    """Zero the smallest `frac` of heights, then add c*mean(h) to all cells."""
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    n = h.size
    if n == 0:
        return h
    k = int(round(frac * n))
    h2 = h.copy()
    if k > 0:
        order = np.argsort(h2)
        h2[order[:k]] = 0.0
    m = h2.mean()
    h2 = h2 + c * m
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # EXPERIMENT: zero smallest 10% of heights, then add c*mean(h).
    for c in (0.01, 0.05, 0.1, 0.2):
        if time.process_time() >= deadline - 2.0:
            break
        h2 = _perturb_zero_add(best, 0.10, c)
        r2 = R_of(h2)
        # Refine the perturbation with a short full L-BFGS pass.
        h3, r3 = _refine(h2, deadline, rounds=1, maxiter=400)
        if r3 > r2:
            h2, r2 = h3, r3
        print("perturb c=%.2f R=%.7f (base %.7f)" % (c, r2, bestR))
        if r2 > bestR + 1e-16:
            best, bestR = h2, r2
            print("  new best R=%.7f" % bestR)

    # Continue the base's polishing loop on the (possibly improved) best.
    if time.process_time() < deadline - 2.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    for sweep in range(2):
        if time.process_time() >= deadline - 2.0:
            break
        runs = _loss_runs(best, top_cells=300, max_run=12)
        improved = False
        for run in runs:
            if time.process_time() >= deadline - 2.0:
                break
            cand = _block_lbfgs_linear(best, run, maxiter=40, deadline=deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
        print("loss-sweep %d R=%.7f improved=%s" % (sweep + 1, bestR, improved))
        if not improved:
            break

    if time.process_time() < deadline - 2.0:
        cand = _exact_lbfgs(best, 400, 800, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("post-polish R=%.7f" % bestR)

    while time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1200)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("full R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

