            best, bestR = cand, r
    return best, bestR


def _local_bump(h, deadline, frac, scale_lo=0.3, scale_hi=3.0):
    """Perturb a fraction `frac` of the largest heights multiplicatively and refine."""
    if time.process_time() >= deadline - 1.0:
        return h, R_of(h)
    n = h.size
    h2 = h.copy()
    k = max(1, int(frac * n))
    idx = np.argsort(h)[::-1][:k]
    rng = np.random.RandomState(int(time.process_time() * 1e6) & 0x7fffffff)
    fac = np.exp(rng.uniform(np.log(scale_lo), np.log(scale_hi), size=k))
    h2[idx] *= fac
    h2 = _rescale_maxL(h2)
    cand, r = _refine(h2, deadline, rounds=1, maxiter=800)
    return cand, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            bestR = 0.0
            best = None
    else:
        bestR = 0.0
        best = None

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Full exact refine to converge the start.
    if time.process_time() < deadline - 2.0:
        h, r = _refine(best, deadline, rounds=3, maxiter=2000)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("refine R=%.7f" % bestR)

    # Multi-scale perturbation search: try different perturbation sizes,
    # keeping the best. This escapes shallow local optima of L-BFGS.
    fracs = [0.01, 0.03, 0.08, 0.15, 0.3]
    tries = 0
    while time.process_time() < deadline - 2.0:
        frac = fracs[tries % len(fracs)]
        tries += 1
        cand, r = _local_bump(best, deadline, frac)
        if r > bestR + 1e-15:
            best, bestR = cand, r
            print("bump f=%.2f R=%.7f (try %d)" % (frac, bestR, tries))
        else:
            # even if not better, occasionally re-refine globally to polish
            if tries % 4 == 0 and time.process_time() < deadline - 3.0:
                h, r = _refine(best, deadline, rounds=1, maxiter=1500)
                if r > bestR + 1e-15:
                    best, bestR = h, r
                    print("polish R=%.7f" % bestR)

    # Final polish.
    if time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=2, maxiter=2000)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("final refine R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _smooth(h, sigma):
    if sigma <= 0:
        return h.copy()
    r = int(np.ceil(3 * sigma))
    x = np.arange(-r, r + 1)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    if r > 0 and h.size > r:
        hp = np.concatenate((h[r:0:-1], h, h[-2:-r - 2:-1]))
    else:
        hp = h
    out = np.convolve(hp, k, mode='valid')
    if out.size != h.size:
        out = out[:h.size]
        if out.size < h.size:
            out = np.concatenate((out, h[out.size:]))
    return np.clip(out, 0, None)


def _perturb_smooth(h, deadline, sigma, amp, rng):
    n = h.size
    eps = rng.standard_normal(n) * amp
    eps = _smooth(eps, sigma)
    h2 = h * np.exp(eps)
    h2 = _rescale_maxL(h2)
    h2 = _full_polish(h2, deadline, iters=1500)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Stage B: full polish from start.
    h = _full_polish(best, deadline, iters=2000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h.copy(), r
        print("full R=%.7f" % bestR)

    # Stage C: alternating window/full polish.
    while time.process_time() < deadline - 1.0:
        h = _window_polish(best, deadline, frac=0.20, extra=6)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            print("full2 R=%.7f" % bestR)
        else:
            break

    # Stage D: basin hopping with smooth perturbations, refined acceptance.
    rng = np.random.default_rng(20240517)
    n = best.size
    sigmas = [max(2.0, n * 0.01), max(3.0, n * 0.03),
              max(5.0, n * 0.07), max(8.0, n * 0.15)]
    amps = [0.005, 0.015, 0.04, 0.08, 0.15]
    tries = 0
    while time.process_time() < deadline - 1.0:
        sig = sigmas[tries % len(sigmas)]
        amp = amps[(tries // len(sigmas)) % len(amps)]
        tries += 1
        cand = _perturb_smooth(best, deadline, sig, amp, rng)
        r = R_of(cand)
        if r > bestR + 1e-15:
            cand2 = _full_polish(cand, deadline, iters=1500)
            r2 = R_of(cand2)
            if r2 > r:
                cand, r = cand2, r2
            best, bestR = cand.copy(), r
            print("hop sig=%.1f amp=%.3f R=%.7f" % (sig, amp, bestR))

    # Final polish in remaining time.
    h = _full_polish(best, deadline, iters=3000)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r
    h = _window_polish(best, deadline, frac=0.3, extra=8)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r

    best = _rescale_maxL(best)
    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

