            r_prol = R_of(h_prol)
            print("DE prol R=%.7f" % r_prol)
            # polish pipeline: exact L-BFGS + loss-weighted block moves
            if time.process_time() < deadline - 1.5:
                h_pol = _exact_lbfgs(h_prol, 1500, 3000, deadline)
                r_pol = R_of(h_pol)
                print("DE polish R=%.7f" % r_pol)
                if time.process_time() < deadline - 1.0:
                    h_pol = _loss_weighted_block_moves(h_pol, deadline, rounds=3)
                    r_pol = R_of(h_pol)
                    print("DE blocks R=%.7f" % r_pol)
                if r_pol > bestR + 1e-15:
                    best, bestR = h_pol, r_pol
                    print("DE-best R=%.7f" % bestR)

    # One exact K=1 polish before phase exploration.
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    # Phase-lifted candidates.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 3.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale_maxL(hp)
        if hp.sum() <= 0:
            continue
        hp = _exact_lbfgs(hp, 1500, 3000, deadline)
        hp = _window_polish(hp, deadline, frac=0.3, extra=8)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("phase-best R=%.7f" % bestR)

    # Top-K surrogate sweep in linear coordinates.
    for K in (2000, 1000, 500, 200, 64, 20, 8, 3, 1):
        if time.process_time() >= deadline - 1.5:
            break
        h = _topk_lin(best, K, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("topk%d R=%.7f" % (K, bestR))

    if time.process_time() < deadline - 1.5:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)

    if time.process_time() < deadline - 1.5:
        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False

        if best.size * 2 <= 200000 and time.process_time() < deadline - 2.0:
            hp = _prolong_free(best, deadline)
            hp = _window_polish(hp, deadline, frac=0.3, extra=8)
            r = R_of(hp)
            if r > bestR + 1e-15:
                best, bestR = hp, r
                improved = True
                print("prol R=%.7f" % bestR)

        n = best.size
        for factor in (2, 3, 4):
            if n // factor < 64:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            hc = _downsample(best, factor)
            hc = _rescale_maxL(hc)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hc = _window_polish(hc, deadline, frac=0.4, extra=6)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hu = _rescale_maxL(_upsample(hc, factor))
            if hu.size != n:
                xo = np.linspace(0.0, hu.size - 1, n)
                hu = np.interp(xo, np.arange(hu.size), hu)
                hu = _rescale_maxL(hu)
            hu = _window_polish(hu, deadline, frac=0.35, extra=8)
            r = R_of(hu)
            if r > bestR + 1e-15:
                best, bestR = hu, r
                improved = True
                print("ds%d R=%.7f" % (factor, bestR))
                break

        if time.process_time() >= deadline - 1.5:
            break

        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if time.process_time() < deadline - 0.8:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    np.random.seed(12345)

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
        else:
            best = None
    else:
        best = None

    if best is None:
        N = 32000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)

    bestR = R_of(best)
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: full exact polish of the start with generous budget.
    if time.process_time() < deadline - 2.0:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("full R=%.7f" % bestR)

    # Phase 2: repeated window polish at decreasing widths, alternating peak regions.
    round_i = 0
    while time.process_time() < deadline - 1.5:
        round_i += 1
        improved = False
        for frac, extra in ((0.35, 10), (0.25, 8), (0.15, 6), (0.08, 4), (0.04, 3)):
            if time.process_time() >= deadline - 1.5:
                break
            cand = _window_polish(best, deadline, frac=frac, extra=extra)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
                print("win%.2f R=%.7f" % (frac, bestR))
        # Random small perturbation of peak to escape a shallow local max.
        if not improved and time.process_time() < deadline - 2.0:
            lo, hi = _peak_region(best)
            pad = max(8, (hi - lo) // 3)
            lo = max(0, lo - pad)
            hi = min(best.size - 1, hi + pad)
            cand = best.copy()
            seg = cand[lo:hi + 1]
            noise = 1.0 + 0.01 * np.random.randn(seg.size)
            cand[lo:hi + 1] = np.clip(seg * noise, 0, None)
            cand = _rescale_maxL(cand)
            cand = _window_polish(cand, deadline, frac=0.30, extra=8)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("pert R=%.7f" % bestR)
            else:
                # no improvement: try full exact polish
                cand = _exact_lbfgs(best, 2000, 4000, deadline)
                r = R_of(cand)
                if r > bestR + 1e-16:
                    best, bestR = cand, r
                    print("full2 R=%.7f" % bestR)
                else:
                    break
        if round_i > 40:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

