def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _linear_lbfgs(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0,
                   linear=False):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    if linear:
        return _linear_lbfgs(h, free, iters, deadline)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _plateau_polish(h, deadline, iters=800):
    """Directly attack the flat top: equalize knots near the max by
    linear-space L-BFGS on a band around the peak, which is what limits R."""
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return h
    # band of knots close to the max defines where f*f must be flattened
    idx = np.flatnonzero(Lf >= 0.995 * M)
    if idx.size < 2:
        return h
    lo_k = idx.min()
    hi_k = idx.max()
    # knots index j correspond to h indices roughly [j-1, j]; widen a bit
    lo = max(0, lo_k - n // 8)
    hi = min(n - 1, hi_k + n // 8)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _linear_lbfgs(h, free, iters, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    shifts = [0, 1, -1, 2, -2, 3, -3]
    si = 0

    # Main loop: alternate global log-space, peak-window (log & linear),
    # and plateau-targeted linear polish. Linear-space steps are the key
    # change: they let heights near the flat top move freely to raise R.
    while time.process_time() < deadline - 2.0:
        cand = _exact_lbfgs(best, 800, 1600, deadline)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
        if time.process_time() >= deadline - 1.0:
            break

        sh = shifts[si % len(shifts)]
        si += 1
        cand = _window_polish(best, deadline, frac=0.25, extra=8,
                              iters=1200, shift=sh, linear=False)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

        cand = _window_polish(best, deadline, frac=0.35, extra=12,
                              iters=1000, shift=sh, linear=True)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

        cand = _plateau_polish(best, deadline, iters=800)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    # Final push: full linear-space and log-space polish near the end.
    if time.process_time() < deadline - 0.5:
        cand = _exact_lbfgs(best, 2500, 5000, deadline)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r
    if time.process_time() < deadline - 0.3:
        n = best.size
        free = np.arange(n)
        cand = _linear_lbfgs(best, free, 400, deadline)
        r = R_of(cand)
        if r > bestR:
            best, bestR = cand, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve
from scipy.interpolate import PchipInterpolator


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = min(K, n)
    if K >= n:
        Lm = Lf.mean()
        gLf = -dq / num + (1.0 / (n * Lm)) * np.ones(n)
    else:
        idx = np.argpartition(Lf, n - K)[n - K:]
        Lm = Lf[idx].mean()
        gLf = -dq / num
        gLf[idx] += 1.0 / (K * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_lin(h0, K, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        return _topk_fun_grad(x, K)

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.clip(res.x, 0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _downsample(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hh = h[:m * factor].reshape(m, factor)
    return hh.mean(axis=1)


def _prolong_free(h, deadline, maxiter=400, maxfun=800):
    n = h.size
    m = 2 * n
    if time.process_time() >= deadline - 0.5:
        return np.repeat(h, 2) * 0.5

    def build(sv):
        s = 1.0 / (1.0 + np.exp(-np.clip(sv, -30, 30)))
        h2 = np.empty(m)
        h2[0::2] = h * (1.0 - s)
        h2[1::2] = h * s
        return h2, s

    def f(sv):
        h2, s = build(sv)
        val, g = _norm_eq_fun_grad(h2)
        gs = g[0::2] * (-h) + g[1::2] * h
        return val, gs * s * (1.0 - s)

    s0 = np.zeros(n)
    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, s0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    if res is None:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    h2, _ = build(res.x)
    return _rescale_maxL(h2)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


# ---- Monotone cumulative-sum DE stage ----

def _build_h_from_controls(c, N):
    K = c.size
    xc = np.linspace(0.0, 1.0, K)
    c = np.maximum.accumulate(np.clip(c, 0.0, None))
    if c[-1] <= 0:
        c[-1] = 1.0
    c = c / c[-1]
    try:
        pch = PchipInterpolator(xc, c)
    except Exception:
        return None
    xs = np.linspace(0.0, 1.0, N + 1)
    S = pch(xs)
    S = np.maximum.accumulate(np.clip(S, 0.0, None))
    h = np.diff(S)
    return h


def _prolongate(h_small, N):
    n = h_small.size
    if n == N:
        return h_small.copy()
    xo = np.linspace(0.0, n - 1, N)
    return np.interp(xo, np.arange(n), h_small)


def _monotone_de_stage(deadline, N_small=2048, K=10, seed=12345):
    if time.process_time() >= deadline - 1.0:
        return None

    def obj(c):
        h = _build_h_from_controls(np.asarray(c), N_small)
        if h is None or h.sum() <= 0:
            return 1.0
        return -R_of(h)

    bounds = [(0.0, 1.0)] * K
    best_h = None
    best_r = -1.0
    try:
        res = differential_evolution(
            obj, bounds, seed=seed, popsize=20, maxiter=60,
            tol=1e-10, polish=False, init='latinhypercube',
            updating='immediate', workers=1)
        h = _build_h_from_controls(res.x, N_small)
        if h is not None and h.sum() > 0:
            r = R_of(h)
            if r > best_r:
                best_r = r
                best_h = h
    except Exception:
        pass
    return best_h


def _loss_weighted_block_moves(h, deadline, rounds=3):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        lo, hi = _peak_region(h)
        blocks = []
        span = max(1, hi - lo)
        for frac in (0.5, 0.25, 0.12, 0.06):
            w = max(8, int(span * frac))
            blocks.append((max(0, lo - w // 2), min(n - 1, hi + w // 2)))
        rng = np.random.RandomState(1234 + _)
        for _k in range(2):
            a = rng.randint(0, max(1, n - 32))
            blocks.append((a, min(n - 1, a + 64)))
        for (a, b) in blocks:
            if time.process_time() >= deadline - 0.5:
                break
            free = np.arange(a, b + 1)
            h = _exact_lbfgs(h, 200, 400, deadline, free=free)
    return h


# ---- NEW: gap-opening experiment ----

def _find_interior_zero_runs(h, min_len=4):
    """Return list of (start, end_exclusive) of runs of >=min_len zeros strictly inside support."""
    nz = h > 0
    if not nz.any():
        return []
    first = int(np.argmax(nz))
    last = n - 1 - int(np.argmax(nz[::-1]))
    runs = []
    i = first
    while i <= last:
        if h[i] == 0.0:
            j = i
            while j <= last and h[j] == 0.0:
                j += 1
            if j - i >= min_len:
                runs.append((i, j))
            i = j
        else:
            i += 1
    return runs


def _open_gap(h, a, b):
    """Replace h[a:b] with linear interpolation between h[a-1] and h[b]."""
    h2 = h.copy()
    left = h[a - 1] if a - 1 >= 0 else 0.0
    right = h[b] if b < h.size else 0.0
    L = b - a
    for k in range(L):
        t = (k + 1) / (L + 1)
        h2[a + k] = left * (1.0 - t) + right * t
    return h2


def _gap_opening_stage(best, bestR, deadline, pad=16, topk=20):
    """Try opening each of the top-k longest interior zero runs, locally re-polish, accept strict gains."""
    n = best.size
    runs = _find_interior_zero_runs(best, min_len=4)
    if not runs:
        print("gap: no interior zero runs found")
        return best, bestR
    runs.sort(key=lambda r: (r[1] - r[0]), reverse=True)
    runs = runs[:topk]
    print("gap: %d interior zero runs (top %d)" % (len(runs), len(runs)))

    for (a, b) in runs:
        if time.process_time() >= deadline - 1.0:
            break
        h_open = _open_gap(best, a, b)
        h_open = _rescale_maxL(h_open)
        lo = max(0, a - pad)
        hi = min(n - 1, b + pad)
        free = np.arange(lo, hi + 1)
        h_pol = _exact_lbfgs(h_open, 400, 800, deadline, free=free)
        r_pol = R_of(h_pol)
        if r_pol > bestR + 1e-15:
            best, bestR = h_pol, r_pol
            print("gap[%d:%d] ACCEPT R=%.7f" % (a, b, bestR))
        else:
            print("gap[%d:%d] reject R=%.7f" % (a, b, r_pol))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- Gap-opening experiment: try to fill interior zero runs ---
    if time.process_time() < deadline - 3.0:
        best, bestR = _gap_opening_stage(best, bestR, deadline - 2.0,
                                         pad=16, topk=20)
        print("after gap stage R=%.7f" % bestR)

    # --- Base pipeline: monotone DE on sparse start ---
    if time.process_time() < deadline - 3.0:
        N_target = best.size
        h_small = _monotone_de_stage(deadline, N_small=2048, K=10, seed=12345)
        if h_small is not None:
            r_small = R_of(h_small)
            print("DE small R=%.7f (N=%d)" % (r_small, h_small.size))
            h_prol = _prolongate(h_small, N_target)
            h_prol = _rescale_maxL(h_prol)
            r_prol = R_of(h_prol)
            print("DE prol R=%.7f" % r_prol)
            if time.process_time() < deadline - 1.5:
                h_pol = _exact_lbfgs(h_prol, 1500, 3000, deadline)
                r_pol = R_of(h_pol)
                print("DE polish R=%.7f" % r_pol)
                if time.process_time() < deadline - 1.0:
                    h_pol = _loss_weighted_block_moves(h_pol, deadline, rounds=3)
                    r_pol = R_of(h_pol)
                    print("DE blocks R=%.7f" % r_pol)
                if r_pol > bestR + 1e-15:
                    best, bestR = h_pol, r_pol
                    print("DE-best R=%.7f" % bestR)

    # One exact K=1 polish before phase exploration.
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    # Phase-lifted candidates.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 3.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale_maxL(hp)
        if hp.sum() <= 0:
            continue
        hp = _exact_lbfgs(hp, 800, 1600, deadline)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("phase %.2f R=%.7f" % (delta, bestR))

    # Final full-space polish + window polish.
    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final full R=%.7f" % bestR)
    if time.process_time() < deadline - 0.5:
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final window R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _topk_meanmax_fun_grad(h, K):
    """Objective: -log(num) + 2 log(s) + log(mean of top-K knots of L)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    if K >= n:
        idx = np.arange(n)
    else:
        idx = np.argpartition(Lf, n - K)[n - K:]
    Ltop = Lf[idx]
    mean_top = Ltop.mean()
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += 1.0 / (K * mean_top)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _topk_lbfgs(h0, K, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _topk_meanmax_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _window_polish(h, deadline, frac=0.30, maxiter=800):
    """Polish a window of width frac*N around the argmax of f*f."""
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # map knot index to cell index roughly
    c = min(max(m - 1, 0), n - 1)
    half = max(int(frac * n / 2), 4)
    lo = max(c - half, 0)
    hi = min(c + half, n)
    free = np.arange(lo, hi)
    if free.size == 0:
        return h
    return _exact_lbfgs(h, maxiter, 2 * maxiter, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # initial exact polish
    if time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 2000, 4000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("init exact R=%.7f" % bestR)

    ladder = [1024, 512, 256, 128, 64, 32, 16, 8, 4, 2, 1]

    # iterate the whole ladder until budget nearly exhausted
    while time.process_time() < deadline - 3.0:
        any_gain = False
        for K in ladder:
            if time.process_time() >= deadline - 2.5:
                break
            cand = _topk_lbfgs(best, K, 600, deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                any_gain = True
                print("K=%d R=%.7f" % (K, bestR))
            if time.process_time() >= deadline - 2.5:
                break
            cand = _exact_lbfgs(best, 800, 1600, deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                any_gain = True
                print("K=%d exact R=%.7f" % (K, bestR))
        if not any_gain:
            # one more full-ladder pass already done; break to final polish
            break

    # final exact polish
    if time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("final exact R=%.7f" % bestR)

    # window polish to the deadline
    while time.process_time() < deadline - 0.8:
        cand = _window_polish(best, deadline, frac=0.30, maxiter=800)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("window R=%.7f" % bestR)
        else:
            # try a narrower window
            cand = _window_polish(best, deadline, frac=0.10, maxiter=600)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("window10 R=%.7f" % bestR)
            else:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _floor(h, f):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    m = h.mean()
    if m <= 0:
        return h
    return h + f * m * (h <= 0)


def _prune(h, eps):
    h = np.clip(np.asarray(h, dtype=float), 0, None)
    mx = h.max()
    if mx <= 0:
        return h
    h2 = np.where(h <= eps * mx, 0.0, h)
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 3.5
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    floors = (1e-5, 3e-5, 1e-4, 3e-4, 1e-3, 3e-3, 1e-2)
    prunes = (1e-7, 1e-6, 1e-5, 1e-4, 3e-4)

    def try_candidate(hh, tag):
        nonlocal best, bestR
        if time.process_time() >= deadline - 1.5:
            return False
        hh = _exact_lbfgs(hh, 1200, 2400, deadline)
        if time.process_time() < deadline - 1.0:
            hh = _window_polish(hh, deadline, frac=0.25, extra=8, iters=800)
        r = R_of(hh)
        if r > bestR + 1e-12:
            best, bestR = hh, r
            print(f"gain {tag} R={bestR:.7f}")
            return True
        return False

    def sweep():
        gained = False
        for f in floors:
            if time.process_time() >= deadline - 1.5:
                return gained
            hh = _floor(best, f)
            if try_candidate(hh, f"floor={f:g}"):
                gained = True
        for eps in prunes:
            if time.process_time() >= deadline - 1.5:
                return gained
            hh = _prune(best, eps)
            if try_candidate(hh, f"prune={eps:g}"):
                gained = True
        return gained

    while time.process_time() < deadline - 1.5:
        if sweep():
            continue
        # No gain in a full sweep: perturb small/zero cells and retry.
        if time.process_time() >= deadline - 1.5:
            break
        hp = best.copy()
        mx = hp.max()
        if mx <= 0:
            break
        mask = hp < 1e-3 * mx
        if not np.any(mask):
            break
        noise = rng.standard_normal(hp.size)
        k = max(3, hp.size // 200)
        kern = np.ones(k) / k
        noise = np.convolve(noise, kern, mode='same')
        hp[mask] = hp[mask] * np.exp(1e-3 * noise[mask])
        hp = _rescale_maxL(hp)
        hh = _exact_lbfgs(hp, 1200, 2400, deadline)
        r = R_of(hh)
        if r > bestR + 1e-12:
            best, bestR = hh, r
            print(f"gain noise R={bestR:.7f}")

    if time.process_time() < deadline - 0.5:
        hh = _exact_lbfgs(best, 2500, 5000, deadline)
        r = R_of(hh)
        if r > bestR:
            best, bestR = hh, r

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

