        res = minimize(f, s0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    if res is None:
        h2 = np.repeat(h, 2) * 0.5
        return _rescale_maxL(h2)
    h2, _ = build(res.x)
    return _rescale_maxL(h2)


def _phase_shift(h, delta):
    """Shift mass profile by delta cells via cumulative-mass reinterpolation."""
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _find_zero_runs(h, min_len=4, topk=20):
    """Find runs of >=min_len exactly-zero cells strictly inside nonzero support."""
    nz = np.flatnonzero(h > 0)
    if nz.size < 2:
        return []
    lo = nz[0]
    hi = nz[-1]
    runs = []
    i = lo
    while i <= hi:
        if h[i] == 0:
            j = i
            while j <= hi and h[j] == 0:
                j += 1
            length = j - i
            if length >= min_len and i > lo and j <= hi:
                runs.append((i, j, length))
            i = j
        else:
            i += 1
    runs.sort(key=lambda r: -r[2])
    return runs[:topk]


def _fill_run(h, i, j, alpha):
    """Replace h[i:j] with linear interpolation between bounding heights, scaled by alpha."""
    h2 = h.copy()
    left = h[i - 1]
    right = h[j]
    m = j - i
    t = (np.arange(1, m + 1, dtype=float)) / (m + 1.0)
    interp = left * (1.0 - t) + right * t
    h2[i:j] = alpha * interp
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Experiment: fill longest interior zero runs and re-polish.
    if time.process_time() < deadline - 3.0:
        runs = _find_zero_runs(best, min_len=4, topk=20)
        print("zero runs found: %d" % len(runs))
        for alpha in (0.1, 0.5, 1.0):
            if time.process_time() >= deadline - 2.5:
                break
            hc = best.copy()
            for (i, j, length) in runs:
                hc = _fill_run(hc, i, j, alpha)
            hc = _rescale_maxL(hc)
            if hc.sum() <= 0:
                continue
            hc = _exact_lbfgs(hc, 2000, 4000, deadline)
            hc = _window_polish(hc, deadline, frac=0.3, extra=8)
            r = R_of(hc)
            print("fill alpha=%.2f R=%.7f" % (alpha, r))
            if r > bestR + 1e-15:
                best, bestR = hc, r
                print("fill-best R=%.7f" % bestR)

    # One exact K=1 polish before phase exploration.
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    # Phase-lifted candidates.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 3.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale_maxL(hp)
        if hp.sum() <= 0:
            continue
        hp = _exact_lbfgs(hp, 1500, 3000, deadline)
        hp = _window_polish(hp, deadline, frac=0.3, extra=8)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("phase-best R=%.7f" % bestR)

    # Top-K surrogate sweep in linear coordinates.
    for K in (2000, 1000, 500, 200, 64, 20, 8, 3, 1):
        if time.process_time() >= deadline - 1.5:
            break
        h = _topk_lin(best, K, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("topk%d R=%.7f" % (K, bestR))

    if time.process_time() < deadline - 1.5:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)

    if time.process_time() < deadline - 1.5:
        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win R=%.7f" % bestR)

    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False

        if best.size * 2 <= 200000 and time.process_time() < deadline - 2.0:
            hp = _prolong_free(best, deadline)
            hp = _window_polish(hp, deadline, frac=0.3, extra=8)
            r = R_of(hp)
            if r > bestR + 1e-15:
                best, bestR = hp, r
                improved = True
                print("prol R=%.7f" % bestR)

        n = best.size
        for factor in (2, 3, 4):
            if n // factor < 64:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            hc = _downsample(best, factor)
            hc = _rescale_maxL(hc)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hc = _window_polish(hc, deadline, frac=0.4, extra=6)
            hc = _exact_lbfgs(hc, 600, 1200, deadline)
            hu = _rescale_maxL(_upsample(hc, factor))
            if hu.size != n:
                xo = np.linspace(0.0, hu.size - 1, n)
                hu = np.interp(xo, np.arange(hu.size), hu)
                hu = _rescale_maxL(hu)
            hu = _window_polish(hu, deadline, frac=0.35, extra=8)
            r = R_of(hu)
            if r > bestR + 1e-15:
                best, bestR = hu, r
                improved = True
                print("ds%d R=%.7f" % (factor, bestR))
                break

        if time.process_time() >= deadline - 1.5:
            break

        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("full R=%.7f" % bestR)

        if time.process_time() >= deadline - 1.5:
            break

        h = _window_polish(best, deadline, frac=0.3, extra=8)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
            print("win R=%.7f" % bestR)

        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    if time.process_time() < deadline - 0.8:
        h = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _coarse_from_fine(h, Nc):
    """Mass-preserving coarsening: cumulative interpolation from fine to coarse."""
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ----- Coarse-to-fine multigrid: optimise on a coarse representation,
    # then prolongate back. This escapes fine-scale local minima that
    # single-resolution L-BFGS cannot. -----
    N_fine = best.size
    scales = [N_fine // 4, N_fine // 2, N_fine]
    scales = [s for s in scales if s >= 16]
    for Nc in scales:
        if time.process_time() >= deadline - 3.0:
            break
        if Nc >= N_fine:
            h_c = best.copy()
        else:
            h_c = _coarse_from_fine(best, Nc)
        h_c = _rescale_maxL(h_c)
        # optimise at coarse resolution (cheap, many iterations)
        sub_deadline = min(deadline - 2.0, time.process_time() + (deadline - time.process_time()) * 0.35)
        h_opt, r_opt = _refine(h_c, sub_deadline, rounds=1, maxiter=3000)
        # prolongate back to fine and refine
        if Nc < N_fine:
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("multigrid N=%d->%d R=%.7f" % (Nc, N_fine, bestR))
        else:
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ----- Fine-scale polish: full L-BFGS then sliding-window. -----
    if time.process_time() < deadline - 2.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine R=%.7f" % bestR)
        h, r = _window_polish(best, deadline, window=64, stride=32, maxiter=60)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("window R=%.7f" % bestR)

    # ----- Use remaining budget alternating multigrid + window polish. -----
    scale_idx = 0
    while time.process_time() < deadline - 1.0:
        Nc = scales[scale_idx % len(scales)]
        scale_idx += 1
        sub_deadline = min(deadline - 1.0, time.process_time() + 1.5)
        if Nc < N_fine:
            h_c = _coarse_from_fine(best, Nc)
            h_c = _rescale_maxL(h_c)
            h_opt, _ = _refine(h_c, sub_deadline, rounds=1, maxiter=800)
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("mg-loop R=%.7f" % bestR)
        else:
            h, r = _refine(best, sub_deadline, rounds=1, maxiter=800)
            if r > bestR + 1e-16:
                best, bestR = h, r
                print("mg-loop R=%.7f" % bestR)
        if time.process_time() < deadline - 1.0:
            h, r = _window_polish(best, deadline, window=48, stride=24, maxiter=40)
            if r > bestR + 1e-16:
                best, bestR = h, r
                print("win-loop R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

