    return _rescale_maxL(h2)


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 1.0:
        return h
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - 1 - (n - 1))
    hi = min(n - 1, m - 1)
    if hi < lo:
        return h
    pad = max(extra, int((hi - lo) * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 800, 1600, deadline, free=free)


def _unzero(h, frac):
    h = np.asarray(h, dtype=float)
    m = h.mean()
    out = h.copy()
    out[h <= 0] += frac * m
    return out


def _local_pair_gradient(h, rng, nsample, step):
    n = h.size
    if n < 2:
        return h
    h = h.copy()
    idx = rng.integers(0, n - 1, size=nsample)
    for j in idx:
        if h[j] <= 0 and h[j + 1] <= 0:
            continue
        best_delta = 0.0
        best_r = R_of(h)
        for sgn in (1.0, -1.0):
            t = sgn * step * (h[j] + h[j + 1] + 1e-12)
            if h[j] - t < 0 or h[j + 1] + t < 0:
                continue
            hh = h.copy()
            hh[j] -= t
            hh[j + 1] += t
            r = R_of(hh)
            if r > best_r + 1e-15:
                best_r = r
                best_delta = t
        if best_delta != 0.0:
            h[j] -= best_delta
            h[j + 1] += best_delta
    return h


def _long_range_transfer(h, rng, deadline, max_trials=400):
    h = h.copy()
    n = h.size
    if n < 2:
        return h
    bestR = R_of(h)
    k = max(1, int(0.05 * n))
    top_idx = np.argpartition(h, -k)[-k:]
    invphi = (np.sqrt(5.0) - 1.0) / 2.0

    for trial in range(max_trials):
        if time.process_time() >= deadline:
            break
        i = int(top_idx[rng.integers(0, top_idx.size)])
        j = int(rng.integers(0, n))
        if j == i:
            continue
        hi = h[i]; hj = h[j]
        if hi <= 0 and hj <= 0:
            continue
        lo_t = -hj
        hi_t = hi
        if hi_t <= lo_t:
            continue

        def eval_t(t):
            hh = h.copy()
            hh[i] -= t
            hh[j] += t
            return R_of(hh)

        a = lo_t; b = hi_t
        c = b - invphi * (b - a)
        d = a + invphi * (b - a)
        fc = eval_t(c); fd = eval_t(d)
        best_t = 0.0
        best_val = bestR
        for _ in range(7):
            if fc > fd:
                b = d; d = c; fd = fc
                c = b - invphi * (b - a)
                fc = eval_t(c)
                if fc > best_val:
                    best_val = fc; best_t = c
            else:
                a = c; c = d; fc = fd
                d = a + invphi * (b - a)
                fd = eval_t(d)
                if fd > best_val:
                    best_val = fd; best_t = d
        if best_val > bestR + 1e-16:
            h[i] -= best_t
            h[j] += best_t
            bestR = best_val

        if (trial + 1) % 50 == 0:
            if time.process_time() >= deadline:
                break
            h = _exact_lbfgs(h, 300, 600, deadline)
            r = R_of(h)
            if r > bestR:
                bestR = r
    return h


def _smooth_noise(h, rng, amp):
    """Multiplicative low-frequency perturbation to escape basin."""
    n = h.size
    k = max(4, n // 400)
    ctrl = rng.standard_normal(k)
    x = np.linspace(0, k - 1, n)
    xi = np.floor(x).astype(int)
    xi1 = np.minimum(xi + 1, k - 1)
    w = x - xi
    noise = (1 - w) * ctrl[xi] + w * ctrl[xi1]
    return np.clip(h * np.exp(amp * noise), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92
    long_deadline = t0 + budget_seconds * 0.45

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: exact polish at native resolution.
    stall = 0
    while time.process_time() < deadline - 3.0 and stall < 2:
        cand = _exact_lbfgs(best, 3000, 6000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            stall = 0
        else:
            stall += 1
    print("phase1 R=%.7f" % bestR)

    # Phase 1b: long-range mass transfer.
    rng_lr = np.random.default_rng(1357911)
    if time.process_time() < long_deadline:
        cand = _long_range_transfer(best, rng_lr, long_deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        print("long transfer R=%.7f" % bestR)
    else:
        print("long transfer R=%.7f (skipped)" % bestR)

    # Phase 2: stochastic adjacent-pair mass transfer + re-polish.
    rng = np.random.default_rng(987654321)
    for k in range(4):
        if time.process_time() >= deadline - 4.0:
            break
        hh = best.copy()
        for step in (2e-3, 5e-4, 1e-4):
            hh = _local_pair_gradient(hh, rng, nsample=400, step=step)
            if time.process_time() >= deadline - 4.0:
                break
        hh = _exact_lbfgs(hh, 1500, 3000, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
            print("transfer %d R=%.7f" % (k + 1, bestR))
        else:
            hh = _unzero(best, 2e-4)
            hh = _exact_lbfgs(hh, 1000, 2000, deadline)
            r = R_of(hh)
            if r > bestR + 1e-16:
                best, bestR = hh, r
                print("unzero %d R=%.7f" % (k + 1, bestR))

    # NEW Phase 2b: smooth multiplicative noise annealing to escape basin.
    rng2 = np.random.default_rng(424242)
    for amp in (2e-2, 1e-2, 5e-3, 2e-3):
        if time.process_time() >= deadline - 3.0:
            break
        hh = _smooth_noise(best, rng2, amp)
        hh = _exact_lbfgs(hh, 1500, 3000, deadline)
        r = R_of(hh)
        if r > bestR + 1e-16:
            best, bestR = hh, r
            print("noise amp=%.0e R=%.7f" % (amp, bestR))

    # Phase 3: windowed polish around peak-region.
    stall = 0
    while time.process_time() < deadline - 2.0 and stall < 3:
        improved = False
        for frac in (0.15, 0.35, 0.7):
            if time.process_time() >= deadline - 2.0:
                break
            cand = _window_polish(best, deadline, frac=frac)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
        if improved:
            stall = 0
        else:
            stall += 1
    print("phase3 R=%.7f" % bestR)

    # Phase 4: final intensive full polish.
    while time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 6000, 12000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("final R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale_maxL(h2)
    except TimeoutError:
        try:
            h2 = np.zeros(n)
            h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
            return _rescale_maxL(h2)
        except Exception:
            return h0
    except Exception:
        return h0


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    thr = 0.999 * mx
    idx = np.flatnonzero(Lf >= thr)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4, iters=1200, shift=0):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad + shift)
    hi = min(n - 1, hi + pad + shift)
    if hi <= lo:
        return h
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _resample_cum(h, n_out):
    n = h.size
    if n == n_out:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(n_out)
    xo = np.linspace(0.0, total, n_out + 1)
    xp = np.linspace(0.0, total, n + 1)
    co = np.interp(xo, xp, c)
    ho = np.diff(co)
    return np.clip(ho, 0, None)


def _block_average(h, M):
    n = h.size
    if n == M:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.linspace(0, n, M + 1)
    co = np.interp(edges, np.arange(n + 1), c)
    return np.clip(np.diff(co), 0, None)


def _sqrt_deconv(g2):
    n = g2.size
    h2 = np.zeros(n)
    if n == 0:
        return h2
    v = float(g2[0])
    if v <= 0:
        return h2
    h2[0] = np.sqrt(v)
    for k in range(1, n):
        if h2[0] <= 0:
            break
        if k > 1:
            d = float(np.dot(h2[1:k], h2[k - 1:0:-1]))
        else:
            d = 0.0
        h2[k] = (g2[k] - 2.0 * d) / (2.0 * h2[0])
    return np.clip(h2, 0, None)


def _gspace_reshape(hc, p):
    g = np.convolve(hc, hc)
    Mx = g.max()
    if Mx <= 0:
        return hc.copy()
    g2 = Mx * np.power(np.clip(g / Mx, 0, None), p)
    s_g = g.sum()
    s_g2 = g2.sum()
    if s_g2 <= 0:
        return hc.copy()
    g2 *= s_g / s_g2
    h2 = _sqrt_deconv(g2)
    return _rescale_maxL(h2)


def _loss_runs(h, top_cells=300, max_run=12):
    """Find runs of cells whose removal from the peak plateau may help."""
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return []
    # weight per cell: contribution of knots near it that are close to max
    w = np.zeros(n)
    idx1 = np.arange(1, n + 1)
    idx1 = idx1[idx1 < Lf.size]
    w[idx1 - 1] += Lf[idx1] * (M - Lf[idx1])
    idx2 = np.arange(n, 2 * n)
    valid2 = idx2 < Lf.size
    idx2v = idx2[valid2]
    w[idx2v - n] += Lf[idx2v] * (M - Lf[idx2v])
    if top_cells < n:
        order = np.argsort(w)[::-1][:top_cells]
        sel = np.zeros(n, dtype=bool)
        sel[order] = True
    else:
        sel = np.ones(n, dtype=bool)
    runs = []
    i = 0
    while i < n:
        if sel[i]:
            j = i
            while j < n and sel[j] and (j - i) < max_run:
                j += 1
            runs.append((i, j))
            i = j
        else:
            i += 1
    return runs


def _try_zero_runs(h, deadline, max_tries=40):
    """Try zeroing short runs of cells to break the peak plateau."""
    best = h
    bestR = R_of(h)
    runs = _loss_runs(h, top_cells=200, max_run=8)
    if not runs:
        return best
    rng = np.random.default_rng(999)
    order = rng.permutation(len(runs))
    for ti, ri in enumerate(order):
        if time.process_time() >= deadline - 1.0:
            break
        if ti >= max_tries:
            break
        lo, hi = runs[ri]
        cand = h.copy()
        cand[lo:hi] = 0.0
        cand = _rescale_maxL(cand)
        # quick local polish of the modified region
        cand = _window_polish(cand, deadline, frac=0.3, extra=8, iters=400)
        r = R_of(cand)
        if r > bestR + 1e-12:
            best, bestR = cand, r
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.90 * budget_seconds - 0.6
    rng = np.random.default_rng(12345)

    if start is not None and np.asarray(start).size > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(1)
    else:
        N = 40000
        x = (np.arange(N) + 0.5) / N
        h = 1.0 / np.sqrt(np.clip(x, 1e-6, 1.0) + 0.02)
        h = _rescale_maxL(h)

    best = h.copy()
    bestR = R_of(best)

    # Phase 1: try to break the peak plateau by zeroing short runs.
    hz = _try_zero_runs(best, deadline, max_tries=60)
    rz = R_of(hz)
    if rz > bestR:
        best, bestR = hz, rz

    # Phase 2: g-space reshaping from a block-averaged version.
    M = 2048
    hc = _block_average(best, M)
    hc = _rescale_maxL(hc)

    ladder = [4096, 8192, 16384, 32768, 42496]

    def polish_candidate(hcand, slice_deadline):
        hcur = hcand
        for n_out in ladder:
            if time.process_time() >= slice_deadline - 0.5:
                break
            hup = _resample_cum(hcur, n_out)
            hup = _rescale_maxL(hup)
            hup = _exact_lbfgs(hup, 400, 800, slice_deadline)
            r = R_of(hup)
            if r >= R_of(hcur) - 1e-9:
                hcur = hup
            else:
                hcur = hup
        return hcur

    ps = [0.92, 0.85, 0.70]
    for i, p in enumerate(ps):
        if time.process_time() >= deadline - 2.0:
            break
        remaining = deadline - time.process_time()
        slice_deadline = time.process_time() + remaining / (len(ps) - i)
        hcand = _gspace_reshape(hc, p)
        hcand = polish_candidate(hcand, slice_deadline)
        r = R_of(hcand)
        if r > bestR:
            best, bestR = hcand, r

        cur = hcand
        while time.process_time() < slice_deadline - 1.0:
            hw = _window_polish(cur, slice_deadline, frac=0.20, extra=6, iters=800)
            rw = R_of(hw)
            if rw > bestR:
                best, bestR = hw, rw
            cur = hw
            if time.process_time() >= slice_deadline - 1.0:
                break
            hf = _exact_lbfgs(cur, 400, 800, slice_deadline)
            rf = R_of(hf)
            if rf > bestR:
                best, bestR = hf, rf
            cur = hf

    # Phase 3: keep polishing the global best with alternating window/full.
    while time.process_time() < deadline - 1.0:
        hw = _window_polish(best, deadline, frac=0.20, extra=6, iters=800)
        rw = R_of(hw)
        if rw > bestR:
            best, bestR = hw, rw
        if time.process_time() >= deadline - 1.0:
            break
        hf = _exact_lbfgs(best, 600, 1200, deadline)
        rf = R_of(hf)
        if rf > bestR:
            best, bestR = hf, rf

    print(f"final R={bestR:.7f} (N={best.size})")
    return best

