        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _loss_runs(h, top_cells=300, max_run=12):
    n = h.size
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return []
    w = np.zeros(n)
    idx1 = np.arange(1, n + 1)
    idx1 = idx1[idx1 < Lf.size]
    w[idx1 - 1] += Lf[idx1] * (M - Lf[idx1])
    idx2 = np.arange(n, 2 * n)
    valid2 = idx2 < Lf.size
    idx2v = idx2[valid2]
    w[idx2v - n] += Lf[idx2v] * (M - Lf[idx2v])
    if top_cells < n:
        order = np.argsort(w)[::-1][:top_cells]
        sel = np.zeros(n, dtype=bool)
        sel[order] = True
    else:
        sel = np.ones(n, dtype=bool)
    cells = np.flatnonzero(sel)
    runs = []
    if cells.size == 0:
        return runs
    start = cells[0]
    prev = cells[0]
    for c in cells[1:]:
        if c == prev + 1 and (c - start + 1) <= max_run:
            prev = c
        else:
            runs.append(np.arange(start, prev + 1))
            start = c
            prev = c
    runs.append(np.arange(start, prev + 1))
    return runs


def _window_polish(h, deadline, window=48, stride=24, maxiter=50):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    improved_any = False
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            improved_any = True
        pos += stride
    return best, bestR, improved_any


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: global full-vector L-BFGS refine (cheap on this N; large win here)
    while time.process_time() < deadline - 12.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=2000)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("full R=%.7f" % bestR)
        else:
            break

    # Phase 2: window polish over the whole vector to squeeze local maxima
    for sweep in range(3):
        if time.process_time() >= deadline - 4.0:
            break
        best, bestR, imp = _window_polish(best, deadline, window=48, stride=24, maxiter=50)
        print("window-sweep %d R=%.7f improved=%s" % (sweep + 1, bestR, imp))
        if not imp:
            break

    # Phase 3: loss-run targeted polish (largest per-cell loss contributions)
    for sweep in range(2):
        if time.process_time() >= deadline - 2.0:
            break
        runs = _loss_runs(best, top_cells=300, max_run=12)
        improved = False
        for run in runs:
            if time.process_time() >= deadline - 2.0:
                break
            cand = _block_lbfgs_linear(best, run, maxiter=40, deadline=deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
        print("loss-sweep %d R=%.7f improved=%s" % (sweep + 1, bestR, improved))
        if not improved:
            break

    # Phase 4: spend the remaining budget on full refine until done
    while time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("full2 R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, linear=False):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if linear:
        x0 = h[active].copy()

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = _norm_eq_fun_grad(hh)
            return val, g[active]

        bounds = [(0.0, None)] * active.size
    else:
        u0 = np.log(np.clip(h[active], 1e-300, None))

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _norm_eq_fun_grad(hh)
            return val, g[active] * hh[active]

        x0 = u0
        bounds = [(-30.0, 30.0)] * active.size

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    if linear:
        h2[active] = np.clip(res.x, 0.0, None)
    else:
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _refine(h, deadline, rounds, free=None, maxiter=1500, linear=False):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline,
                            free=free, linear=linear)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            break
    return best, bestR


def _upsample(h, factor):
    if factor <= 1:
        return h
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    m = n * factor
    edges = np.arange(m + 1, dtype=float) / factor
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    h2 = np.diff(Cq) * factor
    return np.clip(h2, 0, None)


def _window_polish(h, deadline, frac=0.25, extra=4, linear=False):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free, linear=linear)


def _block_sweep(h, deadline, window, stride, maxiter=80):
    """Sliding-window linear-space polish: cheap, escapes tiny local traps."""
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline,
                            free=free, linear=True)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 0: polish the start on its own grid (both parametrisations).
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline, rounds=2, maxiter=1500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)
        h, r = _refine(best, deadline, rounds=1, maxiter=1200, linear=True)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish-lin R=%.7f" % bestR)

    # Phase 1: sliding-window linear sweeps to escape small local traps.
    for window, stride in ((48, 24), (32, 16), (96, 48)):
        if time.process_time() >= deadline - 6.0:
            break
        h, r = _block_sweep(best, deadline, window=window, stride=stride)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("sweep(%d) R=%.7f" % (window, bestR))

    # Phase 2: upsample to a finer grid and polish there.
    n0 = best.size
    if n0 * 2 <= 190000 and time.process_time() < deadline - 8.0:
        up = _upsample(best, 2)
        up = _rescale_maxL(up)
        h_fine, r_fine = _refine(up, deadline, rounds=2, maxiter=2000)
        print("fine R=%.7f (N=%d)" % (r_fine, h_fine.size))
        if r_fine > bestR + 1e-16:
            best, bestR = h_fine, r_fine
            print("accepted fine R=%.7f" % bestR)

    # Phase 3: window polish ladder (both parametrisations alternate).
    for frac, extra, lin in ((0.10, 4, False), (0.20, 8, True),
                             (0.35, 16, False), (0.50, 32, True)):
        if time.process_time() >= deadline - 3.0:
            break
        h = _window_polish(best, deadline, frac=frac, extra=extra, linear=lin)
        h, r = _refine(h, deadline, rounds=1, maxiter=1000)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win(%.2f) R=%.7f" % (frac, bestR))

    # Phase 4: stochastic kicks on the peak band.
    rng = np.random.default_rng(2024)
    lo, hi = _peak_region(best)
    band_lo = max(0, lo - 4)
    band_hi = min(best.size - 1, hi + 4)
    kick_iter = 0
    while time.process_time() < deadline - 2.0:
        kick_iter += 1
        amp = 0.0008 * (1.0 + (kick_iter % 6))
        noise = 1.0 + amp * rng.standard_normal(band_hi - band_lo + 1)
        cand = best.copy()
        cand[band_lo:band_hi + 1] *= np.clip(noise, 0.5, 2.0)
        cand = _rescale_maxL(cand)
        free = np.arange(band_lo, band_hi + 1)
        cand = _exact_lbfgs(cand, 400, 800, deadline, free=free,
                            linear=(kick_iter % 2 == 0))
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("kick %d R=%.7f" % (kick_iter, bestR))

    # Phase 5: final full exact polish until time runs out.
    while time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("full R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

