    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _smooth_sym(h, k):
    """Symmetric moving-average smoothing of h (odd window k) to escape local minima."""
    if k < 3:
        return h.copy()
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    return np.clip(hs, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Primary strategy: heavy full-resolution L-BFGS polish of the start, then
    # smoothing-perturbation restarts to escape the local optimum. The previous
    # programs only did light polishing; this spends the whole budget refining
    # the actual best construction directly.
    n = best.size

    # First: a solid full L-BFGS run from the start.
    cand = _exact_lbfgs(best, 4000, 8000, deadline)
    r = R_of(cand)
    if r > bestR + 1e-16:
        best, bestR = cand, r
        print("full polish R=%.7f" % bestR)

    # Then: alternating smoothing-perturb + L-BFGS restarts, keeping progress.
    sm_windows = [3, 5, 9, 15, 25, 41]
    si = 0
    while time.process_time() < deadline - 2.0:
        k = sm_windows[si % len(sm_windows)]
        si += 1
        pert = _smooth_sym(best, k)
        if pert.sum() <= 0:
            continue
        pert = _rescale_maxL(pert)
        rp = R_of(pert)
        if rp >= bestR - 1e-9:
            # only accept perturbation if it stays close; else re-seed with best
            seed = pert
        else:
            seed = best
        cand = _exact_lbfgs(seed, 2000, 4000, deadline)
        rr = R_of(cand)
        if rr > bestR + 1e-16:
            best, bestR = cand, rr
            print("restart(k=%d) R=%.7f" % (k, bestR))

    # Final window polish to squeeze the last bits.
    if time.process_time() < deadline - 1.0:
        h, r = _window_polish(best, deadline, window=48, stride=24, maxiter=40)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("window R=%.7f" % bestR)

    # Last full polish if any time remains.
    if time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 1500, 3000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _modulation_sweep(h, deadline, band_frac=0.92):
    """EXPERIMENT: period-2/3/4/6 modulation confined to near-max band."""
    best = h
    bestR = R_of(h)
    L = _knots(h)
    mx = L.max()
    if mx <= 0:
        return best, bestR
    # cells whose adjacent knots exceed band_frac*max(L)
    # knot j corresponds to boundary; cell i has knots i, i+1 in Lf
    Lf = L
    thr = band_frac * mx
    cellmask = (Lf[:-1] > thr) | (Lf[1:] > thr)
    P = np.flatnonzero(cellmask)
    if P.size == 0:
        return best, bestR
    periods = [2, 3, 4, 6]
    eps_grid = np.linspace(-0.15, 0.15, 25)
    base = h.copy()
    for p in periods:
        for q in range(p):
            s_full = np.cos(2.0 * np.pi * (np.arange(h.size) - q) / p)
            sP = s_full[P]
            for eps in eps_grid:
                if time.process_time() >= deadline - 2.0:
                    return best, bestR
                cand = base.copy()
                cand[P] = base[P] * np.exp(eps * sP)
                cand = np.clip(cand, 0.0, None)
                r = R_of(cand)
                if r > bestR + 1e-16:
                    best, bestR = cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ----- EXPERIMENT: period-2/3/4/6 modulation sweep on near-max band. -----
    if best.size >= 16 and time.process_time() < deadline - 6.0:
        h_mod, r_mod = _modulation_sweep(best, deadline)
        gain = r_mod - bestR
        print("modulation R=%.7f (gain=%.3e)" % (r_mod, gain))
        if r_mod > bestR + 1e-15:
            best, bestR = h_mod, r_mod
            print("modulation accepted R=%.7f" % bestR)
            # exact log-height L-BFGS + window polish on the modulated best
            if time.process_time() < deadline - 4.0:
                sub_deadline = min(deadline - 3.0,
                                   time.process_time() + (deadline - time.process_time()) * 0.4)
                h_opt, r_opt = _refine(best, sub_deadline, rounds=1, maxiter=2000)
                if r_opt > bestR + 1e-15:
                    best, bestR = h_opt, r_opt
                    print("mod-refine R=%.7f" % bestR)
                if time.process_time() < deadline - 3.0:
                    h_w, r_w = _window_polish(best, sub_deadline, window=64,
                                              stride=32, maxiter=60)
                    if r_w > bestR + 1e-15:
                        best, bestR = h_w, r_w
                        print("mod-window R=%.7f" % bestR)
        else:
            print("modulation rejected (no gain)")

    # ----- Existing multigrid + polish on whatever best is now. -----
    N_fine = best.size
    scales = [N_fine // 4, N_fine // 2, N_fine]
    scales = [s for s in scales if s >= 16]
    for Nc in scales:
        if time.process_time() >= deadline - 3.0:
            break
        if Nc >= N_fine:
            h_c = best.copy()
        else:
            h_c = _coarse_from_fine(best, Nc)
        h_c = _rescale_maxL(h_c)
        sub_deadline = min(deadline - 2.0,
                           time.process_time() + (deadline - time.process_time()) * 0.35)
        h_opt, r_opt = _refine(h_c, sub_deadline, rounds=1, maxiter=3000)
        if Nc < N_fine:
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("multigrid N=%d->%d R=%.7f" % (Nc, N_fine, bestR))
        else:
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    if time.process_time() < deadline - 2.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine R=%.7f" % bestR)
        h, r = _window_polish(best, deadline, window=64, stride=32, maxiter=60)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("window R=%.7f" % bestR)

    # ----- Leftover budget: finer epsilon sweep around best value. -----
    if time.process_time() < deadline - 2.0:
        L = _knots(best)
        mx = L.max()
        if mx > 0:
            thr = 0.92 * mx
            cellmask = (L[:-1] > thr) | (L[1:] > thr)
            P = np.flatnonzero(cellmask)
            if P.size > 0:
                base = best.copy()
                best_eps = 0.0
                best_p = 2
                best_q = 0
                # coarse re-find best (eps,p,q) quickly
                for p in [2, 3, 4, 6]:
                    for q in range(p):
                        sP = np.cos(2.0 * np.pi * (P - q) / p)
                        for eps in np.linspace(-0.15, 0.15, 13):
                            if time.process_time() >= deadline - 1.5:
                                break
                            cand = base.copy()
                            cand[P] = base[P] * np.exp(eps * sP)
                            cand = np.clip(cand, 0.0, None)
                            r = R_of(cand)
                            if r > bestR + 1e-16:
                                best, bestR = cand, r
                                best_eps, best_p, best_q = eps, p, q
                # fine sweep around best_eps
                if best_eps != 0.0:
                    sP = np.cos(2.0 * np.pi * (P - best_q) / best_p)
                    for eps in np.linspace(best_eps - 0.03, best_eps + 0.03, 25):
                        if time.process_time() >= deadline - 1.0:
                            break
                        cand = base.copy()
                        cand[P] = base[P] * np.exp(eps * sP)
                        cand = np.clip(cand, 0.0, None)
                        r = R_of(cand)
                        if r > bestR + 1e-16:
                            best, bestR = cand, r
                    print("fine-sweep R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

