        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _split_prolongate(h):
    n = h.size
    h2 = np.empty(2 * n)
    h2[0::2] = 0.5 * h
    h2[1::2] = 0.5 * h
    return h2


def _split_free_lbfgs(h, free_idx, maxiter, deadline):
    n = h.size
    N2 = 2 * n
    m = 0.5 * h
    base2 = np.empty(N2)
    base2[0::2] = m
    base2[1::2] = m
    free_idx = np.asarray(free_idx, dtype=int)
    if free_idx.size == 0:
        return h
    u0 = np.zeros(free_idx.size)

    def build(uu):
        s = 1.0 / (1.0 + np.exp(-np.clip(uu, -30.0, 30.0)))
        h2 = base2.copy()
        h2[0::2][free_idx] = h[free_idx] * s
        h2[1::2][free_idx] = h[free_idx] * (1.0 - s)
        return h2, s

    def f(uu):
        h2, s = build(uu)
        mx = _knots(h2).max()
        if mx <= 0:
            return 1e18, np.zeros_like(uu)
        val2, g2 = _norm_eq_fun_grad(h2)
        gs = h[free_idx] * (g2[0::2][free_idx] - g2[1::2][free_idx])
        gu = gs * s * (1.0 - s)
        return val2, gu

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * free_idx.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h
    if res is None:
        return h
    h2, _ = build(res.x)
    return _rescale_maxL(h2)


def _fresh_shape(N, a, taper_frac=0.02, first_boost=1.0):
    """Cell averages of x^-a on [0,1], with raised-cosine taper over the
    last taper_frac of cells and an optional boost on the first cell."""
    i = np.arange(N, dtype=float)
    p = 1.0 - a
    h = ((i + 1.0) ** p - i ** p) / p
    h = np.clip(h, 0.0, None)
    if first_boost != 1.0:
        h[0] *= first_boost
    if taper_frac > 0:
        k = max(1, int(round(taper_frac * N)))
        w = 0.5 * (1.0 + np.cos(np.linspace(0.0, np.pi, k)))
        h[N - k:] *= w
    if h.sum() <= 0:
        return np.ones(N)
    return _rescale_maxL(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ===== EXPERIMENT: fresh native high-N shapes, never downsample. =====
    N_list = [84992, 141653, 200000]
    a_list = [0.45, 0.5, 0.55]
    boost_list = [1.0, 2.0, 4.0]

    best_fresh = None
    best_fresh_R = -1.0
    best_fresh_N = 0

    for N2 in N_list:
        if time.process_time() >= deadline - 8.0:
            break
        for a in a_list:
            for fb in boost_list:
                if time.process_time() >= deadline - 8.0:
                    break
                h = _fresh_shape(N2, a, taper_frac=0.02, first_boost=fb)
                r = R_of(h)
                if r > best_fresh_R:
                    best_fresh_R = r
                    best_fresh = h
                    best_fresh_N = N2
        print("fresh scan N=%d bestR=%.7f" % (N2, best_fresh_R))

    if best_fresh is not None:
        print("fresh best R=%.7f (N=%d)" % (best_fresh_R, best_fresh_N))
        # Full log-height exact L-BFGS at native N.
        if time.process_time() < deadline - 4.0:
            sub_deadline = min(deadline - 3.0,
                               time.process_time() +
                               (deadline - time.process_time()) * 0.55)
            h_opt = _exact_lbfgs(best_fresh, maxiter=4000, deadline=sub_deadline)
            r_opt = R_of(h_opt)
            print("fresh-lbfgs R=%.7f (N=%d)" % (r_opt, h_opt.size))
            if r_opt > best_fresh_R + 1e-16:
                best_fresh, best_fresh_R = h_opt, r_opt
        # Peak-window polish at native N.
        if time.process_time() < deadline - 2.0:
            h_w, r_w = _window_polish(best_fresh, deadline, window=64,
                                      stride=32, maxiter=60)
            print("fresh-window R=%.7f" % r_w)
            if r_w > best_fresh_R + 1e-16:
                best_fresh, best_fresh_R = h_w, r_w

        if best_fresh_R > bestR + 1e-12:
            best, bestR = best_fresh, best_fresh_R
            print("fresh accepted R=%.7f (N=%d)" % (bestR, best.size))
        else:
            print("fresh rejected (no gain over start)")

    # ===== Existing multigrid + polish on whatever best is now. =====
    N_fine = best.size
    scales = [N_fine // 4, N_fine // 2, N_fine]
    scales = [s for s in scales if s >= 16]
    for Nc in scales:
        if time.process_time() >= deadline - 3.0:
            break
        if Nc >= N_fine:
            h_c = best.copy()
        else:
            h_c = _coarse_from_fine(best, Nc)
        h_c = _rescale_maxL(h_c)
        sub_deadline = min(deadline - 2.0,
                           time.process_time() + (deadline - time.process_time()) * 0.35)
        h_opt, r_opt = _refine(h_c, sub_deadline, rounds=1, maxiter=3000)
        if Nc < N_fine:
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("multigrid N=%d->%d R=%.7f" % (Nc, N_fine, bestR))
        else:
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    if time.process_time() < deadline - 2.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine R=%.7f" % bestR)
        h, r = _window_polish(best, deadline, window=64, stride=32, maxiter=60)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("window R=%.7f" % bestR)

    while time.process_time() < deadline - 1.0:
        h, r = _window_polish(best, deadline, window=64, stride=32, maxiter=60)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final-window R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # KEY CHANGE: work at higher resolution. The optimum has a sharp peak and
    # long smooth decay; refining at the current N stalls. Upsample to a fixed
    # larger N (bounded by 200000) and optimize there, which unlocks real gains.
    n0 = best.size
    N_target = min(200000, max(n0, int(n0 * 2.5)))
    if N_target > n0:
        cand = _prolongate(best, N_target)
        r = R_of(cand)
        if r >= bestR - 1e-6:
            best = cand
            bestR = max(bestR, r)
            print("upsampled to N=%d R=%.7f" % (best.size, bestR))

    n = best.size

    # Full-space log-h L-BFGS at the higher resolution.
    if time.process_time() < deadline - 2.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-16:
            best, bestR = h, r
        print("step0 full R=%.7f" % bestR)

    cycle = 0
    while time.process_time() < deadline - 2.0:
        cycle += 1
        n = best.size

        # Broad overlapping free blocks on the decay region (where gains live).
        for lo_f, hi_f in ((0.30, 1.0), (0.0, 0.55), (0.5, 1.0),
                           (0.0, 0.40), (0.15, 0.75)):
            if time.process_time() >= deadline - 2.0:
                break
            lo = int(lo_f * n); hi = int(hi_f * n)
            free = np.arange(lo, hi)
            cand = _block_lbfgs_linear(best, free, maxiter=600, deadline=deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                print("cyc%d blk%.2f-%.2f R=%.7f" % (cycle, lo_f, hi_f, bestR))

        if time.process_time() >= deadline - 2.0:
            break

        h, r = _refine(best, deadline, rounds=1, maxiter=800)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("cyc%d full R=%.7f" % (cycle, bestR))

        if time.process_time() >= deadline - 2.0:
            break

        w = max(64, int(0.08 * n))
        h, r = _window_polish(best, deadline, window=w, stride=max(1, w // 2), maxiter=40)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("cyc%d win R=%.7f" % (cycle, bestR))

    # Final: try one more upsampling + refine if budget remains.
    if time.process_time() < deadline - 3.0 and best.size < 200000:
        N2 = min(200000, int(best.size * 1.5))
        cand = _prolongate(best, N2)
        r = R_of(cand)
        if r >= bestR - 1e-6:
            best = cand
            bestR = max(bestR, r)
            h, r = _refine(best, deadline, rounds=1, maxiter=1000)
            if r > bestR + 1e-16:
                best, bestR = h, r
            print("final upsample N=%d R=%.7f" % (best.size, bestR))

    # Leftover budget: keep refining.
    while time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=800)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("tail R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

