        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': gtol})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _overlap_polish(h, deadline, window=256, stride=128, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _deconvolve_target(T, n):
    """Exact causal forward recursion: recover h of length n with h*h ~ T[0:n]."""
    h = np.zeros(n)
    h0sq = T[0]
    if h0sq <= 0:
        return None
    h[0] = np.sqrt(h0sq)
    two_h0 = 2.0 * h[0]
    for k in range(1, n):
        if k == 1:
            s = 0.0
        else:
            s = float(np.dot(h[1:k], h[k - 1:0:-1]))
        h[k] = (T[k] - s) / two_h0
    return h


def _sharpened_seed(h, p):
    n = h.size
    L = fftconvolve(h, h) if n > 1500 else np.convolve(h, h)
    M = L.max()
    if M <= 0:
        return None
    T = M * (np.clip(L, 0.0, None) / M) ** p
    h_try = _deconvolve_target(T[:n], n)
    if h_try is None:
        return None
    h_try = np.clip(h_try, 0.0, None)
    if h_try.sum() <= 0:
        return None
    return _rescale_maxL(h_try)


def _upsample(h, factor):
    """Insert zeros between heights -> finer step function of same shape."""
    n = h.size
    m = n * factor
    out = np.zeros(m)
    out[::factor] = h
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
            print("start R=%.7f (N=%d)" % (bestR, best.size))

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)
        print("fallback R=%.7f (N=%d)" % (bestR, best.size))

    # ----- Main loop: full-variable L-BFGS-B polish on incumbent. -----
    # This is the workhorse: it directly climbs R via the log-height
    # parametrization.  We alternate with sharpening seeds.
    p_list = [1.02, 1.05, 1.1, 1.25, 1.5, 2.0]
    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        prev = bestR
        remain = deadline - time.process_time()
        sub_deadline = time.process_time() + max(2.0, remain * 0.55)
        h, r = _refine(best, sub_deadline, rounds=1, maxiter=3000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if time.process_time() >= deadline - 1.5:
            break
        # Sharpening seeds at rotating p.
        p = p_list[it % len(p_list)]
        h_try = _sharpened_seed(best, p)
        if h_try is not None:
            sub_deadline = time.process_time() + max(1.0, (deadline - time.process_time()) * 0.5)
            h2, r2 = _refine(h_try, sub_deadline, rounds=1, maxiter=800)
            if r2 > bestR + 1e-16:
                best, bestR = h2, r2
        print("iter %d R=%.7f (N=%d)" % (it, bestR, best.size))
        if bestR - prev < 1e-13 and it >= 3:
            break

    # ----- Final extras: try upsampling then polish if time remains. -----
    if time.process_time() < deadline - 3.0 and best.size < 100000:
        for factor in (2, 3):
            if time.process_time() >= deadline - 2.5:
                break
            if best.size * factor > 200000:
                continue
            up = _upsample(best, factor)
            up = _rescale_maxL(up)
            r_up = R_of(up)
            sub_deadline = time.process_time() + max(1.0, (deadline - time.process_time()) * 0.6)
            h_up, r_up2 = _refine(up, sub_deadline, rounds=1, maxiter=500)
            if r_up2 > bestR + 1e-16:
                best, bestR = h_up, r_up2
                print("upsample x%d -> R=%.7f (N=%d)" % (factor, bestR, best.size))

    best = _rescale_maxL(np.clip(best, 0, None))
    bestR = R_of(best)
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _overlap_polish(h, deadline, window=512, stride=256, maxiter=150):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Full exact L-BFGS on all active variables.
    if time.process_time() < deadline - 3.0:
        cand = _exact_lbfgs(best, 2000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("full lbfgs R=%.7f" % bestR)

    # Overlapping-window polish: high-window overlap drives up max-knot region.
    if time.process_time() < deadline - 2.0:
        h2, r2 = _overlap_polish(best, deadline, window=512, stride=256, maxiter=150)
        if r2 > bestR + 1e-16:
            best, bestR = h2, r2
            print("overlap polish R=%.7f" % bestR)

    # Alternate window sizes for diversity.
    for win, stp, mi in [(256, 128, 120), (1024, 512, 100), (128, 64, 100)]:
        if time.process_time() >= deadline - 1.5:
            break
        h2, r2 = _overlap_polish(best, deadline, window=win, stride=stp, maxiter=mi)
        if r2 > bestR + 1e-16:
            best, bestR = h2, r2
            print("overlap w=%d R=%.7f" % (win, bestR))

    # Final full L-BFGS pass.
    if time.process_time() < deadline - 1.0:
        cand = _exact_lbfgs(best, 3000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("final lbfgs R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (R_of(best), best.size))
    return best

