def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _refine(h, deadline, rounds, free=None, maxiter=1500, linear=False):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline,
                            free=free, linear=linear)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        else:
            break
    return best, bestR


def _upsample(h, factor):
    if factor <= 1:
        return h
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    m = n * factor
    edges = np.arange(m + 1, dtype=float) / factor
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    h2 = np.diff(Cq) * factor
    return np.clip(h2, 0, None)


def _block_sweep(h, deadline, window, stride, maxiter=80):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline,
                            free=free, linear=True)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _fine_sweep(h, deadline, window, stride, maxiter=60, rounds=2):
    """Small-window linear sweep, repeated passes, to reduce discretisation
    error at the fine grid. Cheap per-step; concentrates on local smoothness."""
    best = h
    bestR = R_of(h)
    n = h.size
    for _ in range(rounds):
        pos = 0
        improved = False
        while pos < n:
            if time.process_time() >= deadline - 1.0:
                return best, bestR
            end = min(pos + window, n)
            free = np.arange(pos, end)
            cand = _exact_lbfgs(best, maxiter, 2 * maxiter, deadline,
                                free=free, linear=True)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
            pos += stride
        if not improved:
            break
    return best, bestR


def construct(budget_seconds, start):
