        if time.process_time() >= deadline - 8.0:
            break
        h, r = _block_sweep(best, deadline, window=window, stride=stride)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("sweep(%d) R=%.7f" % (window, bestR))

    # Phase 2: upsample to a finer grid and polish there.
    n0 = best.size
    if n0 * 2 <= 190000 and time.process_time() < deadline - 10.0:
        up = _upsample(best, 2)
        up = _rescale_maxL(up)
        h_fine, r_fine = _refine(up, deadline, rounds=2, maxiter=2500)
        print("fine R=%.7f (N=%d)" % (r_fine, h_fine.size))
        if r_fine > bestR + 1e-16:
            best, bestR = h_fine, r_fine
            print("accepted fine R=%.7f" % bestR)

    # Phase 3: fine-grid small-window sweeps to shave discretisation loss.
    for window, stride, rounds in ((24, 12, 2), (16, 8, 2), (40, 20, 1)):
        if time.process_time() >= deadline - 6.0:
            break
        h, r = _fine_sweep(best, deadline, window=window,
                           stride=stride, rounds=rounds)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("fsweep(%d) R=%.7f" % (window, bestR))

    # Phase 4: alternating full and window polish, with occasional
    # higher-fidelity full refine to lock in gains.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)
        else:
            # full refine stuck; try a fine sweep to break out
            h, r = _fine_sweep(best, deadline, window=20, stride=10,
                               rounds=1, maxiter=40)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("fsweep-esc R=%.7f" % bestR)
            else:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = min(K, n)
    if K >= n:
        Lm = Lf.mean()
        gLf = -dq / num + (1.0 / (n * Lm)) * np.ones(n)
    else:
        idx = np.argpartition(Lf, n - K)[n - K:]
        Lm = Lf[idx].mean()
        gLf = -dq / num
        gLf[idx] += 1.0 / (K * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_log(h0, K, maxiter, deadline):
    """L-BFGS on top-K mean surrogate in log-height coords."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.10, extra=4):
    if time.process_time() >= deadline - 0.3:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 400, 800, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Descending K ladder covering the full near-max band.
    KLADDER = [20000, 10000, 5000, 2000, 1000, 500, 200, 100, 50, 20, 10, 5, 2, 1]

    cycle = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        prevR = bestR
        for K in KLADDER:
            if time.process_time() >= deadline - 1.5:
                break
            h = _topk_log(best, K, 300, deadline)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
            # exact polish
            h = _exact_lbfgs(best, 200, 400, deadline)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
            # 10%-width window polish
            h = _window_polish(best, deadline, frac=0.10)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
        if bestR > prevR + 1e-16:
            print("cycle %d R=%.7f" % (cycle, bestR))
        else:
            # one more cycle; the ladder is cheap so keep going until deadline
            if time.process_time() >= deadline - 1.5:
                break

    # Final exact polish until the bell.
    hard = t0 + budget_seconds * 0.97
    while time.process_time() < hard - 0.5:
        h = _exact_lbfgs(best, 4000, 8000, hard - 0.3)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve


