    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


# ===== EXPERIMENT: K-block t^{-1/2} family =====
def _blocks_to_h(params, N):
    """params: [a_k, L_k, log10(c_k)] for k=1..K. Build h on N steps."""
    K = params.size // 3
    x = np.arange(N, dtype=float)
    h = np.zeros(N)
    for k in range(K):
        a = params[3 * k]
        Lk = params[3 * k + 1]
        c = 10.0 ** params[3 * k + 2]
        lo = a
        hi = a + Lk
        mask = (x >= lo) & (x < hi)
        if not np.any(mask):
            continue
        d = x[mask] - lo + 1e-6
        h[mask] += c / np.sqrt(d)
    return h


def _block_objective(params, N):
    h = _blocks_to_h(params, N)
    if h.sum() <= 0:
        return 1.0
    return -R_of(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ===== EXPERIMENT: differential evolution over 8 t^{-1/2} blocks =====
    K = 8
    N0 = 2048
    bounds = []
    for k in range(K):
        bounds.append((0.0, 0.8 * N0))          # a_k
        bounds.append((0.05 * N0, 0.5 * N0))    # L_k
        bounds.append((-3.0, 3.0))              # log10 c_k

    de_deadline = min(deadline - 8.0, time.process_time() + 12.0)
    candidates = []

    def _de_cb(xk, convergence=None):
        if time.process_time() > de_deadline:
            raise TimeoutError

    try:
        res = differential_evolution(
            lambda p: _block_objective(p, N0),
            bounds,
            popsize=15,
            maxiter=200,
            tol=1e-8,
            mutation=(0.5, 1.0),
            recombination=0.7,
            polish=False,
            init='latinhypercube',
            callback=_de_cb,
            seed=12345,
        )
        if res is not None:
            candidates.append(res.x.copy())
            print("DE done R_coarse=%.7f" % (-res.fun))
    except TimeoutError:
        print("DE timeout, using partial")
    except Exception as e:
        print("DE failed:", e)

    # If DE didn't produce anything, fall back to random sampling
    if not candidates:
        rng = np.random.default_rng(7)
        for _ in range(5):
            p = np.zeros(3 * K)
            for k in range(K):
                p[3 * k] = rng.uniform(0.0, 0.8 * N0)
                p[3 * k + 1] = rng.uniform(0.05 * N0, 0.5 * N0)
                p[3 * k + 2] = rng.uniform(-3.0, 3.0)
            candidates.append(p)

    # Evaluate top candidates on fine grid and polish
    N_fine = 42496
    scored = []
    for p in candidates:
        h_fine = _blocks_to_h(p, N_fine)
        if h_fine.sum() <= 0:
            continue
        h_fine = _rescale_maxL(h_fine)
        scored.append((R_of(h_fine), h_fine))
    scored.sort(key=lambda t: -t[0])

    for r0, h_fine in scored[:5]:
        if time.process_time() >= deadline - 3.0:
            break
        sub_dl = min(deadline - 2.0,
                     time.process_time() + (deadline - time.process_time()) * 0.4)
        h_try, r_try = _refine(h_fine, sub_dl, rounds=1, maxiter=1500)
        if time.process_time() < sub_dl - 1.0:
            h_try, r_try = _window_polish(h_try, sub_dl, window=64, stride=32,
                                          maxiter=60)
        if r_try > bestR + 1e-12:
            best, bestR = h_try, r_try
            print("block accept R=%.7f (from %.7f)" % (bestR, r0))

    print("block experiment done R=%.7f" % bestR)

    # ===== Existing multigrid + polish on whatever best is now. =====
    N_fine = best.size
    scales = [N_fine // 4, N_fine // 2, N_fine]
    scales = [s for s in scales if s >= 16]
    for Nc in scales:
        if time.process_time() >= deadline - 3.0:
            break
        if Nc >= N_fine:
            h_c = best.copy()
        else:
