def _find_j0(Lf):
    """First index after the plateau where Lf < 0.99*max(Lf)."""
    m = int(np.argmax(Lf))
    thr = 0.99 * Lf[m]
    n = Lf.size
    j = m
    while j < n and Lf[j] >= thr:
        j += 1
    return j


def _penalised_fun_grad(h, lam, j0):
    """-log R + lam * (width-weighted tail) / total, analytic gradient."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    if lam != 0.0 and j0 < Lf.size:
        tot = Lf.sum()
        if tot > 0:
            w = np.zeros_like(Lf)
            idx = np.arange(Lf.size)
            w[j0:] = (idx[j0:] - j0).astype(float)
            sw = np.dot(w, Lf)
            pen = lam * sw / tot
            val += pen
            gpen = lam * w / tot - lam * sw / (tot * tot)
            gLf = gLf + gpen
    grad = _backprop(gLf, h) + 2.0 / s
    return val, grad


