def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _split_prolongate(h):
    n = h.size
    h2 = np.empty(2 * n)
    h2[0::2] = 0.5 * h
    h2[1::2] = 0.5 * h
    return h2


def _split_free_lbfgs(h, free_idx, maxiter, deadline):
    n = h.size
    N2 = 2 * n
    m = 0.5 * h
    base2 = np.empty(N2)
    base2[0::2] = m
    base2[1::2] = m
    free_idx = np.asarray(free_idx, dtype=int)
    if free_idx.size == 0:
        return h
    u0 = np.zeros(free_idx.size)

    def build(uu):
        s = 1.0 / (1.0 + np.exp(-np.clip(uu, -30.0, 30.0)))
        h2 = base2.copy()
        h2[0::2][free_idx] = h[free_idx] * s
        h2[1::2][free_idx] = h[free_idx] * (1.0 - s)
        return h2, s

    def f(uu):
        h2, s = build(uu)
        mx = _knots(h2).max()
        if mx <= 0:
            return 1e18, np.zeros_like(uu)
        val2, g2 = _norm_eq_fun_grad(h2)
        gs = h[free_idx] * (g2[0::2][free_idx] - g2[1::2][free_idx])
        gu = gs * s * (1.0 - s)
        return val2, gu

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * free_idx.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h
    if res is None:
        return h
    h2, _ = build(res.x)
    return _rescale_maxL(h2)


def _causal_deconv(T, n):
    h = np.zeros(n)
    if n == 0:
        return h
    t0 = max(T[0], 0.0)
    h0 = np.sqrt(t0)
    if h0 <= 0:
        return h
    h[0] = h0
    for k in range(1, n):
        s = 0.0
        if k >= 2:
            i = np.arange(1, k)
            s = float(np.dot(h[1:k], h[k - 1:0:-1]))
        h[k] = (T[k] - s) / (2.0 * h0)
    return h


def _phase_perturb(h, eps, rng, n_modes=6):
    n = h.size
    H = np.fft.rfft(h)
    mag = np.abs(H)
    phase = np.angle(H)
    nf = H.size
    # low-order cosine basis on [0, pi] over frequency index
    t = np.linspace(0.0, np.pi, nf)
    phi = np.zeros(nf)
    for k in range(1, n_modes + 1):
        c = rng.standard_normal()
        phi += c * np.cos(k * t)
    m = np.max(np.abs(phi))
    if m > 0:
        phi *= eps / m
    H2 = mag * np.exp(1j * (phase + phi))
    h2 = np.fft.irfft(H2, n=n)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return None
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # ===== EXPERIMENT: spectral phase annealing loop =====
    rng = np.random.default_rng(12345)
    eps_ladder = [0.2, 0.1, 0.05, 0.02, 0.01, 0.005]
    trials_per_eps = 4
    n_accept = 0
    n_trial = 0
    for eps in eps_ladder:
        if time.process_time() >= deadline - 1.0:
            break
        for _ in range(trials_per_eps):
            if time.process_time() >= deadline - 1.0:
                break
            n_trial += 1
            h_try = _phase_perturb(best, eps, rng, n_modes=6)
            if h_try is None:
                continue
            sub_dl = min(deadline - 0.5,
                         time.process_time() + max(1.0, (deadline - time.process_time()) * 0.4))
            if time.process_time() < sub_dl - 0.4:
                h_try = _exact_lbfgs(h_try, 120, sub_dl)
            r_try = R_of(h_try)
            if time.process_time() < sub_dl - 0.4:
                h_try, r_try = _window_polish(h_try, sub_dl, window=64, stride=32,
                                              maxiter=60)
            if r_try > bestR + 1e-12:
                best, bestR = h_try, r_try
                n_accept += 1
                print("phase accept #%d eps=%.3f R=%.7f" % (n_accept, eps, bestR))
    print("phase-anneal done: trials=%d accepts=%d R=%.7f"
          % (n_trial, n_accept, bestR))

    # ===== Existing multigrid + polish on whatever best is now. =====
    N_fine = best.size
    scales = [N_fine // 4, N_fine // 2, N_fine]
    scales = [s for s in scales if s >= 16]
    for Nc in scales:
        if time.process_time() >= deadline - 3.0:
            break
        if Nc >= N_fine:
            h_c = best.copy()
        else:
            h_c = _coarse_from_fine(best, Nc)
        h_c = _rescale_maxL(h_c)
        sub_deadline = min(deadline - 2.0,
                           time.process_time() + (deadline - time.process_time()) * 0.35)
        h_opt, r_opt = _refine(h_c, sub_deadline, rounds=1, maxiter=3000)
        if Nc < N_fine:
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("multigrid N=%d->%d R=%.7f" % (Nc, N_fine, bestR))
        else:
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    if time.process_time() < deadline - 2.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=1500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine R=%.7f" % bestR)
        h, r = _window_polish(best, deadline, window=64, stride=32, maxiter=60)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("window R=%.7f" % bestR)

    while time.process_time() < deadline - 1.0:
        h, r = _window_polish(best, deadline, window=64, stride=32, maxiter=60)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("window R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=80):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _smooth(h, k):
    if k <= 0:
        return h.copy()
    ker = np.ones(2 * k + 1)
    ker /= ker.sum()
    hp = np.concatenate((np.full(k, h[0]), h, np.full(k, h[-1])))
    return np.convolve(hp, ker, mode='valid')


def _try_smoothing(best, bestR, deadline, strengths=(1, 2, 4)):
    for k in strengths:
        if time.process_time() >= deadline - 2.0:
            break
        hs = _rescale_maxL(_smooth(best, k))
        sub = min(deadline - 1.0, time.process_time() + 3.0)
        cand = _exact_lbfgs(hs, 400, sub)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
            print("smooth k=%d R=%.7f" % (k, bestR))
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # 1) Full L-BFGS refine of the start.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 3.0, rounds=2, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine1 R=%.7f" % bestR)

    # 2) Smoothing kicks.
    best, bestR = _try_smoothing(best, bestR, deadline, strengths=(1, 2, 4))

    # 3) Overlapping-window polish.
    for win, stride in ((128, 64), (64, 32), (32, 16)):
        if time.process_time() >= deadline - 2.0:
            break
        h, r = _window_polish(best, deadline - 1.0, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win%d R=%.7f" % (win, bestR))

    # 4) Another full refine.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 1.5, rounds=1, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine2 R=%.7f" % bestR)

    # 5) Alternate until time runs out.
    while time.process_time() < deadline - 2.0:
        improved = False
        b2, r2 = _try_smoothing(best, bestR, deadline, strengths=(1, 2))
        if r2 > bestR + 1e-15:
            best, bestR = b2, r2
            improved = True
        h, r = _window_polish(best, deadline - 1.0, window=64, stride=32, maxiter=200)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win64 R=%.7f" % bestR)
            improved = True
        if time.process_time() < deadline - 2.5:
            h, r = _refine(best, deadline - 1.0, rounds=1, maxiter=2000)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("refine R=%.7f" % bestR)
                improved = True
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.clip(best, 0, None)

