        xb = np.linspace(0.0, 1.0, n + 1)
        Sb = np.interp(xb, xs, S)
        Sb = np.maximum.accumulate(Sb)
        return np.clip(np.diff(Sb), 0.0, None)
    return h2.reshape(n, k).sum(axis=1)


def _fine_refine(h, deadline, k=2, maxiter=400):
    if time.process_time() >= deadline - 0.5:
        return h, R_of(h)
    n = h.size
    h2 = _upsample(h, k)
    h2o = _exact_lbfgs(h2, maxiter, deadline)
    h_ds = _rescale_maxL(_downsample(h2o, n))
    r0 = R_of(h)
    r1 = R_of(h_ds)
    if r1 > r0 + 1e-16:
        return h_ds, r1
    return h, r0


def _grow_and_refine(h, deadline, R0):
    """Insert extra steps inside the coarse cells to add resolution, then
    jointly optimise on the expanded grid. Returns candidate at larger N."""
    if time.process_time() >= deadline - 1.0:
        return h, R0
    n = h.size
    # aim for ~1.4x resolution per growth step, capped
    k = 2 if n < 120000 else 1
    if k == 1:
        return h, R0
    h2 = _upsample(h, k)  # split each cell into k equal pieces, mass preserved
    sub_dl = min(deadline, time.process_time() +
                 max(1.0, (deadline - time.process_time()) * 0.6))
    h2o = _exact_lbfgs(h2, maxiter=800, deadline=sub_dl)
    r2 = R_of(h2o)
    if r2 > R0 + 1e-16:
        return h2o, r2
    return h, R0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
            print("start R=%.7f (N=%d)" % (bestR, best.size))

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)
        print("fallback R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: fine-grid refinement at native resolution
    for k in (2, 3):
        if time.process_time() >= deadline - 3.0:
            break
        sub_dl = min(deadline - 2.0, time.process_time() +
                     (deadline - time.process_time()) * 0.30)
        h_up, r_up = _fine_refine(best, sub_dl, k=k, maxiter=600)
        if time.process_time() < deadline - 1.5:
            h_p, r_p = _refine(h_up, min(deadline - 1.0,
                                         time.process_time() +
                                         (deadline - time.process_time()) * 0.4),
                               rounds=1, maxiter=1500)
            if r_p > r_up:
                h_up, r_up = h_p, r_p
        if r_up > bestR + 1e-16:
            best, bestR = h_up, r_up
            print("fine k=%d: new best R=%.7f (N=%d)" % (k, bestR, best.size))
        else:
            print("fine k=%d: no gain (R=%.7f vs %.7f)" % (k, r_up, bestR))

    # Phase 2: native polish loop until deadline
    it = 0
    while time.process_time() < deadline - 1.0:
        it += 1
        prev = bestR
        remain = deadline - time.process_time()
        sub_dl = time.process_time() + max(1.0, remain * 0.4)
        h, r = _refine(best, sub_dl, rounds=1, maxiter=3000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if time.process_time() >= deadline - 2.0:
            break
        sub_dl = min(deadline - 1.5, time.process_time() +
                     max(1.0, (deadline - time.process_time()) * 0.5))
        h, r = _overlap_polish(best, sub_dl, window=256, stride=128, maxiter=120)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if time.process_time() < deadline - 4.0 and it % 2 == 0:
            sub_dl = min(deadline - 2.0, time.process_time() +
                         (deadline - time.process_time()) * 0.35)
            h, r = _fine_refine(best, sub_dl, k=2, maxiter=400)
            if r > bestR + 1e-16:
                best, bestR = h, r
        print("iter %d R=%.7f (N=%d)" % (it, bestR, best.size))
        if bestR - prev < 1e-12 and it >= 3:
            break

    best = _rescale_maxL(np.clip(best, 0, None))
    bestR = R_of(best)
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    K = max(1, min(K, Lf.size))
    if K == 1:
        return _norm_eq_fun_grad(h)
    idx = np.argpartition(Lf, -K)[-K:]
    top = Lf[idx]
    mean_top = top.sum() / K
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / K) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, K=1):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        if K == 1:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _full_polish(h, deadline, iters=3000):
    return _exact_lbfgs(h, iters, 2 * iters, deadline)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _smooth(h, k):
    if k <= 1:
        return h
    kern = np.ones(k) / k
    hs = np.convolve(h, kern, mode='same')
    hs = np.clip(hs, 0, None)
    return _rescale_maxL(hs)


def _anneal(h, deadline, iters=2000, seed=0):
    rng = np.random.RandomState(seed)
    best = h.copy()
    bestR = R_of(best)
    n = best.size
    cur = best.copy()
    curR = bestR
    for it in range(iters):
        if time.process_time() > deadline - 0.6:
            break
        cand = cur.copy()
        mode = rng.randint(3)
        if mode == 0:
            k = int(rng.randint(2, 7))
            cand = _smooth(cand, k)
        elif mode == 1:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 4))))
            factor = np.exp(rng.normal(0, 0.05))
            cand[a:b] *= factor
        else:
            a = rng.randint(0, n)
            b = min(n, a + int(rng.randint(1, max(2, n // 6))))
            cand[a:b] += rng.normal(0, 1e-3 * (cand.max() + 1e-12), b - a)
        cand = _rescale_maxL(np.clip(cand, 0, None))
        rc = R_of(cand)
        if rc > curR or rng.rand() < 0.05:
            cur, curR = cand, rc
        if rc > bestR:
            best, bestR = cand.copy(), rc
    return best, bestR


def _edge_refine(h, deadline, iters=800):
    if time.process_time() >= deadline - 0.6:
        return h
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return h
    idx = np.flatnonzero(Lf >= 0.98 * mx)
    if idx.size == 0:
        return h
    w = max(8, int((idx.max() - idx.min() + 1) * 0.5))
    left = np.arange(0, min(n, w))
    right = np.arange(max(0, n - w), n)
    free = np.unique(np.concatenate((left, right)))
    return _exact_lbfgs(h, iters, 2 * iters, deadline, free=free)


def _remesh(h, p, N):
    n = h.size
    if N < 2:
        return h.copy()
    idx = np.round((np.arange(N) / (N - 1)) ** p * (n - 1)).astype(int)
    idx = np.clip(idx, 0, n - 1)
    return h[idx].copy()


def _tail_pen_lbfgs(h0, lam, deadline, iters=800):
    """Shrink the far tail (where f*f has decayed) to reallocate resolution."""
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    active = np.flatnonzero(h > 1e-13 * h.max())
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(active.size)
        num, dq, Lf = _num_and_dq(hh)
        m = int(np.argmax(Lf))
        Lm = Lf[m]
        gLf = -dq / num
        gLf[m] += 1.0 / Lm
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
        # penalise mass in last 15% of domain
        cut = int(0.85 * n)
        if lam > 0 and cut < n:
            val += lam * hh[cut:].sum() / s
            g = _backprop(gLf, hh) + 2.0 / s
            g[cut:] += lam / s
            g -= lam * hh[cut:].sum() / (s * s)
        else:
            g = _backprop(gLf, hh) + 2.0 / s
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.88

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # NEW: tail-shrink remesh — squeeze the far tail so resolution
    # concentrates where f*f is near its max, then resample at same N.
    n0 = best.size
    if n0 >= 4000:
        for lam in (0.02, 0.05, 0.1):
            if time.process_time() >= deadline - 3.0:
                break
            hs = _tail_pen_lbfgs(best, lam, deadline, iters=400)
            rs = R_of(hs)
            print("tailpen lam=%.2f R=%.7f" % (lam, rs))
            if rs > bestR + 1e-15:
                best, bestR = hs.copy(), rs

    # Top-K mean-max proxy ladder.
    h = best.copy()
    for K in (30, 15, 8, 4, 2, 1):
        if time.process_time() >= deadline - 2.0:
            break
        h = _exact_lbfgs(h, 600, 1200, deadline, K=K)
        r = R_of(h)
        print("K=%d R=%.7f" % (K, r))
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r

    # Alternating polish loop.
    stall = 0
    while time.process_time() < deadline - 1.5:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _edge_refine(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("edge R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _full_polish(best, deadline, iters=1500)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                ha, ra = _anneal(best, deadline, iters=400, seed=stall)
                if ra > bestR + 1e-15:
                    h2 = _full_polish(ha, deadline, iters=800)
                    r2 = R_of(h2)
                    if r2 > bestR + 1e-15:
                        best, bestR = h2.copy(), r2
                        stall = 0
                        print("anneal R=%.7f" % bestR)
                if stall >= 4:
                    h = _window_polish(best, deadline, frac=0.6, extra=16)
                    r = R_of(h)
                    if r > bestR + 1e-15:
                        best, bestR = h.copy(), r
                        stall = 0
                        print("wide R=%.7f" % bestR)
                    else:
                        break
        else:
            stall = 0

    # Power-law remeshing stage.
    N_remesh = max(n0, 42496)
    for p in (1.3, 1.6, 2.0, 2.5, 3.0, 0.7, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _rescale_maxL(_remesh(best, p, N_remesh))
        r0 = R_of(hp)
        hp = _exact_lbfgs(hp, 1500, 3000, deadline)
        r1 = R_of(hp)
        if time.process_time() < deadline - 1.0:
            hp = _window_polish(hp, deadline)
        r2 = R_of(hp)
        print("remesh p=%.2f R %.7f -> %.7f -> %.7f" % (p, r0, r1, r2))
        if r2 > bestR + 1e-15:
            best, bestR = hp.copy(), r2
            print("remesh ACCEPT p=%.2f R=%.7f" % (p, bestR))

    # Upsampling stage.
    while time.process_time() < deadline - 1.0:
        n = best.size
        if n >= 200000:
            break
        factor = 2 if n * 2 <= 200000 else max(1, 200000 // n)
        if factor < 2:
            break
        cand = _rescale_maxL(_upsample(best, factor))
        rc = R_of(cand)
        if rc >= bestR - 1e-5:
            h = _full_polish(cand, deadline, iters=1500)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("upsample(f=%d) R=%.7f N=%d" % (factor, bestR, best.size))
            else:
                best, bestR = cand.copy(), rc
                print("upsample(f=%d,raw) R=%.7f N=%d" % (factor, bestR, best.size))
        else:
            break

    # Final polish.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _window_polish(best, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final window R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.0:
            break
        h = _full_polish(best, deadline, iters=1200)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
            improved = True
            print("final full R=%.7f" % bestR)
        if not improved:
            stall += 1
            if stall >= 2:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
