        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=60):
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        cand = _block_lbfgs_linear(best, np.arange(n), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR:
            return cand, r
        return best, bestR
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _smooth(h, k):
    if k <= 0:
        return h.copy()
    ker = np.ones(2 * k + 1)
    ker /= ker.sum()
    hp = np.concatenate((np.full(k, h[0]), h, np.full(k, h[-1])))
    return np.convolve(hp, ker, mode='valid')


def _try_smoothing(best, bestR, deadline, strengths=(1, 2, 4, 8)):
    for k in strengths:
        if time.process_time() >= deadline - 2.0:
            break
        hs = _rescale_maxL(_smooth(best, k))
        sub = min(deadline - 1.0, time.process_time() + 3.0)
        cand = _exact_lbfgs(hs, 400, sub)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
            print("smooth k=%d R=%.7f" % (k, bestR))
    return best, bestR


# ---- Chebyshev / Lawson-IRLS flattening of L ----

def _cheb_fun_grad(h, eps):
    """f(h) = sum_j w_j d_j^2 / sum_j w_j, d_j = (1 - Lf_j)_+, w_j = 1/(d_j + eps).
    Max L treated as fixed stop-gradient constant 1."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    d = 1.0 - Lf
    d = np.maximum(d, 0.0)
    w = 1.0 / (d + eps)
    W = w.sum()
    val = np.sum(w * d * d) / W
    # gradient of val wrt Lf: 2 w d / W (w depends on d, but w*d^2 = d^2/(d+eps);
    # d/dd [d^2/(d+eps)] = (2d(d+eps) - d^2)/(d+eps)^2 = (d^2 + 2 d eps)/(d+eps)^2
    # and W also depends on d: W = sum 1/(d+eps), dW/dd_j = -1/(d_j+eps)^2.
    # Include the W-dependence for correctness.
    num = np.sum(w * d * d)
    # dnum/dd_j = (d_j^2 + 2 d_j eps)/(d_j+eps)^2
    dn = (d * d + 2 * d * eps) / ((d + eps) ** 2)
    dW = -1.0 / ((d + eps) ** 2)
    # val = num/W; dval/dd_j = dn_j/W - num*dW_j/W^2
    dval_dd = dn / W - num * dW / (W * W)
    # d = max(1 - Lf, 0); dd/dLf = -1 where d > 0
    gLf = np.where(d > 0, -dval_dd, 0.0)
    grad = _backprop(gLf, h)
    return val, grad


def _cheb_lbfgs(h0, eps, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _cheb_fun_grad(hh, eps)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_band_window_polish(h, deadline, window=192, maxiter=120):
    """Window polish concentrated around the peak region of L."""
    best = h
    bestR = R_of(h)
    n = h.size
    if n <= window:
        return _window_polish(best, deadline, window=n, stride=max(1, n // 2),
                              maxiter=maxiter)
    # find peak location of L in support coordinates
    Lf = _knots(best)
    m = int(np.argmax(Lf))
    # Lf index m corresponds to knot m; support index ~ m (0..n). Center window there.
    center = min(max(m, 0), n)
    half = window // 2
    lo = max(0, center - half)
    hi = min(n, lo + window)
    lo = max(0, hi - window)
    stride = max(1, window // 4)
    pos = lo
    while pos < hi:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _cheb_ladder(best, bestR, deadline):
    eps_list = [1e-1, 3e-2, 1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 1e-6]
    cur = best
    for eps in eps_list:
        if time.process_time() >= deadline - 1.5:
            break
        sub = min(deadline - 1.0, time.process_time() + 4.0)
        cand = _cheb_lbfgs(cur, eps, 400, sub)
        # exact K=1 polish
        if time.process_time() < deadline - 1.0:
            cand = _exact_lbfgs(cand, 600, min(deadline - 0.5,
                                               time.process_time() + 3.0))
        if time.process_time() < deadline - 1.0:
            cand, _ = _peak_band_window_polish(cand, deadline, window=192,
                                               maxiter=120)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("cheb eps=%.0e R=%.7f" % (eps, bestR))
        cur = cand
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    cheb_deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(h)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # 1) Full L-BFGS refine of the start.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 3.0, rounds=2, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine1 R=%.7f" % bestR)

    # 2) Chebyshev/Lawson ladder loop until 0.92*budget.
    while time.process_time() < cheb_deadline - 2.0:
        b2, r2 = _cheb_ladder(best, bestR, cheb_deadline)
        if r2 > bestR + 1e-16:
            best, bestR = b2, r2
        else:
            # no improvement this round; still try a smoothing kick
            b3, r3 = _try_smoothing(best, bestR, deadline, strengths=(1, 2))
            if r3 > bestR + 1e-16:
                best, bestR = b3, r3
            else:
                break

    # 3) Overlapping-window polish with larger windows.
    for win, stride in ((128, 64), (64, 32), (32, 16)):
        if time.process_time() >= deadline - 2.0:
            break
        h, r = _window_polish(best, deadline - 1.0, window=win, stride=stride,
                              maxiter=200)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win%d R=%.7f" % (win, bestR))

    # 4) Another full refine after window polish.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 1.5, rounds=1, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine2 R=%.7f" % bestR)

    # 5) Loop: alternate smoothing + window polish + refine until time runs out.
    while time.process_time() < deadline - 2.0:
        improved = False
        b2, r2 = _try_smoothing(best, bestR, deadline, strengths=(1, 2))
        if r2 > bestR + 1e-15:
            best, bestR = b2, r2
            improved = True
        h, r = _window_polish(best, deadline - 1.0, window=64, stride=32,
                              maxiter=200)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win64 R=%.7f" % bestR)
            improved = True
        if time.process_time() < deadline - 2.5:
            h, r = _refine(best, deadline - 1.0, rounds=1, maxiter=2000)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("refine R=%.7f" % bestR)
                improved = True
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.clip(best, 0, None)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    base = h.copy()

    def f(x):
        hh = base.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = base.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish(h, deadline, frac=0.4, extra=6, maxiter=400):
    if time.process_time() >= deadline - 0.8:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _block_lbfgs_linear(h, free, maxiter, deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.94

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Upsample once to give finer resolution, keep if not worse.
    if best.size < 100000:
        cand = _rescale_maxL(_upsample(best, 2))
        r = R_of(cand)
        if r > bestR - 1e-6:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    # Alternate: full exact L-BFGS + window polish on the peak region.
    # The window polish with linear (non-log) parametrization allows
    # zeroing out support, which the log parametrization forbids.
    cycle = 0
    stall = 0
    while time.process_time() < deadline - 1.5:
        cycle += 1
        prevR = bestR
        h = _exact_lbfgs(best, 2000, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
        # Several window polishes with varying widths.
        for frac, extra, mi in ((0.15, 4, 300), (0.35, 6, 400),
                                (0.6, 12, 500), (1.0, 30, 600)):
            if time.process_time() >= deadline - 1.5:
                break
            h = _window_polish(best, deadline, frac=frac, extra=extra, maxiter=mi)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
        if bestR > prevR + 1e-15:
            print("cycle %d R=%.7f" % (cycle, bestR))
            stall = 0
        else:
            stall += 1
            if stall >= 2:
                # Try upsampling again to escape.
                if best.size < 150000:
                    cand = _rescale_maxL(_upsample(best, 2))
                    r = R_of(cand)
                    if r > bestR - 1e-6:
                        best, bestR = cand, r
                        print("re-upsample R=%.7f (N=%d)" % (bestR, best.size))
                        stall = 0
                        continue
                break

    # Final exact polish.
    hard = t0 + budget_seconds * 0.98
    while time.process_time() < hard - 0.6:
        h = _exact_lbfgs(best, 4000, hard - 0.3)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

