import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=80):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _resample(h, N):
    """Resample step heights to N steps preserving the piecewise-constant integral."""
    n = h.size
    if n == N:
        return h.copy()
    # cumulative integral of the step function on [0, n]
    c = np.concatenate(([0.0], np.cumsum(h)))
    # target knot positions in original units
    edges = np.linspace(0.0, float(n), N + 1)
    vals = np.interp(edges, np.arange(n + 1, dtype=float), c)
    seg = np.diff(vals)
    # seg = integral over each new cell; height = seg / cellwidth
    cellw = n / float(N)
    return seg / cellw


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # 0) Try a coarser/finer representation via resampling + refine, keeping best.
    n0 = best.size
    for N in (n0 // 2, int(n0 * 0.75), n0, int(n0 * 1.5)):
        if N < 200 or N > 200000:
            continue
        if time.process_time() >= deadline - 4.0:
            break
        hs = _rescale_maxL(_resample(best, N))
        sub = min(deadline - 2.0, time.process_time() + 4.0)
        cand = _exact_lbfgs(hs, 600, sub)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
            print("resample N=%d R=%.7f" % (N, bestR))

    # 1) Full L-BFGS refine of the start.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 3.0, rounds=2, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine1 R=%.7f" % bestR)

    # 3) Overlapping-window polish (small windows first, cheaper).
    for win, stride in ((32, 16), (64, 32), (128, 64), (256, 128)):
        if time.process_time() >= deadline - 2.0:
            break
        h, r = _window_polish(best, deadline - 1.0, window=win, stride=stride, maxiter=150)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win%d R=%.7f" % (win, bestR))

    # 4) Another full refine.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 1.5, rounds=1, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine2 R=%.7f" % bestR)

    # 5) Alternate polishing and refining until time runs out.
    guard = 0
    while time.process_time() < deadline - 2.0 and guard < 50:
        guard += 1
        improved = False
        h, r = _window_polish(best, deadline - 1.0, window=64, stride=32, maxiter=150)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win64 R=%.7f" % bestR)
            improved = True
        if time.process_time() < deadline - 2.5:
            h, r = _refine(best, deadline - 1.0, rounds=1, maxiter=2000)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("refine R=%.7f" % bestR)
                improved = True
        if not improved:
            # try a tiny random perturbation to escape local optimum
            if time.process_time() < deadline - 3.0:
                pert = best * (1.0 + 0.002 * np.random.randn(best.size))
                pert = _rescale_maxL(pert)
                sub = min(deadline - 1.0, time.process_time() + 3.0)
                cand = _exact_lbfgs(pert, 400, sub)
                r = R_of(cand)
                if r > bestR + 1e-15:
                    best, bestR = cand, r
                    print("pert R=%.7f" % bestR)
                else:
                    break
            else:
                break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.clip(best, 0, None)

