    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None, use_log=True):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    if use_log:
        x0 = np.log(np.clip(h[active], 1e-300, None))
        bounds = [(-30.0, 30.0)] * active.size

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _norm_eq_fun_grad(hh)
            return val, g[active] * hh[active]
    else:
        x0 = h[active].copy()
        bounds = [(0.0, None)] * active.size

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = _norm_eq_fun_grad(hh)
            return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    h2 = h.copy()
    if use_log:
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    else:
        h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    return _exact_lbfgs(h0, maxiter, deadline, free=free, use_log=False)


def _window_polish(h, deadline, window=64, stride=32, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.8:
            break
        end = min(pos + window, n)
        cand = _block_lbfgs_linear(best, np.arange(pos, end), maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _perturb_refine(best, bestR, deadline, scale, rng):
    """Random multiplicative perturbation, then full refine. Keep if improved."""
    if time.process_time() >= deadline - 2.0:
        return best, bestR
    n = best.size
    noise = np.exp(scale * rng.standard_normal(n))
    hp = _rescale_maxL(best * noise)
    sub = min(deadline - 1.0, time.process_time() + 6.0)
    cand = _exact_lbfgs(hp, 1500, sub)
    r = R_of(cand)
    if r > bestR + 1e-15:
        return cand, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # 1) Full refine with log-parametrization (handles spikes well).
    if time.process_time() < deadline - 3.0:
        sub = min(deadline - 2.0, time.process_time() + budget_seconds * 0.35)
        cand = _exact_lbfgs(best, 4000, sub)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("refine-log R=%.7f" % bestR)

    # 2) Linear-parametrization full refine (better for smooth parts).
    if time.process_time() < deadline - 2.0:
        sub = min(deadline - 1.5, time.process_time() + budget_seconds * 0.20)
        cand = _exact_lbfgs(best, 4000, sub, use_log=False)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("refine-lin R=%.7f" % bestR)

    # 3) Alternating window polish + refine until time out.
    rng = np.random.default_rng(12345)
    win_sizes = [(128, 64), (64, 32), (32, 16)]
    wi = 0
    while time.process_time() < deadline - 1.5:
        win, stride = win_sizes[wi % len(win_sizes)]
        wi += 1
        cand, r = _window_polish(best, deadline, window=win, stride=stride, maxiter=150)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("win%d R=%.7f" % (win, bestR))
        if time.process_time() >= deadline - 1.5:
            break
        sub = min(deadline - 1.0, time.process_time() + 3.0)
        cand = _exact_lbfgs(best, 2000, sub)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("refine R=%.7f" % bestR)

    # 4) Perturbation kicks if time remains.
    tries = 0
    while time.process_time() < deadline - 1.5 and tries < 6:
        tries += 1
        scale = 0.02 / (1 + tries)
        b2, r2 = _perturb_refine(best, bestR, deadline, scale, rng)
        if r2 > bestR + 1e-15:
            best, bestR = b2, r2
            print("perturb R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.clip(best, 0, None)

