    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=80):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 1.0:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _smooth(h, k):
    if k <= 0:
        return h.copy()
    ker = np.ones(2 * k + 1)
    ker /= ker.sum()
    hp = np.concatenate((np.full(k, h[0]), h, np.full(k, h[-1])))
    return np.convolve(hp, ker, mode='valid')


def _try_smoothing(best, bestR, deadline, strengths=(1, 2, 4)):
    for k in strengths:
        if time.process_time() >= deadline - 2.0:
            break
        hs = _rescale_maxL(_smooth(best, k))
        sub = min(deadline - 1.0, time.process_time() + 3.0)
        cand = _exact_lbfgs(hs, 400, sub)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
            print("smooth k=%d R=%.7f" % (k, bestR))
    return best, bestR


def _family(N, a, delta, K, T):
    i = np.arange(N, dtype=float)
    h = (i + delta) ** (-a)
    if T > 0 and K < N:
        end = min(K + T, N)
        idx = np.arange(K, end)
        u = (idx - K + 1.0) / float(T)
        taper = (1.0 - u * u) ** 2
        h[idx] *= taper
        if end < N:
            h[end:] = 0.0
    return np.clip(h, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- Experiment: native coarse-N family search ---
    coarse_best = None
    coarse_bestR = 0.0
    coarse_N = None
    try:
        cands = []
        for N in (4096, 8192, 16384):
            if time.process_time() > deadline - 8.0:
                break
            for a in (0.45, 0.50, 0.55):
                for delta in (0.01, 0.1, 1.0):
                    for Kfrac in (0.4, 0.5, 0.6):
                        K = int(Kfrac * N)
                        for Tfrac in (0.05, 0.1, 0.2):
                            T = int(Tfrac * N)
                            h = _family(N, a, delta, K, T)
                            if h.sum() <= 0:
                                continue
                            r = R_of(h)
                            cands.append((r, N, h))
        cands.sort(key=lambda x: -x[0])
        print("family top R=%.7f (of %d)" % (cands[0][0] if cands else 0.0, len(cands)))
        # polish top-3
        for rank, (r0, N, h0) in enumerate(cands[:3]):
            if time.process_time() > deadline - 6.0:
                break
            sub = min(deadline - 4.0, time.process_time() + 5.0)
            hp, rp = _refine(h0, sub, rounds=1, maxiter=3000)
            print("coarse N=%d rank%d R=%.7f -> %.7f" % (N, rank, r0, rp))
            if rp > coarse_bestR:
                coarse_best, coarse_bestR, coarse_N = hp, rp, N
    except Exception as e:
        print("family err", e)

    if coarse_best is not None:
        print("coarse best R=%.7f (N=%d) vs base %.7f" % (coarse_bestR, coarse_N, bestR))
        if coarse_bestR > bestR + 1e-15:
            best, bestR = coarse_best, coarse_bestR
            print("coarse accepted R=%.7f" % bestR)

    # window-polish the coarse-N array if it's the current best
    if coarse_best is not None and best is coarse_best:
        if time.process_time() < deadline - 3.0:
            sub = min(deadline - 2.0, time.process_time() + 4.0)
            h, r = _window_polish(best, sub, window=64, stride=32, maxiter=200)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("coarse win64 R=%.7f" % bestR)

    # 1) Full L-BFGS refine of the start.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 3.0, rounds=2, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine1 R=%.7f" % bestR)

    # 2) Smoothing kicks.
    best, bestR = _try_smoothing(best, bestR, deadline, strengths=(1, 2, 4))

    # 3) Overlapping-window polish.
    for win, stride in ((128, 64), (64, 32), (32, 16)):
        if time.process_time() >= deadline - 2.0:
            break
        h, r = _window_polish(best, deadline - 1.0, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win%d R=%.7f" % (win, bestR))

    # 4) Another full refine.
    if time.process_time() < deadline - 3.0:
        h, r = _refine(best, deadline - 1.5, rounds=1, maxiter=2500)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("refine2 R=%.7f" % bestR)

    # 5) Alternate until time runs out.
    while time.process_time() < deadline - 2.0:
        improved = False
        b2, r2 = _try_smoothing(best, bestR, deadline, strengths=(1, 2))
        if r2 > bestR + 1e-15:
            best, bestR = b2, r2
            improved = True
        h, r = _window_polish(best, deadline - 1.0, window=64, stride=32, maxiter=200)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win64 R=%.7f" % bestR)
            improved = True
        if time.process_time() < deadline - 2.5:
            h, r = _refine(best, deadline - 1.0, rounds=1, maxiter=2000)
            if r > bestR + 1e-15:
                best, bestR = h, r
                print("refine R=%.7f" % bestR)
                improved = True
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.clip(best, 0, None)

