                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _topk_flatten_lbfgs(h0, free, K, maxiter, deadline):
    """Linear L-BFGS on free set, objective = num/s^2 / mean(top-K knots)."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    n = h.size
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        s = hh.sum()
        if s <= 0:
            return 1e18, np.zeros(active.size)
        num, dq, Lf = _num_and_dq(hh)
        Lk = Lf[1:-1]
        k = min(K, Lk.size)
        # top-k indices
        idx = np.argpartition(Lk, -k)[-k:]
        topmean = Lk[idx].mean()
        if topmean <= 0:
            return 1e18, np.zeros(active.size)
        # objective = num / (s^2 * topmean)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(topmean)
        # gradient wrt Lf
        gLf = np.zeros_like(Lf)
        gLf[1:-1] = -dq / num
        # d topmean / d Lf: 1/k on top-k indices (in Lf[1:-1] offsets +1)
        gLf[idx + 1] += 1.0 / (k * topmean)
        grad = _backprop(gLf, hh) + 2.0 / s
        return val, grad[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _argmax_window(h, window=512):
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    # knot index m corresponds to cell boundary; centre window on cell m
    n = h.size
    c = min(max(m, 0), n)
    lo = max(0, c - window // 2)
    hi = min(n, lo + window)
    lo = max(0, hi - window)
    return np.arange(lo, hi)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _free_set_band(h, lo_frac=0.5, hi_frac=1.0):
    """Cells i where knot L[i] or L[i+1] in [lo_frac*M, hi_frac*M]."""
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return np.arange(h.size)
    lo = lo_frac * M
    hi = hi_frac * M
    n = h.size
    # Lf has length n+1; cell i touches knots i and i+1
    mask = np.zeros(n, dtype=bool)
    inband = (Lf >= lo) & (Lf <= hi)
    # cell i touches Lf[i] and Lf[i+1]
    mask |= inband[:-1]
    mask |= inband[1:]
    return np.flatnonzero(mask)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Experiment: top-K mean-flattening on band-restricted free set ----
    def run_topk_cycle(best, bestR, deadline):
        free = _free_set_band(best, 0.5, 1.0)
        if free.size == 0:
            return best, bestR
        Ks = [15000, 8000, 4000, 2000, 1000, 500, 200, 100, 50, 20, 10, 5, 2, 1]
        for K in Ks:
            if time.process_time() >= deadline - 2.0:
                break
            cand = _topk_flatten_lbfgs(best, free, K, maxiter=800, deadline=deadline)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
            # exact K=1 full polish
            if time.process_time() < deadline - 2.0:
                h2, r2 = _refine(best, deadline, rounds=1, maxiter=800)
                if r2 > bestR + 1e-16:
                    best, bestR = h2, r2
            # argmax-centred 512-cell linear block polish
            if time.process_time() < deadline - 2.0:
                win = _argmax_window(best, 512)
                cand2 = _block_lbfgs_linear(best, win, maxiter=300, deadline=deadline)
                r3 = R_of(cand2)
                if r3 > bestR + 1e-16:
                    best, bestR = cand2, r3
            # refresh free set as shape changes
            free = _free_set_band(best, 0.5, 1.0)
        return best, bestR

    best, bestR = run_topk_cycle(best, bestR, deadline)
    print("topk cycle R=%.7f" % bestR)

    # ---- Keep base's primary fine-grained local search ----
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        win = max(32, min(256, n // 8))
        stride = max(16, win // 2)
        h, r = _window_polish(best, deadline, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if bestR - prev < 1e-12:
            h, r = _window_polish(best, deadline, window=max(8, win // 4),
                                  stride=max(4, stride // 2), maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = h, r
            else:
                break
        print("polish R=%.7f" % bestR)

    # ---- Secondary: multigrid coarsening if time remains ----
    if time.process_time() < deadline - 3.0:
        N_fine = best.size
        for Nc in [max(16, N_fine // 4), max(16, N_fine // 2)]:
            if time.process_time() >= deadline - 2.0:
                break
            h_c = _coarse_from_fine(best, Nc)
            h_c = _rescale_maxL(h_c)
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt, r_opt = _refine(h_c, sub_dl, rounds=1, maxiter=3000)
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Tertiary: try a larger N by prolongating, then refine ----
    if time.process_time() < deadline - 3.0:
        for N_big in [min(200000, int(best.size * 1.5)), min(200000, best.size * 2)]:
            if time.process_time() >= deadline - 2.0:
                break
            if N_big <= best.size:
                continue
            h_big = _prolongate(best, N_big)
            h_big = _rescale_maxL(h_big)
            r_big = R_of(h_big)
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.4)
            h_opt, r_opt = _refine(h_big, sub_dl, rounds=1, maxiter=2000)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final full refine to use remaining budget ----
    if time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("final refine R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _deconvolve_causal(g, N):
    """Exact causal forward recursion; clip negatives to 0 and continue."""
    h = np.zeros(N)
    h0 = np.sqrt(max(g[0], 0.0))
    if h0 <= 0:
        return np.ones(N)
    h[0] = h0
    for k in range(1, N):
        s = 0.0
        for i in range(1, k):
            s += h[i] * h[k - i]
        val = (g[k] - s) / (2.0 * h0)
        if val < 0.0:
            val = 0.0
        h[k] = val
    s = h.sum()
    if s > 0:
        h = h / s
    return h


def _deconvolve_causal_fast(g, N):
    """Causal deconvolution via incremental convolution (O(N^2) but vectorized)."""
    h = np.zeros(N)
    h0 = np.sqrt(max(g[0], 0.0))
    if h0 <= 0:
        return np.ones(N)
    h[0] = h0
    # h[k] = (g[k] - sum_{i=1}^{k-1} h[i] h[k-i]) / (2 h0)
    # Maintain partial convolution conv[k] = sum_{i=1}^{k-1} h[i] h[k-i]
    # We'll compute incrementally: after fixing h[k], it contributes to conv[k+1..]
    conv = np.zeros(N + 1)
    for k in range(1, N):
        val = (g[k] - conv[k]) / (2.0 * h0)
        if val < 0.0:
            val = 0.0
        h[k] = val
        # update conv for future indices
        if k + 1 < N + 1:
            # h[k] * h[i] contributes to conv[k+i] for i=1..N-1-k
            hi = h[1:N - k]
            if hi.size > 0:
                conv[k + 1:k + 1 + hi.size] += val * hi
    s = h.sum()
    if s > 0:
        h = h / s
    return h


def _blend_and_recover(hA, hB, alpha, N):
    gA = np.convolve(hA, hA)
    gB = np.convolve(hB, hB)
    m = min(gA.size, gB.size)
    gA = gA[:m]; gB = gB[:m]
    g = (1.0 - alpha) * gA + alpha * gB
    # need g of length 2N-1; pad if necessary
    if g.size < 2 * N - 1:
        g = np.concatenate((g, np.zeros(2 * N - 1 - g.size)))
    return _deconvolve_causal_fast(g, N)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size
    hA = best.copy()

    # ---- Experiment: g-space blending with a neighbour family shape ----
    # We don't have p0705's output in the tree; the experiment says to build hB
    # only from that program's output. Since it's unavailable, we skip the
    # blend experiment and fall back to the base's proven local search.
    # (If it were available, we would blend gA and gB and deconvolve.)
    hB = None  # p0705-family shape not available

    if hB is not None and hB.size == n:
        hB = _rescale_maxL(hB)
        for alpha in [0.1, 0.25, 0.5, 0.75, 0.9]:
            if time.process_time() >= deadline - 3.0:
                break
            try:
                h_rec = _blend_and_recover(hA, hB, alpha, n)
            except Exception:
                continue
            h_rec = _rescale_maxL(h_rec)
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.3)
            h_opt, r_opt = _refine(h_rec, sub_dl, rounds=1, maxiter=3000)
            if r_opt > bestR + 1e-9:
                best, bestR = h_opt, r_opt
                print("blend alpha=%.2f R=%.7f" % (alpha, bestR))

    # ---- Primary: fine-grained local search on the existing start ----
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        win = max(32, min(256, n // 8))
        stride = max(16, win // 2)
        h, r = _window_polish(best, deadline, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if bestR - prev < 1e-12:
            h, r = _window_polish(best, deadline, window=max(8, win // 4),
                                  stride=max(4, stride // 2), maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = h, r
            else:
                break
        print("polish R=%.7f" % bestR)

    # ---- Secondary: multigrid coarsening if time remains ----
    if time.process_time() < deadline - 3.0:
        N_fine = best.size
        for Nc in [max(16, N_fine // 4), max(16, N_fine // 2)]:
            if time.process_time() >= deadline - 2.0:
                break
