            h_c = _rescale_maxL(h_c)
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt, r_opt = _refine(h_c, sub_dl, rounds=1, maxiter=3000)
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Tertiary: try a larger N by prolongating, then refine ----
    if time.process_time() < deadline - 3.0:
        for N_big in [min(200000, int(best.size * 1.5)), min(200000, best.size * 2)]:
            if time.process_time() >= deadline - 2.0:
                break
            if N_big <= best.size:
                continue
            h_big = _prolongate(best, N_big)
            h_big = _rescale_maxL(h_big)
            r_big = R_of(h_big)
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.4)
            h_opt, r_opt = _refine(h_big, sub_dl, rounds=1, maxiter=2000)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final full refine to use remaining budget ----
    if time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("final refine R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None, gtol=1e-16, ftol=1e-20):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': ftol, 'gtol': gtol})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline, gtol=1e-16):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': gtol})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=128, stride=64, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    """Linear (mass-preserving) prolongation of heights to a finer grid."""
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, N_big + 1)
    ns = np.arange(n + 1) / n
    cum = np.interp(xs, ns, S)
    h = np.diff(cum) * N_big
    return np.clip(h, 0, None)


def _restrict(h_big, N_small):
    """Mass-preserving block-average restriction to coarser grid."""
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    edges = np.linspace(0, n, N_small + 1)
    out = np.empty(N_small)
    c = np.concatenate(([0.0], np.cumsum(h_big)))
    for k in range(N_small):
        a = int(round(edges[k])); b = int(round(edges[k + 1]))
        if b <= a:
            b = a + 1
        out[k] = (c[b] - c[a]) / (b - a)
    return np.clip(out, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5  # margin

    if start is not None and len(start) > 0:
        h = np.clip(np.asarray(start, dtype=float), 0, None)
        if h.sum() <= 0:
            h = np.ones(max(1, len(h)))
    else:
        # fallback: a smooth bump
        N = 4096
        x = np.linspace(0, 1, N)
        h = np.exp(-((x - 0.5) ** 2) / 0.05)

    best = _rescale_maxL(h)
    bestR = R_of(best)
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase 1: coarse-to-fine resolution ladder.
    # Restrict to a coarse grid, optimise there, prolongate and refine.
    N_full = best.size
    ladder = []
    N = N_full
    while N >= 256:
        ladder.append(N)
        N = N // 2
    ladder = ladder[::-1]  # ascending, e.g. [256, 512, ...]

    cur = best
    for N in ladder:
        if time.process_time() >= deadline - 1.0:
            break
        if N != cur.size:
            cur = _restrict(cur, N)
        sub_deadline = min(deadline - 0.5,
                           time.process_time() + (deadline - time.process_time()) * 0.25)
        cur, r = _refine(cur, sub_deadline, rounds=2, maxiter=800)
        if r > bestR + 1e-14:
            best, bestR = cur.copy(), r
        print("ladder N=%d R=%.7f" % (N, r))

    # Phase 2: full-grid polish
    if time.process_time() < deadline - 1.0:
        sub_deadline = min(deadline - 0.5,
                           time.process_time() + (deadline - time.process_time()) * 0.5)
        cand, r = _refine(best, sub_deadline, rounds=3, maxiter=2000)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("full R=%.7f" % bestR)

    # Phase 3: window polish for local refinement
    if time.process_time() < deadline - 0.5:
        cand, r = _window_polish(best, deadline, window=256, stride=128, maxiter=150)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("window R=%.7f" % bestR)

    # Phase 4: if time remains, try a finer grid prolongation + polish
    if time.process_time() < deadline - 1.0 and best.size < 200000:
        N_big = min(200000, best.size * 2)
        big = _prolongate(best, N_big)
        big = _rescale_maxL(big)
        sub_deadline = min(deadline - 0.5, time.process_time() + (deadline - time.process_time()) * 0.6)
        cand, r = _refine(big, sub_deadline, rounds=1, maxiter=600)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("upsample R=%.7f (N=%d)" % (bestR, best.size))

    # final safety
    best = _rescale_maxL(np.clip(best, 0, None))
    bestR = R_of(best)
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

