        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = np.concatenate(([0.0], _conv(h), [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _window_polish(h, deadline, window, stride, maxiter=300):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.4:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _lbfgs_block(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Primary: alternating full refine + multi-scale window polish ----
    # Keep trying until no improvement; window polish at several granularities.
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    stall = 0
    while time.process_time() < deadline - 1.0:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        for (w, s) in win_levels:
            if time.process_time() >= deadline - 0.8:
                break
            cand, r = _window_polish(best, deadline, w, s, maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = cand, r
        if bestR - prev < 1e-13:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
        print("polish R=%.7f" % bestR)

    # ---- Multigrid: coarsen, optimize, prolongate back ----
    if time.process_time() < deadline - 2.0:
        N_fine = best.size
        for Nc in [max(16, N_fine // 2), max(16, N_fine // 4)]:
            if time.process_time() >= deadline - 1.5:
                break
            h_c = _rescale(_coarse(best, Nc))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt = _lbfgs_log(h_c, 3000, sub_dl)
            h_up = _rescale(_prolongate(h_opt, N_fine))
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                # polish the prolonged solution
                sub_dl2 = min(deadline - 0.5,
                              time.process_time() + (deadline - time.process_time()) * 0.4)
                h_opt2 = _lbfgs_log(h_up, 3000, sub_dl2)
                r2 = R_of(h_opt2)
                if r2 > bestR + 1e-16:
                    best, bestR = h_opt2, r2
                else:
                    best, bestR = h_up, r_up
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Upsample to larger N and refine ----
    if time.process_time() < deadline - 2.0:
        for N_big in [int(best.size * 1.5), int(best.size * 2)]:
            if N_big > 200000:
                N_big = 200000
            if N_big <= best.size:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            h_big = _rescale(_prolongate(best, N_big))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.4)
            h_opt = _lbfgs_log(h_big, 2000, sub_dl)
            r_opt = R_of(h_opt)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final refine to use remaining budget ----
    while time.process_time() < deadline - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish(best, deadline, 8, 4, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    """Objective -log(num)+2log(s)+log(mean of top-K Lf)."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = min(K, n)
    if k <= 0:
        k = 1
    if k >= n:
        idx = np.arange(n)
    else:
        idx = np.argpartition(Lf, n - k)[n - k:]
    Lk = Lf[idx]
    mean_top = Lk.mean()
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / k) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline, K=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if K is None:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _band_free(h):
    """Map band indicator on convolution knots to cells (sliding-window OR)."""
    n = h.size
    if n > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    M = Lf.max()
    if M <= 0:
        return np.arange(n)
    B = ((Lf >= 0.5 * M) & (Lf <= M)).astype(float)
    # convolution of B with ones(n) > 0 gives OR over window of length n
    # knot j influences cells i with i <= j <= i+n-1, i.e. i in [j-n+1, j]
    win = np.ones(n)
    cnt = np.convolve(B, win, mode='full')
    # cnt[k] corresponds to sum B[j] for j in [k-n+1, k], k = 0..Lf.size+n-2
    # We want for cell i: any knot j in [i, i+n-1] in band.
    # That's sum B[j] over j in [i, i+n-1] = cnt at index i+n-1
    free = np.zeros(n, dtype=bool)
    for i in range(n):
        k = i + n - 1
        if 0 <= k < cnt.size and cnt[k] > 0.5:
            free[i] = True
    if not free.any():
        return np.arange(n)
    return np.flatnonzero(free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Primary: fine-grained local search on the existing start ----
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        win = max(32, min(256, n // 8))
        stride = max(16, win // 2)
        h, r = _window_polish(best, deadline, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if bestR - prev < 1e-12:
            h, r = _window_polish(best, deadline, window=max(8, win // 4),
                                  stride=max(4, stride // 2), maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = h, r
            else:
                break
        print("polish R=%.7f" % bestR)

    # ---- Experiment: band-restricted top-K mean flattening ----
    Ks = [20000, 10000, 5000, 2000, 1000, 500, 200, 100, 50, 20, 10, 5, 2, 1]
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        free = _band_free(best)
        if free.size == 0:
            break
        improved = False
        for K in Ks:
            if time.process_time() >= deadline - 0.8:
                break
            cand = _block_lbfgs_linear(best, free, maxiter=300,
                                       deadline=deadline, K=K)
            r = R_of(cand)
            if r > bestR + 1e-16:
                best, bestR = cand, r
                improved = True
                print("band K=%d R=%.7f" % (K, bestR))
            # exact K=1 refine
            if time.process_time() >= deadline - 0.8:
                break
            cand2 = _exact_lbfgs(best, 300, deadline)
            r2 = R_of(cand2)
            if r2 > bestR + 1e-16:
                best, bestR = cand2, r2
                improved = True
                print("band exact R=%.7f" % bestR)
        # peak-window polish
        if time.process_time() < deadline - 0.8:
            h, r = _window_polish(best, deadline, window=max(16, n // 16),
                                  stride=max(8, n // 32), maxiter=150)
            if r > bestR + 1e-16:
                best, bestR = h, r
                improved = True
                print("band polish R=%.7f" % bestR)
        if not improved:
            break

    # ---- Final full refine to use remaining budget ----
    if time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("final refine R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

