    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.diff(Sb)
    h = np.clip(h, 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse_from_fine(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.diff(Sb)
    hc = np.clip(hc, 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _de_edge_search(h, deadline, block=2048, time_cap=12.0):
    """Population-based global search on first `block` log-heights, rest frozen."""
    n = h.size
    if n < 4:
        return h, R_of(h)
    b = min(block, n)
    base = h.copy()
    tail = base[b:].copy()
    tail_sum = tail.sum()

    def unpack(x):
        hh = np.empty(n)
        hh[:b] = np.exp(np.clip(x, -30.0, 10.0))
        hh[b:] = tail
        return hh

    def obj(x):
        hh = unpack(x)
        s = hh.sum()
        if s <= 0:
            return 1.0
        return -R_of(hh)

    x0 = np.log(np.clip(base[:b], 1e-12, None))
    bounds = [(-30.0, 10.0)] * b
    t_start = time.process_time()
    t_end = min(deadline - 1.0, t_start + time_cap)
    if t_end <= t_start + 0.5:
        return h, R_of(h)

    # DE with a wall-clock cap via callback on generation
    class _Cap(Exception):
        pass

    def _cb(xk, convergence=None):
        if time.process_time() > t_end:
            raise _Cap

    best_h = h
    bestR = R_of(h)
    try:
        res = differential_evolution(
            obj, bounds, x0=x0, popsize=15, maxiter=200,
            polish=False, seed=12345, tol=0.0,
            callback=_cb, updating='immediate', workers=1)
        cands = [res.x]
    except _Cap:
        cands = []
    except Exception:
        cands = []

    # Also collect a few random perturbed candidates around x0 as fallback
    rng = np.random.default_rng(12345)
    for _ in range(2):
        cands.append(x0 + rng.normal(0, 0.5, size=b))

    scored = []
    for x in cands:
        hh = unpack(x)
        scored.append((R_of(hh), x))
    scored.sort(key=lambda t: -t[0])
    top = scored[:3]

    for _, x in top:
        if time.process_time() >= deadline - 1.0:
            break
        hh = unpack(x)
        hh = _rescale_maxL(hh)
        # exact full L-BFGS
        h2, r2 = _refine(hh, deadline, rounds=1, maxiter=2000)
        if r2 > bestR + 1e-16:
            best_h, bestR = h2, r2
        # window polish on the edge block
        win = max(32, min(256, b // 4))
        stride = max(16, win // 2)
        h3, r3 = _window_polish(best_h, deadline, window=win, stride=stride, maxiter=200)
        if r3 > bestR + 1e-16:
            best_h, bestR = h3, r3

    return best_h, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Experiment: DE global search on first 2048 edge cells ----
    if time.process_time() < deadline - 2.0:
        h_de, r_de = _de_edge_search(best, deadline, block=2048, time_cap=12.0)
        if r_de > bestR + 1e-16:
            best, bestR = h_de, r_de
            print("DE edge R=%.7f" % bestR)
        else:
            print("DE edge no gain (R=%.7f)" % r_de)

    # ---- Experiment: DE on reversed orientation (last 2048 cells) ----
    if time.process_time() < deadline - 2.0:
        rev = best[::-1].copy()
        h_de2, r_de2 = _de_edge_search(rev, deadline, block=2048, time_cap=8.0)
        h_de2 = h_de2[::-1].copy()
        r_de2 = R_of(h_de2)
        if r_de2 > bestR + 1e-16:
            best, bestR = h_de2, r_de2
            print("DE tail R=%.7f" % bestR)
        else:
            print("DE tail no gain (R=%.7f)" % r_de2)

    # ---- Primary: fine-grained local search on the existing start ----
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        win = max(32, min(256, n // 8))
        stride = max(16, win // 2)
        h, r = _window_polish(best, deadline, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if bestR - prev < 1e-12:
            h, r = _window_polish(best, deadline, window=max(8, win // 4),
                                  stride=max(4, stride // 2), maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = h, r
            else:
                break
        print("polish R=%.7f" % bestR)

    # ---- Secondary: multigrid coarsening if time remains ----
    if time.process_time() < deadline - 3.0:
        N_fine = best.size
        for Nc in [max(16, N_fine // 4), max(16, N_fine // 2)]:
            if time.process_time() >= deadline - 2.0:
                break
            h_c = _coarse_from_fine(best, Nc)
            h_c = _rescale_maxL(h_c)
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt, r_opt = _refine(h_c, sub_dl, rounds=1, maxiter=3000)
            h_up = _prolongate(h_opt, N_fine)
            h_up = _rescale_maxL(h_up)
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                best, bestR = h_up, r_up
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Tertiary: try a larger N by prolongating, then refine ----
    if time.process_time() < deadline - 3.0:
        for N_big in [min(200000, int(best.size * 1.5)), min(200000, best.size * 2)]:
            if time.process_time() >= deadline - 2.0:
                break
            if N_big <= best.size:
                continue
            h_big = _prolongate(best, N_big)
            h_big = _rescale_maxL(h_big)
            r_big = R_of(h_big)
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.4)
            h_opt, r_opt = _refine(h_big, sub_dl, rounds=1, maxiter=2000)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final full refine to use remaining budget ----
    if time.process_time() < deadline - 1.0:
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("final refine R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
        active = active[h[active] > 0]
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, float(n), N_big + 1)
    Sq = np.interp(xs, np.arange(n + 1, dtype=float), S)
    return np.diff(Sq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale_maxL(base)
            bestR = R_of(best)

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Phase perturbations at the current resolution, each followed by a
    # full exact polish. Small shifts frequently escape the flat peak.
    for delta in (-0.5, 0.5, -0.25, 0.25, -0.75, 0.75):
        if time.process_time() >= deadline - 3.0:
            break
        hp = _rescale_maxL(_phase_shift(best, delta))
        if hp.sum() <= 0:
            continue
        hp = _exact_lbfgs(hp, 800, deadline)
        r = R_of(hp)
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("ph%+.2f R=%.7f" % (delta, bestR))

    # Refinement loop: full polish until convergence, then try upsampling
    # the current best to a finer grid and polishing there. This is the
    # main lever for squeezing the last digits.
    stall = 0
    while time.process_time() < deadline - 2.0:
        improved = False

        if time.process_time() < deadline - 2.5:
            h = _exact_lbfgs(best, 2000, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h, r
                improved = True
                print("full R=%.7f" % bestR)

        # Upsample: try a moderately finer grid and polish from there.
        if not improved and time.process_time() < deadline - 4.0:
            n = best.size
            if n < 120000:
                Nbig = min(int(n * 1.5), 160000)
                hp = _rescale_maxL(_prolongate(best, Nbig))
                hp = _exact_lbfgs(hp, 1500, deadline)
                r = R_of(hp)
                if r > bestR + 1e-15:
                    best, bestR = hp, r
                    improved = True
                    print("up R=%.7f (N=%d)" % (bestR, best.size))

        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    # Final exact polish.
    if time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

