    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, deadline, free=free)


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Full exact polish first.
    if time.process_time() < deadline - 2.0:
        h = _exact_lbfgs(best, 1500, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("pre-polish R=%.7f" % bestR)

    # Main: multi-scale window polishing around peak.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32),
                        (0.75, 64), (1.00, 128)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish(best, deadline, frac=frac, extra=extra)
        h = _exact_lbfgs(h, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win(%.2f) R=%.7f" % (frac, bestR))

    # Phase exploration.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale_maxL(hp)
        if hp.sum() <= 0:
            continue
        hp = _exact_lbfgs(hp, 1000, deadline)
        hp = _window_polish(hp, deadline, frac=0.35, extra=16)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final loop: alternate full and window polish until time.
    while time.process_time() < deadline - 1.0:
        h = _exact_lbfgs(best, 1200, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("full R=%.7f" % bestR)
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish(best, deadline, frac=0.40, extra=24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("win R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _window_polish(h, deadline, window, stride, maxiter=300):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.4:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _lbfgs_block(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Primary: alternating full refine + multi-scale window polish ----
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    stall = 0
    while time.process_time() < deadline - 1.0:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        for (w, s) in win_levels:
            if time.process_time() >= deadline - 0.8:
                break
            cand, r = _window_polish(best, deadline, w, s, maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = cand, r
        if bestR - prev < 1e-13:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
        print("polish R=%.7f" % bestR)

    # ---- Multigrid: coarsen, optimize, prolongate back ----
    if time.process_time() < deadline - 2.0:
        N_fine = best.size
        for Nc in [max(16, N_fine // 2), max(16, N_fine // 4)]:
            if time.process_time() >= deadline - 1.5:
                break
            h_c = _rescale(_coarse(best, Nc))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt = _lbfgs_log(h_c, 3000, sub_dl)
            h_up = _rescale(_prolongate(h_opt, N_fine))
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                sub_dl2 = min(deadline - 0.5,
                              time.process_time() + (deadline - time.process_time()) * 0.4)
                h_opt2 = _lbfgs_log(h_up, 3000, sub_dl2)
                r2 = R_of(h_opt2)
                if r2 > bestR + 1e-16:
                    best, bestR = h_opt2, r2
                else:
                    best, bestR = h_up, r_up
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Upsample to larger N and refine ----
    if time.process_time() < deadline - 2.0:
        for N_big in [int(best.size * 1.5), int(best.size * 2)]:
            if N_big > 200000:
                N_big = 200000
            if N_big <= best.size:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            h_big = _rescale(_prolongate(best, N_big))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.4)
            h_opt = _lbfgs_log(h_big, 2000, sub_dl)
            r_opt = R_of(h_opt)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final refine to use remaining budget ----
    while time.process_time() < deadline - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish(best, deadline, 8, 4, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve
from scipy.interpolate import PchipInterpolator


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = min(K, n)
    if k <= 0:
        k = 1
    if k >= n:
        idx = np.arange(n)
    else:
        idx = np.argpartition(Lf, n - k)[n - k:]
    Lk = Lf[idx]
    mean_top = Lk.mean()
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / k) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline, K=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if K is None:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _band_free(h):
    n = h.size
    if n > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    M = Lf.max()
    if M <= 0:
        return np.arange(n)
    B = ((Lf >= 0.5 * M) & (Lf <= M)).astype(float)
    win = np.ones(n)
    cnt = np.convolve(B, win, mode='full')
    free = np.zeros(n, dtype=bool)
    for i in range(n):
        k = i + n - 1
        if 0 <= k < cnt.size and cnt[k] > 0.5:
            free[i] = True
    if not free.any():
        return np.arange(n)
    return np.flatnonzero(free)


# ---- Experiment: 12-parameter log-spline multiplicative envelope ----
_NNODES = 12


def _spline_log_env(coef, n):
    """coef: 10 interior values; nodes 0 and 11 clamped to 0.
    Returns s(x) on n equally spaced points in [0,1]."""
    nodes = np.linspace(0.0, 1.0, _NNODES)
    vals = np.zeros(_NNODES)
    vals[1:-1] = coef
    interp = PchipInterpolator(nodes, vals)
    x = np.linspace(0.0, 1.0, n)
    return interp(x)


def _apply_env(h, coef):
    s = _spline_log_env(coef, h.size)
    return _rescale_maxL(h * np.exp(np.clip(s, -20.0, 20.0)))


def _optimize_env(h, deadline, x0=None, maxiter=3000):
    n = h.size
    if x0 is None:
        x0 = np.zeros(_NNODES - 2)
    best = {"R": R_of(h), "coef": np.array(x0, dtype=float)}

    def obj(c):
        if time.process_time() > deadline:
            raise TimeoutError
        hh = _apply_env(h, c)
        r = R_of(hh)
        if r > best["R"]:
            best["R"] = r
            best["coef"] = np.array(c, dtype=float)
        return -r

    try:
        minimize(obj, x0, method='Nelder-Mead',
                 options={'initial_simplex': None, 'xatol': 1e-6,
                          'fatol': 1e-12, 'maxiter': maxiter,
                          'maxfev': maxiter * 2})
    except TimeoutError:
        pass
    except Exception:
        pass
    return best["coef"], best["R"]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size
    rng = np.random.default_rng(12345)

    # ---- Experiment: 12-parameter log-spline envelope, 3 restarts ----
    start_h = best.copy()
    start_R = bestR
    for restart in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        if restart == 0:
            x0 = np.zeros(_NNODES - 2)
        else:
            x0 = rng.normal(0.0, 0.05, _NNODES - 2)
        coef, r_env = _optimize_env(start_h, deadline - 0.5, x0=x0,
                                    maxiter=3000)
        cand = _apply_env(start_h, coef)
        r_cand = R_of(cand)
        print("env restart %d: env R=%.7f (from %.7f)" % (restart, r_cand, start_R))
        if r_cand > bestR + 1e-16:
            best, bestR = cand, r_cand
        # polish: exact lbfgs then window
        if time.process_time() < deadline - 1.0:
            h2, r2 = _refine(best, deadline, rounds=1, maxiter=5000)
            if r2 > bestR + 1e-16:
                best, bestR = h2, r2
            h3, r3 = _window_polish(best, deadline, window=256, stride=64,
                                    maxiter=200)
            if r3 > bestR + 1e-16:
                best, bestR = h3, r3
        print("env restart %d: post-polish R=%.7f" % (restart, bestR))

    # ---- Existing exact + window polish loop for remaining budget ----
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        win = max(32, min(256, n // 8))
        stride = max(16, win // 2)
        h, r = _window_polish(best, deadline, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if bestR - prev < 1e-12:
            h, r = _window_polish(best, deadline, window=max(8, win // 4),
                                  stride=max(4, stride // 2), maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = h, r
            else:
                break
        print("polish R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    K = min(K, n)
    if K >= n:
        Lm = Lf.mean()
        gLf = -dq / num + (1.0 / (n * Lm)) * np.ones(n)
    else:
        idx = np.argpartition(Lf, n - K)[n - K:]
        Lm = Lf[idx].mean()
        gLf = -dq / num
        gLf[idx] += 1.0 / (K * Lm)
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_lin(h0, K, maxiter, deadline):
    if time.process_time() >= deadline - 0.5:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    x0 = h.copy()

    def f(x):
        return _topk_fun_grad(x, K)

    cb = _make_cb(deadline - 0.3)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * n,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.clip(res.x, 0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.25, extra=4):
    if time.process_time() >= deadline - 0.5:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _exact_lbfgs(h, 1200, 2400, deadline, free=free)


def _upsample(h, factor):
    n = h.size
    m = (n - 1) * factor + 1
    xo = np.linspace(0.0, n - 1, m)
    return np.interp(xo, np.arange(n), h)


def _split_prolong(h, deadline, iters=600):
    """Mass-preserving free split: h2[2i]=2 h[i] s_i, h2[2i+1]=2 h[i] (1-s_i).
    Free only s_i for cells i adjacent to a zero gap. s_i = sigmoid(x_i)."""
    n = h.size
    if time.process_time() >= deadline - 0.5:
        return h
    zero = (h <= 0)
    # neighbours: i-1, i, i+1, i+2 (as specified)
    free_mask = np.zeros(n, dtype=bool)
    for shift in (-1, 0, 1, 2):
        idx = np.arange(n) + shift
        valid = (idx >= 0) & (idx < n)
        src = np.zeros(n, dtype=bool)
        src[valid] = zero[idx[valid]]
        free_mask |= src
    free_idx = np.flatnonzero(free_mask)
    if free_idx.size == 0:
        return h
    m = 2 * n
    x0 = np.zeros(free_idx.size)  # sigmoid(0)=0.5

    def build(x):
        s = 1.0 / (1.0 + np.exp(-np.clip(x, -30, 30)))
        h2 = np.empty(m)
        h2[0::2] = 2.0 * h * 0.5
        h2[1::2] = 2.0 * h * 0.5
        h2[2 * free_idx] = 2.0 * h[free_idx] * s
        h2[2 * free_idx + 1] = 2.0 * h[free_idx] * (1.0 - s)
        return h2, s

    def f(x):
        h2, s = build(x)
        val, g = _norm_eq_fun_grad(h2)
        # backprop through split: dh2[2i]=2h_i ds, dh2[2i+1]=-2h_i ds
        ds = 2.0 * h[free_idx] * (g[2 * free_idx] - g[2 * free_idx + 1])
        dx = ds * s * (1.0 - s)
        return val, dx

    cb = _make_cb(deadline - 0.3)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(-6.0, 6.0)] * free_idx.size,
                       callback=cb,
                       options={'maxiter': iters, 'maxfun': 2 * iters,
                                'ftol': 1e-20, 'gtol': 1e-16})
        h2, _ = build(res.x)
    except TimeoutError:
        return h
    except Exception:
        return h
    # decimate back by summing pairs
    hd = h2[0::2] + h2[1::2]
    return _rescale_maxL(hd)


def _small_k_ladder(best, bestR, deadline, t0, budget_seconds):
    """Run small-K ladder with window polish between rungs."""
    for K in (1, 2, 3, 4, 6, 8, 12):
        if time.process_time() >= deadline - 1.0:
            break
        h = _topk_lin(best, K, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h.copy(), r
        # window polish swept over argmax-knot region
        if time.process_time() < deadline - 1.0:
            h = _window_polish(best, deadline, frac=0.02, extra=2)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
        # exact K=1 between rungs
        if time.process_time() < deadline - 1.0:
            h = _exact_lbfgs(best, 400, 800, deadline)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # Experiment: split-prolongation + small-K ladder cycles
    cycle = 0
    while cycle < 4 and time.process_time() < deadline - 2.0:
        cycle += 1
        prevR = bestR
        # free-split prolongation with only gap-adjacent cells free
        if best.size < 100000:
            h = _split_prolong(best, deadline, iters=600)
            r = R_of(h)
            if r > bestR + 1e-15:
                best, bestR = h.copy(), r
                print("split cycle %d R=%.7f (N=%d)" % (cycle, bestR, best.size))
        # small-K ladder
        best, bestR = _small_k_ladder(best, bestR, deadline, t0, budget_seconds)
        print("cycle %d R=%.7f (N=%d)" % (cycle, bestR, best.size))
        if bestR <= prevR + 1e-16:
            break

    # Keep base's window/final polish if time remains
    hard = t0 + budget_seconds * 0.97
    while time.process_time() < hard - 1.0:
        h = _window_polish(best, hard - 0.5, frac=0.35)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("window R=%.7f" % bestR)
        else:
            break

    while time.process_time() < hard - 0.5:
        h = _exact_lbfgs(best, 4000, 8000, hard - 0.3)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

