def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _topk_fun_grad(h, K):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    n = Lf.size
    k = min(K, n)
    if k <= 0:
        k = 1
    if k >= n:
        idx = np.arange(n)
    else:
        idx = np.argpartition(Lf, n - k)[n - k:]
    Lk = Lf[idx]
    mean_top = Lk.mean()
    if mean_top <= 0:
        return 1e18, np.zeros(h.size)
    gLf = -dq / num
    gLf[idx] += (1.0 / k) / mean_top
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(mean_top)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, deadline, free=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _block_lbfgs_linear(h0, free, maxiter, deadline, K=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if K is None:
            val, g = _norm_eq_fun_grad(hh)
        else:
            val, g = _topk_fun_grad(hh, K)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except TimeoutError:
        return h0
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _refine(h, deadline, rounds=1, free=None, maxiter=1500):
    best = h
    bestR = R_of(h)
    for _ in range(rounds):
        if time.process_time() >= deadline - 0.5:
            break
        cand = _exact_lbfgs(best, maxiter, deadline, free=free)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
    return best, bestR


def _window_polish(h, deadline, window=64, stride=32, maxiter=200):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.5:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _block_lbfgs_linear(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _band_free(h):
    n = h.size
    if n > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    M = Lf.max()
    if M <= 0:
        return np.arange(n)
    B = ((Lf >= 0.5 * M) & (Lf <= M)).astype(float)
    win = np.ones(n)
    cnt = np.convolve(B, win, mode='full')
    free = np.zeros(n, dtype=bool)
    for i in range(n):
        k = i + n - 1
        if 0 <= k < cnt.size and cnt[k] > 0.5:
            free[i] = True
    if not free.any():
        return np.arange(n)
    return np.flatnonzero(free)


def _loss_per_knot(h):
    """Per-knot loss contribution to -log(R) (up to constants), and Lf, M."""
    num, dq, Lf = _num_and_dq(h)
    s = h.sum()
    M = Lf.max()
    # loss = log(M) + 2 log s - log(num); derivative wrt Lf is dq/num - e_argmax/M
    # per-knot contribution ~ dq/num * Lf - (Lf/M) * [argmax]  (linearised)
    contrib = dq / num * Lf
    m = int(np.argmax(Lf))
    contrib[m] -= 1.0
    return contrib, Lf, M, num, s


def _donor_recipient_lists(h):
    n = h.size
    contrib, Lf, M, num, s = _loss_per_knot(h)
    # donor cells: whose generated knots carry largest loss with 0.15M < L < 0.85M
    band_mask = (Lf > 0.15 * M) & (Lf < 0.85 * M)
    # map knot j to cells i in [j-n+1, j] (clipped); approximate: cell i ~ knot i+n/2
    # Use knot index j -> cell i = j - n//2, clipped to [0,n-1]
    cell_contrib = np.full(n, -np.inf)
    idxs = np.flatnonzero(band_mask)
    for j in idxs:
        i = j - n // 2
        if 0 <= i < n:
            if contrib[j] > cell_contrib[i]:
                cell_contrib[i] = contrib[j]
    valid = np.isfinite(cell_contrib)
    if not valid.any():
        D = np.argsort(-h)[:64]
    else:
        cand = np.flatnonzero(valid)
        order = np.argsort(-cell_contrib[cand])
        D = cand[order[:64]]
    # recipient cells: whose adjacent knot is within 1e-3 of M
    near_max = np.abs(Lf - M) <= 1e-3 * M
    cell_near = np.zeros(n, dtype=bool)
    idxs2 = np.flatnonzero(near_max)
    for j in idxs2:
        i = j - n // 2
        if 0 <= i < n:
            cell_near[i] = True
    Rc = np.flatnonzero(cell_near)
    if Rc.size == 0:
        Rc = np.argsort(-h)[:64]
    elif Rc.size > 64:
        Rc = Rc[np.argsort(-h[Rc])[:64]]
    return D, Rc


def _discrete_beam(h, deadline, rounds=5):
    best = h
    bestR = R_of(h)
    alphas = [0.1, 0.25, 0.5, 1.0]
    for rnd in range(rounds):
        if time.process_time() >= deadline - 1.0:
            break
        D, Rc = _donor_recipient_lists(best)
        if D.size == 0 or Rc.size == 0:
            break
        cands = []
        for alpha in alphas:
            for d in D:
                hd = best[d]
                if hd <= 0:
                    continue
                moved = alpha * hd
                for r in Rc:
                    if r == d:
                        continue
                    h2 = best.copy()
                    h2[d] = (1.0 - alpha) * hd
                    h2[r] = best[r] + moved
                    rv = R_of(h2)
                    cands.append((rv, h2))
            if time.process_time() >= deadline - 1.0:
                break
        if not cands:
            break
        cands.sort(key=lambda t: -t[0])
        top = cands[:8]
        improved = False
        for rv, h2 in top:
            if time.process_time() >= deadline - 1.0:
                break
            c = _exact_lbfgs(h2, 400, deadline)
            rc = R_of(c)
            if rc > bestR + 1e-16:
                c2, rc2 = _window_polish(c, deadline, window=128, stride=64, maxiter=150)
                if rc2 > bestR + 1e-16:
                    best, bestR = c2, rc2
                    improved = True
                    print("beam r%d R=%.7f" % (rnd, bestR))
                elif rc > bestR + 1e-16:
                    best, bestR = c, rc
                    improved = True
                    print("beam r%d R=%.7f" % (rnd, bestR))
        alphas = [a * 0.5 for a in alphas]
        if not improved:
            # still continue, alphas halved
            pass
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            base = _rescale_maxL(base)
            best = base
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale_maxL(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Experiment: discrete donor->recipient mass-transfer beam ----
    h, r = _discrete_beam(best, deadline, rounds=5)
    if r > bestR + 1e-16:
        best, bestR = h, r
    print("after beam R=%.7f" % bestR)

    # ---- Standard full+window polish loop to deadline ----
    while time.process_time() < deadline - 1.0:
        prev = bestR
        h, r = _refine(best, deadline, rounds=1, maxiter=5000)
        if r > bestR + 1e-16:
            best, bestR = h, r
        win = max(32, min(256, n // 8))
        stride = max(16, win // 2)
        h, r = _window_polish(best, deadline, window=win, stride=stride, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = h, r
        if bestR - prev < 1e-12:
            h, r = _window_polish(best, deadline, window=max(8, win // 4),
                                  stride=max(4, stride // 2), maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = h, r
            else:
                break
        print("polish R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, ftol=1e-20, gtol=1e-16):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': ftol, 'gtol': gtol,
                                'maxcor': 30})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block_log(h0, free, maxiter, deadline, ftol=1e-20, gtol=1e-16):
    """Optimize a subset in log-space. Much better conditioned than linear."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    active = active[h[active] > 0]
    if active.size == 0:
        return h0
    n = h.size
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = h.copy()
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': ftol, 'gtol': gtol,
                                'maxcor': 20})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _window_polish_log(h, deadline, window, stride, maxiter=150):
    """Overlapping windows in log-space. Cheap because windows are small."""
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.4:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _lbfgs_block_log(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Phase 1: full-scale L-BFGS log-space, repeated with restarts ----
    # This is the main workhorse. Do it while there's plenty of time.
    phase1_end = t0 + budget_seconds * 0.55
    while time.process_time() < phase1_end - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 3000, min(deadline, phase1_end + 2.0),
                          ftol=1e-22, gtol=1e-18)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("phase1 R=%.7f" % bestR)

    # ---- Phase 2: window polish at moderate scale, then full refine ----
    # Windows in log-space; overlapping to allow coupling between neighbours.
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    for (w, s) in win_levels:
        if time.process_time() >= deadline - 1.0:
            break
        cand, r = _window_polish_log(best, deadline, w, s, maxiter=150)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        # follow up with a short full refine
        cand = _lbfgs_log(best, 500, deadline, ftol=1e-22, gtol=1e-18)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        print("win w=%d R=%.7f" % (w, bestR))

    # ---- Phase 3: multigrid coarsen/refine (only if time permits) ----
    if time.process_time() < deadline - 4.0:
        N_fine = best.size
        for Nc in [max(32, N_fine // 2), max(32, N_fine // 4)]:
            if time.process_time() >= deadline - 3.0:
                break
            h_c = _rescale(_coarse(best, Nc))
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.30)
            h_opt = _lbfgs_log(h_c, 2000, sub_dl)
            h_up = _rescale(_prolongate(h_opt, N_fine))
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                sub_dl2 = min(deadline - 0.8,
                              time.process_time() + (deadline - time.process_time()) * 0.5)
                h_opt2 = _lbfgs_log(h_up, 2000, sub_dl2)
                r2 = R_of(h_opt2)
                if r2 > bestR + 1e-16:
                    best, bestR = h_opt2, r2
                else:
                    best, bestR = h_up, r_up
                print("mgrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Phase 4: spend the rest on fine window polish + full refine ----
    while time.process_time() < deadline - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 2000, deadline, ftol=1e-22, gtol=1e-18)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish_log(best, deadline, 16, 8, maxiter=100)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish_log(best, deadline, 8, 4, maxiter=100)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

