def _smooth(h, sigma):
    # Gaussian smoothing of step heights (treat as samples on the grid)
    if sigma <= 0:
        return h
    r = int(max(1, round(3 * sigma)))
    x = np.arange(-r, r + 1, dtype=float)
    k = np.exp(-0.5 * (x / sigma) ** 2)
    k /= k.sum()
    hs = np.convolve(h, k, mode='same')
    return np.clip(hs, 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    best = None
    bestR = 0.0
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
            print("start R=%.7f (N=%d)" % (bestR, best.size))

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)
        print("fallback R=%.7f (N=%d)" % (bestR, best.size))

    startN = best.size

    # New idea: try smoothing + re-refining at a LARGER N.
    # The optimum appears to have a smooth envelope; refining on a finer grid
    # after a slight smoothing step lets the optimizer escape the current
    # local optimum (many near-flat knots pinning it down).
    trial_Ns = []
    for fac in (1.25, 1.5, 2.0):
        Nt = int(min(200000, max(startN + 500, startN * fac)))
        if Nt > startN and Nt not in trial_Ns:
            trial_Ns.append(Nt)

    for Nt in trial_Ns:
        if time.process_time() >= deadline - 3.0:
            break
        h_up = _prolongate(best, Nt)
        # smoothing at the finer grid, then refine
        for sigma in (0.0, 1.0, 2.0):
            if time.process_time() >= deadline - 2.5:
                break
            h0 = _rescale(_smooth(h_up, sigma * (Nt / max(startN, 1))))
            r0 = R_of(h0)
            sub_deadline = min(deadline - 2.0,
                               time.process_time() + (deadline - time.process_time()) * 0.3)
            h_opt = _lbfgs_log(h0, 3000, sub_deadline)
            r_opt = R_of(h_opt)
            print("upsample N=%d sigma=%.1f: R=%.7f -> R=%.7f"
                  % (Nt, sigma, r0, r_opt))
            if r_opt > bestR + 1e-15:
                best, bestR = h_opt, r_opt
                print("new best R=%.7f (N=%d)" % (bestR, best.size))
            if time.process_time() >= deadline - 2.5:
                break

    # Window polish on the incumbent to squeeze out local improvements.
    if time.process_time() < deadline - 2.0:
        h, r = _window_polish(best, min(deadline - 1.0,
                                        time.process_time() + (deadline - time.process_time()) * 0.5),
                              window=256, stride=128, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("window polish R=%.7f (N=%d)" % (bestR, best.size))

    # Final full L-BFGS on the incumbent.
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 4000, deadline - 0.5)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h, r
            print("final L-BFGS R=%.7f (N=%d)" % (bestR, best.size))

    best = _rescale(np.clip(best, 0, None))
    bestR = R_of(best)
    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _window_polish(h, deadline, window, stride, maxiter=300):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.4:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _lbfgs_block(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _right_end_patch(h, m, u):
    """Force last m knots of L to M via hyperbolic right-end rise."""
    h2 = h.copy()
    Lf = _knots(h)
    M = Lf.max()
    K = int(np.flatnonzero(h > 1e-9 * h.max())[-1]) + 1
    if K < m + 1:
        return None
    h2[:100] *= u
    b = np.sqrt(M)
    h2[K - 1] = b
    for t in range(1, m):
        idx = K - 1 - t
        s = 0.0
        for r in range(1, t):
            s += h2[K - 1 - r] * h2[K - 1 - (t - r)]
        val = (M - s) / (2.0 * b)
        h2[idx] = val
    if np.any(h2[K - m:K] <= 0):
        return None
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Experiment: right-end hyperbolic patch candidates ----
    if time.process_time() < deadline - 3.0:
        for m in (8, 16, 32):
            for u in (1.0, 0.85, 0.7):
                if time.process_time() >= deadline - 2.5:
                    break
                h2 = _right_end_patch(best, m, u)
                if h2 is None:
                    print("patch m=%d u=%.2f skipped" % (m, u))
                    continue
                r_pre = R_of(h2)
                print("patch m=%d u=%.2f pre R=%.7f" % (m, u, r_pre))
                sub_dl = min(deadline - 1.5,
                             time.process_time() + (deadline - time.process_time()) * 0.25)
                h_opt = _lbfgs_log(h2, 400, sub_dl)
                h_opt, r_opt = _window_polish(h_opt, sub_dl,
                                              max(64, n // 16), max(32, n // 32),
                                              maxiter=200)
                r_opt = R_of(h_opt)
                if r_opt > bestR + 1e-16:
                    best, bestR = h_opt, r_opt
                    print("patch m=%d u=%.2f GAIN R=%.7f" % (m, u, bestR))
                else:
                    print("patch m=%d u=%.2f post R=%.7f (no gain)" % (m, u, r_opt))

    # ---- Primary: alternating full refine + multi-scale window polish ----
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    stall = 0
    while time.process_time() < deadline - 1.0:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        for (w, s) in win_levels:
            if time.process_time() >= deadline - 0.8:
                break
            cand, r = _window_polish(best, deadline, w, s, maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = cand, r
        if bestR - prev < 1e-13:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
        print("polish R=%.7f" % bestR)

    # ---- Multigrid: coarsen, optimize, prolongate back ----
    if time.process_time() < deadline - 2.0:
        N_fine = best.size
        for Nc in [max(16, N_fine // 2), max(16, N_fine // 4)]:
            if time.process_time() >= deadline - 1.5:
                break
            h_c = _rescale(_coarse(best, Nc))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt = _lbfgs_log(h_c, 3000, sub_dl)
            h_up = _rescale(_prolongate(h_opt, N_fine))
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                sub_dl2 = min(deadline - 0.5,
                              time.process_time() + (deadline - time.process_time()) * 0.4)
                h_opt2 = _lbfgs_log(h_up, 3000, sub_dl2)
                r2 = R_of(h_opt2)
                if r2 > bestR + 1e-16:
                    best, bestR = h_opt2, r2
                else:
                    best, bestR = h_up, r_up
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Upsample to larger N and refine ----
    if time.process_time() < deadline - 2.0:
        for N_big in [int(best.size * 1.5), int(best.size * 2)]:
            if N_big > 200000:
                N_big = 200000
            if N_big <= best.size:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            h_big = _rescale(_prolongate(best, N_big))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.4)
            h_opt = _lbfgs_log(h_big, 2000, sub_dl)
            r_opt = R_of(h_opt)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final refine to use remaining budget ----
    while time.process_time() < deadline - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish(best, deadline, 8, 4, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

