def _warp_L_and_invert(h, gamma):
    """Warp interior knots Lint(x)->Lint(x^gamma), invert via causal recursion."""
    n = h.size
    Lf = _knots(h)
    Lint = Lf[1:-1]  # length 2n-1
    m = Lint.size  # 2n-1
    if m < 2:
        return h.copy()
    j = np.arange(m, dtype=float)
    t = (j / (m - 1.0)) ** gamma * (m - 1.0)
    T = np.interp(t, j, Lint)
    T[0] = Lint[0]
    T[-1] = 0.0
    # causal recursion: h0=1, h_j = (T[j-1] - sum_{i=1}^{j-1} h_i h_{j-i})/2
    hout = np.zeros(n)
    hout[0] = 1.0
    for jj in range(1, n):
        if jj - 1 >= m:
            break
        s = 0.0
        # sum_{i=1}^{jj-1} h_i h_{jj-i}
        if jj >= 2:
            s = float(np.dot(hout[1:jj], hout[jj - 1:0:-1]))
        hout[jj] = (T[jj - 1] - s) / 2.0
    hout = np.clip(hout, 0.0, None)
    if hout.sum() <= 0:
        return h.copy()
    return hout


