        hw = _rescale(hw)
        r_raw = R_of(hw)
        print("warp gamma=%.2f raw R=%.7f" % (gamma, r_raw))
        # polish: exact log-L-BFGS + window polish
        sub_dl = min(deadline - 1.0,
                     time.process_time() + (deadline - time.process_time()) * 0.30)
        h_opt = _lbfgs_log(hw, 800, sub_dl)
