                     time.process_time() + 4.0)
        h_opt = _lbfgs_log(h_c, 4000, sub_dl)
        r_opt = R_of(h_opt)
        print("native N=%d R=%.7f (init %.7f)" % (Nc, r_opt, r_c0))
