                best_N = N_fine
            print("  prolong N=%d -> R=%.7f" % (Nc, r_up))

    # ---- Keep the base's polish loop as fallback / improver ----
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    stall = 0
    while time.process_time() < deadline - 1.0:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        for (w, s) in win_levels:
            if time.process_time() >= deadline - 0.8:
                break
            cand, r = _window_polish(best, deadline, w, s, maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = cand, r
        if bestR - prev < 1e-13:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0
        print("polish R=%.7f" % bestR)

    # ---- Multigrid: coarsen, optimize, prolongate back ----
    if time.process_time() < deadline - 2.0:
        N_fine_now = best.size
        for Nc in [max(16, N_fine_now // 2), max(16, N_fine_now // 4)]:
            if time.process_time() >= deadline - 1.5:
                break
            h_c = _rescale(_coarse(best, Nc))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt = _lbfgs_log(h_c, 3000, sub_dl)
            h_up = _rescale(_prolongate(h_opt, N_fine_now))
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                sub_dl2 = min(deadline - 0.5,
                              time.process_time() + (deadline - time.process_time()) * 0.4)
                h_opt2 = _lbfgs_log(h_up, 3000, sub_dl2)
                r2 = R_of(h_opt2)
                if r2 > bestR + 1e-16:
                    best, bestR = h_opt2, r2
                else:
                    best, bestR = h_up, r_up
                print("multigrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Upsample to larger N and refine ----
    if time.process_time() < deadline - 2.0:
        for N_big in [int(best.size * 1.5), int(best.size * 2)]:
            if N_big > 200000:
                N_big = 200000
            if N_big <= best.size:
                continue
            if time.process_time() >= deadline - 1.5:
                break
            h_big = _rescale(_prolongate(best, N_big))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.4)
            h_opt = _lbfgs_log(h_big, 2000, sub_dl)
            r_opt = R_of(h_opt)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final refine to use remaining budget ----
    while time.process_time() < deadline - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish(best, deadline, 8, 4, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    # ---- Compare against best native-N candidate and return the winner ----
    if best_any_R > bestR + 1e-16:
        best, bestR = best_any, best_any_R
        print("native-N wins: N=%d R=%.7f" % (best_N, bestR))

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, ftol=1e-20, gtol=1e-16):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': ftol, 'gtol': gtol,
                                'maxcor': 30})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block_log(h0, free, maxiter, deadline, ftol=1e-20, gtol=1e-16):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    active = active[h[active] > 0]
    if active.size == 0:
        return h0
    n = h.size
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = h.copy()
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': ftol, 'gtol': gtol,
                                'maxcor': 20})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _window_polish_log(h, deadline, window, stride, maxiter=150):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.4:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _lbfgs_block_log(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _invert_knots(T):
    """Exact causal recursion: given target knots T (len N+1, T[0]=0),
    find h (len N) with [0,*convolve(h,h),0] approximating T.
    h0 = sqrt(T[1]); hk = (T[k+1] - sum_{i=1}^{k-1} h_i h_{k-i}) / (2 h0)."""
    N = T.size - 1
    T = np.asarray(T, dtype=float)
    if T.size < 2 or T[1] <= 0:
        return None
    h = np.zeros(N)
    h0 = math_sqrt(max(T[1], 0.0))
    if h0 <= 0:
        return None
    h[0] = h0
    # accumulate convolution incrementally
    for k in range(1, N):
        # sum_{i=1}^{k-1} h_i h_{k-i}
        if k >= 2:
            s = float(np.dot(h[1:k], h[k-1:0:-1]))
        else:
            s = 0.0
        hk = (T[k + 1] - s) / (2.0 * h0)
        h[k] = hk
    return h


def math_sqrt(x):
    return float(np.sqrt(x))


def _pull_up_candidate(h, lam):
    """Push interior knots toward M, invert via causal recursion."""
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return None
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return None
    T = Lf.copy()
    mask = (Lf > 0.02 * M) & (Lf < 0.98 * M)
    T[mask] += lam * (M - Lf[mask])
    T[0] = 0.0
    T[-1] = 0.0
    hnew = _invert_knots(T)
    if hnew is None:
        return None
    hnew = np.clip(hnew, 0.0, None)
    if hnew.sum() <= 0:
        return None
    return _rescale(hnew)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Experiment: pull-up knot perturbation + inversion + polish ----
    lams = [0.5, 0.3, 0.15, 0.07]
    for lam in lams:
        if time.process_time() >= deadline - 2.0:
            break
        cand0 = _pull_up_candidate(best, lam)
        if cand0 is None:
            print("pull lam=%.2f: invert failed" % lam)
            continue
        r_raw = R_of(cand0)
        # short polish
        sub_dl = min(deadline - 1.0,
                     time.process_time() + max(1.0, (deadline - time.process_time()) * 0.15))
        cand = _lbfgs_log(cand0, 1000, sub_dl, ftol=1e-22, gtol=1e-18)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("pull lam=%.2f raw=%.7f pol=%.7f ACCEPT R=%.7f"
                  % (lam, r_raw, r, bestR))
        else:
            print("pull lam=%.2f raw=%.7f pol=%.7f (no gain)" % (lam, r_raw, r))

    # ---- Phase 1: full-scale L-BFGS log-space ----
    phase1_end = t0 + budget_seconds * 0.55
    while time.process_time() < phase1_end - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 3000, min(deadline, phase1_end + 2.0),
                          ftol=1e-22, gtol=1e-18)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("phase1 R=%.7f" % bestR)

    # ---- Phase 2: window polish ----
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    for (w, s) in win_levels:
        if time.process_time() >= deadline - 1.0:
            break
        cand, r = _window_polish_log(best, deadline, w, s, maxiter=150)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand = _lbfgs_log(best, 500, deadline, ftol=1e-22, gtol=1e-18)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        print("win w=%d R=%.7f" % (w, bestR))

    # ---- Phase 3: multigrid ----
    if time.process_time() < deadline - 4.0:
        N_fine = best.size
        for Nc in [max(32, N_fine // 2), max(32, N_fine // 4)]:
            if time.process_time() >= deadline - 3.0:
                break
            h_c = _rescale(_coarse(best, Nc))
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.30)
            h_opt = _lbfgs_log(h_c, 2000, sub_dl)
            h_up = _rescale(_prolongate(h_opt, N_fine))
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                sub_dl2 = min(deadline - 0.8,
                              time.process_time() + (deadline - time.process_time()) * 0.5)
                h_opt2 = _lbfgs_log(h_up, 2000, sub_dl2)
                r2 = R_of(h_opt2)
                if r2 > bestR + 1e-16:
                    best, bestR = h_opt2, r2
                else:
                    best, bestR = h_up, r_up
                print("mgrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Phase 4: fine window polish + full refine ----
    while time.process_time() < deadline - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 2000, deadline, ftol=1e-22, gtol=1e-18)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish_log(best, deadline, 16, 8, maxiter=100)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish_log(best, deadline, 8, 4, maxiter=100)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

