def _window_polish(h, deadline, window, stride, maxiter=300):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.4:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _lbfgs_block(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _warp_L_and_invert(h, gamma):
    n = h.size
    Lf = _knots(h)
    Lint = Lf[1:-1]
    m = Lint.size
    if m < 2:
        return h.copy()
    j = np.arange(m, dtype=float)
    t = (j / (m - 1.0)) ** gamma * (m - 1.0)
    T = np.interp(t, j, Lint)
    T[0] = Lint[0]
    T[-1] = 0.0
    hout = np.zeros(n)
    hout[0] = 1.0
    for jj in range(1, n):
        if jj - 1 >= m:
            break
        s = 0.0
        if jj >= 2:
            s = float(np.dot(hout[1:jj], hout[jj - 1:0:-1]))
        hout[jj] = (T[jj - 1] - s) / 2.0
    hout = np.clip(hout, 0.0, None)
    if hout.sum() <= 0:
        return h.copy()
    return hout


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))
    n = best.size

    # ---- Two strategies compete for the remaining time:
    #      (A) keep polishing current best at its resolution,
    #      (B) upsample to a much larger N and refine there, which
    #          exposes fine structure the current grid cannot represent.
    #      The old program only tried modest 1.5x/2x upsampling late and
    #      rarely won; we try a much larger jump first, which is the main
    #      new lever for breaking plateaus.

    # First: try a big upsampling early (most promising structural move).
    if time.process_time() < deadline - 6.0 and best.size < 200000:
        for factor in [3.0, 2.0, 1.5]:
            N_big = min(200000, int(best.size * factor))
            if N_big <= best.size + 8:
                continue
            if time.process_time() >= deadline - 5.0:
                break
            h_big = _rescale(_prolongate(best, N_big))
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.35)
            h_opt = _lbfgs_log(h_big, 3000, sub_dl)
            r_opt = R_of(h_opt)
            print("big-upsample x%.1f N=%d R=%.7f" % (factor, N_big, r_opt))
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("ACCEPT big-upsample R=%.7f" % bestR)
                break

    n = best.size

    # ---- Warp experiments on the (possibly upsampled) best ----
    for gamma in [0.95, 1.05]:
        if time.process_time() >= deadline - 4.0:
            break
        try:
            hw = _warp_L_and_invert(best, gamma)
        except Exception:
            continue
        hw = _rescale(hw)
        sub_dl = min(deadline - 1.0,
                     time.process_time() + (deadline - time.process_time()) * 0.20)
        h_opt = _lbfgs_log(hw, 800, sub_dl)
        r_opt = R_of(h_opt)
        if r_opt > bestR + 1e-16:
            best, bestR = h_opt, r_opt
            print("warp gamma=%.2f ACCEPT R=%.7f" % (gamma, bestR))

    n = best.size

    # ---- Alternating full + window polish until deadline ----
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    stall = 0
    while time.process_time() < deadline - 0.8:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        for (w, s) in win_levels:
            if time.process_time() >= deadline - 0.6:
                break
            cand, r = _window_polish(best, deadline, w, s, maxiter=200)
            if r > bestR + 1e-16:
                best, bestR = cand, r
        if bestR - prev < 1e-13:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0
        print("polish R=%.7f" % bestR)

    # ---- If we still have time and the grid is small, upsample once more ----
    if time.process_time() < deadline - 3.0 and best.size < 200000:
        N_big = min(200000, int(best.size * 2))
        if N_big > best.size + 8:
            h_big = _rescale(_prolongate(best, N_big))
            sub_dl = min(deadline - 0.8,
                         time.process_time() + (deadline - time.process_time()) * 0.5)
            h_opt = _lbfgs_log(h_big, 2000, sub_dl)
            r_opt = R_of(h_opt)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("late-upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Final tight window polish ----
    while time.process_time() < deadline - 0.4:
        prev = bestR
        cand = _lbfgs_log(best, 5000, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish(best, deadline, 8, 4, maxiter=200)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize, differential_evolution
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, ftol=1e-22, gtol=1e-18):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': ftol, 'gtol': gtol,
                                'maxcor': 30})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block_log(h0, free, maxiter, deadline, ftol=1e-22, gtol=1e-18):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    active = active[h[active] > 0]
    if active.size == 0:
        return h0
    n = h.size
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = h.copy()
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': ftol, 'gtol': gtol,
                                'maxcor': 20})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _window_polish_log(h, deadline, window, stride, maxiter=150):
    best = h
    bestR = R_of(h)
    n = h.size
    pos = 0
    while pos < n:
        if time.process_time() >= deadline - 0.4:
            break
        end = min(pos + window, n)
        free = np.arange(pos, end)
        cand = _lbfgs_block_log(best, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        pos += stride
    return best, bestR


def _subspace_global_search(best, bestR, deadline, rng, dim=100):
    """Randomized subspace differential evolution + L-BFGS-B polish."""
    n = best.size
    if n < dim + 10:
        return best, bestR
    # gradient of -log R at current point
    _, g = _fun_grad(best)
    g = np.abs(g)
    k = min(50, n)
    top = np.argsort(-g)[:k]
    rest = np.setdiff1d(np.arange(n), top, assume_unique=False)
    nrand = min(dim - top.size, rest.size)
    if nrand <= 0:
        S = top[:dim]
    else:
        S = np.concatenate((top, rng.choice(rest, size=nrand, replace=False)))
    S = np.asarray(S, dtype=int)
    S = S[best[S] > 0]
    if S.size < 4:
        return best, bestR

    h_base = best.copy()
    u0 = np.log(np.clip(h_base[S], 1e-300, None))

    def obj(u):
        uu = np.clip(u, -8.0, 8.0)
        hh = h_base.copy()
        hh[S] = np.exp(uu)
        return -R_of(hh)

    # DE with a hard time guard via callback
    def de_cb(xk, convergence=None):
        if time.process_time() > deadline - 1.0:
            raise TimeoutError

    try:
        res = differential_evolution(
            obj, bounds=[(-8.0, 8.0)] * S.size,
            popsize=10, maxiter=50, tol=1e-10,
            polish=False, seed=int(rng.integers(0, 2**31 - 1)),
            callback=de_cb, updating='immediate', workers=1)
        u_best = res.x
    except (TimeoutError, Exception):
        return best, bestR

    h_try = h_base.copy()
    h_try[S] = np.exp(np.clip(u_best, -8.0, 8.0))
    h_try = _rescale(h_try)

    # L-BFGS-B polish on S
    if time.process_time() < deadline - 0.5:
        h_try = _lbfgs_block_log(h_try, S, maxiter=200, deadline=deadline)

    r = R_of(h_try)
    if r > bestR + 1e-16:
        return h_try, r
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    n = best.size

    # ---- Phase 1: full L-BFGS log-space ----
    phase1_end = t0 + budget_seconds * 0.30
    while time.process_time() < phase1_end - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 3000, min(deadline, phase1_end + 2.0))
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("phase1 R=%.7f" % bestR)

    # ---- Phase 2: window polish ----
    win_levels = [(max(64, n // 8), max(32, n // 16)),
                  (max(32, n // 16), max(16, n // 32)),
                  (max(16, n // 32), max(8, n // 64)),
                  (8, 4)]
    for (w, s) in win_levels:
        if time.process_time() >= deadline - 1.0:
            break
        cand, r = _window_polish_log(best, deadline, w, s, maxiter=150)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand = _lbfgs_log(best, 500, deadline)
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        print("win w=%d R=%.7f" % (w, bestR))

    # ---- Phase 3: multigrid coarsen/refine ----
    if time.process_time() < deadline - 4.0:
        N_fine = best.size
        for Nc in [max(32, N_fine // 2), max(32, N_fine // 4)]:
            if time.process_time() >= deadline - 3.0:
                break
            h_c = _rescale(_coarse(best, Nc))
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.30)
            h_opt = _lbfgs_log(h_c, 2000, sub_dl)
            h_up = _rescale(_prolongate(h_opt, N_fine))
            r_up = R_of(h_up)
            if r_up > bestR + 1e-16:
                sub_dl2 = min(deadline - 0.8,
                              time.process_time() + (deadline - time.process_time()) * 0.5)
                h_opt2 = _lbfgs_log(h_up, 2000, sub_dl2)
                r2 = R_of(h_opt2)
                if r2 > bestR + 1e-16:
                    best, bestR = h_opt2, r2
                else:
                    best, bestR = h_up, r_up
                print("mgrid N=%d R=%.7f" % (Nc, bestR))

    # ---- Phase 4: fine window polish + full refine ----
    phase4_end = t0 + budget_seconds * 0.55
    while time.process_time() < phase4_end - 0.5:
        prev = bestR
        cand = _lbfgs_log(best, 2000, min(deadline, phase4_end + 1.0))
        r = R_of(cand)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish_log(best, min(deadline, phase4_end + 1.0), 16, 8, maxiter=100)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        cand, r = _window_polish_log(best, min(deadline, phase4_end + 1.0), 8, 4, maxiter=100)
        if r > bestR + 1e-16:
            best, bestR = cand, r
        if bestR - prev < 1e-14:
            break

    print("phase4 R=%.7f" % bestR)

    # ---- Phase 5: randomized subspace global search (the experiment) ----
    rng = np.random.default_rng(12345)
    trial = 0
    while time.process_time() < deadline - 1.5:
        prev = bestR
        cand, r = _subspace_global_search(best, bestR, deadline, rng, dim=100)
        trial += 1
        if r > bestR + 1e-16:
            best, bestR = cand, r
            print("subspace trial=%d R=%.7f" % (trial, bestR))
        else:
            if trial % 5 == 0:
                print("subspace trial=%d no gain R=%.7f" % (trial, bestR))
        if bestR - prev < 1e-14 and trial % 3 == 0:
            # occasional full refine to keep the incumbent sharp
            cand = _lbfgs_log(best, 200, deadline)
            r2 = R_of(cand)
            if r2 > bestR + 1e-16:
                best, bestR = cand, r2

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.asarray(best, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    # KEY NEW MOVE: over-resolve the shape. Prolongate to a much finer grid,
    # then optimise there. Step-function optima gain from finer discretisation.
    N_big = min(200000, max(N, int(N * 1.6)))
    if N_big > N and time.process_time() < deadline - 5.0:
        hp = _prolongate(best, N_big)
        hp = _lbfgs_log(hp, 400, deadline)
        r = R_of(hp)
        print("upsample %d->%d R=%.7f" % (N, N_big, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r
            N = N_big

    # Coarse-to-fine refinement at the (possibly new) resolution.
    for Nc in (2048, 4096, 8192):
        if time.process_time() >= deadline - 3.0:
            break
        if Nc >= N:
            continue
        hc = _coarse(best, Nc)
        hc = _lbfgs_log(hc, 800, deadline)
        hp = _prolongate(hc, N)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 600, deadline)
        r = R_of(hp)
        print("coarse %d -> R=%.7f" % (Nc, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r
            print("coarse improved R=%.7f" % bestR)

    # Peak-focused multi-scale polish.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # Phase exploration.
