def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _half_power_candidate(N, c):
    # h_i = sum_{k=0}^4 c_k t^{k-1/2}, t=(i+0.5)/N, c_0=1
    i = np.arange(N, dtype=float)
    t = (i + 0.5) / N
    h = np.zeros(N)
    for k in range(5):
        ck = 1.0 if k == 0 else c[k - 1]
        h += ck * t ** (k - 0.5)
    return np.clip(h, 0.0, None)


def _optimize_half_power(N, deadline, maxiter=200):
    def f(c):
        h = _half_power_candidate(N, c)
        r = R_of(h)
        if r <= 0:
            return 1e18, np.zeros(4)
        # finite-difference gradient (cheap: only 4 params)
        eps = 1e-6
        g = np.zeros(4)
        for j in range(4):
            cp = c.copy(); cp[j] += eps
            cm = c.copy(); cm[j] -= eps
            rp = R_of(_half_power_candidate(N, cp))
            rm = R_of(_half_power_candidate(N, cm))
            g[j] = -(np.log(rp) - np.log(rm)) / (2 * eps)
        return -np.log(r), g

    cb = _make_cb(deadline - 0.5)
    c0 = np.zeros(4)
    try:
        res = minimize(f, c0, jac=True, method='L-BFGS-B',
                       bounds=[(-0.5, 0.5)] * 4, callback=cb,
                       options={'maxiter': maxiter, 'ftol': 1e-18, 'gtol': 1e-14})
        if res is not None:
            return _half_power_candidate(N, res.x), res.x
    except (TimeoutError, Exception):
        pass
    return _half_power_candidate(N, c0), c0


def construct(budget_seconds, start):
    t0 = time.process_time()
