            h_big = _rescale(_prolongate(best, N_big))
            sub_dl = min(deadline - 1.0,
                         time.process_time() + (deadline - time.process_time()) * 0.40)
            h_opt = _lbfgs_log(h_big, 3000, sub_dl)
            r_opt = R_of(h_opt)
            if r_opt > bestR + 1e-16:
                best, bestR = h_opt, r_opt
                print("upsample N=%d R=%.7f" % (N_big, bestR))

    # ---- Sub-sample refine on a finer grid via phase-shift embedding ----
    if time.process_time() < deadline - 3.0:
        N_big = min(200000, best.size + max(2000, best.size // 3))
        if N_big > best.size:
            h_big = _rescale(_shift_and_pad(best, 0.5 / N_big, N_big))
            sub_dl = min(deadline - 1.0,
