                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _phase_shift(h, delta):
    n = h.size
    C = np.concatenate(([0.0], np.cumsum(h)))
    edges = np.arange(n + 1, dtype=float) - delta
    edges = np.clip(edges, 0.0, float(n))
    Cq = np.interp(edges, np.arange(n + 1, dtype=float), C)
    return np.diff(Cq)


def _split_cell(h, i):
    # split cell i into two equal halves, mass-conserving
    n = h.size
    out = np.empty(n + 1)
    out[:i] = h[:i]
    out[i] = 0.5 * h[i]
    out[i + 1] = 0.5 * h[i]
    out[i + 2:] = h[i + 1:]
    return out


def _merge_cells(h, i, j):
    # merge cells i and j (adjacent) into one, mass-conserving
    n = h.size
    if i > j:
        i, j = j, i
    out = np.empty(n - 1)
    out[:i] = h[:i]
    out[i] = h[i] + h[j]
    out[i + 1:] = h[j + 1:]
    return out


def _adaptive_mesh(best, bestR, deadline):
    N = best.size
    h = best.copy()
    curR = bestR
    accepted = 0
    while time.process_time() < deadline - 1.0:
        Lf = _knots(h)
        M = Lf.max()
        if M <= 0:
            break
        w = Lf * (M - Lf)
        # cell loss: use interior knots (index 1..n-1 correspond to cells? use all knots)
        # cell i corresponds to knots i and i+1; use w at knot i+1 as proxy
        n = h.size
        # per-cell loss: max of w at its two bounding knots
        wc = np.maximum(w[:-1], w[1:])
        # split candidates: cells adjacent to largest w_j (knots)
        order_hi = np.argsort(w)[::-1]
        split_cells = set()
        for kj in order_hi:
            if len(split_cells) >= 40:
                break
            # knot kj: adjacent cells kj-1 and kj (in cell index)
            for ci in (kj - 1, kj):
                if 0 <= ci < n:
                    split_cells.add(ci)
        split_cells = list(split_cells)[:40]

        # merge candidates: cells adjacent to smallest w_j
        order_lo = np.argsort(w)
        merge_pairs = set()
        for kj in order_lo:
            if len(merge_pairs) >= 40:
                break
            for ci in (kj - 1, kj):
                if 0 <= ci < n - 1:
                    # merge ci with smaller neighbour
                    if ci == 0:
                        j = 1
                    elif ci == n - 1:
                        j = n - 2
                    else:
                        j = ci - 1 if h[ci - 1] < h[ci + 1] else ci + 1
                    a, b = min(ci, j), max(ci, j)
                    merge_pairs.add((a, b))
        merge_pairs = list(merge_pairs)[:40]

        best_cand = None
        best_candR = curR
        best_kind = None

        # evaluate splits
        if n < 200000:
            for ci in split_cells:
                hc = _split_cell(h, ci)
                r = R_of(hc)
                if r > best_candR + 1e-16:
                    best_candR = r
                    best_cand = hc
                    best_kind = 'split'
        # evaluate merges
        if n > 2000:
            for (a, b) in merge_pairs:
                hc = _merge_cells(h, a, b)
                r = R_of(hc)
                if r > best_candR + 1e-16:
                    best_candR = r
                    best_cand = hc
                    best_kind = 'merge'

        if best_cand is not None:
            h = best_cand
            curR = best_candR
            accepted += 1
            if curR > bestR + 1e-15:
                bestR = curR
                best = h.copy()
            if accepted % 100 == 0:
                print("adapt %d N=%d R=%.7f" % (accepted, h.size, bestR))
                if time.process_time() < deadline - 2.0:
                    hp = _window_polish_peak(h, deadline, 0.40, 24)
                    rp = R_of(hp)
                    if rp > curR + 1e-16:
                        h = hp
                        curR = rp
                        if rp > bestR + 1e-15:
                            bestR = rp
                            best = hp.copy()
        else:
            # no improving move: polish
            if time.process_time() >= deadline - 1.5:
                break
            hp = _lbfgs_log(h, 300, deadline)
            rp = R_of(hp)
            if rp > curR + 1e-16:
                h = hp
                curR = rp
                if rp > bestR + 1e-15:
                    bestR = rp
                    best = hp.copy()
            else:
                # try peak polish then break if still no gain
                hp = _window_polish_peak(h, deadline, 0.40, 24)
                rp = R_of(hp)
                if rp > curR + 1e-16:
                    h = hp
                    curR = rp
                    if rp > bestR + 1e-15:
                        bestR = rp
                        best = hp.copy()
                else:
                    break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Adaptive-mesh experiment: objective-driven split/merge moves.
    try:
        best, bestR = _adaptive_mesh(best, bestR, deadline)
    except Exception as e:
        print("adaptive failed:", e)

    # If time remains, fall back to a short full polish.
    if time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("final polish R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _loss_center(h):
    """Index of knot maximizing local loss w_j = L_j*(M-L_j)."""
    Lf = _knots(h)
    M = Lf.max()
    if M <= 0:
        return h.size // 2
    w = Lf * (M - Lf)
    return int(np.argmax(w))


def _window_around(h, center, width, deadline, maxiter=800):
    n = h.size
    half = max(1, width // 2)
    lo = max(0, center - half)
    hi = min(n - 1, center + half)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Phase 1: global log-domain L-BFGS to squeeze the whole shape.
    while time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("global R=%.7f" % bestR)
        else:
            break

    # Phase 2: random-width windows centred on largest local loss.
    rng = np.random.default_rng(12345)
    n = best.size
    lo_w = max(2, int(0.02 * n))
    hi_w = max(lo_w + 1, int(0.50 * n))
    log_lo = np.log(lo_w)
    log_hi = np.log(hi_w)
    it = 0
    while time.process_time() < deadline - 0.6:
        if it % 5 == 4:
            hg = _lbfgs_log(best, 1500, deadline)
            rg = R_of(hg)
            if rg > bestR + 1e-16:
                best, bestR = hg.copy(), rg
                print("reglobal R=%.7f" % bestR)
        else:
            center = _loss_center(best)
            w = int(np.exp(rng.uniform(log_lo, log_hi)))
            h = _window_around(best, center, w, deadline, maxiter=800)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
                print("win w=%d c=%d R=%.7f" % (w, center, bestR))
        it += 1

    # Final full polish.
    if time.process_time() < deadline - 0.2:
        h = _lbfgs_log(best, 2000, deadline)
        r = R_of(h)
        if r > bestR:
            best, bestR = h.copy(), r
            print("final polish R=%.7f" % bestR)

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale_maxL(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _norm_eq_fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _exact_lbfgs(h0, maxiter, maxfun, deadline, free=None, ftol=1e-20, gtol=1e-16):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if free is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': maxfun,
                                'ftol': ftol, 'gtol': gtol})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale_maxL(h2)


def _linear_lbfgs(h0, deadline, maxiter=400):
    """One linear (non-log) L-BFGS-B on the active set."""
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = np.zeros(n)
        hh[active] = np.clip(x, 0.0, None)
        val, g = _norm_eq_fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    res = None
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-22, 'gtol': 1e-18})
    except TimeoutError:
        pass
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale_maxL(h2)


def _peak_region(h):
    n = h.size
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, n - 1
    idx = np.flatnonzero(Lf >= 0.999 * mx)
    if idx.size == 0:
        m = int(np.argmax(Lf))
        return max(0, m - 1), min(n - 1, m)
    lo = max(0, idx.min() - 1)
    hi = min(n - 1, idx.max())
    if hi < lo:
        return 0, n - 1
    return lo, hi


def _window_polish(h, deadline, frac=0.10, shift=0.0):
    if time.process_time() >= deadline - 0.3:
        return h
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(4, int(span * frac))
    center = 0.5 * (lo + hi) + shift * n
    lo2 = int(center - pad)
    hi2 = int(center + pad)
    lo2 = max(0, lo2)
    hi2 = min(n - 1, hi2)
    if hi2 <= lo2:
        return h
    free = np.arange(lo2, hi2 + 1)
    return _exact_lbfgs(h, 400, 800, deadline, free=free)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale_maxL(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.7f (N=%d)" % (bestR, best.size))

    # One-time: floor exact-zero cells at 1e-4*mean, then linear L-BFGS on active set.
    if time.process_time() < deadline - 1.5:
        h = best.copy()
        mean = h.mean()
        floor = 1e-4 * mean
        h[h <= 0] = floor
        h = _linear_lbfgs(h, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("linear pre-pass R=%.7f" % bestR)

    WIDTHS = [0.04, 0.10, 0.20, 0.35]
    cycle = 0
    while time.process_time() < deadline - 1.0:
        cycle += 1
        prevR = bestR
        # Full global log L-BFGS-B
        if time.process_time() < deadline - 1.0:
            h = _exact_lbfgs(best, 1500, 3000, deadline,
                             ftol=1e-22, gtol=1e-18)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
        # Peak-window polish at multiple widths; every third window shifts centre.
        for wi, frac in enumerate(WIDTHS):
            if time.process_time() >= deadline - 1.0:
                break
            shift = 0.10 if (cycle % 3 == 0 and wi % 2 == 1) else 0.0
            h = _window_polish(best, deadline, frac=frac, shift=shift)
            r = R_of(h)
            if r > bestR + 1e-16:
                best, bestR = h.copy(), r
        if bestR > prevR + 1e-16:
            print("cycle %d R=%.7f" % (cycle, bestR))
        else:
            if time.process_time() >= deadline - 1.0:
                break

    # Final exact polish until the bell.
    hard = t0 + budget_seconds * 0.97
    while time.process_time() < hard - 0.5:
        h = _exact_lbfgs(best, 4000, 8000, hard - 0.3,
                         ftol=1e-22, gtol=1e-18)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("final polish R=%.7f" % bestR)
        else:
            break

    if bestR < R_of(base):
        best, bestR = base, R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _peak_block(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _smooth(h, k):
    if k <= 0:
        return h.copy()
    ker = np.ones(2 * k + 1)
    ker /= ker.sum()
    hp = np.concatenate((np.full(k, h[0]), h, np.full(k, h[-1])))
    return np.convolve(hp, ker, mode='valid')


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _phase_shift(h, delta):
    n = h.size
    d = int(round(delta))
    if d == 0:
        return h.copy()
    return np.roll(h, d)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best = None
            bestR = 0.0
    else:
        best = None
        bestR = 0.0

    if best is None:
        N = 8000
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # --- Phase 1: peak-region polish on the original grid (cheap, high-value) ---
    if time.process_time() < deadline - 3.0:
        for frac, extra in ((0.25, 64), (0.5, 128), (1.0, 0)):
            if time.process_time() >= deadline - 2.5:
                break
            cand = _peak_block(best, deadline - 1.5, frac, extra, maxiter=300)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                print("peak frac=%.2f R=%.7f" % (frac, bestR))

    # --- Phase 2: coarse-grid re-optimization then prolongate back ---
    if time.process_time() < deadline - 4.0:
        n = best.size
        for Nc in (1024, 2048, 4096):
            if time.process_time() >= deadline - 3.0:
                break
            if Nc >= n:
                continue
            hc = _coarse(best, Nc)
            hc = _rescale(hc)
            sub = min(deadline - 2.0, time.process_time() + 3.0)
            cand = _lbfgs_log(hc, 800, sub)
            rc = R_of(cand)
            if rc > 0:
                hp = _rescale(_prolongate(cand, n))
                sub2 = min(deadline - 1.5, time.process_time() + 2.5)
                hp = _lbfgs_log(hp, 500, sub2)
                r = R_of(hp)
                if r > bestR + 1e-15:
                    best, bestR = hp, r
                    print("coarse Nc=%d R=%.7f" % (Nc, bestR))

    # --- Phase 3: smoothing kicks ---
    for k in (1, 2, 4):
        if time.process_time() >= deadline - 2.0:
            break
        hs = _rescale(_smooth(best, k))
        sub = min(deadline - 1.0, time.process_time() + 3.0)
        cand = _lbfgs_log(hs, 500, sub)
        r = R_of(cand)
        if r > bestR + 1e-14:
            best, bestR = cand, r
            print("smooth k=%d R=%.7f" % (k, bestR))

    # --- Phase 4: alternate full + peak until time runs out ---
    while time.process_time() < deadline - 2.0:
        improved = False
        if time.process_time() < deadline - 2.5:
            cand = _lbfgs_log(best, 1500, deadline - 1.5)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                print("full R=%.7f" % bestR)
                improved = True
        if time.process_time() < deadline - 2.0:
            cand = _peak_block(best, deadline - 1.0, 0.5, 128, maxiter=400)
            r = R_of(cand)
            if r > bestR + 1e-15:
                best, bestR = cand, r
                print("peak R=%.7f" % bestR)
                improved = True
        if not improved:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return np.clip(best, 0, None)

