import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _knots(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    return np.concatenate(([0.0], L, [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    if h.size > 1500:
        L = fftconvolve(h, h)
    else:
        L = np.convolve(h, h)
    Lf = np.concatenate(([0.0], L, [0.0]))
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a*a + a*b + b*b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2*a + b)
    dq[1:] += (a + 2*b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _deconvolve(T):
    # T has length 2n-1; recover h of length n via causal recursion
    m = T.size
    n = (m + 1) // 2
    h = np.zeros(n)
    h0 = np.sqrt(max(T[0], 0.0))
    if h0 <= 0:
        return None
    h[0] = h0
    for k in range(1, n):
        s = 0.0
        for i in range(1, k):
            s += h[i] * h[k - i]
        h[k] = (T[k] - s) / (2.0 * h0)
    return np.clip(h, 0.0, None)


def _warp(h, gL, gR):
    n = h.size
    Lf = _knots(h)
    m = Lf.size  # 2n-1
    jc = int(np.argmax(Lf))
    j = np.arange(m, dtype=float)
    x = np.empty(m)
    # left side j <= jc
    maskL = j <= jc
    if jc > 0:
        x[maskL] = jc * (j[maskL] / jc) ** gL
    else:
        x[maskL] = j[maskL]
    # right side j > jc
    maskR = ~maskL
    if jc < m - 1:
        denom = (m - 1 - jc)
        t = (m - 1 - j[maskR]) / denom
        x[maskR] = jc + denom * (1.0 - t ** gR)
    else:
        x[maskR] = j[maskR]
    T = np.interp(x, np.arange(m, dtype=float), Lf)
    hw = _deconvolve(T)
    if hw is None or hw.sum() <= 0:
        return None
    return _rescale(hw)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)
    base = _rescale(base)

    best = base.copy()
    bestR = R_of(best)
    print("start R=%.6f (N=%d)" % (bestR, best.size))

    # Phase 0: x-warp scan
    gvals = [0.90, 0.95, 1.05, 1.10]
    for gL in gvals:
        for gR in gvals:
            if time.process_time() >= deadline - 2.0:
                break
            hw = _warp(best, gL, gR)
            if hw is None:
                continue
            hw = _lbfgs_log(hw, 600, deadline)
            hw = _window_polish_peak(hw, deadline, 0.35, extra=4, maxiter=400)
            r = R_of(hw)
            if r > bestR + 1e-16:
                best, bestR = hw.copy(), r
                print("warp gL=%.2f gR=%.2f R=%.7f" % (gL, gR, bestR))

    # Phase 1: global log-domain L-BFGS
    while time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 3000, deadline)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            print("global R=%.7f" % bestR)
        else:
            break

    # Phase 2: alternating wide/narrow window polish around the peak
    fracs = [0.60, 0.35, 0.20, 0.12, 0.07, 0.04, 0.02]
    idx = 0
    stall = 0
    while time.process_time() < deadline - 0.6:
        frac = fracs[idx % len(fracs)]
        h = _window_polish_peak(best, deadline, frac, extra=4, maxiter=800)
        r = R_of(h)
        if r > bestR + 1e-16:
            best, bestR = h.copy(), r
            stall = 0
            print("win %.2f R=%.7f" % (frac, bestR))
        else:
            stall += 1
            if stall >= 2:
                hg = _lbfgs_log(best, 1500, deadline)
                rg = R_of(hg)
                if rg > bestR + 1e-16:
                    best, bestR = hg.copy(), rg
                    print("reglobal R=%.7f" % bestR)
                stall = 0
        idx += 1

    if bestR < R_of(base):
        best = base
        bestR = R_of(base)

    print("final R=%.7f (N=%d)" % (bestR, best.size))
    return best

